INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hgchrre/finserv-webinar/verify-changes', 'community', 'hgchrre', 'finserv-webinar', 'hgchrre/finserv-webinar', 'verify-changes', 0, 0, 48, '2026-03-08T01:57:15.493Z', '2026-03-08T02:10:10.900Z', '6a101c2474f700705f2aa3d1a7de6f1680effdbfcf9a66cb4221879ccdb1497d', '{"id":"hgchrre/finserv-webinar/verify-changes","name":"verify-changes","description":{"en":"The verify-changes skill automates code validation for developers, running PII compliance checks and security scans in parallel to ensure secure code deployment.","zh":"verify-changes 技术通过并行运行 4 个验证代理来验证更改，确保代码安全和合规","ja":"verify-changes は、並列実行の検証エージェントを使用して変更を検証します","ko":"verify-changes 기술은 병렬로 4개의 검증 에이전트를 실행하여 변경 사항을 검증합니다","es":"Verify-changes es una habilidad que ejecuta cuatro agentes de verificación en paralelo para validar cambios antes de comprometer o implementar. Incluye PII Compliance Checker y Security Scanner","fr":"Verify-changes est une compétence qui exécute quatre agents de vérification en parallèle pour valider les modifications avant de les valider ou de les déployer. Elle comprend le PII Compliance Checker et le Security Scanner","de":"Verify-changes ist eine Fähigkeit, die vier Überprüfungsagenten parallel ausführt, um Änderungen vor dem Commit oder Deploy zu überprüfen. Sie umfasst den PII Compliance Checker und den Security Scanner","pt":"O verify-changes é uma ferramenta que executa agents de verificação em paralelo para validar alterações no código, garantindo a conformidade e segurança.","ru":"Verify-changes - это инструмент, который запускает агенты верификации параллельно для проверки изменений в коде, обеспечивая соответствие и безопасность.","ar":"verify-changes هو أداة تنفذ وكلاء التحقق بالتوازي للتحقق من التغييرات في الكود، مما يضمن الامتثال والأمان."},"seo":{"title":{"en":"verify-changes: Automated Code Validation Setup Gui