INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hgchrre/finserv-webinar/verify-changes', 'verify-changes', 'hgchrre', 'finserv-webinar', 'community', 'verify-changes hgchrre finserv-webinar community The verify-changes skill automates code validation for developers, running PII compliance checks and security scans in parallel to ensure secure code deployment. verify-changes 技术通过并行运行 4 个验证代理来验证更改，确保代码安全和合规 verify-changes は、並列実行の検証エージェントを使用して変更を検証します verify-changes 기술은 병렬로 4개의 검증 에이전트를 실행하여 변경 사항을 검증합니다 Verify-changes es una habilidad que ejecuta cuatro agentes de verificación en paralelo para validar cambios antes de comprometer o implementar. Incluye PII Compliance Checker y Security Scanner Verify-changes est une compétence qui exécute quatre agents de vérification en parallèle pour valider les modifications avant de les valider ou de les déployer. Elle comprend le PII Compliance Checker et le Security Scanner Verify-changes ist eine Fähigkeit, die vier Überprüfungsagenten parallel ausführt, um Änderungen vor dem Commit oder Deploy zu überprüfen. Sie umfasst den PII Compliance Checker und den Security Scanner O verify-changes é uma ferramenta que executa agents de verificação em paralelo para validar alterações no código, garantindo a conformidade e segurança. Verify-changes - это инструмент, который запускает агенты верификации параллельно для проверки изменений в коде, обеспечивая соответствие и безопасность. verify-changes هو أداة تنفذ وكلاء التحقق بالتوازي للتحقق من التغييرات في الكود، مما يضمن الامتثال والأمان. how to use verify-changes verify-changes setup guide automated code validation PII compliance checker Snyk security scanner verify-changes alternative verify-changes vs code validation tools verify-changes install code validation best practices verify-changes 代码验证 并行验证代理 PII 合规检查 安全扫描 Snyk 代码安全 AI 에이전트 Runs PII compliance checker to detect masking, audit logging, and data leak issues Executes security scanner using Snyk scans for source vulnerabilities Supports parallel execution of verification agents for efficient code validation Checks for data leaks in console and error logs Validates code changes before committing or deploying verify-changes is a code validation skill that runs multiple verification agents in parallel to detect security vulnerabilities and PII handling violations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('WSU-Carbon-Lab/pyref/polars-expertise', 'community', 'WSU-Carbon-Lab', 'pyref', 'WSU-Carbon-Lab/pyref', 'polars-expertise', 0, 0, 48, '2026-03-08T01:57:15.493Z', '2026-03-08T02:10:10.997Z', '16cf49e414cdfb653c9a26e6fd56f1c3bc68f70b57fd2c90493f63463ad442fb', '{"id":"WSU-Carbon-Lab/pyref/polars-expertise","name":"polars-expertise","description":{"en":"The polars-expertise skill provides a Python toolkit for processing and analyzing Polarized Resonant Reflectivity Data, benefiting developers and data scientists. It supports Python and Rust with an expression-based API.","zh":"Polars Expertise 是一个 Python 工具包，用于处理和分析 Polarized Resonant Reflectivity 数据，具有高性能和并行化能力","ja":"Polars Expertise は、偏光共鳴反射率データの処理と分析を行う Python ツールキットであり、高性能と並列化機能を備えています","ko":"Polars Expertise는 고성능 데이터 분석을 위한 Python 도구입니다. Polarized Resonant Reflectivity 데이터를 처리하고 분석할 수 있습니다","es":"polars-expertise es una herramienta de Python para procesar y analizar datos de reflectividad resonante polarizada, basada en Apache Arrow","fr":"polars-expertise est un outil Python pour traiter et analyser les données de réflectivité résonante polarisée, basé sur Apache Arrow","de":"polars-expertise ist ein Python-Tool zur Verarbeitung und Analyse von Daten der polarisierten resonanten Reflexivität, basierend auf Apache Arrow","pt":"O Polars é uma ferramenta Python de alto desempenho para processar e analisar dados de reflectividade resonante polarizada","ru":"Поларс - это высокопроизводительная библиотека Python для обработки и анализа данных о поляризованной резонансной отражательной способности","ar":"أداة Polars هي أداة بايثون عالية الأداء لتحليل البيانات المتناظرة للأشعة تحت الحمراء"},"seo":{"title":{"en":"polars-expertise: High-Performance DataFrame Library Setu...","zh":"Polars Expertise Setup Guide - Python 高性能数据处理","ja":"Polars Expertise を使った高速データ処理のベ