INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('WSU-Carbon-Lab/pyref/polars-expertise', 'polars-expertise', 'WSU-Carbon-Lab', 'pyref', 'community', 'polars-expertise WSU-Carbon-Lab pyref community The polars-expertise skill provides a Python toolkit for processing and analyzing Polarized Resonant Reflectivity Data, benefiting developers and data scientists. It supports Python and Rust with an expression-based API. Polars Expertise 是一个 Python 工具包，用于处理和分析 Polarized Resonant Reflectivity 数据，具有高性能和并行化能力 Polars Expertise は、偏光共鳴反射率データの処理と分析を行う Python ツールキットであり、高性能と並列化機能を備えています Polars Expertise는 고성능 데이터 분석을 위한 Python 도구입니다. Polarized Resonant Reflectivity 데이터를 처리하고 분석할 수 있습니다 polars-expertise es una herramienta de Python para procesar y analizar datos de reflectividad resonante polarizada, basada en Apache Arrow polars-expertise est un outil Python pour traiter et analyser les données de réflectivité résonante polarisée, basé sur Apache Arrow polars-expertise ist ein Python-Tool zur Verarbeitung und Analyse von Daten der polarisierten resonanten Reflexivität, basierend auf Apache Arrow O Polars é uma ferramenta Python de alto desempenho para processar e analisar dados de reflectividade resonante polarizada Поларс - это высокопроизводительная библиотека Python для обработки и анализа данных о поляризованной резонансной отражательной способности أداة Polars هي أداة بايثون عالية الأداء لتحليل البيانات المتناظرة للأشعة تحت الحمراء how to use polars-expertise polars-expertise alternative polars-expertise install polars-expertise vs pandas polars-expertise setup guide polars-expertise gpu support what is polars-expertise polars-expertise documentation polars-expertise tutorial Polars Expertise Python 数据处理 Apache Arrow 高性能 DataFrame 表达式基于 API 懒惰评估 自动并行化 GPU 支持 Built on Apache Arrow for high-performance data processing Supports Python and Rust with an expression-based API Offers lazy evaluation for optimized execution Provides automatic parallelization for efficient data analysis Allows GPU support via pip install polars[gpu] Enables eager and lazy execution modes for flexible data processing polars-expertise is a high-performance DataFrame library built on Apache Arrow, supporting Python and Rust with features like lazy evaluation and automatic parallelization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jamesjfoong/github-pr-review-mcp/validate-code', 'community', 'jamesjfoong', 'github-pr-review-mcp', 'jamesjfoong/github-pr-review-mcp', 'validate-code', 0, 0, 48, '2026-03-08T01:57:15.509Z', '2026-03-08T02:10:24.686Z', 'da823419dadba82b72abef4365b575cd4eb83541e352abc876e2e17f5114fc80', '{"id":"jamesjfoong/github-pr-review-mcp/validate-code","name":"validate-code","description":{"en":"The validate-code skill automates Github PR reviews for developers, ensuring code quality checks and fixing linting or type errors. It supports TypeScript, ESLint, and Prettier.","zh":"代码验证工具可以帮助开发者自动化代码检查和格式化，提高代码质量和开发效率","ja":"コード検証ツールは、開発者がコードの検証とフォーマットを自動化できるようにして、コードの品質と開発効率を向上させる","ko":"코드 검증 도구는 개발자가 코드의 검증과 형식화를 자동화할 수 있도록 해서 코드의 품질과 개발 효율성을 향상시킨다","es":"El agente de AI ''validate-code'' es una herramienta para revisar y mejorar la calidad del código en Github, utilizando npm y TypeScript para realizar comprobaciones de tipo, linting y formato.","fr":"L''agent d''IA ''validate-code'' est un outil pour examiner et améliorer la qualité du code sur Github, en utilisant npm et TypeScript pour effectuer des vérifications de type, de linting et de formatage.","de":"Der AI-Agent ''validate-code'' ist ein Werkzeug zur Überprüfung und Verbesserung der Code-Qualität auf Github, das npm und TypeScript verwendet, um Typ-, Linting- und Formatierungsprüfungen durchzuführen.","pt":"O Validate-Code é uma ferramenta de Inteligência Artificial que executa verificações de tipo, lint e formatação para garantir a qualidade do código","ru":"Validate-Code - это инструмент ИИ Агентов, который выполняет проверки типа, lint и форматирования для обеспечения качества кода","ar":"Validate-Code هو أداة ذكاء اصطناعي تقوم بتشغيل عمليات التحقق من النوع و lint والتنسيق لضمان جودة الكود"},"seo":{"title":{"en":"validate-code: Github PR Review Setup Guide | AI Agent Skill","zh":"代码验证工具：AI代码检查设置指南","ja":"コード検証ツール：AIエージェントによるコードチェックベストプラクティス","ko":"코드 검증 도구: AI 에이전트를 이용한 코드 검사 설정 가이드","es":"Guía de configuración de validate-code para revisión de c...","fr":"Guide de mise en place de validate-code pour la révision ...","de":"Einrichtungsleitfaden für validate-code zur Code-Überprüf...","pt":"Guia de Configuração do Validate-Code para Ferramentas de...","ru":"Настройка Validate-Code: ИИ Агенты для Проверки Код","ar":"دليل إعداد Validate-Code لأدوات الذكاء الاصطناعي"},"description":{"en":"Streamline your Github PR review process with validate-code. Learn how to run type-check, lint, and format-check with a single command: npm run validate","zh":"使用AI代码验证工具提高代码质量，自动化代码检查和格式化，提高开发效率","ja":"AIエージェントを使用してコードの品質を向上させ、コードの検証とフォーマットを自動化する","ko":"AI 에이전트를 이용하여 코드 품질을 향상시키고, 코드 검증과 형식화를 자동화하여 개발 효율성을 높여라","es":"Aprende a utilizar el agente de AI ''validate-code'' para revisar y mejorar la calidad de tu código en Github con npm y TypeScript","fr":"Découvrez comment utiliser l''agent d''IA ''validate-code'' pour examiner et améliorer la qualité de votre code sur Github avec npm et TypeScript","de":"Erfahren Sie, wie Sie den AI-Agent ''validate-code'' verwenden, um Ihren Code auf Github mit npm und TypeScript zu überprüfen und zu verbessern","pt":"Aprenda a validar código com o Validate-Code, uma ferramenta de Inteligência Artificial para garantir a qualidade do código","ru":"Проверьте код с помощью Validate-Code, инструмент ИИ Агентов для обеспечения качества кода","ar":"تعلم كيفية التحقق من الكود باستخدام Validate-Code، أداة الذكاء الاصطناعي لضمان جودة الكود"},"definition":{"en":"validate-code is a Github PR review tool that runs type-check, lint, and format-check to ensure code quality and consistency","zh":"代码验证工具是一种AI驱动的工具，用于自动化代码检查和格式化","ja":"コード検証ツールは、AIエージェントによって駆動されるツールで、コードの検証とフォーマットを自動化する","ko":"코드 검증 도구는 AI 에이전트에 의해 구동되는 도구로, 코드의 검증과 형식화를 자동화한다","es":"El agente de AI ''validate-code'' es una herramienta de revisión de código que utiliza npm y TypeScript para comprobar la calidad del código","fr":"L''agent d''IA ''validate-code'' est un outil d''examen de code qui utilise npm et TypeScript pour vérifier la qualité du code","de":"Der AI-Agent ''validate-code'' ist ein Code-Überprüfungstool, das npm und TypeScript verwendet, um die Code-Qualität zu prüfen","pt":"O Validate-Code é uma ferramenta que verifica a qualidade do código, executando verificações de tipo, lint e formatação","ru":"Validate-Code - это инструмент, который проверяет качество кода, выполняя проверки типа, lint и форматирования","ar":"Validate-Code هو أداة تتحقق من جودة الكود عن طريق تشغيل عمليات التحقق من النوع و lint والتنسيق"},"features":{"en":["Runs type-check, lint, and format-check with a single command: npm run validate","Fixes linting issues with npm run lint:fix","Fixes formatting issues with npm run format","Supports individual checks for TypeScript, ESLint, and Prettier","Re-validates code after fixes with npm run validate"],"zh":["支持TypeScript类型检查","集成ESLint代码风格检查","自动化代码格式化","支持npm run validate命令","支持npm run lint:fix命令","支持npm run format命令"],"ja":["TypeScriptの型チェックをサポート","ESLintによるコードスタイルのチェックを統合","コードのフォーマットを自動化","npm run validateコマンドをサポート","npm run lint:fixコマンドをサポート","npm run formatコマンドをサポート"],"ko":["TypeScript 유형 확인 지원","ESLint를 통한 코드 스타일 확인 통합","코드 형식화를 자동화","npm run validate 명령어 지원","npm run lint:fix 명령어 지원","npm run format 명령어 지원"],"es":["Comprobación de tipo con TypeScript","Linting con ESLint","Comprobación de formato con Prettier","Corrección automática de errores de linting y formato","Ejecución de comprobaciones individuales con npm","Validación completa del código con npm run validate"],"fr":["Vérification de type avec TypeScript","Linting avec ESLint","Vérification de formatage avec Prettier","Correction automatique des erreurs de linting et de formatage","Exécution de vérifications individuelles avec npm","Validation complète du code avec npm run validate"],"de":["Typprüfung mit TypeScript","Linting mit ESLint","Formatierungsprüfung mit Prettier","Automatische Korrektur von Linting- und Formatierungsfehlern","Ausführung von Einzelprüfungen mit npm","Vollständige Validierung des Codes mit npm run validate"],"pt":["Verificação de tipo com TypeScript","Verificação de lint com ESLint","Verificação de formatação com Prettier","Comando de validação rápido com ''npm run validate''","Comando de correção de lint com ''npm run lint:fix''","Comando de formatação com ''npm run format''"],"ru":["Проверка типа с помощью TypeScript","Проверка lint с помощью ESLint","Проверка форматирования с помощью Prettier","Быстрая проверка с помощью ''npm run validate''","Команда исправления lint с помощью ''npm run lint:fix''","Команда форматирования с помощью ''npm run format''"],"ar":["التحقق من النوع باستخدام TypeScript","التحقق من lint باستخدام ESLint","التحقق من التنسيق باستخدام Prettier","أمر التحقق السريع باستخدام ''npm run validate''","أمر تصحيح lint باستخدام ''npm run lint:fix''","أمر التنسيق باستخدام ''npm run format''"]},"keywords":{"en":["how to use validate-code","validate-code setup guide","Github PR review tool","npm run validate","validate-code vs code quality tools","install validate-code","what is validate-code","validate-code alternative","validate-code for developers"],"zh":["代码验证工具","AI代码检查","代码质量","自动化代码检查","代码格式化","TypeScript","ESLint","npm run validate","npm run lint:fix","npm run format"],"ja":["コード検証ツール","AIエージェント","コードの品質","コードの検証","コードのフォーマット","TypeScript","ESLint","npm run validate","npm run lint:fix","npm run format"],"ko":["코드 검증 도구","AI 에이전트","코드 품질","코드 검사","코드 형식화","TypeScript","ESLint","npm run validate","npm run lint:fix","npm run format"],"es":["validate-code","revisión de código","Github","npm","TypeScript","ESLint","Prettier","comprobación de tipo","linting","formato de código"],"fr":["validate-code","examen de code","Github","npm","TypeScript","ESLint","Prettier","vérification de type","linting","formatage de code"],"de":["validate-code","Code-Überprüfung","Github","npm","TypeScript","ESLint","Prettier","Typprüfung","Linting","Code-Formatierung"],"pt":["validate-code","ferramentas de inteligência artificial","verificação de código","TypeScript","ESLint","Prettier","npm run validate","desenvolvimento de software"],"ru":["validate-code","ИИ Агенты","проверка кода","TypeScript","ESLint","Prettier","npm run validate","разработка программного обеспечения"],"ar":["validate-code","أدوات الذكاء الاصطناعي","التحقق من الكود","TypeScript","ESLint","Prettier","npm run validate","تطوير البرمجيات"]}},"owner":"jamesjfoong","repo":"github-pr-review-mcp","repoPath":"jamesjfoong/github-pr-review-mcp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.509Z","topics":[],"category":"community","skillMd":{"name":"validate-code","description":"Validate code before committing. Use before commits or when fixing linting/type errors.","bodyPreview":"# Validate Code\n\n## When to Use\n\n- Before committing any changes\n- When fixing linting or type errors\n- When code quality checks fail\n\n## Quick Validation\n\n```bash\nnpm run validate\n```\n\nRuns: type-check + lint + format-check\n\n## Fix Issues\n\n```bash\n# Fix linting\nnpm run lint:fix\n\n# Fix formatting\nnpm run format\n\n# Re-validate\nnpm run validate\n```\n\n## Individual Checks\n\n```bash\nnpm run type-check    # TypeScript only\nnpm run lint          # ESLint only\nnpm run format:check  # Prettier only\n```\n\n#","body":"# Validate Code\n\n## When to Use\n\n- Before committing any changes\n- When fixing linting or type errors\n- When code quality checks fail\n\n## Quick Validation\n\n```bash\nnpm run validate\n```\n\nRuns: type-check + lint + format-check\n\n## Fix Issues\n\n```bash\n# Fix linting\nnpm run lint:fix\n\n# Fix formatting\nnpm run format\n\n# Re-validate\nnpm run validate\n```\n\n## Individual Checks\n\n```bash\nnpm run type-check    # TypeScript only\nnpm run lint          # ESLint only\nnpm run format:check  # Prettier only\n```\n\n## Common Type Errors\n\n| Error              | Fix                                       |\n| ------------------ | ----------------------------------------- |\n| Implicit any       | Add explicit type annotations             |\n| Type mismatch      | Verify schema matches type                |\n| Missing properties | Use optional `?` if needed                |\n| Optional values    | Use `?` instead of `\\| null \\| undefined` |\n\n## Debugging Steps\n\n1. Run `npm run type-check` to see all errors\n2. Check Zod schemas match expected structure\n3. Ensure types exported from `types.ts`\n4. Verify optional properties use `?`\n"},"lastSynced":"2026-03-08T02:10:24.686Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing automated GitHub PR reviews with TypeScript, ESLint, and Prettier support.","zh":"适合需要自动化 GitHub PR 代码审查的代码审查代理，支持 TypeScript、ESLint 和 Prettier。","ja":"TypeScript、ESLint、Prettier をサポートする GitHub PR コードレビューの自動化に適したコードレビュー エージェントです。","ko":"TypeScript, ESLint, Prettier를 지원하는 GitHub PR 코드 리뷰 자동화에 적합한 코드 리뷰 에이전트입니다.","es":"Ideal para agentes de revisión de código que necesitan revisiones automatizadas de GitHub PR con soporte para TypeScript, ESLint y Prettier.","fr":"Idéal pour les agents de révision de code nécessitant des examens de PR GitHub automatisés avec prise en charge de TypeScript, ESLint et Prettier.","de":"Ideal für Code-Review-Agents, die automatisierte GitHub-PR-Überprüfungen mit TypeScript-, ESLint- und Prettier-Unterstützung benötigen.","pt":"Ideal para Agentes de Revisão de Código que precisam de revisões automatizadas de PR do GitHub com suporte a TypeScript, ESLint e Prettier.","ru":"Идеально для агентов кодового обзора, которым необходимы автоматизированные обзоры PR GitHub с поддержкой TypeScript, ESLint и Prettier.","ar":"مثالي لعميل مراجعة الكود الذي يحتاج إلى مراجعاتautomated لPR GitHub مع دعم TypeScript و ESLint و Prettier."},"recommendation":{"en":"Empowers agents to automate code quality checks, fix linting or type errors, and ensure formatting consistency using npm scripts for type-check, lint, and format validation.","zh":"赋予代理自动化代码质量检查、修复 linting 或类型错误、并使用 npm 脚本确保格式一致性，用于类型检查、lint 和格式验证。","ja":"エージェントにコード品質のチェック、linting エラーまたは型エラーの修復、npm スクリプトを使用したフォーマットの一貫性の確保などの自動化を可能にします。","ko":"에이전트가 코드 품질 검사, 린팅 오류 또는 타입 오류를 수정하고, npm 스크립트를 사용하여 포맷팅 일관성을 보장하는 등의 자동화를 가능하게 합니다.","es":"Habilita a los agentes a automatizar las comprobaciones de calidad del código, corregir errores de linting o de tipo y garantizar la consistencia de formato mediante scripts de npm para la validación de tipo, lint y formato.","fr":"Permet aux agents d''automatiser les vérifications de qualité de code, de corriger les erreurs de linting ou de type et d''assurer la cohérence de formatage en utilisant des scripts npm pour la validation de type, lint et de format.","de":"Ermächtigt die Agenten, Code-Qualitätsprüfungen zu automatisieren, Linting- oder Typfehler zu beheben und die Formatierungsconsistenz mithilfe von npm-Skripten für Typ-, Lint- und Formatvalidierung sicherzustellen.","pt":"Habilita os agentes a automatizar verificações de qualidade de código, corrigir erros de linting ou de tipo e garantir a consistência de formatação usando scripts npm para validação de tipo, lint e formatação.","ru":"Наделяет агентов возможностью автоматизировать проверки качества кода, исправлять ошибки linting или типов и обеспечивать последовательность форматирования, используя скрипты npm для проверки типа, lint и форматирования.","ar":"يمنح العميل القدرة على توفير عمليات فحص جودة الكود自动يًا وتصحيح الأخطاء الناتجة عن linting أو أخطاء النوع وضمان الاتساق في تنسيق باستخدام سكريبتات npm للتحقق من نوع وlint وتنسيق."},"useCases":{"en":["Automating GitHub PR reviews for code quality","Fixing linting errors with ESLint","Validating TypeScript code for type errors"],"zh":["自动化 GitHub PR 代码审查以检查代码质量","使用 ESLint 修复 linting 错误","验证 TypeScript 代码以检查类型错误"],"ja":["コード品質のチェックのための GitHub PR コードレビューの自動化","ESLint を使用して linting エラーを修復する","型エラーのチェックのための TypeScript コードの検証"],"ko":["코드 품질 검사를 위한 GitHub PR 코드 리뷰 자동화","ESLint를 사용하여 린팅 오류를 수정","타입 오류를 확인하기 위한 TypeScript 코드 검증"],"es":["Automatización de revisiones de PR de GitHub para la calidad del código","Corrección de errores de linting con ESLint","Validación de código TypeScript para errores de tipo"],"fr":["Automatisation des examens de PR GitHub pour la qualité du code","Correction des erreurs de linting avec ESLint","Validation du code TypeScript pour les erreurs de type"],"de":["Automatisierung von GitHub-PR-Überprüfungen für die Codequalität","Behebung von Linting-Fehlern mit ESLint","Validierung von TypeScript-Code für Typfehler"],"pt":["Automatizar revisões de PR do GitHub para qualidade de código","Corrigir erros de linting com ESLint","Validar código TypeScript para erros de tipo"],"ru":["Автоматизировать обзоры PR GitHub для качества кода","Исправлять ошибки linting с помощью ESLint","Проверять код TypeScript на ошибки типов"],"ar":["توفير عمليات مراجعة PR GitHub الآلية لجودة الكود","تصحيح أخطاء لينتينج باستخدام ESLint","التحقق من صحة كود TypeScript لأخطاء النوع"]},"limitations":{"en":["Requires npm and GitHub setup","Supports TypeScript, ESLint, and Prettier only"],"zh":["需要 npm 和 GitHub 设置","仅支持 TypeScript、ESLint 和 Prettier"],"ja":["npm と GitHub の設定が必要","TypeScript、ESLint、Prettier のみをサポート"],"ko":["npm과 GitHub 설정이 필요","TypeScript, ESLint, Prettier만 지원"],"es":["Requiere configuración de npm y GitHub","Soporta solo TypeScript, ESLint y Prettier"],"fr":["Nécessite une configuration de npm et GitHub","Prend en charge uniquement TypeScript, ESLint et Prettier"],"de":["Erfordert npm- und GitHub-Setup","Unterstützt nur TypeScript, ESLint und Prettier"],"pt":["Requer configuração do npm e do GitHub","Suporta apenas TypeScript, ESLint e Prettier"],"ru":["Требует настройки npm и GitHub","Поддерживает только TypeScript, ESLint и Prettier"],"ar":["يتطلب إعداد npm و GitHub","يدعم فقط TypeScript و ESLint و Prettier"]},"version":4},"contentHash":"da823419dad