INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jamesjfoong/github-pr-review-mcp/validate-code', 'validate-code', 'jamesjfoong', 'github-pr-review-mcp', 'community', 'validate-code jamesjfoong github-pr-review-mcp community The validate-code skill automates Github PR reviews for developers, ensuring code quality checks and fixing linting or type errors. It supports TypeScript, ESLint, and Prettier. 代码验证工具可以帮助开发者自动化代码检查和格式化，提高代码质量和开发效率 コード検証ツールは、開発者がコードの検証とフォーマットを自動化できるようにして、コードの品質と開発効率を向上させる 코드 검증 도구는 개발자가 코드의 검증과 형식화를 자동화할 수 있도록 해서 코드의 품질과 개발 효율성을 향상시킨다 El agente de AI ''validate-code'' es una herramienta para revisar y mejorar la calidad del código en Github, utilizando npm y TypeScript para realizar comprobaciones de tipo, linting y formato. L''agent d''IA ''validate-code'' est un outil pour examiner et améliorer la qualité du code sur Github, en utilisant npm et TypeScript pour effectuer des vérifications de type, de linting et de formatage. Der AI-Agent ''validate-code'' ist ein Werkzeug zur Überprüfung und Verbesserung der Code-Qualität auf Github, das npm und TypeScript verwendet, um Typ-, Linting- und Formatierungsprüfungen durchzuführen. O Validate-Code é uma ferramenta de Inteligência Artificial que executa verificações de tipo, lint e formatação para garantir a qualidade do código Validate-Code - это инструмент ИИ Агентов, который выполняет проверки типа, lint и форматирования для обеспечения качества кода Validate-Code هو أداة ذكاء اصطناعي تقوم بتشغيل عمليات التحقق من النوع و lint والتنسيق لضمان جودة الكود how to use validate-code validate-code setup guide Github PR review tool npm run validate validate-code vs code quality tools install validate-code what is validate-code validate-code alternative validate-code for developers 代码验证工具 AI代码检查 代码质量 自动化代码检查 代码格式化 TypeScript ESLint npm run validate npm run lint:fix npm run format Runs type-check, lint, and format-check with a single command: npm run validate Fixes linting issues with npm run lint:fix Fixes formatting issues with npm run format Supports individual checks for TypeScript, ESLint, and Prettier Re-validates code after fixes with npm run validate validate-code is a Github PR review tool that runs type-check, lint, and format-check to ensure code quality and consistency');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aiyuekuang/LLMProxy/docker', 'community', 'aiyuekuang', 'LLMProxy', 'aiyuekuang/LLMProxy', 'docker', 0, 0, 48, '2026-03-08T01:57:15.521Z', '2026-03-08T02:10:46.259Z', 'a5b8a7bb8b36a74334248ee523ec338cbe966c98f197c7dddf0bc2b342fcfcd1', '{"id":"aiyuekuang/LLMProxy/docker","name":"docker","description":{"en":"The Docker skill provides container best practices for development, building, and deployment, benefiting AI agent developers. It handles Dockerfile configuration, multi-stage builds, and container security.","zh":"Docker 技术提供了容器化的解决方案，包括多阶段构建和容器安全","ja":"Docker 技術は、コンテナ化されたソリューションを提供し、多段階ビルドとコンテナセキュリティを含む","ko":"Docker 기술은 컨테이너화된 솔루션을 제공하며, 멀티 스테이지 빌드와 컨테이너 보안을 포함","es":"Docker es una herramienta para crear, implementar y ejecutar aplicaciones en contenedores, con características como multi-stage builds y seguridad de contenedores","fr":"Docker est un outil pour créer, déployer et exécuter des applications dans des conteneurs, avec des fonctionnalités telles que les builds multi-étapes et la sécurité des conteneurs","de":"Docker ist ein Tool zum Erstellen, Bereitstellen und Ausführen von Anwendungen in Containern, mit Funktionen wie Multi-Stage-Builds und Container-Sicherheit","pt":"O Docker é uma plataforma de contêineres que permite desenvolver, construir e implantar aplicações de forma eficiente","ru":"Docker - это платформа контейнеров, которая позволяет разработать, собрать и развернуть приложения эффективно","ar":"دッカー هو منصة حاويات تتيح لك برمجة وتشغيل وحفظ التطبيقات بفعالية"},"seo":{"title":{"en":"Docker: Best Practices for AI Agents | AI Agent Skill","zh":"Docker 最佳实践指南","ja":"Docker 導入ガイド - ベストプラクティス","ko":"Docker 설정 가이드 - 컨테이너 최적화","es":"Guía de configuración de Docker para desarrolladores","fr":"Guide de mise en route de Docker pour les développeurs","de":"Docker-Setup-Leitfaden für Entwickler","pt":"Docker: Guia de Configuração e Práticas de Otimização","ru":"Docker: Настройка и Лучшие Практики для Разработки","ar":"دッカー: دليل الإعداد وأفضل الممارسات للبرمجة"},"description":{"en":"Unlock efficient containerization with Docker. Discover expert tips and best practices for building, deploying, and securing containers. Get started now!","zh":"了解 Docker 的最佳实践，包括多阶段构建、容器安全和优化","ja":"Docker のベストプラクティスを学び、効率的なコンテナ開発を実現","ko":"Docker 설정과 컨테이너 최적화를 위한 최고의 가이드","es":"Aprende a utilizar Docker de manera efectiva con nuestras mejores prácticas para desarrolladores, incluyendo Dockerfile y docker-compose","fr":"Découvrez comment utiliser Docker de manière efficace avec nos meilleures pratiques pour les développeurs, y compris Dockerfile et docker-compose","de":"Erfahren Sie, wie Sie Docker effektiv nutzen können, mit unseren Best Practices für Entwickler, einschließlich Dockerfile und docker-compose","pt":"Aprenda a configurar e otimizar o Docker para desenvolvimento, construção e implantação de contêineres com nossas dicas e práticas recomendadas","ru":"Узнайте, как настроить и оптимизировать Docker для разработки, сборки и развертывания контейнеров с нашей помощью","ar":"تعلم كيفية تهيئة وتحسين دッカー لبرمجة وتشغيل وحفظ الحاويات باستخدام نصائحنا وأفضل الممارسات"},"definition":{"en":"Docker is a containerization platform that enables efficient and secure deployment of applications, using technologies like Dockerfiles and docker-compose.","zh":"Docker 是一个容器化平台，用于构建、部署和运行应用程序","ja":"Docker は、コンテナ化されたプラットフォームであり、アプリケーションの構築、展開、実行に使用","ko":"Docker는 컨테이너화된 플랫폼으로, 애플리케이션의 빌드, 배포, 실행에 사용","es":"Docker es una plataforma de contenerización que permite a los desarrolladores crear, implementar y ejecutar aplicaciones de manera portable y segura","fr":"Docker est une plate-forme de conteneurisation qui permet aux développeurs de créer, de déployer et d''exécuter des applications de manière portable et sécurisée","de":"Docker ist eine Containerisierungsplattform, die es Entwicklern ermöglicht, Anwendungen portabel und sicher zu erstellen, bereitzustellen und auszuführen","pt":"Docker é uma tecnologia de contêineres que permite isolar aplicações e serviços em ambientes leves e portáteis","ru":"Docker - это технология контейнеров, которая позволяет изолировать приложения и сервисы в легких и переносимых средах","ar":"دッカー هو تقنية حاويات تتيح عزل التطبيقات والخدمات في بيئات خفيفة ومرنة"},"features":{"en":["Supports multi-stage builds using Dockerfiles","Optimizes container images for reduced size and improved performance","Provides intelligent load balancing and OpenAI-compatible API routing","Handles stream=false for standard JSON responses and stream=true for real-time token streaming via Server-Sent Events (SSE)","Enables zero buffering on streams for efficient data transfer","Supports container security best practices for secure deployment"],"zh":["多阶段构建","容器安全","优化容器镜像","智能负载均衡","OpenAI 兼容 API 路由"],"ja":["多段階ビルド","コンテナセキュリティ","コンテナイメージの最適化","インテリジェントな負荷分散","OpenAI 互換 API ルーティング"],"ko":["멀티 스테이지 빌드","컨테이너 보안","컨테이너 이미지 최적화","지능형 부하 분산","OpenAI 호환 API 라우팅"],"es":["Multi-stage builds para reducir el tamaño de las imágenes de contenedores","Dockerfile para definir la configuración de los contenedores","docker-compose para gestionar múltiples contenedores","Seguridad de contenedores para proteger las aplicaciones","Optimización de imágenes de contenedores para mejorar el rendimiento"],"fr":["Builds multi-étapes pour réduire la taille des images de conteneurs","Dockerfile pour définir la configuration des conteneurs","docker-compose pour gérer plusieurs conteneurs","Sécurité des conteneurs pour protéger les applications","Optimisation des images de conteneurs pour améliorer les performances"],"de":["Multi-Stage-Builds, um die Größe von Containern zu reduzieren","Dockerfile, um die Konfiguration von Containern zu definieren","docker-compose, um mehrere Container zu verwalten","Container-Sicherheit, um Anwendungen zu schützen","Optimierung von Containern, um die Leistung zu verbessern"],"pt":["Multi-stage build com suporte a linguagens como Go","Otimização de imagens de contêiner para reduzir o tamanho e melhorar a performance","Configuração de docker-compose para orquestração de contêineres","Suporte a Server-Sent Events (SSE) para streaming de tokens em tempo real","Intelligent load balancing para distribuir carga de trabalho entre contêineres"],"ru":["Мультистадийная сборка с поддержкой языков như Go","Оптимизация образов контейнеров для уменьшения размера и улучшения производительности","Настройка docker-compose для оркестровки контейнеров","Поддержка Server-Sent Events (SSE) для потоковой передачи токенов в реальном времени","Интеллектуальное балансирование нагрузки для распределения рабочей нагрузки между контейнерами"],"ar":["بناء متعدد المراحل مع دعم لغات مثل Go","تحسين صور الحاويات لتقليل الحجم وتحسين الأداء","تهيئة docker-compose لتنسيق الحاويات","دعم أحداث الخادم (SSE) لنقل الرموز في الوقت الفعلي","تحسين التوزيع الذكي للحمل لتحميل العمل بين الحاويات"]},"keywords":{"en":["how to use docker","docker best practices","docker vs containerd","docker install guide","docker setup for ai agents","dockerfile configuration","multi-stage build docker","container security docker","docker compose tutorial","docker optimization techniques"],"zh":["Docker 最佳实践","容器化技术","多阶段构建","容器安全","优化容器镜像","Docker-compose","Server-Sent Events"],"ja":["Docker 導入","コンテナ化技術","多段階ビルド","コンテナセキュリティ","コンテナイメージの最適化","Docker-compose","Server-Sent Events"],"ko":["Docker 설정","컨테이너화 기술","멀티 스테이지 빌드","컨테이너 보안","컨테이너 이미지 최적화","Docker-compose","Server-Sent Events"],"es":["Docker para desarrolladores","Guía de configuración de Docker","Mejores prácticas de Docker","Dockerfile","docker-compose","Seguridad de contenedores","Optimización de imágenes de contenedores","Desarrollo de aplicaciones con Docker"],"fr":["Docker pour les développeurs","Guide de mise en route de Docker","Meilleures pratiques de Docker","Dockerfile","docker-compose","Sécurité des conteneurs","Optimisation des images de conteneurs","Développement d''applications avec Docker"],"de":["Docker für Entwickler","Docker-Setup-Leitfaden","Best Practices für Docker","Dockerfile","docker-compose","Container-Sicherheit","Optimierung von Containern","Anwendungsentwicklung mit Docker"],"pt":["docker","contêineres","desenvolvimento de aplicações","otimização de contêineres","multi-stage build","docker-compose","Server-Sent Events","load balancing"],"ru":["docker","контейнеры","разработка приложений","оптимизация контейнеров","мультистадийная сборка","docker-compose","Server-Sent Events","балансирование нагрузки"],"ar":["دッカー","حاويات","برمجة التطبيقات","تحسين الحاويات","بناء متعدد المراحل","docker-compose","أحداث الخادم","تحسين التوزيع"]}},"owner":"aiyuekuang","repo":"LLMProxy","repoPath":"aiyuekuang/LLMProxy","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.521Z","topics":[],"category":"community","skillMd":{"name":"docker","description":"Docker and containerization best practices. Use for Dockerfile creation, docker-compose, multi-stage builds, and container optimization.","bodyPreview":"# Docker Skill\n\nContainer best practices for development, building, and deployment.\n\n## When to Use This Skill\n\n- Writing Dockerfiles\n- Configuring docker-compose\n- Optimizing container images\n- Container security\n- Multi-stage builds\n\n---\n\n# 📦 Dockerfile Best Practices\n\n## Multi-Stage Build (Go)\n\n```dockerfile\n# Build stage\nFROM golang:1.22-alpine AS builder\n\nWORKDIR /app\n\n# Cache dependencies\nCOPY go.mod go.sum ./\nRUN go mod download\n\n# Build\nCOPY . .\nRUN CGO_ENABLED=0 GOOS=linux go build -ld","body":"# Docker Skill\n\nContainer best practices for development, building, and deployment.\n\n## When to Use This Skill\n\n- Writing Dockerfiles\n- Configuring docker-compose\n- Optimizing container images\n- Container security\n- Multi-stage builds\n\n---\n\n# 📦 Dockerfile Best Practices\n\n## Multi-Stage Build (Go)\n\n```dockerfile\n# Build stage\nFROM golang:1.22-alpine AS builder\n\nWORKDIR /app\n\n# Cache dependencies\nCOPY go.mod go.sum ./\nRUN go mod download\n\n# Build\nCOPY . .\nRUN CGO_ENABLED=0 GOOS=linux go build -ldflags=\"-w -s\" -o /app/server ./cmd/main.go\n\n# Runtime stage\nFROM alpine:3.19\n\nRUN apk --no-cache add ca-certificates tzdata\n\nWORKDIR /app\n\n# Copy binary from builder\nCOPY --from=builder /app/server .\nCOPY --from=builder /app/config.yaml .\n\n# Non-root user\nRUN adduser -D -g '''' appuser\nUSER appuser\n\nEXPOSE 8080\n\nENTRYPOINT [\"./server\"]\n```\n\n## Multi-Stage Build (Node.js)\n\n```dockerfile\n# Dependencies stage\nFROM node:20-alpine AS deps\nWORKDIR /app\nCOPY package.json yarn.lock ./\nRUN yarn install --frozen-lockfile\n\n# Build stage\nFROM node:20-alpine AS builder\nWORKDIR /app\nCOPY --from=deps /app/node_modules ./node_modules\nCOPY . .\nRUN yarn build\n\n# Runtime stage\nFROM node:20-alpine AS runner\nWORKDIR /app\n\nENV NODE_ENV=production\n\nRUN addgroup -g 1001 -S nodejs\nRUN adduser -S nextjs -u 1001\n\nCOPY --from=builder /app/public ./public\nCOPY --from=builder --chown=nextjs:nodejs /app/.next/standalone ./\nCOPY --from=builder --chown=nextjs:nodejs /app/.next/static ./.next/static\n\nUSER nextjs\n\nEXPOSE 3000\nENV PORT 3000\n\nCMD [\"node\", \"server.js\"]\n```\n\n---\n\n# 🔧 Layer Optimization\n\n## Order Matters\n\n```dockerfile\n# ✅ Good: Least changing files first\nCOPY go.mod go.sum ./\nRUN go mod download\n\nCOPY . .\nRUN go build -o app\n\n# ❌ Bad: COPY all invalidates cache\nCOPY . .\nRUN go mod download\nRUN go build -o app\n```\n\n## Reduce Layers\n\n```dockerfile\n# ❌ Bad: Multiple RUN commands\nRUN apt-get update\nRUN apt-get install -y curl\nRUN apt-get install -y git\nRUN rm -rf /var/lib/apt/lists/*\n\n# ✅ Good: Single RUN command\nRUN apt-get update && \\\n    apt-get install -y --no-install-recommends \\\n        curl \\\n        git && \\\n    rm -rf /var/lib/apt/lists/*\n```\n\n## Use .dockerignore\n\n```dockerignore\n# Git\n.git\n.gitignore\n\n# Dependencies\nnode_modules\nvendor\n\n# Build artifacts\ndist\nbuild\n*.exe\n\n# Development files\n*.md\n*.log\n.env.local\n.vscode\n.idea\n\n# Tests\n*_test.go\n__tests__\ncoverage\n```\n\n---\n\n# 🐳 Docker Compose\n\n## Development Setup\n\n```yaml\nversion: ''3.8''\n\nservices:\n  app:\n    build:\n      context: .\n      dockerfile: Dockerfile.dev\n    ports:\n      - \"8080:8080\"\n    volumes:\n      - .:/app\n      - /app/node_modules  # Exclude node_modules\n    environment:\n      - DATABASE_URL=postgres://user:pass@db:5432/app\n      - REDIS_URL=redis://redis:6379\n    depends_on:\n      db:\n        condition: service_healthy\n      redis:\n        condition: service_started\n\n  db:\n    image: postgres:16-alpine\n    environment:\n      POSTGRES_USER: user\n      POSTGRES_PASSWORD: pass\n      POSTGRES_DB: app\n    volumes:\n      - postgres_data:/var/lib/postgresql/data\n    ports:\n      - \"5432:5432\"\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U user -d app\"]\n      interval: 5s\n      timeout: 5s\n      retries: 5\n\n  redis:\n    image: redis:7-alpine\n    ports:\n      - \"6379:6379\"\n    volumes:\n      - redis_data:/data\n\nvolumes:\n  postgres_data:\n  redis_data:\n```\n\n## Production Setup\n\n```yaml\nversion: ''3.8''\n\nservices:\n  app:\n    image: ${REGISTRY}/app:${VERSION}\n    deploy:\n      replicas: 3\n      resources:\n        limits:\n          cpus: ''1''\n          memory: 512M\n        reservations:\n          cpus: ''0.5''\n          memory: 256M\n      restart_policy:\n        condition: on-failure\n        delay: 5s\n        max_attempts: 3\n    environment:\n      - DATABASE_URL=${DATABASE_URL}\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:8080/health\"]\n      interval: 30s\n      timeout: 10s\n      retries: 3\n      start_period: 40s\n    logging:\n      driver: \"json-file\"\n      options:\n        max-size: \"10m\"\n        max-file: \"3\"\n\n  nginx:\n    image: nginx:alpine\n    ports:\n      - \"80:80\"\n      - \"443:443\"\n    volumes:\n      - ./nginx.conf:/etc/nginx/nginx.conf:ro\n      - ./certs:/etc/nginx/certs:ro\n    depends_on:\n      - app\n```\n\n---\n\n# 🔒 Security\n\n## Run as Non-Root\n\n```dockerfile\n# Create non-root user\nRUN addgroup -g 1001 -S appgroup && \\\n    adduser -u 1001 -S appuser -G appgroup\n\n# Change ownership\nCOPY --chown=appuser:appgroup . .\n\n# Switch to non-root user\nUSER appuser\n```\n\n## Scan for Vulnerabilities\n\n```bash\n# Using Docker Scout\ndocker scout cves myimage:latest\n\n# Using Trivy\ntrivy image myimage:latest\n\n# Using Snyk\nsnyk container test myimage:latest\n```\n\n## Read-Only Filesystem\n\n```yaml\nservices:\n  app:\n    read_only: true\n    tmpfs:\n      - /tmp\n      - /var/run\n```\n\n---\n\n# 📊 Health Checks\n\n```dockerfile\nHEALTHCHECK --interval=30s --timeout=10s --start-period=5s --retries=3 \\\n  CMD curl -f http://localhost:8080/health || exit 1\n```\n\n```go\n// Health endpoint\nfunc (h *Handler) Health(w http.ResponseWriter, r *http.Request) {\n    checks := map[string]string{\n        \"database\": h.checkDB(),\n        \"redis\":    h.checkRedis(),\n    }\n    \n    healthy := true\n    for _, status := range checks {\n        if status != \"ok\" {\n            healthy = false\n            break\n        }\n    }\n    \n    if healthy {\n        w.WriteHeader(http.StatusOK)\n    } else {\n        w.WriteHeader(http.StatusServiceUnavailable)\n    }\n    json.NewEncoder(w).Encode(checks)\n}\n```\n\n---\n\n# 🛠️ Useful Commands\n\n```bash\n# Build\ndocker build -t myapp:latest .\ndocker build --no-cache -t myapp:latest .  # Fresh build\n\n# Run\ndocker run -d -p 8080:8080 --name myapp myapp:latest\ndocker run --rm -it myapp:latest /bin/sh  # Interactive\n\n# Logs\ndocker logs -f myapp\ndocker logs --tail 100 myapp\n\n# Exec into container\ndocker exec -it myapp /bin/sh\n\n# Cleanup\ndocker system prune -a  # Remove all unused\ndocker volume prune     # Remove unused volumes\ndocker image prune      # Remove dangling images\n\n# Inspect\ndocker stats            # Resource usage\ndocker inspect myapp    # Container details\ndocker history myapp    # Image layers\n```\n\n---\n\n# 📚 References\n\n- [Docker Best Practices](https://docs.docker.com/develop/develop-images/dockerfile_best-practices/)\n- [Docker Security](https://docs.docker.com/engine/security/)\n- [dmmulroy/cloudflare-skill](https://github.com/dmmulroy/cloudflare-skill)\n"},"lastSynced":"2026-03-08T02:10:46.259Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing efficient containerization and deployment capabilities.","zh":"非常适合需要高效容器化和部署能力的DevOps Agents。","ja":"DevOps Agent が効率的なコンテナ化とデプロイ能力を必要とする場合に最適です。","ko":"효율적인 컨테이너화 및 배포 기능이 필요한 DevOps 에이전트에게 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan capacidades de contenerización y despliegue eficientes.","fr":"Parfait pour les agents DevOps ayant besoin de capacités de conteneurisation et de déploiement efficaces.","de":"Perfekt für DevOps-Agents, die effiziente Containerisierungs- und Bereitstellungsfunktionen benötigen.","pt":"Perfeito para Agentes DevOps que precisam de capacidades de containerização e implantação eficientes.","ru":"Идеально подходит для агентов DevOps, которым необходимы эффективные возможности контейнеризации и развертывания.","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى قدرات حاويات وتركيب فعال"},"recommendation":{"en":"Empowers agents to optimize container images using multi-stage builds, configure docker-compose for seamless orchestration, and enhance container security through best practices, all while leveraging Dockerfile configurations.","zh":"赋予代理优化容器镜像的能力，使用多阶段构建，配置docker-compose实现无缝编排，并通过最佳实践增强容器安全，同时利用Dockerfile配置。","ja":"エージェントに、マルチステージビルドを使用してコンテナイメージを最適化し、docker-composeを構成して無縫なオーケストレーションを行い、ベストプラクティスを通じてコンテナのセキュリティを強化し、同時にDockerfileの構成を活用する能力を与えます。","ko":"에이전트에게 다단계 빌드를 사용하여 컨테이너 이미지를 최적화하고, docker-compose를 