INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiyuekuang/LLMProxy/docker', 'docker', 'aiyuekuang', 'LLMProxy', 'community', 'docker aiyuekuang LLMProxy community The Docker skill provides container best practices for development, building, and deployment, benefiting AI agent developers. It handles Dockerfile configuration, multi-stage builds, and container security. Docker 技术提供了容器化的解决方案，包括多阶段构建和容器安全 Docker 技術は、コンテナ化されたソリューションを提供し、多段階ビルドとコンテナセキュリティを含む Docker 기술은 컨테이너화된 솔루션을 제공하며, 멀티 스테이지 빌드와 컨테이너 보안을 포함 Docker es una herramienta para crear, implementar y ejecutar aplicaciones en contenedores, con características como multi-stage builds y seguridad de contenedores Docker est un outil pour créer, déployer et exécuter des applications dans des conteneurs, avec des fonctionnalités telles que les builds multi-étapes et la sécurité des conteneurs Docker ist ein Tool zum Erstellen, Bereitstellen und Ausführen von Anwendungen in Containern, mit Funktionen wie Multi-Stage-Builds und Container-Sicherheit O Docker é uma plataforma de contêineres que permite desenvolver, construir e implantar aplicações de forma eficiente Docker - это платформа контейнеров, которая позволяет разработать, собрать и развернуть приложения эффективно دッカー هو منصة حاويات تتيح لك برمجة وتشغيل وحفظ التطبيقات بفعالية how to use docker docker best practices docker vs containerd docker install guide docker setup for ai agents dockerfile configuration multi-stage build docker container security docker docker compose tutorial docker optimization techniques Docker 最佳实践 容器化技术 多阶段构建 容器安全 优化容器镜像 Docker-compose Server-Sent Events Supports multi-stage builds using Dockerfiles Optimizes container images for reduced size and improved performance Provides intelligent load balancing and OpenAI-compatible API routing Handles stream=false for standard JSON responses and stream=true for real-time token streaming via Server-Sent Events (SSE) Enables zero buffering on streams for efficient data transfer Supports container security best practices for secure deployment Docker is a containerization platform that enables efficient and secure deployment of applications, using technologies like Dockerfiles and docker-compose.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hdkiller/coach/reka-ui', 'community', 'hdkiller', 'coach', 'hdkiller/coach', 'reka-ui', 0, 0, 48, '2026-03-08T01:57:15.563Z', '2026-03-08T02:11:38.587Z', '397474ecdb0a6ef065def617b7df53fb714c4688d84bade4c863dbc026843817', '{"id":"hdkiller/coach/reka-ui","name":"reka-ui","description":{"en":"reka-ui is an open-source AI coach and unified fitness dashboard that provides unstyled, accessible Vue 3 component primitives. It benefits developers building headless components from scratch.","zh":"Reka UI是一个开源的AI教练和统一健身仪表盘，提供WAI-ARIA兼容的Vue 3组件","ja":"Reka UIは、AIエージェントのためのオープンソースのAIコーチと統一されたフィットネスダッシュボードです","ko":"Reka UI는 오픈소스의 AI 코치와 통합된 피트니스 대시보드로, WAI-ARIA 호환 Vue 3 컴포넌트를 제공합니다","es":"reka-ui es un conjunto de componentes Vue 3 accesibles y personalizables para crear interfaces de usuario innovadoras. Incluye componentes como formularios, diálogos, menús y popovers","fr":"reka-ui est un ensemble de composants Vue 3 accessibles et personnalisables pour créer des interfaces utilisateur innovantes. Il comprend des composants tels que des formulaires, des dialogues, des menus et des popovers","de":"reka-ui ist eine Sammlung von zugänglichen und anpassbaren Vue-3-Komponenten für die Erstellung innovativer Benutzeroberflächen. Enthält Komponenten wie Formulare, Dialoge, Menüs und Popovers","pt":"O Reka UI é uma coleção de componentes Vue 3 não estilizados e acessíveis, compatíveis com WAI-ARIA. Ele fornece uma base sólida para a criação de interfaces de usuário personalizadas.","ru":"Reka UI - это коллекция нестилизованных и доступных компонентов Vue 3, соответствующих WAI-ARIA. Она предоставляет прочную основу для создания индивидуальных интерфейсов пользователя.","ar":"Reka UI هو مجموعة من المكونات Vue 3 غير المنسقة ومتوافقة مع إرشادات الويب، متوافقة مع WAI-ARIA. يوفر أساسًا قويًا لإنشاء واجهات مستخدم مخصصة"},"seo":{"title":{"en":"reka-ui: Accessible Vue 3 Component Setup Guide | AI Agen...","zh":"Reka UI Setup Guide - AIエージェント组件库","ja":"Reka UI ベストプラクティス - AIエージェントのためのVue 3 コンポーネント","ko":"Reka UI 튜토리얼 - AI 도구용 Vue 3 컴포넌트 라이브러리","es":"Guía de configuración de reka-ui para desarrolladores","fr":"Guide de mise en route de reka-ui pour les développeurs","de":"Einrichtungsleitfaden für reka-ui-Entwickler","pt":"Guia de Configuração do Reka UI: Componentes Vue 3 Acessí...","ru":"Руководство по настройке Reka UI: ИИ Агенты для доступных...","ar":"دليل إعداد Reka UI: مكونات Vue 3 المتوافقة مع إرشادات الويب"},"description":{"en":"Unlock the full potential of reka-ui with our expert guide. Learn how to implement WAI-ARIA compliant components and accessible forms with ease. Get started ...","zh":"了解Reka UI，一个开源的AI教练和统一健身仪表盘，提供WAI-ARIA兼容的Vue 3组件","ja":"Reka UIは、AIエージェントのためのオープンソースのAIコーチと統一されたフィットネスダッシュボードです。WAI-ARIA準拠のVue 3コンポーネントを提供します","ko":"Reka UI는 오픈소스의 AI 코치와 통합된 피트니스 대시보드로, WAI-ARIA 호환 Vue 3 컴포넌트를 제공합니다","es":"Aprende a utilizar reka-ui, un conjunto de componentes Vue 3 accesibles y personalizables, para crear interfaces de usuario innovadoras","fr":"Découvrez comment utiliser reka-ui, un ensemble de composants Vue 3 accessibles et personnalisables, pour créer des interfaces utilisateur innovantes","de":"Erfahren Sie, wie Sie reka-ui, eine Sammlung von zugänglichen und anpassbaren Vue-3-Komponenten, verwenden können, um innovative Benutzeroberflächen zu erste...","pt":"Aprenda a utilizar o Reka UI para criar componentes headless e acessíveis com Vue 3. Descubra como implementar formulários, diálogos e menus acessíveis.","ru":"Узнайте, как использовать Reka UI для создания головных и доступных компонентов с Vue 3. Откройте для себя, как реализовать доступные формы, диалоги и меню.","ar":"تعلم كيفية استخدام Reka UI لإنشاء مكونات headless ومتوافقة مع إرشادات الويب باستخدام Vue 3. اكتشف كيفية تنفيذ أشكال وحدائق وменوس متوافقة"},"definition":{"en":"reka-ui is an open-source library of unstyled, accessible Vue 3 component primitives that are WAI-ARIA compliant.","zh":"Reka UI是一个开源的AI教练和统一健身仪表盘","ja":"Reka UIは、AIエージェントのためのオープンソースのAIコーチと統一されたフィットネスダッシュボードです","ko":"Reka UI는 오픈소스의 AI 코치와 통합된 피트니스 대시보드입니다","es":"reka-ui es un conjunto de componentes Vue 3 accesibles y personalizables para la creación de interfaces de usuario","fr":"reka-ui est un ensemble de composants Vue 3 accessibles et personnalisables pour la création d''interfaces utilisateur","de":"reka-ui ist eine Sammlung von zugänglichen und anpassbaren Vue-3-Komponenten für die Erstellung von Benutzeroberflächen","pt":"O Reka UI é uma biblioteca de componentes Vue 3 que fornece uma base para a criação de interfaces de usuário acessíveis e personalizadas.","ru":"Reka UI - это библиотека компонентов Vue 3, которая предоставляет основу для создания доступных и индивидуальных интерфейсов пользователя.","ar":"Reka UI هو مكتبة مكونات Vue 3 توفر أساسًا لإنشاء واجهات مستخدم متوافقة مع إرشادات الويب ومخصصة"},"features":{"en":["Provides WAI-ARIA compliant components for accessible forms and dialogs","Supports building headless/unstyled components from scratch","Compatible with Nuxt UI, shadcn-vue, and other Reka-based libraries","Offers accessible menus and popovers","Available as a Vue 3 component library"],"zh":["WAI-ARIA兼容的Vue 3组件","无样式组件，适合自定义","支持Nuxt UI、shadcn-vue等Reka-based库","提供可访问的表单、对话框、菜单、弹出窗口"],"ja":["WAI-ARIA準拠のVue 3コンポーネント","スタイルのないコンポーネント、カスタマイズに適しています","Nuxt UI、shadcn-vueなどのRekaベースのライブラリをサポート","アクセス可能なフォーム、ダイアログ、メニュー、ポップオーバーを提供"],"ko":["WAI-ARIA 호환 Vue 3 컴포넌트","스타일 없는 컴포넌트, 커스터마이즈에 적합","Nuxt UI, shadcn-vue 등의 Reka 기반 라이브러리를 지원","접근 가능한 폼, 대화상자, 메뉴, 팝오버 제공"],"es":["Componentes Vue 3 accesibles y personalizables","Compatibilidad con WAI-ARIA","Incluye formularios, diálogos, menús y popovers","Integración con Nuxt UI y shadcn-vue","Compatibilidad con versiones anteriores hasta la v2.7.0"],"fr":["Composants Vue 3 accessibles et personnalisables","Compatibilité avec WAI-ARIA","Comprend des formulaires, des dialogues, des menus et des popovers","Intégration avec Nuxt UI et shadcn-vue","Compatibilité ascendante jusqu''à la v2.7.0"],"de":["Zugängliche und anpassbare Vue-3-Komponenten","Kompatibilität mit WAI-ARIA","Enthält Formulare, Dialoge, Menüs und Popovers","Integration mit Nuxt UI und shadcn-vue","Abwärtskompatibilität bis zur Version 2.7.0"],"pt":["Componentes headless e não estilizados","Compatibilidade com WAI-ARIA","Integração com Nuxt UI e shadcn-vue","Implementação de formulários, diálogos e menus acessíveis","Compatibilidade com Vue 3"],"ru":["Головные и нестилизованные компоненты","Соответствие WAI-ARIA","Интеграция с Nuxt UI и shadcn-vue","Реализация доступных форм, диалогов и меню","Совместимость с Vue 3"],"ar":["مكونات headless وغیر منسقة","التوافق مع WAI-ARIA","التكامل مع Nuxt UI وshadcn-vue","تنفيذ أشكال وحدائق وменوس متوافقة","التوافق مع Vue 3"]},"keywords":{"en":["reka-ui setup guide","how to use reka-ui","what is reka-ui","reka-ui vs radix vue","reka-ui alternative","reka-ui install","accessible vue 3 components","WAI-ARIA compliant components","reka-ui documentation"],"zh":["Reka UI","AIエージェント","Vue 3","WAI-ARIA","无样式组件","Nuxt UI","shadcn-vue","可访问的表单"],"ja":["Reka UI","AIエージェント","Vue 3","WAI-ARIA","スタイルのないコンポーネント","Nuxt UI","shadcn-vue","アクセス可能なフォーム"],"ko":["Reka UI","AI 도구","Vue 3","WAI-ARIA","스타일 없는 컴포넌트","Nuxt UI","shadcn-vue","접근 가능한 폼"],"es":["reka-ui","componentes Vue 3","accesibilidad web","WAI-ARIA","Nuxt UI","shadcn-vue","desarrollo de interfaces de usuario","herramientas de desarrollo web","frameworks de JavaScript"],"fr":["reka-ui","composants Vue 3","accessibilité web","WAI-ARIA","Nuxt UI","shadcn-vue","développement d''interfaces utilisateur","outils de développement web","frameworks JavaScript"],"de":["reka-ui","Vue-3-Komponenten","Web-Zugänglichkeit","WAI-ARIA","Nuxt UI","shadcn-vue","Entwicklung von Benutzeroberflächen","Webentwicklungstools","JavaScript-Frameworks"],"pt":["Reka UI","componentes Vue 3","acessibilidade","WAI-ARIA","Nuxt UI","shadcn-vue","formulários acessíveis","diálogos acessíveis","menus acessíveis"],"ru":["Reka UI","компоненты Vue 3","доступность","WAI-ARIA","Nuxt UI","shadcn-vue","доступные формы","доступные диалоги","доступные меню","ИИ Агенты"],"ar":["Reka UI","مكونات Vue 3","إرشادات الويب","WAI-ARIA","Nuxt UI","shadcn-vue","أشكال متوافقة","حدائق متوافقة","منوس متوافقة","أدوات الذكاء الاصطناعي"]}},"owner":"hdkiller","repo":"coach","repoPath":"hdkiller/coach","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.563Z","topics":[],"category":"community","skillMd":{"name":"reka-ui","description":"Use when building with Reka UI (headless Vue components) - provides component API, accessibility patterns, composition (asChild), controlled/uncontrolled state, virtualization, and styling integration. Formerly Radix Vue.","bodyPreview":"# Reka UI\n\nUnstyled, accessible Vue 3 component primitives. WAI-ARIA compliant. Previously Radix Vue.\n\n**Current version:** v2.7.0 (December 2025)\n\n## When to Use\n\n- Building headless/unstyled components from scratch\n- Need WAI-ARIA compliant components\n- Using Nuxt UI, shadcn-vue, or other Reka-based libraries\n- Implementing accessible forms, dialogs, menus, popovers\n\n**For Vue patterns:** use `vue` skill\n\n## Available Guidance\n\n| File                                                     | Topic","body":"# Reka UI\n\nUnstyled, accessible Vue 3 component primitives. WAI-ARIA compliant. Previously Radix Vue.\n\n**Current version:** v2.7.0 (December 2025)\n\n## When to Use\n\n- Building headless/unstyled components from scratch\n- Need WAI-ARIA compliant components\n- Using Nuxt UI, shadcn-vue, or other Reka-based libraries\n- Implementing accessible forms, dialogs, menus, popovers\n\n**For Vue patterns:** use `vue` skill\n\n## Available Guidance\n\n| File                                                     | Topics                                                              |\n| -------------------------------------------------------- | ------------------------------------------------------------------- |\n| **[references/components.md](references/components.md)** | Component index by category (Form, Date, Overlay, Menu, Data, etc.) |\n| **components/\\*.md**                                     | Per-component details (dialog.md, select.md, etc.)                  |\n\n**New guides** (see [reka-ui.com](https://reka-ui.com)): Controlled State, Inject Context, Virtualization, Migration\n\n## Usage Pattern\n\n**Load based on context:**\n\n- Component index → [references/components.md](references/components.md)\n- Specific component → [components/dialog.md](components/dialog.md), [components/select.md](components/select.md), etc.\n- For styled Nuxt components built on Reka UI → use **nuxt-ui** skill\n\n## Key Concepts\n\n| Concept                 | Description                                                           |\n| ----------------------- | --------------------------------------------------------------------- |\n| `asChild`               | Render as child element instead of wrapper, merging props/behavior    |\n| Controlled/Uncontrolled | Use `v-model` for controlled, `default*` props for uncontrolled       |\n| Parts                   | Components split into Root, Trigger, Content, Portal, etc.            |\n| `forceMount`            | Keep element in DOM for animation libraries                           |\n| Virtualization          | Optimize large lists (Combobox, Listbox, Tree) with virtual scrolling |\n| Context Injection       | Access component context from child components                        |\n\n## Installation\n\n```ts\n// nuxt.config.ts (auto-imports all components)\nexport default defineNuxtConfig({\n  modules: [''reka-ui/nuxt'']\n})\n```\n\n```ts\nimport { RekaResolver } from ''reka-ui/resolver''\n// vite.config.ts (with auto-import resolver)\nimport Components from ''unplugin-vue-components/vite''\n\nexport default defineConfig({\n  plugins: [vue(), Components({ resolvers: [RekaResolver()] })]\n})\n```\n\n## Basic Patterns\n\n```vue\n<!-- Dialog with controlled state -->\n<script setup>\n  import {\n    DialogRoot,\n    DialogTrigger,\n    DialogPortal,\n    DialogOverlay,\n    DialogContent,\n    DialogTitle,\n    DialogDescription,\n    DialogClose\n  } from ''reka-ui''\n  const open = ref(false)\n</script>\n\n<template>\n  <DialogRoot v-model:open=\"open\">\n    <DialogTrigger>Open</DialogTrigger>\n    <DialogPortal>\n      <DialogOverlay class=\"fixed inset-0 bg-black/50\" />\n      <DialogContent\n        class=\"fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 bg-white p-6 rounded\"\n      >\n        <DialogTitle>Title</DialogTitle>\n        <DialogDescription>Description</DialogDescription>\n        <DialogClose>Close</DialogClose>\n      </DialogContent>\n    </DialogPortal>\n  </DialogRoot>\n</template>\n```\n\n```vue\n<!-- Select with uncontrolled default -->\n<SelectRoot default-value=\"apple\">\n  <SelectTrigger>\n    <SelectValue placeholder=\"Pick fruit\" />\n  </SelectTrigger>\n  <SelectPortal>\n    <SelectContent>\n      <SelectViewport>\n        <SelectItem value=\"apple\"><SelectItemText>Apple</SelectItemText></SelectItem>\n        <SelectItem value=\"banana\"><SelectItemText>Banana</SelectItemText></SelectItem>\n      </SelectViewport>\n    </SelectContent>\n  </SelectPortal>\n</SelectRoot>\n```\n\n```vue\n<!-- asChild for custom trigger element -->\n<DialogTrigger as-child>\n  <button class=\"my-custom-button\">Open</button>\n</DialogTrigger>\n```\n\n## Recent Updates (v2.5.0-v2.7.0)\n\n- **New composables exposed**: `useLocale`, `useDirection` (v2.6.0)\n- **Select**: Added `disableOutsidePointerEvents` prop to Content\n- **Toast**: Added `disableSwipe` prop for swipe control\n- **DatePicker**: Added `closeOnSelect` property\n- **ContextMenu**: Added `pressOpenDelay` for long-press configuration\n- **Virtualization**: `estimateSize` now accepts function for Listbox/Tree (v2.7.0); supported in Combobox, Listbox, Tree\n\n## Resources\n\n- [Reka UI Docs](https://reka-ui.com)\n- [GitHub](https://github.com/unovue/reka-ui)\n- [Nuxt UI](https://ui.nuxt.com) (styled Reka components)\n- [shadcn-vue](https://www.shadcn-vue.com) (styled Reka components)\n\n---\n\n_Token efficiency: ~350 tokens base, components.md index ~100 tokens, per-component ~50-150 tokens_\n"},"lastSynced":"2026-03-08T02:11:38.587Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing accessible and customizable Vue 3 component primitives.","zh":"非常适合需要可访问和可定制的Vue 3组件原语的前端代理。","ja":"フロントエンドエージェントがアクセスしやすくカスタマイズ可能なVue 3コンポーネントプリミティブを必要とする場合に最適です。","ko":"접근성과 사용자 정의가 가능한 Vue 3 컴포넌트 원시 값을 필요로 하는 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan primitivas de componentes personalizables y accesibles de Vue 3.","fr":"Parfait pour les agents Frontend qui ont besoin de primitives de composants personnalisables et accessibles de Vue 3.","de":"Perfekt für Frontend-Agenten, die benutzerdefinierbare und zugängliche Vue-3-Komponentenprimitiven benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de primitivos de componentes Vue 3 acessíveis e personalizáveis.","ru":"Идеально подходит для агентов фронтенда, которым необходимы доступные и настраиваемые примитивы компонентов Vue 3.","ar":"مثالي للوكلاء الأمامي الذين يحتاجون إلى البدائيات المكونات Vue 3 القابلة للاستخدام والقابلة للتخصيص."},"recommendation":{"en":"Empowers agents to build headless components from scratch with WAI-ARIA compliant and unstyled Vue 3 components, utilizing libraries like Nuxt UI and shadcn-vue, and implementing accessible forms, dialogs, menus, and popovers.","zh":"赋予代理从头开始构建无头组件的能力，使用WAI-ARIA兼容和无样式的Vue 3组件，利用诸如Nuxt UI和shadcn-vue之类的库，并实现可访问的表单、对话框、菜单和弹出窗口。","ja":"WAI-ARIA準拠のスタイルが適用されていないVue 3コンポーネントを使用し、Nuxt UIやshadcn-vueなどのライブラリを活用して、ヘッドレスコンポーネントをスクラッチから構築できるようにエージェントに権限を与え、さらにアクセシブルなフォーム、ダイアログ、メニュー、ポップオーバーを実装します。","ko":"WAI-ARIA 호환 및 스타일이 적용되지 않은 Vue 3 컴포넌트를 사용하여 헤드리스 컴포넌트를 처음부터 구축할 수 있는 기능을 에이전트에 부여하며, Nuxt UI 및 shadcn-vue와 같은 라이브러리를 활용하여 접근성이 향상된 폼, 대화 상자, 메뉴 및 팝오버를 구현합니다.","es":"Habilita a los agentes a crear componentes headless desde cero con componentes de Vue 3 compatibles con WAI-ARIA y sin estilo, utilizando bibliotecas como Nuxt UI y shadcn-vue, e implementando formularios accesibles, diálogos, menús y popovers.","fr":"Permet aux agents de créer des composants headless à partir de zéro avec des composants Vue 3 compatibles WAI-ARIA et sans style, en utilisant des bibliothèques comme Nuxt UI et shadcn-vue, et en mettant en œuvre des formulaires accessibles, des dialogues, des menus et des popovers.","de":"Ermächtigt Agenten, Headless-Komponenten von Grund auf mit WAI-ARIA-kompatiblen und ungestylten Vue-3-Komponenten zu erstellen, indem Bibliotheken wie Nuxt UI und shadcn-vue verwendet und zugängliche Formulare, Dialoge, Menüs und Popovers implementiert werden.","pt":"Habilita os agentes a criar componentes headless do zero com componentes Vue 3 compatíveis com WAI-ARIA e sem estilo, utilizando bibliotecas como Nuxt UI e shadcn-vue, e implementando formulários acessíveis, diálogos, menus e popovers.","ru":"Наделяет агентов возможностью создавать компоненты headless с нуля с помощью компонентов Vue 3, совместимых с WAI-ARIA и не имеющих стиля, используя библиотеки như Nuxt UI и shadcn-vue, и реализуя доступные формы, диалоги, меню и поповеры.","ar":"يُمكّن الوكلاء من إنشاء مكونات رأسية من الصفر باستخدام مكونات Vue 3 المتوافقة مع WAI-ARIA وبدون نمط، باستخدام مكتبات مثل Nuxt UI و shadcn-vue، وتنفيذ نماذج يمكن الوصول إليها، وحوارات، وقوائم، وpopover."},"useCases":{"en":["Building accessible and customizable UI components for web applications","Creating headless components for reuse across multiple projects","Implementing WAI-ARIA compliant components for enhanced accessibility","Developing unified fitness dashboards with reusable component primitives"],"zh":["为Web应用程序构建可访问和可定制的UI组件","为跨多个项目重用而创建无头组件","实现WAI-ARIA兼容组件以增强可访问性","使用可重用组件原语开发统一的健身仪表盘"],"ja":["Webアプリケーションのためのアクセスしやすくカスタマイズ可能なUIコンポーネントを構築する","複数のプロジェクトで再利用するためのヘッドレスコンポーネントを作成する","アクセシビリティを高めるためのWAI-ARIA準拠コンポーネントを実装する","再利用可能なコンポーネントプリミティブを使用して統一されたフィットネスダッシュボードを開発する"],"ko":["웹 애플리케이션을 위한 접근성과 사용자 정의가 가능한 UI 컴포넌트를 구축","여러 프로젝트에서 재사용하기 위한 헤드리스 컴포넌트를 생성","접근성을 향상시키는 WAI-ARIA 호환 컴포넌트를 구현","재사용 가능한 컴포넌트 원시 값을 사용하여 통일된 피트니스 대시보드를 개발"],"es":["Crear componentes de interfaz de usuario personalizables y accesibles para aplicaciones web","Crear componentes headless para reutilizar en varios proyectos","Implementar componentes compatibles con WAI-ARIA para una mayor accesibilidad","Desarrollar paneles de fitness unificados con primitivas de componentes reutilizables"],"fr":["Créer des composants d''interface utilisateur personnalisables et accessibles pour les applications web","Créer des composants headless pour les réutiliser dans plusieurs projets","Mettre en œuvre des composants compatibles WAI-ARIA pour une meilleure accessibilité","Développer des tableaux de bord de fitness unifiés avec des primitives de composants réutilisables"],"de":["Erstellen von benutzerdefinierbaren und zugänglichen Benutzeroberflächenkomponenten für Webanwendungen","Erstellen von Headless-Komponenten zur Wiederverwendung in mehreren Projekten","Implementieren von WAI-ARIA-kompatiblen Komponenten für eine verbesserte Zugänglichkeit","Entwickeln von einheitlichen Fitness-Dashboards mit wiederverwendbaren Komponentenprimitiven"],"pt":["Construir componentes de UI acessíveis e personalizáveis para aplicações web","Criar componentes headless para reutilização em vários projetos","Implementar componentes compatíveis com WAI-ARIA para acessibilidade melhorada","Desenvolver painéis de fitness unificados com primitivos de componentes reutilizáveis"],"ru":["Создание доступных и настраиваемых компонентов UI для веб-приложений","Создание компонентов headless для повторного использования в нескольких проектах","Реализация компонентов, совместимых с WAI-ARIA, для улучшенной доступности","Разработка унифицированных панелей фитнеса с переиспользуемыми примитивами компонентов"],"ar":["بناء مكونات واجهة المستخدم القابلة للاستخدام والقابلة للتخصيص لتطبيقات الويب","إنشاء مكونات رأسية لإعادة استخدامها في مشاريع متعددة","تنفيذ مكونات متوافقة مع WAI-ARIA لتحسين إمكانية الوصول","تطوير لوحات تحكم للياقة البدنية الموحدة مع البدائيات المكونات القابلة لإعادة الاستخدام"]},"limitations":{"en":["Requires Vue 3 compatibility","Limited to building headless or unstyled components","Dependent on Reka-based libraries for full functionality"],"zh":["需要Vue 3兼容性","仅限于构建无头或无样式组件","依赖于Reka-based库以实现全部功能"],"ja":["Vue 3の互換性が必要","ヘッドレスまたはスタイルが適用されていないコンポーネントの構築のみに限定","全機能を実現するためにRekaベースのライブラリに依存"],"ko":["Vue 3 호환성이 필요","헤드리스 또는 스타일이 적용되지 않은 컴포넌트를 구축하는 것만으로 제한","전체 기능을 구현하기 위해 Reka 기반 라이브러리에 의존"],"es":["Requiere compatibilidad con Vue 3","Limitado a la creación de componentes headless o sin estilo","Dependiente de bibliotecas basadas en Reka para la funcionalidad completa"],"fr":["Nécessite la compatibilité avec Vue 3","Limité à la création de composants headless ou sans style","Dépendant de bibliothèques basées sur Reka pour la fonctionnalité complète"],"de":["Benötigt Vue-3-Kompatibilität","Begrenzt auf die Erstellung von Headless- oder ungestylten Komponenten","Abhängig von Reka-basierten Bibliotheken für die vollständige Funktionalität"],"pt":["Exige compatibilidade com Vue 3","Limitado à construção de componentes headless ou sem estilo","Dependente de bibliotecas baseadas em Reka para funcionalidade completa"],"ru":["Требует совместимости с Vue 3","Ограничен созданием компонентов headless или не имеющих стиля","Зависит от библиотек на основе Reka для полной функциональности"],"ar":["يتطلب توافقًا مع Vue 3","محدود ببناء مكونات رأسية أو بدون نمط","يعتمد على مكتبات مبنية على Reka للوظائف الكاملة"]},"version":4},"contentHash":"397474ecdb0a6ef065def617b7df53fb714c4688d84bade4c863dbc026843817","qualityScore":48}');
