INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hdkiller/coach/reka-ui', 'reka-ui', 'hdkiller', 'coach', 'community', 'reka-ui hdkiller coach community reka-ui is an open-source AI coach and unified fitness dashboard that provides unstyled, accessible Vue 3 component primitives. It benefits developers building headless components from scratch. Reka UI是一个开源的AI教练和统一健身仪表盘，提供WAI-ARIA兼容的Vue 3组件 Reka UIは、AIエージェントのためのオープンソースのAIコーチと統一されたフィットネスダッシュボードです Reka UI는 오픈소스의 AI 코치와 통합된 피트니스 대시보드로, WAI-ARIA 호환 Vue 3 컴포넌트를 제공합니다 reka-ui es un conjunto de componentes Vue 3 accesibles y personalizables para crear interfaces de usuario innovadoras. Incluye componentes como formularios, diálogos, menús y popovers reka-ui est un ensemble de composants Vue 3 accessibles et personnalisables pour créer des interfaces utilisateur innovantes. Il comprend des composants tels que des formulaires, des dialogues, des menus et des popovers reka-ui ist eine Sammlung von zugänglichen und anpassbaren Vue-3-Komponenten für die Erstellung innovativer Benutzeroberflächen. Enthält Komponenten wie Formulare, Dialoge, Menüs und Popovers O Reka UI é uma coleção de componentes Vue 3 não estilizados e acessíveis, compatíveis com WAI-ARIA. Ele fornece uma base sólida para a criação de interfaces de usuário personalizadas. Reka UI - это коллекция нестилизованных и доступных компонентов Vue 3, соответствующих WAI-ARIA. Она предоставляет прочную основу для создания индивидуальных интерфейсов пользователя. Reka UI هو مجموعة من المكونات Vue 3 غير المنسقة ومتوافقة مع إرشادات الويب، متوافقة مع WAI-ARIA. يوفر أساسًا قويًا لإنشاء واجهات مستخدم مخصصة reka-ui setup guide how to use reka-ui what is reka-ui reka-ui vs radix vue reka-ui alternative reka-ui install accessible vue 3 components WAI-ARIA compliant components reka-ui documentation Reka UI AIエージェント Vue 3 WAI-ARIA 无样式组件 Nuxt UI shadcn-vue 可访问的表单 Provides WAI-ARIA compliant components for accessible forms and dialogs Supports building headless/unstyled components from scratch Compatible with Nuxt UI, shadcn-vue, and other Reka-based libraries Offers accessible menus and popovers Available as a Vue 3 component library reka-ui is an open-source library of unstyled, accessible Vue 3 component primitives that are WAI-ARIA compliant.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sf-bcca/PromptArchitect-Studio/supabase-architect', 'community', 'sf-bcca', 'PromptArchitect-Studio', 'sf-bcca/PromptArchitect-Studio', 'supabase-architect', 0, 0, 48, '2026-03-08T01:57:15.572Z', '2026-03-08T02:11:46.114Z', '27669c7de100848f4a3e92a67d412488b0b111b96ca65877c992c9d72816d6a2', '{"id":"sf-bcca/PromptArchitect-Studio/supabase-architect","name":"supabase-architect","description":{"en":"The supabase-architect skill automates the database lifecycle for Supabase, enforcing security standards and streamlining development for AI agents and developers.","zh":"Supabase Architect 是一个自动化数据库生命周期和强制安全标准的工具，支持创建迁移和同步类型","ja":"Supabase Architect は、データベースのライフサイクルを自動化し、セキュリティ標準を強制するツールです","ko":"Supabase Architect는 데이터베이스 생명주기 자동화 및 보안 표준 적용을 지원하는 툴입니다","es":"Supabase Architect es una herramienta que automatiza el ciclo de vida de la base de datos y aplica estándares de seguridad. Crea migraciones y sincroniza tipos","fr":"Supabase Architect est un outil qui automatise le cycle de vie de la base de données et applique des normes de sécurité. Créez des migrations et synchronisez les types","de":"Supabase Architect ist ein Tool, das den Datenbanklebenszyklus automatisiert und Sicherheitsstandards anwendet. Erstellen Sie Migrationen und synchronisieren Sie Typen","pt":"O Supabase Architect é uma ferramenta que automatiza o ciclo de vida do banco de dados e impõe padrões de segurança para o Supabase.","ru":"Supabase Architect — это инструмент, который автоматизирует жизненный цикл базы данных и обеспечивает соблюдение стандартов безопасности для Supabase.","ar":"معماري Supabase هو أداة تؤتمة دورة حياة قاعدة البيانات وتنفذ معايير الأمان لمعماري Supabase."},"seo":{"title":{"en":"supabase-architect: Automate Database Lifecycle for AI Ag...","zh":"Supabase Architect 设置指南 - 自动生成迁移和同步类型","ja":"Supabase Architect のベストプラクティス - AIエージェントによる自動化","ko":"Supabase Architect 설정 가이드 - 마이그레이션 생성 및 유형 동기화","es":"Guía de configuración de Supabase Architect","fr":"Supabase Architect - Guide de mise en œuvre","de":"Supabase Architect Setup-Leitfaden","pt":"Guia de Configuração do Supabase Architect para Desenvolv...","ru":"ИИ Агент Supabase Architect: Руководство по Настройке","ar":"دليل إعداد معماري Supabase للبرمجة"},"description":{"en":"Streamline Supabase development with supabase-architect. Learn how to automate migrations, synchronize types, and audit schema for secure database management.","zh":"使用 Supabase Architect 自动生成迁移和同步类型，简化数据库管理","ja":"AIエージェントを使用して Supabase のマイグレーションとタイプの同期を自動化","ko":"Supabase Architect를 사용하여 마이그레이션 생성 및 유형 동기화를 자동화하고 데이터베이스 관리를 간소화","es":"Automatice el ciclo de vida de la base de datos y aplique estándares de seguridad con Supabase Architect. Descubra cómo","fr":"Automatisez le cycle de vie de la base de données et appliquez des normes de sécurité avec Supabase Architect. Découvrez comment","de":"Automatisieren Sie den Datenbanklebenszyklus und wenden Sie Sicherheitsstandards mit Supabase Architect an. Erfahren Sie, wie","pt":"Aprenda a criar migrações e sincronizar tipos com o Supabase Architect, uma ferramenta de automação de ciclo de vida de banco de dados","ru":"Откройте для себя, как создавать миграции и синхронизировать типы с помощью Supabase Architect, инструмента для автоматизации жизненного цикла базы данных","ar":"تعرف على كيفية إنشاء هجرات وتنظيم أنواع مع معماري Supabase، أداة آليّة لمدى حياة قاعدة البيانات"},"definition":{"en":"supabase-architect is a skill that automates Supabase database lifecycle management, providing capabilities such as migration creation and type synchronization.","zh":"Supabase Architect 是一个自动化 Supabase 数据库管理的工具","ja":"Supabase Architect は、Supabase データベースの管理を自動化する AI エージェントです","ko":"Supabase Architect는 Supabase 데이터베이스 관리를 자동화하는 툴입니다","es":"Supabase Architect es una herramienta de automatización de bases de datos que aplica estándares de seguridad","fr":"Supabase Architect est un outil d''automatisation de bases de données qui applique des normes de sécurité","de":"Supabase Architect ist ein Tool zur Automatisierung von Datenbanken, das Sicherheitsstandards anwendet","pt":"O que é Supabase Architect? É uma ferramenta de automação de ciclo de vida de banco de dados que cria migrações e sincroniza tipos","ru":"Что такое Supabase Architect? Это инструмент для автоматизации жизненного цикла базы данных, создающий миграции и синхронизирующий типы","ar":"ما هو معماري Supabase؟ هو أداة آليّة لمدى حياة قاعدة البيانات التي تنشئ هجرات وتنظيم أنواع"},"features":{"en":["Generates timestamped migrations for Supabase","Synchronizes TypeScript definitions from local Supabase instances","Audits schema for missing Row Level Security (RLS) policies","Creates new schema change files for database updates","Regenerates TypeScript definitions for type syncing","Scans migrations for security vulnerabilities"],"zh":["创建timestamped迁移","同步类型定义","扫描迁移以查找缺失的行级安全性策略","支持TypeScript定义的重新生成","自动化数据库生命周期管理","强制安全标准"],"ja":["タイムスタンプ付きマイグレーションの作成","タイプ定義の同期","マイグレーションのスキャンによる行レベルのセキュリティポリシーの欠如の検出","TypeScript 定義の再生成","データベースライフサイクルの自動化","セキュリティ標準の強制"],"ko":["타임스탬프가 있는 마이그레이션 생성","타입 정의 동기화","마이그레이션 스캔을 통해 행 수준 보안 정책 누락 검색","TypeScript 정의 재생성","데이터베이스 生命周期 자동화","보안 표준 적용"],"es":["Crea migraciones con timestamp","Sincroniza definiciones de TypeScript","Auditoría de esquema para políticas de seguridad de nivel de fila","Genera archivos de cambio de esquema","Proporciona pasos siguientes para la sincronización de tipos"],"fr":["Créez des migrations avec timestamp","Synchronisez les définitions TypeScript","Audit de schéma pour les politiques de sécurité de niveau de ligne","Générez des fichiers de modification de schéma","Fournit les étapes suivantes pour la synchronisation des types"],"de":["Erstellen Sie Migrationen mit Timestamp","Synchronisieren Sie TypeScript-Definitionen","Schema-Audit für Zeilensicherheitsrichtlinien","Erstellen Sie Schema-Änderungsdateien","Bietet nächste Schritte für die Typsynchronisierung"],"pt":["Criação de migrações com carimbo de data e hora","Sincronização de tipos com a instância local do Supabase","Análise de esquema para detectar políticas de segurança de nível de linha ausentes","Geração de definições de tipo TypeScript a partir da instância local do Supabase","Suporte à criação de arquivos de migração com timestamp"],"ru":["Создание миграций с меткой даты и времени","Синхронизация типов с локальной инстанцией Supabase","Анализ схемы для обнаружения отсутствующих политик безопасности уровня строки","Генерация определений типа TypeScript из локальной инстанции Supabase","Поддержка создания файлов миграции с меткой времени"],"ar":["إنشاء هجرات بتاريخ ووقت","تنظيم أنواع مع نسخة محلية من Supabase","فحص مخطط قاعدة البيانات لاكتشاف سياسات أمان مستوى الصفوف الناقصة","توليد تعريفات أنواع TypeScript من نسخة محلية من Supabase","دعم إنشاء ملفات هجرة بتاريخ"]},"keywords":{"en":["how to use supabase-architect","supabase-architect setup guide","supabase-architect alternative","supabase-architect vs prisma","supabase-architect install","what is supabase-architect","supabase-architect tutorial","supabase-architect documentation","supabase database management","automate supabase migrations"],"zh":["Supabase Architect","自动化数据库管理","创建迁移","同步类型","扫描迁移","强制安全标准","Supabase AI 工具","数据库生命周期管理"],"ja":["Supabase Architect","データベースの自動化","マイグレーションの作成","タイプの同期","マイグレーションのスキャン","セキュリティ標準の強制","AIエージェント","データベースライフサイクルの管理"],"ko":["Supabase Architect","데이터베이스 자동화","마이그레이션 생성","타입 동기화","마이그레이션 스캔","보안 표준 적용","AI 에이전트","데이터베이스 生命周期 관리"],"es":["Supabase Architect","automatización de bases de datos","estándares de seguridad","migraciones de bases de datos","sincronización de tipos","auditoría de esquema","Row Level Security","TypeScript","herramientas de desarrollo"],"fr":["Supabase Architect","automatisation de bases de données","normes de sécurité","migrations de bases de données","synchronisation de types","audit de schéma","Row Level Security","TypeScript","outils de développement"],"de":["Supabase Architect","Datenbankautomatisierung","Sicherheitsstandards","Datenbankmigrationen","Typsynchronisierung","Schema-Audit","Row Level Security","TypeScript","Entwicklungstools"],"pt":["Supabase Architect","automação de ciclo de vida de banco de dados","criação de migrações","sincronização de tipos","análise de esquema","segurança de nível de linha","TypeScript","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Supabase Architect","автоматизация жизненного цикла базы данных","создание миграций","синхронизация типов","анализ схемы","безопасность уровня строки","TypeScript","разработка программного обеспечения","инструменты разработки"],"ar":["معماري Supabase","آليّة مدى حياة قاعدة البيانات","إنشاء هجرات","تنظيم أنواع","فحص مخطط قاعدة البيانات","أمان مستوى الصفوف","TypeScript","برمجة","أدوات البرمجة"]}},"owner":"sf-bcca","repo":"PromptArchitect-Studio","repoPath":"sf-bcca/PromptArchitect-Studio","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.572Z","topics":[],"category":"community","skillMd":{"name":"supabase-architect","description":"Automates Supabase workflows including migrations, type synchronization, and schema security audits. Use when creating new database tables, updating schemas, or ensuring RLS compliance.","bodyPreview":"# Supabase Architect\n\nThis skill automates the database lifecycle and enforces security standards for Supabase.\n\n## Capabilities\n\n1.  **Create Migrations**: Generates timestamped migrations and provides next steps for type syncing.\n2.  **Synchronize Types**: Regenerates TypeScript definitions from the local Supabase instance.\n3.  **Audit Schema**: Scans migrations for missing Row Level Security (RLS) policies.\n\n## Usage\n\n### 1. Create a New Migration\nUse this to create a new schema change file.","body":"# Supabase Architect\n\nThis skill automates the database lifecycle and enforces security standards for Supabase.\n\n## Capabilities\n\n1.  **Create Migrations**: Generates timestamped migrations and provides next steps for type syncing.\n2.  **Synchronize Types**: Regenerates TypeScript definitions from the local Supabase instance.\n3.  **Audit Schema**: Scans migrations for missing Row Level Security (RLS) policies.\n\n## Usage\n\n### 1. Create a New Migration\nUse this to create a new schema change file.\n```bash\nnode .gemini/skills/supabase-architect/scripts/create_migration.cjs <migration_name>\n```\n\n### 2. Sync Types\nRun this after applying migrations to update your TypeScript types.\n```bash\nnode .gemini/skills/supabase-architect/scripts/sync_types.cjs\n```\n\n### 3. Audit Migrations\nRun this to check for security anti-patterns like missing RLS.\n```bash\nnode .gemini/skills/supabase-architect/scripts/audit_schema.cjs\n```\n\n## Reference\nSee [conventions.md](references/conventions.md) for project-specific SQL standards and RLS patterns.\n\n## Workflow\n1. **Plan**: Define the schema change in your task''s `plan.md`.\n2. **Create**: Run `create_migration.cjs`.\n3. **Implement**: Add SQL to the generated file in `supabase/migrations/`.\n4. **Audit**: Run `audit_schema.cjs` to verify RLS.\n5. **Apply**: Run `npx supabase db reset` (local).\n6. **Sync**: Run `sync_types.cjs` to update `types_db.ts`."},"lastSynced":"2026-03-08T02:11:46.114Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing streamlined Supabase database lifecycle management and security enforcement.","zh":"非常适合需要简化Supabase数据库生命周期管理和安全强制的AI代理。","ja":"Supabaseデータベースのライフサイクル管理とセキュリティの適用をストリームライン化する必要があるAIエージェントに最適です。","ko":"Supabase 데이터베이스 라이프사이클 관리와 보안 시행을 단순화해야 하는 AI 에이전트에게 적합합니다.","es":"Perfecto para Agentes de IA que necesitan una gestión de ciclo de vida de base de datos Supabase optimizada y aplicación de seguridad.","fr":"Parfait pour les Agents IA nécessitant une gestion du cycle de vie de la base de données Supabase rationalisée et une application de sécurité.","de":"Perfekt für KI-Agents, die eine optimierte Verwaltung des Supabase-Datenbanklebenszyklus und Sicherheitsdurchsetzung benötigen.","pt":"Perfeito para Agentes de IA que necessitam de gerenciamento de ciclo de vida de banco de dados Supabase e aplicação de segurança simplificados.","ru":"Идеально для агентов ИИ, которым необходим упрощенный менеджмент жизненного цикла базы данных Supabase и принудительное обеспечение безопасности.","ar":"مثالي لعمليات الوكيل الإصطناعي التي تحتاج إلى إدارة دورة حياة قاعدة بيانات Supabase ومحاكمة الأمن المبسطة."},"recommendation":{"en":"Empowers agents to automate database migrations, synchronize types, and audit schema for Row Level Security (RLS) policies, ensuring a secure and efficient Supabase development process using timestamped migrations and TypeScript definitions.","zh":"赋予代理自动化数据库迁移、同步类型和审计模式以应用行级安全（RLS）策略，确保使用时间戳迁移和TypeScript定义的安全高效的Supabase开发过程。","ja":"エージェントにデータベースの移行を自動化し、タイプを同期し、行レベルのセキュリティ（RLS）ポリシーを適用するためのスキーマを監査する機能を提供し、タイムスタンプによる移行とTypeScript定義を使用した安全で効率的なSupabase開発プロセスを保証します。","ko":"에이전트가 데이터베이스 마이그레이션을 자동화하고, 타입을 동기화하고, 행 수준 보안(RLS) 정책을 적용하기 위한 스키마를 감사하여 타임스탬프 마이그레이션과 TypeScript 정의를 사용한 보안하고 효율적인 Supabase 개발 프로세스를 보장합니다.","es":"Habilita a los agentes a automatizar las migraciones de la base de datos, sincronizar tipos y auditar el esquema para las políticas de seguridad de nivel de fila (RLS), garantizando un proceso de desarrollo de Supabase seguro y eficiente utilizando migraciones con marca de tiempo y definiciones de TypeScript.","fr":"Permet aux agents d''automatiser les migrations de base de données, de synchroniser les types et d''auditer le schéma pour les stratégies de sécurité au niveau des lignes (RLS), garantissant un processus de développement Supabase sécurisé et efficace à l''aide de migrations avec horodatage et de définitions TypeScript.","de":"Ermöglicht es den Agents, Datenbankmigrationen zu automatisieren, Typen zu synchronisieren und das Schema für Zeilenberechtigungssicherheitsrichtlinien (RLS) zu überprüfen, um so einen sicheren und effizienten Supabase-Entwicklungsprozess unter Verwendung von Timestamp-Migrationen und TypeScript-Definitionen zu gewährleisten.","pt":"Habilita os agentes a automatizar migrações de banco de dados, sincronizar tipos e auditar esquema para políticas de Segurança de Nível de Linha (RLS), garantindo um processo de desenvolvimento Supabase seguro e eficiente usando migrações com carimbo de data/hora e definições TypeScript.","ru":"Наделяет агентов возможностью автоматизировать миграции базы данных, синхронизировать типы и аудировать схему для политик Безопасности на уровне строк (RLS), обеспечивая безопасный и эффективный процесс разработки на Supabase с использованием миграций с меткой времени и определений TypeScript.","ar":"تمكّن الوكلاء من توفير آلي لمهاجرات قاعدة البيانات ومزامنة الأنواع ومراجعة مخطط للسياسات أمنية على مستوى الصف (RLS) ، مما يضمن عملية تطوير Supabase آمنة وفعالة باستخدام مهاجرات ذات علامات زمنية وتعريفات TypeScript."},"useCases":{"en":["Automating Supabase database migrations with generated timestamped files","Synchronizing TypeScript definitions from local Supabase instances","Auditing schema for missing Row Level Security (RLS) policies"],"zh":["使用生成的时间戳文件自动化Supabase数据库迁移","从本地Supabase实例同步TypeScript定义","审计模式以查找缺失的行级安全(RLS)策略"],"ja":["生成されたタイムスタンプファイルを使用してSupabaseデータベースの移行を自動化する","ローカルのSupabaseインスタンスからTypeScript定義を同期する","行レベルのセキュリティ（RLS）ポリシーが欠けているスキーマを監査する"],"ko":["생성된 타임스탬프 파일을 사용하여 Supabase 데이터베이스 마이그레이션 자동화","로컬 Supabase 인스턴스에서 TypeScript 정의 동기화","행 수준 보안(RLS) 정책이 누락된 스키마 감사"],"es":["Automatización de migraciones de la base de datos Supabase con archivos con marca de tiempo generados","Sincronización de definiciones de TypeScript desde instancias locales de Supabase","Auditoría del esquema para políticas de seguridad de nivel de fila (RLS) que faltan"],"fr":["Automatisation des migrations de base de données Supabase avec des fichiers horodatés générés","Synchronisation des définitions TypeScript à partir d''instances locales Supabase","Audit du schéma pour les stratégies de sécurité au niveau des lignes (RLS) manquantes"],"de":["Automatisierung von Supabase-Datenbankmigrationen mit generierten Timestamp-Dateien","Synchronisierung von TypeScript-Definitionen von lokalen Supabase-Instanzen","Überprüfung des Schemas auf fehlende Zeilenberechtigungssicherheitsrichtlinien (RLS)"],"pt":["Automatizar mhaigrates de banco de dados Supabase com arquivos carimbados com data/hora","Sincronizar definições TypeScript de instâncias Supabase locais","Auditar esquema para políticas de Segurança de Nível de Linha (RLS) faltantes"],"ru":["Автоматизация миграций базы данных Supabase с использованием файлов с меткой времени","Синхронизация определений TypeScript из локальных экземпляров Supabase","Аудит схемы для отсутствующих политик Безопасности на уровне строк (RLS)"],"ar":["توفير آلي لمهاجرات قاعدة بيانات Supabase مع ملفات محددة زمنيا","مزامنة تعريفات TypeScript من مثيلات Supabase المحلية","مراجعة مخطط لقواعد الأمان على مستوى الصف (RLS) المفقودة"]},"limitations":{"en":["Requires Supabase instance access","Limited to Supabase database management","Dependent on TypeScript for type syncing"],"zh":["需要Supabase实例访问","仅限于Supabase数据库管理","依赖TypeScript进行类型同步"],"ja":["Supabaseインスタンスへのアクセスが必要","Supabaseデータベース管理のみに限定される","タイプの同期にTypeScriptに依存する"],"ko":["Supabase 인스턴스 액세스가 필요함","Supabase 데이터베이스 관리에만限定됨","타입 동기화에 TypeScript에 의존"],"es":["Requiere acceso a la instancia de Supabase","Limitado a la gestión de la base de datos Supabase","Dependiente de TypeScript para la sincronización de tipos"],"fr":["Nécessite un accès à l''instance Supabase","Limité à la gestion de la base de données Supabase","Dépendant de TypeScript pour la synchronisation des types"],"de":["Erfordert Zugriff auf die Supabase-Instanz","Begrenzt auf die Verwaltung der Supabase-Datenbank","Abhängig von TypeScript für die Typsynchronisierung"],"pt":["Exige acesso à instância Supabase","Limitado ao gerenciamento de banco de dados Supabase","Dependente do TypeScript para sincronização de tipos"],"ru":["Требует доступа к экземпляру Supabase","Ограничен менеджментом базы данных Supabase","Зависит от TypeScript для синхронизации типов"],"ar":["يتطلب الوصول إلى مثيل Supabase","محدود بإدارة قاعدة بيانات Supabase","يعتمد على TypeScript لمزامنة الأنواع"]},"version":4},"contentHash":"27669c7de100848f4a3e92a67d412488b0b111b96ca65877c992c9d72816d6a2","qualityScore":48}');
