INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sf-bcca/PromptArchitect-Studio/supabase-architect', 'supabase-architect', 'sf-bcca', 'PromptArchitect-Studio', 'community', 'supabase-architect sf-bcca PromptArchitect-Studio community The supabase-architect skill automates the database lifecycle for Supabase, enforcing security standards and streamlining development for AI agents and developers. Supabase Architect 是一个自动化数据库生命周期和强制安全标准的工具，支持创建迁移和同步类型 Supabase Architect は、データベースのライフサイクルを自動化し、セキュリティ標準を強制するツールです Supabase Architect는 데이터베이스 생명주기 자동화 및 보안 표준 적용을 지원하는 툴입니다 Supabase Architect es una herramienta que automatiza el ciclo de vida de la base de datos y aplica estándares de seguridad. Crea migraciones y sincroniza tipos Supabase Architect est un outil qui automatise le cycle de vie de la base de données et applique des normes de sécurité. Créez des migrations et synchronisez les types Supabase Architect ist ein Tool, das den Datenbanklebenszyklus automatisiert und Sicherheitsstandards anwendet. Erstellen Sie Migrationen und synchronisieren Sie Typen O Supabase Architect é uma ferramenta que automatiza o ciclo de vida do banco de dados e impõe padrões de segurança para o Supabase. Supabase Architect — это инструмент, который автоматизирует жизненный цикл базы данных и обеспечивает соблюдение стандартов безопасности для Supabase. معماري Supabase هو أداة تؤتمة دورة حياة قاعدة البيانات وتنفذ معايير الأمان لمعماري Supabase. how to use supabase-architect supabase-architect setup guide supabase-architect alternative supabase-architect vs prisma supabase-architect install what is supabase-architect supabase-architect tutorial supabase-architect documentation supabase database management automate supabase migrations Supabase Architect 自动化数据库管理 创建迁移 同步类型 扫描迁移 强制安全标准 Supabase AI 工具 数据库生命周期管理 Generates timestamped migrations for Supabase Synchronizes TypeScript definitions from local Supabase instances Audits schema for missing Row Level Security (RLS) policies Creates new schema change files for database updates Regenerates TypeScript definitions for type syncing Scans migrations for security vulnerabilities supabase-architect is a skill that automates Supabase database lifecycle management, providing capabilities such as migration creation and type synchronization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('k2works/case-study-accounting/killing-processes', 'community', 'k2works', 'case-study-accounting', 'k2works/case-study-accounting', 'killing-processes', 0, 0, 48, '2026-03-08T01:57:15.580Z', '2026-03-08T02:11:52.505Z', '37fb6dc03e6b2bc8ea5507ff80e729eea6aa2393d8fa00763e713a424cee129c', '{"id":"k2works/case-study-accounting/killing-processes","name":"killing-processes","description":{"en":"The killing-processes skill allows developers to forcefully terminate development processes, including Node.js servers, across multiple ports. It benefits developers working with development servers and Node.js applications.","zh":"杀死进程技能可以强制终止开发服务器和Node.js进程，支持一括终了和特定端口终了","ja":"プロセス終了スキルは開発サーバーとNode.jsプロセスを強制終了できます","ko":"프로세스 종료 스킬은 개발 서버와 Node.js 프로세스를 강제 종료할 수 있습니다","es":"La habilidad de matar procesos permite terminar Node.js y servidores de desarrollo de manera efectiva. Puede utilizar opciones como --port y --check para personalizar el proceso.","fr":"La compétence de tuer les processus permet de terminer les serveurs de développement Node.js et les processus de développement de manière efficace. Vous pouvez utiliser des options telles que --port et --check pour personnaliser le processus.","de":"Die Fähigkeit zum Beenden von Prozessen ermöglicht es, Node.js- und Entwicklungsprozesse effektiv zu beenden. Sie können Optionen wie --port und --check verwenden, um den Prozess anzupassen.","pt":"O killing-processes é uma habilidade que permite terminar processos de desenvolvimento Node.js e servidores de desenvolvimento de forma eficaz","ru":"ИИ Агент killing-processes - это навык, который позволяет прекратить процессы разработки Node.js и серверы разработки эффективно","ar":"مُضيف killing-processes هو مهارة تسمح بإنهاء عمليات التطوير Node.js والخادم التطويري بفعالية"},"seo":{"title":{"en":"killing-processes: Force Qui