INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('k2works/case-study-accounting/killing-processes', 'killing-processes', 'k2works', 'case-study-accounting', 'community', 'killing-processes k2works case-study-accounting community The killing-processes skill allows developers to forcefully terminate development processes, including Node.js servers, across multiple ports. It benefits developers working with development servers and Node.js applications. 杀死进程技能可以强制终止开发服务器和Node.js进程，支持一括终了和特定端口终了 プロセス終了スキルは開発サーバーとNode.jsプロセスを強制終了できます 프로세스 종료 스킬은 개발 서버와 Node.js 프로세스를 강제 종료할 수 있습니다 La habilidad de matar procesos permite terminar Node.js y servidores de desarrollo de manera efectiva. Puede utilizar opciones como --port y --check para personalizar el proceso. La compétence de tuer les processus permet de terminer les serveurs de développement Node.js et les processus de développement de manière efficace. Vous pouvez utiliser des options telles que --port et --check pour personnaliser le processus. Die Fähigkeit zum Beenden von Prozessen ermöglicht es, Node.js- und Entwicklungsprozesse effektiv zu beenden. Sie können Optionen wie --port und --check verwenden, um den Prozess anzupassen. O killing-processes é uma habilidade que permite terminar processos de desenvolvimento Node.js e servidores de desenvolvimento de forma eficaz ИИ Агент killing-processes - это навык, который позволяет прекратить процессы разработки Node.js и серверы разработки эффективно مُضيف killing-processes هو مهارة تسمح بإنهاء عمليات التطوير Node.js والخادم التطويري بفعالية how to use killing-processes killing-processes alternative killing-processes setup guide what is killing-processes killing-processes vs taskkill killing-processes install node.js process termination development process management 杀死进程 开发服务器 Node.js进程 强制终止 一括终了 特定端口终了 CLI命令行 Windows环境 AIエージェント 开发工具 Forcefully terminates all Node.js development processes Supports termination of specific processes by port number using --port option Allows for process status checking without termination using --check option Enables bulk termination of development processes in Windows environments Supports termination of processes across multiple ports killing-processes is a skill that enables forced termination of development processes, including Node.js servers, to efficiently manage and stop development environments.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('monarch-initiative/dismech/dismech-terms', 'community', 'monarch-initiative', 'dismech', 'monarch-initiative/dismech', 'dismech-terms', 0, 0, 48, '2026-03-08T01:57:15.615Z', '2026-03-08T02:13:19.694Z', 'e63b1a790291363cc65d9ff3facd4a5d64e3547037376e7b65b6d01b9c14ecf1', '{"id":"monarch-initiative/dismech/dismech-terms","name":"dismech-terms","description":{"en":"The dismech-terms skill enables the addition and validation of ontology term references in the Disease Mechanisms KB, ensuring accurate linking of entities to authoritative terms. This benefits developers and researchers working with disease mechanisms data.","zh":"Dismech-Terms是一个用于验证和标准化ontology term的AIエージェント，支持HP和CL等多个ontology","ja":"Dismech-Termsは、オントロジー用語の検証と標準化を実現するAIエージェントです。HPやCLなどの複数のオントロジーをサポートしています","ko":"Dismech-Terms는 온톨로지 용어의 검증과 표준화를 구현하는 인공지능 에이전트입니다. HP와 CL 등의 여러 온톨로지를 지원합니다","es":"dismech-terms es una habilidad que agrega y valida referencias de términos de ontología en la base de conocimiento de trastornos dismech, utilizando ontologías como HP y CL","fr":"dismech-terms est une compétence qui ajoute et valide des références de termes d''ontologie dans la base de connaissances des troubles dismech, en utilisant des ontologies comme HP et CL","de":"dismech-terms ist eine Fähigkeit, die Referenzen von Ontologie-Terms in der dismech-Störungs-Knowledge-Base hinzufügt und validiert, unter Verwendung von Ontologien wie HP und CL","pt":"Dismech-Terms é uma habilidade que adiciona e valida referências de termos de ontologia no conhecimento de distúrbios de doenças, garantindo a ligação correta de fenótipos, tipos de células e processos biológicos.","ru":"Dismech-Terms — это навык, который добавляет и проверяет ссылки на термины онтологии в базе знаний о расстройствах заболеваний, обеспечивая правильную связь фенотипов, типов клеток и биологических процессов.","ar":"Dismech-Terms هو مهارة تضيف وتحقق من المراجع المصطلحية لتنميط الأمراض في قاعدة المعرفة، مما يضمن ربط الفينوتايب وأنواع الخلايا والعمليات البيولوجية بشكل صحيح."},"seo":{"title":{"en":"dismech-terms: Ontology Term Validation for AI Agents | D...","zh":"Dismech-Terms Setup Guide - AIエージェント for Ontology Term Va...","ja":"Dismech-Terms ベストプラクティス - AIエージェントによるオントロジー用語の検証","ko":"Dismech-Terms 구축 가이드 - 인공지능 에이전트를 통한 온톨로지 용어 검증","es":"Guía de Configuración de dismech-terms para Ontologías de...","fr":"Guide de Configuration de dismech-terms pour les Ontologi...","de":"Konfigurationsleitfaden für dismech-terms zur Erkrankungs...","pt":"Guia de Configuração do Dismech-Terms para Ontologia de D...","ru":"Руководство по настройке Dismech-Terms для онтологии забо...","ar":"دليل إعداد Dismech-Terms لتنميط الأمراض باستخدام أدوات ال..."},"description":{"en":"Unlock accurate disease mechanism insights with dismech-terms. Learn how to add and validate ontology terms for phenotypes, cell types, and biological proces...","zh":"了解Dismech-Terms的功能和特点，实现ontology term的验证和标准化，提升开发效率","ja":"Dismech-Termsの機能と特徴を紹介。オントロジー用語の検証と標準化を実現し、開発効率を向上させる","ko":"Dismech-Terms의 기능과 특징을 살펴보세요. 온톨로지 용어의 검증과 표준화를 구현하여 개발 효율성을 높여보세요","es":"Aprende a configurar dismech-terms para agregar y validar referencias de términos de ontología en la base de conocimiento de trastornos dismech","fr":"Découvrez comment configurer dismech-terms pour ajouter et valider des références de termes d''ontologie dans la base de connaissances des troubles dismech","de":"Erfahren Sie, wie Sie dismech-terms konfigurieren, um Referenzen von Ontologie-Terms in der dismech-Störungs-Knowledge-Base hinzuzufügen und zu validieren","pt":"Aprenda a configurar e validar referências de termos de ontologia no conhecimento de distúrbios de doenças com Dismech-Terms","ru":"Узнайте, как настроить и проверить ссылки на термины онтологии в базе знаний о расстройствах заболеваний с помощью Dismech-Terms и ИИ Агенты","ar":"تعرف على كيفية إعداد وتحقق من المراجع المصطلحية لتنميط الأمراض في قاعدة المعرفة باستخدام Dismech-Terms وأدوات الذكاء الاصطناعي"},"definition":{"en":"dismech-terms is a skill that validates ontology term references for disease mechanisms, using ontologies like Human Phenotype Ontology (HP) and Cell Ontology (CL).","zh":"Dismech-Terms是用于验证和标准化ontology term的AIエージェント，确保phenotypes、cell types、biological processes等实体正确链接到权威的ontology term","ja":"Dismech-Termsは、オントロジー用語の検証と標準化を実現するAIエージェントです。phenotypes、cell types、biological processesなどの実体を正確にオントロジー用語にリンクします","ko":"Dismech-Terms는 온톨로지 용어의 검증과 표준화를 구현하는 인공지능 에이전트입니다. phenotypes, cell types, biological processes 등의实体를 정확히 온톨로지 용어에 연결합니다","es":"dismech-terms es una habilidad de AI que utiliza ontologías para agregar y validar términos en la base de conocimiento de trastornos dismech","fr":"dismech-terms est une compétence d''IA qui utilise des ontologies pour ajouter et valider des termes dans la base de connaissances des troubles dismech","de":"dismech-terms ist eine KI-Fähigkeit, die Ontologien verwendet, um Terme in der dismech-Störungs-Knowledge-Base hinzuzufügen und zu validieren","pt":"Dismech-Terms é uma habilidade de ontologia que vincula entidades biológicas a termos autorizados","ru":"Dismech-Terms — это онтологический навык, который связывает биологические сущности с авторитетными терминами","ar":"Dismech-Terms هو مهارة منتمية إلى علم التصنيف التي تربط الكائنات البيولوجية بالمراجع المعتمدة"},"features":{"en":["Adds phenotype_term to phenotype entries using Human Phenotype Ontology (HP)","Validates term references for cell_types entries using Cell Ontology (CL)","Links biological_processes entries to authoritative ontology terms","Ensures correct IDs and labels for ontology terms","Supports integration with the dismech disorder knowledge base"],"zh":["支持HP和CL等多个ontology","验证和标准化ontology term","确保phenotypes、cell types、biological processes等实体正确链接到权威的ontology term","使用Python和CLI等技术实现","适用于开发者和研究人员"],"ja":["HPやCLなどの複数のオントロジーをサポート","オントロジー用語の検証と標準化","phenotypes、cell types、biological processesなどの実体を正確にオントロジー用語にリンク","PythonとCLIなどの技術を使用","開発者と研究者向け"],"ko":["HP와 CL 등의 여러 온톨로지를 지원","온톨로지 용어의 검증과 표준화","phenotypes, cell types, biological processes 등의实体를 정확히 온톨로지 용어에 연결","Python과 CLI 등의 기술을 사용","개발자와 연구자를 위한 기능"],"es":["Adición de términos de fenotipo utilizando la ontología HP","Adición de términos de tipos de células utilizando la ontología CL","Validación de referencias de términos de ontología","Integración con la base de conocimiento de trastornos dismech","Soporte para términos de procesos biológicos","Uso de identificadores y etiquetas correctas para los términos de ontología"],"fr":["Ajout de termes de phénotype en utilisant l''ontologie HP","Ajout de termes de types de cellules en utilisant l''ontologie CL","Validation des références de termes d''ontologie","Intégration avec la base de connaissances des troubles dismech","Prise en charge des termes de processus biologiques","Utilisation d''identificateurs et d''étiquettes corrects pour les termes d''ontologie"],"de":["Hinzufügen von Phänotyp-Terms unter Verwendung der Ontologie HP","Hinzufügen von Zelltyp-Terms unter Verwendung der Ontologie CL","Validierung von Referenzen von Ontologie-Terms","Integration mit der dismech-Störungs-Knowledge-Base","Unterstützung für biologische Prozess-Terme","Verwendung von korrekten Identifiern und Labels für Ontologie-Terme"],"pt":["Adiciona referências de termos de ontologia para fenótipos usando HP (Human Phenotype Ontology)","Valida termos para tipos de células usando CL (Cell Ontology)","Suporta a adição de termos para processos biológicos","Garante a ligação correta de entidades biológicas a termos autorizados","Usa IDs e rótulos corretos para termos de ontologia"],"ru":["Добавляет ссылки на термины онтологии для фенотипов с использованием HP (Human Phenotype Ontology)","Проверяет термины для типов клеток с использованием CL (Cell Ontology)","Поддерживает добавление терминов для биологических процессов","Обеспечивает правильную связь биологических сущностей с авторитетными терминами","Использует правильные идентификаторы и метки для терминов онтологии"],"ar":["تضيف مراجع مصطلحية لتنميط الفينوتايب باستخدام HP (Human Phenotype Ontology)","تحقق من المصطلحات لأنواع الخلايا باستخدام CL (Cell Ontology)","تدعم إضافة المصطلحات للعمليات البيولوجية","تضمن ربط الكائنات البيولوجية بالمراجع المعتمدة بشكل صحيح","تستخدم المعرفات والتعليمات الصحيحة للمصطلحات المصطلحية"]},"keywords":{"en":["how to use dismech-terms","dismech-terms setup guide","ontology term validation","disease mechanisms knowledge base","Human Phenotype Ontology","Cell Ontology","dismech-terms install","dismech-terms alternative","dismech-terms vs other ontology tools"],"zh":["Dismech-Terms","AIエージェント","ontology term","HP","CL","phenotypes","cell types","biological processes","Python","CLI"],"ja":["Dismech-Terms","AIエージェント","オントロジー用語","HP","CL","phenotypes","cell types","biological processes","Python","CLI"],"ko":["Dismech-Terms","인공지능 에이전트","온톨로지 용어","HP","CL","phenotypes","cell types","biological processes","Python","CLI"],"es":["dismech-terms","ontologías de enfermedades","base de conocimiento de trastornos dismech","términos de fenotipo","términos de tipos de células","procesos biológicos","ontología HP","ontología CL","herramientas de AI para la salud"],"fr":["dismech-terms","ontologies de maladies","base de connaissances des troubles dismech","termes de phénotype","termes de types de cellules","processus biologiques","ontologie HP","ontologie CL","outils d''IA pour la santé"],"de":["dismech-terms","Erkrankungsontologien","dismech-Störungs-Knowledge-Base","Phänotyp-Terme","Zelltyp-Terme","biologische Prozesse","Ontologie HP","Ontologie CL","KI-Tools für die Gesundheit"],"pt":["Dismech-Terms","ontologia de doenças","fenótipos","tipos de células","processos biológicos","HP","CL","ontologia","desenvolvimento de habilidades"],"ru":["Dismech-Terms","онтология заболеваний","фенотипы","типы клеток","биологические процессы","HP","CL","онтология","разработка навыков","ИИ Агенты"],"ar":["Dismech-Terms","تنميط الأمراض","الفينوتايب","أنواع الخلايا","العمليات البيولوجية","HP","CL","التنميط","تطوير المهارات","أدوات الذكاء الاصطناعي"]}},"owner":"monarch-initiative","repo":"dismech","repoPath":"monarch-initiative/dismech","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.615Z","topics":[],"category":"community","skillMd":{"name":"dismech-terms","description":">","bodyPreview":"# Dismech Ontology Terms Skill\n\n## Overview\n\nAdd and validate ontology term references in the dismech disorder knowledge base. This ensures\nphenotypes, cell types, biological processes, and other entities are properly linked to\nauthoritative ontology terms with correct IDs and labels.\n\n## When to Use\n\n- Adding `phenotype_term` to phenotype entries (uses HP - Human Phenotype Ontology)\n- Adding `term` to `cell_types` entries (uses CL - Cell Ontology)\n- Adding `term` to `biological_processes` entri","body":"# Dismech Ontology Terms Skill\n\n## Overview\n\nAdd and validate ontology term references in the dismech disorder knowledge base. This ensures\nphenotypes, cell types, biological processes, and other entities are properly linked to\nauthoritative ontology terms with correct IDs and labels.\n\n## When to Use\n\n- Adding `phenotype_term` to phenotype entries (uses HP - Human Phenotype Ontology)\n- Adding `term` to `cell_types` entries (uses CL - Cell Ontology)\n- Adding `term` to `biological_processes` entries (uses GO - Gene Ontology)\n- Adding `disease_term` to disease entries (uses MONDO)\n- Validating existing ontology term references\n- Fixing label mismatches between preferred_term and ontology labels\n\n## Term Object Structure\n\nAll term references follow this YAML structure:\n\n```yaml\n# For phenotypes:\nphenotype_term:\n  preferred_term: <Human readable name>\n  term:\n    id: HP:XXXXXXX\n    label: <Exact HP label from ontology>\n\n# For cell types:\ncell_types:\n- preferred_term: <Human readable name>\n  term:\n    id: CL:XXXXXXX\n    label: <Exact CL label from ontology>\n\n# For biological processes:\nbiological_processes:\n- preferred_term: <Human readable name>\n  term:\n    id: GO:XXXXXXX\n    label: <Exact GO label from ontology>\n```\n\n## Ontology Lookup with OAK\n\nUse the Ontology Access Kit (OAK) to look up terms:\n\n### Exact Match\n```bash\nuv run runoak -i sqlite:obo:hp info \"seizure\"\n# Returns: HP:0001250 ! Seizure\n```\n\n### Fuzzy Search\n```bash\nuv run runoak -i sqlite:obo:hp info \"l~cognitive impairment\"\n# Returns multiple matches - select the most appropriate\n```\n\n### Get Full Term Details\n```bash\nuv run runoak -i sqlite:obo:cl info CL:0000540 -O obo\n# Returns complete term information including definition\n```\n\n### Common Ontology Prefixes\n| Ontology | Prefix | Adapter | Use For |\n|----------|--------|---------|---------|\n| Human Phenotype | HP | sqlite:obo:hp | phenotype_term |\n| Cell Ontology | CL | sqlite:obo:cl | cell_types |\n| Gene Ontology | GO | sqlite:obo:go | biological_processes |\n| MONDO Disease | MONDO | sqlite:obo:mondo | disease_term |\n| Uberon Anatomy | UBERON | sqlite:obo:uberon | anatomical locations |\n\n## Specificity Guidelines\n\n**Critical**: Always use the most specific term that accurately describes the entity:\n\n| Incorrect (too general) | Correct (specific) |\n|------------------------|-------------------|\n| CL:0000066 epithelial cell | CL:0002202 epithelial cell of tracheobronchial tree |\n| HP:0000001 All | HP:0001250 Seizure |\n| CL:0000000 cell | CL:0000540 neuron |\n\nWhen a fuzzy search returns multiple results:\n1. Review all candidates\n2. Check term definitions with `-O obo` flag\n3. Select the term that most precisely matches the biological context\n4. If no specific term exists, use the closest parent but note the limitation\n\n## Validation\n\nAfter adding terms, validate with:\n\n```bash\njust validate-terms\n```\n\nThis checks:\n- Term IDs exist in the ontology\n- Labels match the canonical ontology labels exactly\n- Required fields are present\n\n### Fixing Label Mismatches\n\nIf validation reports a label mismatch:\n```\nLABEL MISMATCH: Cholera.yaml\n  Term: HP:0003394\n  Expected: Muscle cramps\n  Actual: Muscle spasm\n```\n\nUpdate the `label` field to match the ontology''s canonical label exactly.\n\n## Batch Processing\n\nTo find entries missing term annotations:\n\n```python\nimport yaml\nimport glob\n\nfor f in glob.glob(\"kb/disorders/*.yaml\"):\n    with open(f) as file:\n        data = yaml.safe_load(file)\n    for pheno in data.get(''phenotypes'', []):\n        if ''phenotype_term'' not in pheno:\n            print(f\"{f}: {pheno.get(''name'')} - missing phenotype_term\")\n```\n\n## Common Patterns\n\n### Adding HPO to a Phenotype\n1. Look up term: `uv run runoak -i sqlite:obo:hp info \"l~<phenotype name>\"`\n2. Verify specificity: `uv run runoak -i sqlite:obo:hp info <HP:ID> -O obo`\n3. Add to YAML:\n   ```yaml\n   phenotype_term:\n     preferred_term: <Original Name>\n     term:\n       id: <HP:ID>\n       label: <Exact label from OAK>\n   ```\n4. Validate: `just validate-terms`\n\n### Adding CL to Cell Types\n1. Look up term: `uv run runoak -i sqlite:obo:cl info \"l~<cell type>\"`\n2. Verify specificity\n3. Add `term:` block under the cell_type entry\n4. Validate\n"},"lastSynced":"2026-03-08T02:13:19.694Z","agentAnalysis":{"suitability":{"en":"Perfect for Biomedical Agents needing precise ontology term integration for disease mechanisms data.","zh":"适用于需要精确本体论术语集成的生物医学代理，用于疾病机制数据。","ja":"疾病メカニズムのデータに対して正確なオントロジー用語の統合が必要なバイオメディカルエージェントに最適。","ko":"질병 기전 데이터에 대한 정확한 온톨로지 용어 통합이 필요한 바이오 의학 에이전트에 적합합니다.","es":"Perfecto para agentes biomédicos que necesitan una integración precisa de términos de ontología para datos de mecanismos de enfermedad.","fr":"Parfait pour les agents biomédicaux nécessitant une intégration précise de termes d''ontologie pour les données de mécanismes de maladie.","de":"Perfekt für Biomedizinische Agenten, die eine präzise Ontologie-Termin-Integration für Krankheitsmechanismus-Daten benötigen.","pt":"Perfeito para Agentes Biomédicos que necessitam de integração precisa de termos de ontologia para dados de mecanismos de doenças.","ru":"Идеально подходит для биомедицинских агентов, которым требуется точная интеграция терминов онтологии для данных о механизмах заболеваний.","ar":"مثالي للوكلاء البيولوجية الطبية التي تحتاج إلى دمج دقيق لمصطلحات علم الонтولوجيا لبيانات آليات الأمراض."},"recommendation":{"en":"Empowers agents to validate and add ontology term references using Human Phenotype Ontology and Cell Ontology, ensuring accurate entity linking with correct IDs and labels via the dismech disorder knowledge base.","zh":"赋予代理验证和添加本体论用语引用，使用人类表型本体论和细胞本体论，确保通过dismech障碍知识库用正确的ID和标签进行准确的实体链接。","ja":"ヒューマン・フェノタイプ・オントロジーとセル・オントロジーを使用して、エージェントがオントロジー用語参照を検証および追加できるようにし、dismech障碍知識ベースを介して正しいIDとラベルで正確なエンティティのリンクを保証する。","ko":"인간 표현형 온톨로지와 세포 온톨로지를 사용하여 에이전트가 온톨로지 용어 참조를 검증 및 추가 할 수 있도록 하여 dismech 장애 지식베이스를 통해 올바른 ID 및 레이블로 정확한 엔티티 연결을 보장합니다.","es":"Habilita a los agentes a validar y agregar referencias de términos de ontología utilizando la Ontología de Fenotipo Humano y la Ontología de Células, garantizando un enlace de entidad preciso con IDs y etiquetas correctas a través de la base de conocimiento de trastornos dismech.","fr":"Permet aux agents de valider et d''ajouter des références de termes d''ontologie en utilisant l''Ontologie de Phénotype Humain et l''Ontologie de Cellules, garantissant un lien d''entité précis avec des IDs et des libellés corrects via la base de connaissances de désordres dismech.","de":"Ermächtigt Agenten, Ontologie-Termin-Referenzen mit der Human Phenotype Ontology und der Cell Ontology zu validieren und hinzuzufügen, um eine genaue Entitätsverknüpfung mit korrekten IDs und Labels über die dismech-Störungswissensbasis sicherzustellen.","pt":"Habilita os agentes a validar e adicionar referências de termos de ontologia usando a Ontologia de Fenótipo Humano e a Ontologia de Células, garantindo a ligação de entidades precisa com IDs e rótulos corretos via a base de conhecimento dismech de distúrbios.","ru":"Позволяет агентам проверять и добавлять ссылки на термины онтологии, используя Онтологию Человеческого Фенотипа и Онтологию Клеток, обеспечивая точную связь сущностей с правильными идентификаторами и метками через базу знаний о нарушениях dismech.","ar":"تمكّن الوكلاء من التحقق من صحة الإشارات إلى المصطلحات من أجل علم الонтولوجيا بإستخدام علم الонтولوجيا للفينوتايب البشري وعلم الонтولوجيا للخلايا، مما يضمن ربط الكيانات بدقة مع المعرفات والمعرفات الصحيحة من خلال قاعدة المعرفة حول اضطرابات من أجل dismech."},"useCases":{"en":["Validating phenotype terms against the Human Phenotype Ontology","Adding authoritative terms to cell types entries using the Cell Ontology","Linking biological processes to standard ontology terms"],"zh":["验证表型用语与人类表型本体论","使用细胞本体论向细胞类型条目添加权威术语","将生物过程链接到标准本体论用语"],"ja":["ヒューマン・フェノタイプ・オントロジーに対するフェノタイプ用語の検証","セル・オントロジーを使用して細胞タイプのエントリに権威ある用語を追加","生物学的プロセスを標準オントロジー用語にリンク"],"ko":["인간 표현형 온톨로지에 대한 표현형 용어의 검증","세포 온톨로지를 사용하여 세포 유형 항목에 권위 있는 용어 추가","생물학적 프로세스를 표준 온톨로지 용어에 연결"],"es":["Validar términos de fenotipo contra la Ontología de Fenotipo Humano","Agregar términos autorizados a las entradas de tipos de células utilizando la Ontología de Células","Enlazar procesos biológicos con términos de ontología estándar"],"fr":["Valider les termes de phénotype contre l''Ontologie de Phénotype Humain","Ajouter des termes autorisés aux entrées de types de cellules en utilisant l''Ontologie de Cellules","Relier les processus biologiques à des termes d''ontologie standard"],"de":["Phänotyp-Terme gegen die Human Phenotype Ontology validieren","Autorisierte Terme zu Zelltyp-Einträgen mit der Cell Ontology hinzufügen","Biologische Prozesse mit Standard-Ontologie-Terminen verknüpfen"],"pt":["Validar termos de fenótipo contra a Ontologia de Fenótipo Humano","Adicionar termos autorizados a entradas de tipos de células usando a Ontologia de Células","Vincular processos biológicos a termos de ontologia padrão"],"ru":["Проверять термины фенотипа против Онтологии Человеческого Фенотипа","Добавлять авторитетные термины в записи типов клеток, используя Онтологию Клеток","Связывать биологические процессы со стандартными терминами онтологии"],"ar":["التحقق من مصطلحات الفينوتايب مقابل علم الонтولوجيا للفينوتايب البشري","إضافة مصطلحات موثوقة إلى مدخلات أنواع الخلايا باستخدام علم الонтولوجيا للخلايا","ربط العمليات البيولوجية بالمصطلحات الموحدة لعلم الонтولوجيا"]},"limitations":{"en":["Requires access to the Disease Mechanisms KB","Limited to specific ontologies like Human Phenotype Ontology and Cell Ontology"],"zh":["需要访问疾病机制知识库","仅限于像人类表型本体论和细胞本体论这样的特定本体论"],"ja":["障碍メカニズムの知識ベースへのアクセスが必要","ヒューマン・フェノタイプ・オントロジーとセル・オントロジーなどの特定のオントロジーに限定"],"ko":["질병 기전 지식베이스에 대한 액세스가 필요합니다.","인간 표현형 온톨로지 및 세포 온톨로지와 같은 특정 온톨로지에 제한"],"es":["Requiere acceso a la base de conocimiento de mecanismos de enfermedad","Limitado a ontologías específicas como la Ontología de Fenotipo Humano y la Ontología de Células"],"fr":["Nécessite un accès à la base de connaissances de mécanismes de maladie","Limité à des ontologies spécifiques comme l''Ontologie de Phénotype Humain et l''Ontologie de Cellules"],"de":["Erfordert Zugriff auf die Krankheitsmechanismus-Wissensbasis","Begrenzt auf spezifische Ontologien wie die Human Phenotype Ontology und die Cell Ontology"],"pt":["Requer acesso à Base de Conhecimento de Mecanismos de Doenças","Limitado a ontologias específicas, como a Ontologia de Fenótipo Humano e a Ontologia de Células"],"ru":["Требует доступа к Базе Знаний о Механизмах Заболеваний","Ограничен конкретными онтологиями, такими как Онтология Человеческого Фенотипа и Онтология Клеток"],"ar":["يتطلب الوصول إلى قاعدة المعرفة حول آليات الأمراض","محدود بال ontologias الخاصة، مثل علم الонтولوجيا للفينوتايب البشري وعلم الонтولوجيا للخلايا"]},"version":4},"contentHash":"e63b1a790291363cc65d9ff3facd4a5