INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('monarch-initiative/dismech/dismech-terms', 'dismech-terms', 'monarch-initiative', 'dismech', 'community', 'dismech-terms monarch-initiative dismech community The dismech-terms skill enables the addition and validation of ontology term references in the Disease Mechanisms KB, ensuring accurate linking of entities to authoritative terms. This benefits developers and researchers working with disease mechanisms data. Dismech-Terms是一个用于验证和标准化ontology term的AIエージェント，支持HP和CL等多个ontology Dismech-Termsは、オントロジー用語の検証と標準化を実現するAIエージェントです。HPやCLなどの複数のオントロジーをサポートしています Dismech-Terms는 온톨로지 용어의 검증과 표준화를 구현하는 인공지능 에이전트입니다. HP와 CL 등의 여러 온톨로지를 지원합니다 dismech-terms es una habilidad que agrega y valida referencias de términos de ontología en la base de conocimiento de trastornos dismech, utilizando ontologías como HP y CL dismech-terms est une compétence qui ajoute et valide des références de termes d''ontologie dans la base de connaissances des troubles dismech, en utilisant des ontologies comme HP et CL dismech-terms ist eine Fähigkeit, die Referenzen von Ontologie-Terms in der dismech-Störungs-Knowledge-Base hinzufügt und validiert, unter Verwendung von Ontologien wie HP und CL Dismech-Terms é uma habilidade que adiciona e valida referências de termos de ontologia no conhecimento de distúrbios de doenças, garantindo a ligação correta de fenótipos, tipos de células e processos biológicos. Dismech-Terms — это навык, который добавляет и проверяет ссылки на термины онтологии в базе знаний о расстройствах заболеваний, обеспечивая правильную связь фенотипов, типов клеток и биологических процессов. Dismech-Terms هو مهارة تضيف وتحقق من المراجع المصطلحية لتنميط الأمراض في قاعدة المعرفة، مما يضمن ربط الفينوتايب وأنواع الخلايا والعمليات البيولوجية بشكل صحيح. how to use dismech-terms dismech-terms setup guide ontology term validation disease mechanisms knowledge base Human Phenotype Ontology Cell Ontology dismech-terms install dismech-terms alternative dismech-terms vs other ontology tools Dismech-Terms AIエージェント ontology term HP CL phenotypes cell types biological processes Python CLI Adds phenotype_term to phenotype entries using Human Phenotype Ontology (HP) Validates term references for cell_types entries using Cell Ontology (CL) Links biological_processes entries to authoritative ontology terms Ensures correct IDs and labels for ontology terms Supports integration with the dismech disorder knowledge base dismech-terms is a skill that validates ontology term references for disease mechanisms, using ontologies like Human Phenotype Ontology (HP) and Cell Ontology (CL).');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('foscomputerservices/FOSUtilities/fosmvvm-fields-generator', 'community', 'foscomputerservices', 'FOSUtilities', 'foscomputerservices/FOSUtilities', 'fosmvvm-fields-generator', 0, 0, 48, '2026-03-08T01:57:15.615Z', '2026-03-08T02:13:21.593Z', '195afd1053edd24681e5cb2d7f5cc0613254a83b60aa260dc511df82246caea6', '{"id":"foscomputerservices/FOSUtilities/fosmvvm-fields-generator","name":"fosmvvm-fields-generator","description":{"en":"The fosmvvm-fields-generator skill generates Form Specifications following FOSMVVM patterns, supporting the Model-View-ViewModel architecture on multiple platforms. It benefits developers working with Swift libraries on macOS, iOS, Windows, and Linux.","zh":"FOSMVVM 表单生成器是 Swift 库，支持 Model-View-ViewModel 模式，用于生成表单规范","ja":"FOSMVVM フィールド生成器は、Model-View-ViewModel パターンをサポートする Swift ライブラリです","ko":"FOSMVVM 필드 생성기는 Model-View-ViewModel 패턴을 지원하는 Swift 라이브러리입니다","es":"fosmvvm-fields-generator es una biblioteca Swift para generar formularios siguiendo el patrón Model-View-ViewModel en macOS, iOS, Windows y Linux","fr":"fosmvvm-fields-generator est une bibliothèque Swift pour générer des formulaires suivant le modèle Model-View-ViewModel sur macOS, iOS, Windows et Linux","de":"fosmvvm-fields-generator ist eine Swift-Bibliothek zum Generieren von Formularen gemäß dem Model-View-ViewModel-Muster auf macOS, iOS, Windows und Linux","pt":"O FOSMVVM Fields Generator é uma biblioteca Swift para suportar o padrão Model-View-ViewModel em macOS, iOS, Windows e Linux.","ru":"FOSMVVM Fields Generator - это библиотека Swift для поддержки шаблона Model-View-ViewModel на macOS, iOS, Windows и Linux.","ar":"FOSMVVM Fields Generator هو مكتبة Swift لدعم نمط Model-View-ViewModel على منصة macOS, iOS, Windows و Linux."},"seo":{"title":{"en":"fosmvvm-fields-generator: Form Specification Generator fo...","zh":"FOSMVVM 表单生成器使用指南 - Swift 库","ja":"FOSMVVM フィールド生成器のベストプラクティス - AIエージェント","ko":"FOSMVVM 필드 생성기 설정 가이드 - Swift 라이브러리","es":"Guía de configuración de fosmvvm-fields-generator para ma...","fr":"Guide de mise en place de fosmvvm-fields-generator pour m...","de":"Einrichtungsleitfaden für fosmvvm-fields-generator auf ma...","pt":"Guia de Configuração do FOSMVVM Fields Generator para Des...","ru":"ИИ Агенты: Настройка FOSMVVM Fields Generator для macOS, ...","ar":"دليل إعداد FOSMVVM Fields Generator لمنصة macOS, iOS, Win..."},"description":{"en":"Discover how fosmvvm-fields-generator simplifies Form Specification creation for macOS, iOS, Windows, and Linux. Get started with FOSMVVM patterns today!","zh":"使用 FOSMVVM 表单生成器简化用户输入表单的创建，支持 macOS、iOS、Windows 和 Linux","ja":"FOSMVVM フィールド生成器を使用して、ユーザー入力フォームの作成を簡素化します - AIエージェント","ko":"FOSMVVM 필드 생성기를 사용하여 사용자 입력 폼을 단순화하는 방법 - Swift 라이브러리","es":"Descubre cómo utilizar fosmvvm-fields-generator para generar formularios siguiendo el patrón Model-View-ViewModel en Swift","fr":"Découvrez comment utiliser fosmvvm-fields-generator pour générer des formulaires suivant le modèle Model-View-ViewModel en Swift","de":"Erfahren Sie, wie Sie fosmvvm-fields-generator verwenden, um Formulare gemäß dem Model-View-ViewModel-Muster in Swift zu generieren","pt":"Aprenda a utilizar o FOSMVVM Fields Generator para criar formularios com padrão Model-View-ViewModel em Swift para macOS, iOS, Windows e Linux","ru":"Узнайте, как использовать FOSMVVM Fields Generator для создания форм с шаблоном Model-View-ViewModel на Swift для macOS, iOS, Windows и Linux","ar":"تعرف على كيفية استخدام FOSMVVM Fields Generator لإنشاء استمارة باستخدام نمط Model-View-ViewModel في Swift لمنصة macOS, iOS, Windows و Linux"},"definition":{"en":"fosmvvm-fields-generator is a Swift library that generates Form Specifications, serving as the single source of truth for user input in FOSMVVM-based applications.","zh":"FOSMVVM 表单生成器是一种 Swift 库，用于生成表单规范和支持 Model-View-ViewModel 模式","ja":"FOSMVVM フィールド生成器は、Model-View-ViewModel パターンをサポートする Swift ライブラリの一種です","ko":"FOSMVVM 필드 생성기는 Model-View-ViewModel 패턴을 지원하는 Swift 라이브러리입니다","es":"fosmvvm-fields-generator es una herramienta de código abierto que genera formularios siguiendo el patrón Model-View-ViewModel","fr":"fosmvvm-fields-generator est un outil open source qui génère des formulaires suivant le modèle Model-View-ViewModel","de":"fosmvvm-fields-generator ist ein Open-Source-Tool, das Formulare gemäß dem Model-View-ViewModel-Muster generiert","pt":"O que é FOSMVVM Fields Generator? É uma biblioteca Swift que gera especificações de formulário seguindo o padrão FOSMVVM.","ru":"Что такое FOSMVVM Fields Generator? Это библиотека Swift, генерирующая спецификации форм в соответствии с шаблоном FOSMVVM.","ar":"ما هو FOSMVVM Fields Generator؟ هو مكتبة Swift لتوليد مواصفات الاستمارة ตาม نمط FOSMVVM."},"features":{"en":["Generates Form Specifications as {Name}Fields protocols","Supports FOSMVVM patterns on macOS, iOS, Windows, and Linux","Provides a single source of truth for user input","Defines what data can be provided by the user and how it should be presented","Follows the conceptual foundation outlined in FOSMVVMArchitecture.md"],"zh":["支持 Model-View-ViewModel 模式","生成表单规范","支持 macOS、iOS、Windows 和 Linux","使用 Swift 编程语言","简化用户输入表单的创建"],"ja":["Model-View-ViewModel パターンをサポート","フォーム仕様を生成","macOS、iOS、Windows、Linux をサポート","Swift プログラミング言語を使用","ユーザー入力フォームの作成を簡素化"],"ko":["Model-View-ViewModel 패턴을 지원","폼 사양을 생성","macOS、iOS、Windows、Linux를 지원","Swift 프로그래밍 언어를 사용","사용자 입력 폼을 단순화"],"es":["Generación de formularios siguiendo el patrón Model-View-ViewModel","Soporte para macOS, iOS, Windows y Linux","Implementación de la interfaz {Name}Fields para la especificación de formularios","Definición de propiedades y presentación de datos para la entrada del usuario","Compatibilidad con Swift"],"fr":["Génération de formulaires suivant le modèle Model-View-ViewModel","Support pour macOS, iOS, Windows et Linux","Implémentation de l''interface {Name}Fields pour la spécification de formulaires","Définition de propriétés et de présentation de données pour la saisie de l''utilisateur","Compatibilité avec Swift"],"de":["Generierung von Formularen gemäß dem Model-View-ViewModel-Muster","Unterstützung für macOS, iOS, Windows und Linux","Implementierung der Schnittstelle {Name}Fields für die Formularspezifikation","Definition von Eigenschaften und Datenpräsentation für die Benutzereingabe","Kompatibilität mit Swift"],"pt":["Geração de especificações de formulário com padrão Model-View-ViewModel","Suporte a múltiplas plataformas: macOS, iOS, Windows e Linux","Implementação de protocolo {Name}Fields para formularios","Definição de propriedades e apresentação de dados do usuário","Integração com a arquitetura FOSMVVM"],"ru":["Генерация спецификаций форм с шаблоном Model-View-ViewModel","Поддержка нескольких платформ: macOS, iOS, Windows и Linux","Реализация протокола {Name}Fields для форм","Определение свойств и представления данных пользователя","Интеграция с архитектурой FOSMVVM"],"ar":["توليد مواصفات الاستمارة بنمط Model-View-ViewModel","دعم منصات متعددة: macOS, iOS, Windows و Linux","تنفيذ بروتوكول {Name}Fields للاستمارات","تعريف خصائص وعرض بيانات المستخدم","التكامل مع هندسة FOSMVVM"]},"keywords":{"en":["how to use fosmvvm-fields-generator","fosmvvm-fields-generator alternative","fosmvvm-fields-generator setup guide","what is fosmvvm-fields-generator","fosmvvm-fields-generator vs other FOSMVVM libraries","installing fosmvvm-fields-generator on macOS","fosmvvm-fields-generator for iOS development","FOSMVVM pattern implementation","Swift library for Form Specification generation"],"zh":["FOSMVVM 表单生成器","Swift 库","Model-View-ViewModel 模式","表单规范","用户输入表单","macOS","iOS","Windows","Linux"],"ja":["FOSMVVM フィールド生成器","Swift ライブラリ","Model-View-ViewModel パターン","フォーム仕様","ユーザー入力フォーム","macOS","iOS","Windows","Linux","AIエージェント"],"ko":["FOSMVVM 필드 생성기","Swift 라이브러리","Model-View-ViewModel 패턴","폼 사양","사용자 입력 폼","macOS","iOS","Windows","Linux"],"es":["fosmvvm-fields-generator","Model-View-ViewModel","Swift","macOS","iOS","Windows","Linux","generación de formularios","patrón de diseño"],"fr":["fosmvvm-fields-generator","Model-View-ViewModel","Swift","macOS","iOS","Windows","Linux","génération de formulaires","modèle de conception"],"de":["fosmvvm-fields-generator","Model-View-ViewModel","Swift","macOS","iOS","Windows","Linux","Formulargenerierung","Entwurfsmuster"],"pt":["FOSMVVM Fields Generator","Model-View-ViewModel","Swift","macOS","iOS","Windows","Linux","desenvolvimento de software","bibliotecas Swift"],"ru":["FOSMVVM Fields Generator","Model-View-ViewModel","Swift","macOS","iOS","Windows","Linux","разработка программного обеспечения","библиотеки Swift","ИИ Агенты"],"ar":["FOSMVVM Fields Generator","Model-View-ViewModel","Swift","macOS","iOS","Windows","Linux","تطوير البرمجيات","مكتبات Swift","وكلاء الذكاء الاصطناعي"]}},"owner":"foscomputerservices","repo":"FOSUtilities","repoPath":"foscomputerservices/FOSUtilities","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.615Z","topics":[],"category":"community","skillMd":{"name":"fosmvvm-fields-generator","description":"Generate FOSMVVM Fields protocols with validation rules, FormField definitions, and localized messages. Define form contracts once, validate everywhere.","bodyPreview":"# FOSMVVM Fields Generator\n\nGenerate Form Specifications following FOSMVVM patterns.\n\n## Conceptual Foundation\n\n> For full architecture context, see [FOSMVVMArchitecture.md](../../docs/FOSMVVMArchitecture.md) | [OpenClaw reference]({baseDir}/references/FOSMVVMArchitecture.md)\n\nA **Form Specification** (implemented as a `{Name}Fields` protocol) is the **single source of truth** for user input. It answers:\n\n1. **What data** can the user provide? (properties)\n2. **How should it be presented?** (For","body":"# FOSMVVM Fields Generator\n\nGenerate Form Specifications following FOSMVVM patterns.\n\n## Conceptual Foundation\n\n> For full architecture context, see [FOSMVVMArchitecture.md](../../docs/FOSMVVMArchitecture.md) | [OpenClaw reference]({baseDir}/references/FOSMVVMArchitecture.md)\n\nA **Form Specification** (implemented as a `{Name}Fields` protocol) is the **single source of truth** for user input. It answers:\n\n1. **What data** can the user provide? (properties)\n2. **How should it be presented?** (FormField with type, keyboard, autofill semantics)\n3. **What constraints apply?** (validation rules)\n4. **What messages should be shown?** (localized titles, placeholders, errors)\n\n### Why This Matters\n\nThe Form Specification is **defined once, used everywhere**:\n\n```swift\n// Same protocol adopted by different consumers:\nstruct CreateIdeaRequestBody: ServerRequestBody, IdeaFields { ... }  // HTTP transmission\n@ViewModel struct IdeaFormViewModel: IdeaFields { ... }              // Form rendering\nfinal class Idea: Model, IdeaFields { ... }                          // Persistence validation\n```\n\nThis ensures:\n- **Consistent validation** - Same rules on client and server\n- **Shared localization** - One YAML file, used everywhere\n- **Single source of truth** - Change once, applies everywhere\n\n### Connection to FOSMVVM\n\nForm Specifications integrate with:\n- **Localization System** - FormField titles/placeholders and validation messages use `LocalizableString`\n- **Validation System** - Implements `ValidatableModel` protocol\n- **Request System** - RequestBody types adopt Fields for validated transmission\n- **ViewModel System** - ViewModels adopt Fields for form rendering\n\n## When to Use This Skill\n\n- Defining a new form (create, edit, filter, search)\n- Adding validation to a request body\n- Any type that needs to conform to `ValidatableModel`\n- When `fosmvvm-fluent-datamodel-generator` needs form fields for a DataModel\n\n## What This Skill Generates\n\nA complete Form Specification consists of **3 files**:\n\n| File | Purpose |\n|------|---------|\n| `{Name}Fields.swift` | Protocol + FormField definitions + validation methods |\n| `{Name}FieldsMessages.swift` | `@FieldValidationModel` struct with `@LocalizedString` properties |\n| `{Name}FieldsMessages.yml` | YAML localization (titles, placeholders, error messages) |\n\n## Project Structure Configuration\n\nReplace placeholders with your project''s actual paths:\n\n| Placeholder | Description | Example |\n|-------------|-------------|---------|\n| `{ViewModelsTarget}` | Shared ViewModels SPM target | `ViewModels`, `SharedViewModels` |\n| `{ResourcesPath}` | Localization resources path | `Sources/Resources` |\n\n**Expected Structure:**\n```\nSources/\n  {ViewModelsTarget}/\n    FieldModels/\n      {Name}Fields.swift\n      {Name}FieldsMessages.swift\n  {ResourcesPath}/\n    FieldModels/\n      {Name}FieldsMessages.yml\n```\n\n## How to Use This Skill\n\n**Invocation:**\n/fosmvvm-fields-generator\n\n**Prerequisites:**\n- Form purpose understood from conversation context\n- Field requirements discussed (names, types, constraints)\n- Entity relationship identified (what is this form creating/editing)\n\n**Workflow integration:**\nThis skill is used when defining form validation and user input contracts. The skill references conversation context automatically—no file paths or Q&A needed. Often precedes fosmvvm-fluent-datamodel-generator for form-backed models.\n\n## Pattern Implementation\n\nThis skill references conversation context to determine Fields protocol structure:\n\n### Form Analysis\n\nFrom conversation context, the skill identifies:\n- **Form purpose** (create, edit, filter, login, settings)\n- **Entity relation** (User, Idea, Document - what''s being created/edited)\n- **Protocol naming** (CreateIdeaFields, UpdateProfile, LoginCredentials)\n\n### Field Design\n\nFor each field from requirements:\n- **Property specification** (name, type, optional vs required)\n- **Presentation type** (FormFieldType: text, textArea, select, checkbox)\n- **Input semantics** (FormInputType: email, password, tel, date)\n- **Constraints** (required, length range, value range, date range)\n- **Localization** (title, placeholder, validation error messages)\n\n### File Generation Order\n\n1. Fields protocol with FormField definitions and validation\n2. FieldsMessages struct with @LocalizedString properties\n3. FieldsMessages YAML with localized strings\n\n### Context Sources\n\nSkill references information from:\n- **Prior conversation**: Form requirements, field specifications discussed\n- **Specification files**: If Claude has read form specs into context\n- **Existing patterns**: From codebase analysis of similar Fields protocols\n\n## Key Patterns\n\n### Protocol Structure\n\n```swift\npublic protocol {Name}Fields: ValidatableModel, Codable, Sendable {\n    var fieldName: FieldType { get set }\n    var {name}ValidationMessages: {Name}FieldsMessages { get }\n}\n```\n\n### FormField Definition\n\n```swift\nstatic var contentField: FormField<String?> { .init(\n    fieldId: .init(id: \"content\"),\n    title: .localized(for: {Name}FieldsMessages.self, propertyName: \"content\", messageKey: \"title\"),\n    placeholder: .localized(for: {Name}FieldsMessages.self, propertyName: \"content\", messageKey: \"placeholder\"),\n    type: .textArea(inputType: .text),\n    options: [\n        .required(value: true)\n    ] + FormInputOption.rangeLength(contentRange)\n) }\n```\n\n### FormField Types Reference\n\n| FormFieldType | Use Case |\n|---------------|----------|\n| `.text(inputType:)` | Single-line input |\n| `.textArea(inputType:)` | Multi-line input |\n| `.checkbox` | Boolean toggle |\n| `.select` | Dropdown selection |\n| `.colorPicker` | Color selection |\n\n### FormInputType Reference (common ones)\n\n| FormInputType | Keyboard/Autofill |\n|---------------|-------------------|\n| `.text` | Default keyboard |\n| `.emailAddress` | Email keyboard, email autofill |\n| `.password` | Secure entry |\n| `.tel` | Phone keyboard |\n| `.url` | URL keyboard |\n| `.date`, `.datetimeLocal` | Date picker |\n| `.givenName`, `.familyName` | Name autofill |\n\n### Validation Method Pattern\n\n```swift\ninternal func validateContent(_ fields: [FormFieldBase]?) -> [ValidationResult]? {\n    guard fields == nil || (fields?.contains(Self.contentField) == true) else {\n        return nil\n    }\n\n    var result = [ValidationResult]()\n\n    if content.isEmpty {\n        result.append(.init(\n            status: .error,\n            field: Self.contentField,\n            message: {name}ValidationMessages.contentRequiredMessage\n        ))\n    } else if !Self.contentRange.contains(NSString(string: content).length) {\n        result.append(.init(\n            status: .error,\n            field: Self.contentField,\n            message: {name}ValidationMessages.contentOutOfRangeMessage\n        ))\n    }\n\n    return result.isEmpty ? nil : result\n}\n```\n\n### Messages Struct Pattern\n\n```swift\n@FieldValidationModel public struct {Name}FieldsMessages {\n    @LocalizedString(\"content\", messageGroup: \"validationMessages\", messageKey: \"required\")\n    public var contentRequiredMessage\n\n    @LocalizedString(\"content\", messageGroup: \"validationMessages\", messageKey: \"outOfRange\")\n    public var contentOutOfRangeMessage\n}\n```\n\n### YAML Structure\n\n```yaml\nen:\n  {Name}FieldsMessages:\n    content:\n      title: \"Content\"\n      placeholder: \"Enter your content...\"\n      validationMessages:\n        required: \"Content is required\"\n        outOfRange: \"Content must be between 1 and 10,000 characters\"\n```\n\n## Naming Conventions\n\n| Concept | Convention | Example |\n|---------|------------|---------|\n| Protocol | `{Name}Fields` | `IdeaFields`, `CreateIdeaFields` |\n| Messages struct | `{Name}FieldsMessages` | `IdeaFieldsMessages` |\n| Messages property | `{name}ValidationMessages` | `ideaValidationMessages` |\n| Field definition | `{fieldName}Field` | `contentField` |\n| Range constant | `{fieldName}Range` | `contentRange` |\n| Validate method | `validate{FieldName}` | `validateContent` |\n| Required message | `{fieldName}RequiredMessage` | `contentRequiredMessage` |\n| OutOfRange message | `{fieldName}OutOfRangeMessage` | `contentOutOfRangeMessage` |\n\n## See Also\n\n- [FOSMVVMArchitecture.md](../../docs/FOSMVVMArchitecture.md) - Full FOSMVVM architecture reference\n- [fosmvvm-viewmodel-generator](../fosmvvm-viewmodel-generator/SKILL.md) - For ViewModels that adopt Fields\n- [fosmvvm-fluent-datamodel-generator](../fosmvvm-fluent-datamodel-generator/SKILL.md) - For Fluent DataModels that implement Fields\n- [reference.md](reference.md) - Complete file templates\n\n## Version History\n\n| Version | Date | Changes |\n|---------|------|---------|\n| 1.0 | 2024-12-24 | Initial skill |\n| 2.0 | 2024-12-26 | Rewritten with conceptual foundation; generalized from Kairos-specific |\n| 2.1 | 2026-01-24 | Update to context-aware approach (remove file-parsing/Q&A). Skill references conversation context instead of asking questions or accepting file paths. |\n"},"lastSynced":"2026-03-08T02:13:21.593Z","agentAnalysis":{"suitability":{"en":"Perfect for Cross-Platform Agents needing to generate Form Specifications following FOSMVVM patterns for macOS, iOS, Windows, and Linux","zh":"适合需要为 macOS、iOS、Windows 和 Linux 生成表单规范的跨平台代理，遵循 FOSMVVM 模式","ja":"macOS、iOS、Windows、Linux 向けのフォーム仕様を FOSMVVM パターンに従って生成するクロスプラットフォーム エージェントに適しています","ko":"macOS, iOS, Windows 및 Linux를 위한 表单 규격을 FOSMVVM 패턴에 따라 생성하는 크로스 플랫폼 에이전트에 적합합니다","es":"Perfecto para agentes de plataforma cruzada que necesitan generar especificaciones de formularios siguiendo patrones FOSMVVM para macOS, iOS, Windows y Linux","fr":"Parfait pour les agents de plate-forme croisée ayant besoin de générer des spécifications de formulaire suivant les modèles FOSMVVM pour macOS, iOS, Windows et Linux","de":"Perfekt für Cross-Platform-Agents, die Formularspezifikationen gemäß FOSMVVM-Mustern für macOS, iOS, Windows und Linux generieren müssen","pt":"Perfeito para Agentes Cross-Platform que precisam gerar Especificações de Formulário seguindo padrões FOSMVVM para macOS, iOS, Windows e Linux","ru":"Идеально подходит для агентов Cross-Platform, которым необходимо生成ировать спецификации форм в соответствии с шаблонами FOSMVVM для macOS, iOS, Windows и Linux","ar":"مثالي لعميل Cross-Platform الذي يحتاج إلى إنشاء مواصفات النموذج اتباعًا لأنماط FOSMVVM لنظامي macOS و iOS و Windows و Linux"},"recommendation":{"en":"Empowers agents to create Model-View-ViewModel architectures using Swift libraries, generating Form Specifications as a single source of truth for user input, including properties and presentation details, implemented as {Name}Fields protocols","zh":"赋予代理使用 Swift 库创建 Model-View-ViewModel 架构的能力，生成表单规范作为用户输入的单一真实来源，包括属性和呈现细节，作为 {Name}Fields 协议实现","ja":"Swift ライブラリを使用して Model-View-ViewModel アーキテクチャを作成するエージェントの能力を提供し、ユーザー入力の単一の真実源としてフォーム仕様を生成し、プロパティとプレゼンテーションの詳細を含み、{Name}Fields プロトコルとして実装します","ko":"Swift 라이브러리를 사용하여 Model-View-ViewModel 아키텍처를 생성하는 에이전트의 능력을 제공하며, 사용자 입력의 단일 진실 源으로서 表单 규격을 생성하며, 속성 및 프레젠테이션 세부 정보를 포함하며, {Name}Fields 프로토콜로 구현합니다","es":"Habilita a los agentes a crear arquitecturas Model-View-ViewModel utilizando bibliotecas Swift, generando especificaciones de formularios como una sola fuente de verdad para la entrada del usuario, incluyendo propiedades y detalles de presentación, implementadas como protocolos {Name}Fields","fr":"Permet aux agents de créer des architectures Model-View-ViewModel en utilisant des bibliothèques Swift, en générant des spécifications de formulaire comme une seule source de vérité pour la saisie utilisateur, y compris les propriétés et les détails de présentation, implementés comme des protocoles {Name}Fields","de":"Ermöglich es Agents, Model-View-ViewModel-Architekturen mithilfe von Swift-Bibliotheken zu erstellen, indem Formularspezifikationen als einzige Quelle der Wahrheit für Benutzereingaben generiert werden, einschließlich Eigenschaften und Präsentationsdetails, implementiert als {Name}Fields-Protokolle","pt":"Habilita os agentes a criar arquiteturas Model-View-ViewModel usando bibliotecas Swift, gerando Especificações de Formulário como uma única fonte de verdade para entrada de usuário, incluindo propriedades e detalhes de apresentação, implementadas como protocolos {Name}Fields","ru":"Позволяет агентам создавать архитектуру Model-View-ViewModel с использованием библиотек Swift, генерируя спецификации форм как единственный источник истины для ввода пользователя, включая свойства и детали представления, реализованные как протоколы {Name}Fields","ar":"تمكّن العميل من إنشاء هيكل Model-View-ViewModel باستخدام مكتبات Swift، مع توليد مواصفات النموذج كمرجع وحيد للحقيقة لمدخلات المستخدم، بما في ذلك الخصائص و细节 العرض، مع تنفيذها كبروتوكولات {Name}Fields"},"useCases":{"en":["Generating Form Specifications for cross-platform applications","Creating Model-View-ViewModel architectures for macOS, iOS, Windows, and Linux","Implementing {Name}Fields protocols for user input validation and presentation"],"zh":["为跨平台应用程序生成表单规范","为 macOS、iOS、Windows 和 Linux 创建 Model-View-ViewModel 架构","实现 {Name}Fields 协议用于用户输入验证和呈现"],"ja":["クロスプラットフォーム アプリケーションのフォーム仕様を生成する","macOS、iOS、Windows、Linux 用の Model-View-ViewModel アーキテクチャを作成する","{Name}Fields プロトコルを実装してユーザー入力の検証とプレゼンテーションを行う"],"ko":["크로스 플랫폼 애플리케이션을 위한 表单 규격을 생성하는 것","macOS, iOS, Windows 및 Linux를 위한 Model-View-ViewModel 아키텍처를 생성하는 것","{Name}Fields 프로토콜을 구현하여 사용자 입력의 검증 및 프레젠테이션을 수행하는 것"],"es":["Generar especificaciones de formularios para aplicaciones de plataforma cruzada","Crear arquitecturas Model-View-ViewModel para macOS, iOS, Windows y Linux","Implementar protocolos {Name}Fields para la validación y presentación de la entrada del usuario"],"fr":["Générer des spécifications de formulaire pour les applications de plate-forme croisée","Créer des architectures Model-View-ViewModel pour macOS, iOS, Windows et Linux","Implémenter des protocoles {Name}Fields pour la validation et la présentation de la saisie utilisateur"],"de":["Formularspezifikationen für Cross-Platform-Anwendungen generieren","Model-View-ViewModel-Architekturen für macOS, iOS, Windows und Linux erstellen","Implementierung von {Name}Fields-Protokollen für die Validierung und Darstellung von Benutzereingaben"],"pt":["Geração de Especificações de Formulário para aplicações cross-platform","Criação de arquiteturas Model-View-ViewModel para macOS, iOS, Windows e Linux","Implementação de protocolos {Name}Fields para validação e apresentação de entrada de usuário"],"ru":["Генерация спецификаций форм для кроссплатформенных приложений","Создание архитектур Model-View-ViewModel для macOS, iOS, Windows и Linux","Реализация протоколов {Name}Fields для валидации и представления ввода пользователя"],"ar":["توليد مواصفات النموذج لبرامج التطبيق متعددة المنصات","إنشاء هيكل Model-View-ViewModel لأنظمة macOS و iOS و Windows و Linux","تنفيذ بروتوكولات {Name}Fields لتحقق صحة مدخلات المستخدم وعرضها"]},"limitations":{"en":["Requires Swift libraries","Limited to FOSMVVM patterns and Model-View-ViewModel architecture"],"zh":["需要 Swift 库","仅限 FOSMVVM 模式和 Model-View-ViewModel 架构"],"ja":["Swift ライブラリが必要","FOSMVVM パターンと Model-View-ViewModel アーキテクチャに限定される"],"ko":["Swift 라이브러리가 필요함","FOSMVVM 패턴 및 Model-View-ViewModel 아키텍처로 제한됨"],"es":["Requiere bibliotecas Swift","Limitado a patrones FOSMVVM y arquitectura Model-View-ViewModel"],"fr":["Nécessite des bibliothèques Swift","Limité aux modèles FOSMVVM et à l''architecture Model-View-ViewModel"],"de":["Benötigt Swift-Bibliotheken","Begrenzt auf FOSMVVM-Muster und Model-View-ViewModel-Architektur"],"pt":["Exige bibliotecas Swift","Limitado a padrões FOSMVVM e arquitetura Model-View-ViewModel"],"ru":["Требует библиотек Swift","Ограничен шаблонами FOSMVVM и архитектурой Model-View-ViewModel"],"ar":["يتطلب مكتبات Swift","محدود لأنماط FOSMVVM وهيكل Model-View-ViewModel"]},"version":4},"contentHash":"195afd1053edd24681e5cb2d7f5cc0613254a83b60aa260dc511df82246caea6","qualityScore":48}');
