INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('foscomputerservices/FOSUtilities/fosmvvm-fields-generator', 'fosmvvm-fields-generator', 'foscomputerservices', 'FOSUtilities', 'community', 'fosmvvm-fields-generator foscomputerservices FOSUtilities community The fosmvvm-fields-generator skill generates Form Specifications following FOSMVVM patterns, supporting the Model-View-ViewModel architecture on multiple platforms. It benefits developers working with Swift libraries on macOS, iOS, Windows, and Linux. FOSMVVM 表单生成器是 Swift 库，支持 Model-View-ViewModel 模式，用于生成表单规范 FOSMVVM フィールド生成器は、Model-View-ViewModel パターンをサポートする Swift ライブラリです FOSMVVM 필드 생성기는 Model-View-ViewModel 패턴을 지원하는 Swift 라이브러리입니다 fosmvvm-fields-generator es una biblioteca Swift para generar formularios siguiendo el patrón Model-View-ViewModel en macOS, iOS, Windows y Linux fosmvvm-fields-generator est une bibliothèque Swift pour générer des formulaires suivant le modèle Model-View-ViewModel sur macOS, iOS, Windows et Linux fosmvvm-fields-generator ist eine Swift-Bibliothek zum Generieren von Formularen gemäß dem Model-View-ViewModel-Muster auf macOS, iOS, Windows und Linux O FOSMVVM Fields Generator é uma biblioteca Swift para suportar o padrão Model-View-ViewModel em macOS, iOS, Windows e Linux. FOSMVVM Fields Generator - это библиотека Swift для поддержки шаблона Model-View-ViewModel на macOS, iOS, Windows и Linux. FOSMVVM Fields Generator هو مكتبة Swift لدعم نمط Model-View-ViewModel على منصة macOS, iOS, Windows و Linux. how to use fosmvvm-fields-generator fosmvvm-fields-generator alternative fosmvvm-fields-generator setup guide what is fosmvvm-fields-generator fosmvvm-fields-generator vs other FOSMVVM libraries installing fosmvvm-fields-generator on macOS fosmvvm-fields-generator for iOS development FOSMVVM pattern implementation Swift library for Form Specification generation FOSMVVM 表单生成器 Swift 库 Model-View-ViewModel 模式 表单规范 用户输入表单 macOS iOS Windows Linux Generates Form Specifications as {Name}Fields protocols Supports FOSMVVM patterns on macOS, iOS, Windows, and Linux Provides a single source of truth for user input Defines what data can be provided by the user and how it should be presented Follows the conceptual foundation outlined in FOSMVVMArchitecture.md fosmvvm-fields-generator is a Swift library that generates Form Specifications, serving as the single source of truth for user input in FOSMVVM-based applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('uwu/flora/rustdoc', 'community', 'uwu', 'flora', 'uwu/flora', 'rustdoc', 0, 0, 48, '2026-03-08T01:57:15.617Z', '2026-03-08T02:13:25.159Z', 'e98bcd1db4a98ae378833ddda62fb160c017479feae64aa138d2e04baa2f2836', '{"id":"uwu/flora/rustdoc","name":"rustdoc","description":{"en":"rustdoc helps Rust developers write proper documentation for their code. It provides guidelines for writing doc comments that follow Rust Documentation Conventions (RFC 1574).","zh":"Rustdoc 是一种用于生成 Rust 代码文档的工具，通过遵循特定的文档约定可以提高代码质量","ja":"Rustdoc は Rust コードの文書化に使用されるツールです - AIエージェント開発","ko":"Rustdoc은 러스트 코드 문서화에 사용되는 도구로, 특정 문서 규칙을 준수하면 코드 품질을 높일 수 있습니다","es":"Rustdoc es una herramienta para documentar código Rust. Permite crear documentación clara y concisa para tus proyectos","fr":"Rustdoc est un outil pour documenter du code Rust. Il permet de créer une documentation claire et concise pour vos projets","de":"Rustdoc ist ein Tool zur Dokumentation von Rust-Code. Es ermöglicht die Erstellung klarer und präziser Dokumentationen für Ihre Projekte","pt":"O Rustdoc é uma ferramenta essencial para documentar código Rust. Aprenda a usá-lo para melhorar a produtividade do seu time","ru":"Rustdoc - это важнейший инструмент для документирования кода на Rust. Узнайте, как им пользоваться, чтобы повысить производительность вашей команды","ar":"رسومات روست هي أداة أساسية لتوثيق شفرة روست. تعلم كيفية استخدامها لتحسين إنتاجية فريقك"},"seo":{"title":{"en":"rustdoc: Documentation Best Practices for Rust Developers...","zh":"Rustdoc 文档最佳实践指南","ja":"Rustdoc Setup Guide - AIエージェント開発","ko":"Rustdoc 개발자 가이드 - 효율적인 문서 작성","es":"Guía de configuración de rustdoc para documentación de Rust","fr":"Meilleures pratiques de rustdoc pour la documentation Rust","de":"Rustdoc-Setup-Anleitung für effiziente Dokumentation","pt":"Guia de Configuração do Rustdoc: Melhores Práticas para D...","ru":"Настройка Rustdoc: Руководство по созданию качественной д...","ar":"إعداد رسومات روست: دليل أفضل الممارسات لتوثيق الشفرة"},"description":{"en":"Discover how to write effective doc comments with rustdoc. Learn the conventions and rules for documenting Rust code with our expert guide.","zh":"了解 Rustdoc 文档约定，提高代码质量和可读性","ja":"Rustdoc を使用して、高品質なコードを作成しましょう - AIエージェント開発","ko":"Rustdoc을 사용하여 효율적인 문서를 작성하고 코드 품질을 높여보세요","es":"Aprende a utilizar rustdoc para documentar tu código Rust de manera efectiva y mejorar la comprensión de tus proyectos","fr":"Découvrez comment utiliser rustdoc pour documenter votre code Rust et améliorer la compréhension de vos projets","de":"Erfahren Sie, wie Sie rustdoc verwenden, um Ihren Rust-Code effizient zu dokumentieren und die Verständlichkeit Ihrer Projekte zu verbessern","pt":"Aprenda a configurar o Rustdoc para criar documentação de código de alta qualidade e melhorar a produtividade do seu time de desenvolvimento","ru":"Узнайте, как настроить Rustdoc для создания качественной документации кода и повышения производительности вашей команды разработчиков с помощью ИИ Агентов","ar":"تعلم كيفية إعداد رسومات روست لإنشاء توثيق شفرة عالي الجودة وتحسين إنتاجية فريق التطوير الخاص بك"},"definition":{"en":"rustdoc is a documentation tool that helps Rust developers follow standard conventions for writing doc comments, ensuring clarity and consistency in their code documentation.","zh":"Rustdoc 是一种 Rust 代码文档生成工具，遵循 RFC 1574 文档约定","ja":"Rustdoc は Rust コードの文書化に使用されるツールで、RFC 1574 に基づいた文書化規約を提供します","ko":"Rustdoc은 러스트 코드 문서화에 사용되는 도구로, RFC 1574 문서 규칙을 따릅니다","es":"Rustdoc es una herramienta de documentación para el lenguaje de programación Rust","fr":"Rustdoc est un outil de documentation pour le langage de programmation Rust","de":"Rustdoc ist ein Dokumentationswerkzeug für die Programmiersprache Rust","pt":"O Rustdoc é uma ferramenta de documentação de código para a linguagem Rust","ru":"Rustdoc - это инструмент для документирования кода на языке Rust для ИИ Агентов","ar":"رسومات روست هي أداة توثيق شفرة للغة روست"},"features":{"en":["Applies Rust Documentation Conventions (RFC 1574) for consistent documentation","Enforces the use of third person singular present indicative in summary sentences","Requires a period at the end of summary sentences for proper grammar","Supports documentation of public Rust items with proper formatting","Provides guidelines for writing clear and concise doc comments"],"zh":["遵循 RFC 1574 文档约定","使用第三人称单数现在时态","每个文档注释以单行摘要句开始","支持多种文档注释样式"],"ja":["RFC 1574 に基づいた文書化規約を提供します","第三人称単数現在時態を使用","各文書注釈は単行の要約文で始まります","複数の文書注釈スタイルをサポート"],"ko":["RFC 1574 문서 규칙을 따름","第三人称 단수現在時制를 사용","각 문서 주석은 단일행 요약문으로 시작","다양한 문서 주석 스타일을 지원"],"es":["Soporte para comentarios de documentación en línea","Generación de documentación en formato HTML","Compatibilidad con la convención de documentación de Rust (RFC 1574)","Uso de frases resumen en los comentarios de documentación","Soporte para documentación de código Rust en tercer persona singular"],"fr":["Prise en charge des commentaires de documentation en ligne","Génération de documentation au format HTML","Compatibilité avec la convention de documentation Rust (RFC 1574)","Utilisation de phrases résumé dans les commentaires de documentation","Prise en charge de la documentation de code Rust à la troisième personne du singulier"],"de":["Unterstützung für Inline-Dokumentationskommentare","Generierung von Dokumentationen im HTML-Format","Kompatibilität mit der Rust-Dokumentationskonvention (RFC 1574)","Verwendung von Zusammenfassungssätzen in Dokumentationskommentaren","Unterstützung für die Dokumentation von Rust-Code im Singular"],"pt":["Suporte a comentários de documentação em Rust","Geração automática de documentação para código Rust","Compatibilidade com a linguagem Rust","Suporte a RFC 1574 para documentação de código","Otimização para melhorar a produtividade do time de desenvolvimento"],"ru":["Поддержка комментариев для документации на Rust","Автоматическая генерация документации для кода на Rust","Совместимость с языком Rust для ИИ Агентов","Поддержка RFC 1574 для документирования кода","Оптимизация для повышения производительности команды разработчиков"],"ar":["دعم التعليقات على توثيق الشفرة بلغة روست","توليد تلقائي لتوثيق الشفرة بلغة روست","التوافق مع لغة روست","دعم RFC 1574 لتوثيق الشفرة","تحسين الأداء لتحسين إنتاجية فريق التطوير"]},"keywords":{"en":["how to use rustdoc","rustdoc documentation conventions","rustdoc vs rust book","rustdoc install guide","rustdoc setup for rust developers","what is rustdoc","rustdoc alternative tools","rustdoc best practices"],"zh":["Rustdoc","RFC 1574","文档约定","代码质量","Rust 代码文档","文档注释","第三人称单数现在时态"],"ja":["Rustdoc","RFC 1574","文書化規約","コード品質","Rust コード文書","文書注釈","第三人称単数現在時態","AIエージェント"],"ko":["Rustdoc","RFC 1574","문서 규칙","코드 품질","러스트 코드 문서","문서 주석","第三人称 단수現在時制","AI 에이전트"],"es":["rustdoc","documentación de Rust","Rust RFC 1574","comentarios de documentación","generación de documentación","dokumentación en línea","herramientas de desarrollo de Rust"],"fr":["rustdoc","documentation Rust","Rust RFC 1574","commentaires de documentation","génération de documentation","documentation en ligne","outils de développement Rust"],"de":["rustdoc","Rust-Dokumentation","Rust RFC 1574","Dokumentationskommentare","Dokumentenerzeugung","Dokumentation online","Rust-Entwicklungstools"],"pt":["Rustdoc","documentação de código","Rust","desenvolvimento de software","produtividade","ferramentas de desenvolvimento","linguagem Rust","RFC 1574","comentários de documentação"],"ru":["Rustdoc","документирование кода","Rust","разработка программного обеспечения","производительность","инструменты разработки","язык Rust","RFC 1574","комментарии для документации","ИИ Агенты"],"ar":["رسومات روست","توثيق الشفرة","روست","تطوير البرمجيات","الإنتاجية","أدوات التطوير","لغة روست","RFC 1574","تعليقات التوثيق","أدوات الذكاء الاصطناعي"]}},"owner":"uwu","repo":"flora","repoPath":"uwu/flora","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.617Z","topics":[],"category":"community","skillMd":{"name":"rustdoc","description":"Rust documentation conventions (RFC 1574). Apply when writing doc comments on public Rust items. Covers summary sentences, section headings, type references, and examples.","bodyPreview":"# Rust Documentation Conventions (RFC 1574)\n\nApply these rules when writing doc comments (`///`) on public Rust items.\n\n## Summary Sentence\n\nEvery doc comment starts with a single-line summary sentence.\n\n```rust\n// DO: third person singular present indicative, ends with period\n/// Returns the length of the string.\n/// Creates a new instance with default settings.\n/// Parses the input and returns the result.\n\n// DON''T: imperative, missing period, or verbose\n/// Return the length of the string\n///","body":"# Rust Documentation Conventions (RFC 1574)\n\nApply these rules when writing doc comments (`///`) on public Rust items.\n\n## Summary Sentence\n\nEvery doc comment starts with a single-line summary sentence.\n\n```rust\n// DO: third person singular present indicative, ends with period\n/// Returns the length of the string.\n/// Creates a new instance with default settings.\n/// Parses the input and returns the result.\n\n// DON''T: imperative, missing period, or verbose\n/// Return the length of the string\n/// This function creates a new instance with default settings.\n/// Use this to parse the input and get the result back.\n```\n\n## Comment Style\n\nUse line comments, not block comments.\n\n```rust\n// DO\n/// Summary sentence here.\n///\n/// More details if needed.\n\n// DON''T\n/**\n * Summary sentence here.\n *\n * More details if needed.\n */\n```\n\nUse `//!` only for crate-level and module-level docs at the top of the file.\n\n## Section Headings\n\nUse these exact headings (always plural):\n\n```rust\n/// Summary sentence.\n///\n/// # Examples\n///\n/// # Panics\n///\n/// # Errors\n///\n/// # Safety\n///\n/// # Aborts\n///\n/// # Undefined Behavior\n```\n\n```rust\n// DO\n/// # Examples\n\n// DON''T\n/// # Example\n/// ## Examples\n/// **Examples:**\n```\n\n## Type References\n\nUse full generic forms and link with reference-style markdown.\n\n```rust\n// DO\n/// Returns [`Option<T>`] if the value exists.\n///\n/// [`Option<T>`]: std::option::Option\n\n// DON''T\n/// Returns `Option` if the value exists.\n/// Returns an optional value.\n```\n\n## Examples\n\nEvery public item should have examples showing usage.\n\n````rust\n/// Adds two numbers together.\n///\n/// # Examples\n///\n/// ```\n/// let result = my_crate::add(2, 3);\n/// assert_eq!(result, 5);\n/// ```\npub fn add(a: i32, b: i32) -> i32 {\n    a + b\n}\n````\n\nFor multiple patterns:\n\n````rust\n/// Parses a string into a number.\n///\n/// # Examples\n///\n/// Basic usage:\n///\n/// ```\n/// let n: i32 = my_crate::parse(\"42\").unwrap();\n/// assert_eq!(n, 42);\n/// ```\n///\n/// Handling errors:\n///\n/// ```\n/// let result = my_crate::parse::<i32>(\"not a number\");\n/// assert!(result.is_err());\n/// ```\n````\n\n## Errors Section\n\nDocument what errors can be returned and when.\n\n```rust\n/// Reads a file from disk.\n///\n/// # Errors\n///\n/// Returns [`io::Error`] if the file does not exist or cannot be read.\n///\n/// [`io::Error`]: std::io::Error\n```\n\n## Panics Section\n\nDocument conditions that cause panics.\n\n```rust\n/// Divides two numbers.\n///\n/// # Panics\n///\n/// Panics if `divisor` is zero.\npub fn divide(dividend: i32, divisor: i32) -> i32 {\n    assert!(divisor != 0, \"divisor must not be zero\");\n    dividend / divisor\n}\n```\n\n## Safety Section\n\nRequired for `unsafe` functions.\n\n```rust\n/// Dereferences a raw pointer.\n///\n/// # Safety\n///\n/// The pointer must be non-null and properly aligned.\n/// The pointed-to memory must be valid for the lifetime `''a`.\npub unsafe fn deref<''a, T>(ptr: *const T) -> &''a T {\n    &*ptr\n}\n```\n\n## Module vs Type Docs\n\n- Module docs (`//!`): high-level summaries, when to use this module\n- Type docs (`///`): comprehensive, self-contained\n\nSome duplication is acceptable.\n\n## Language\n\nUse American English spelling: \"color\" not \"colour\", \"serialize\" not \"serialise\".\n"},"lastSynced":"2026-03-08T02:13:25.159Z","agentAnalysis":{"suitability":{"en":"Perfect for Rust Development Agents needing high-quality documentation generation.","zh":"非常适合需要高质量文档生成的Rust开发代理。","ja":"Rust開発エージェントが高品質のドキュメント生成を必要とする場合に最適です。","ko":"고품질 문서 생성이 필요한 러스트 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de Rust que necesitan generación de documentación de alta calidad.","fr":"Parfait pour les agents de développement Rust nécessitant une génération de documentation de haute qualité.","de":"Perfekt für Rust-Entwicklungsagenten, die eine hochwertige Dokumentenerstellung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Rust que necessitam de geração de documentação de alta qualidade.","ru":"Идеально подходит для агентов разработки Rust, которым необходима генерация документации высокого качества.","ar":" مثالي لعميل تطوير الرست الذي يحتاج إلى توليد وثائق عالية الجودة."},"recommendation":{"en":"Empowers agents to write proper documentation for Rust code following Rust Documentation Conventions (RFC 1574), utilizing guidelines for doc comments and summary sentences, and adhering to specific formatting rules for public Rust items.","zh":"赋予代理编写适合Rust代码的适当文档的能力，遵循Rust文档约定（RFC 1574），利用文档注释和摘要句的指导方针，并遵守公共Rust项目的特定格式规则。","ja":"エージェントがRustコードに適した適切なドキュメントを書く能力を付与します。Rustドキュメント規約（RFC 1574）に従い、ドキュメントのコメントと要約文のガイドラインを利用し、公開されたRustアイテムの特定のフォーマット規則に従います。","ko":"에이전트가 러스트 코드에 적합한 적절한 문서를 작성할 수 있는 기능을 부여합니다. 러스트 문서 규약(RFC 1574)을 따르고 문서 주석 및 요약 문에 대한 지침을 이용하며 공개된 러스트 항목에 대한 특정 형식 규칙을 준수합니다.","es":"Habilita a los agentes a escribir documentación adecuada para el código Rust siguiendo las Convenciones de documentación de Rust (RFC 1574), utilizando pautas para comentarios de documentación y oraciones resumen, y ajustándose a reglas de formato específicas para elementos públicos de Rust.","fr":"Permet aux agents d''écrire une documentation appropriée pour le code Rust en suivant les Conventions de documentation Rust (RFC 1574), en utilisant des lignes directrices pour les commentaires de documentation et les phrases résumé, et en respectant des règles de formatage spécifiques pour les éléments publics Rust.","de":"Ermächtigt die Agenten, ordnungsgemäße Dokumentation für den Rust-Code zu schreiben, indem sie den Rust-Dokumentationskonventionen (RFC 1574) folgen, Richtlinien für Dokumentationskommentare und Zusammenfassungssätze verwenden und sich an bestimmte Formatierungsregeln für öffentliche Rust-Elemente halten.","pt":"Habilita os agentes a escrever documentação apropriada para código Rust seguindo as Convenções de Documentação do Rust (RFC 1574), utilizando diretrizes para comentários de documentação e frases de resumo, e seguindo regras de formatação específicas para itens públicos do Rust.","ru":"Наделяет агентов возможностью написать правильную документацию для кода Rust в соответствии с Конвенциями документации Rust (RFC 1574), используя рекомендации для комментариев документации и резюме предложений, и следуя определенным правилам форматирования для общедоступных элементов Rust.","ar":"يمكن الوكلاء من كتابة توثيق مناسب للكود الرست اتباعًا لاتفاقيات توثيق الرست (RFC 1574) ، باستخدام إرشادات للتعليقات التوضيحية وجمل الملخص ، والالتزام بقواعد تنسيق محددة لأغراض الرست العامة."},"useCases":{"en":["Generating documentation for Rust crates","Validating doc comments against RFC 1574","Automating documentation updates for Rust projects"],"zh":["为Rust包生成文档","验证文档注释是否符合RFC 1574","自动更新Rust项目的文档"],"ja":["Rustクレートのドキュメントを生成する","ドキュメントのコメントがRFC 1574に準拠していることを検証する","Rustプロジェクトのドキュメントを自動的に更新する"],"ko":["러스트 크레이트에 대한 문서 생성","문서 주석이 RFC 1574를 준수하는지 확인","러스트 프로젝트의 문서를 자동으로 업데이트"],"es":["Generación de documentación para crates de Rust","Validación de comentarios de documentación contra RFC 1574","Automatización de actualizaciones de documentación para proyectos de Rust"],"fr":["Génération de documentation pour les crates Rust","Validation des commentaires de documentation contre la RFC 1574","Automatisation des mises à jour de documentation pour les projets Rust"],"de":["Generierung von Dokumentation für Rust-Crates","Validierung von Dokumentationskommentaren gegen RFC 1574","Automatisierung von Dokumentationsaktualisierungen für Rust-Projekte"],"pt":["Geração de documentação para caixas Rust","Validação de comentários de documentação contra RFC 1574","Automação de atualizações de documentação para projetos Rust"],"ru":["Генерация документации для ящиков Rust","Проверка комментариев документации на соответствие RFC 1574","Автоматизация обновления документации для проектов Rust"],"ar":["توليد وثائق لصندوقيات الرست","التحقق من تعليقات الوثائق مقابل RFC 1574","آليّة تحديث الوثائق لمشاريع الرست"]},"limitations":{"en":["Requires Rust codebase","Adherence to Rust Documentation Conventions (RFC 1574)"],"zh":["需要Rust代码库","遵守Rust文档约定（RFC 1574）"],"ja":["Rustコードベースが必要","Rustドキュメント規約（RFC 1574）に準拠"],"ko":["러스트 코드베이스가 필요","러스트 문서 규약(RFC 1574)을 준수"],"es":["Requiere base de código Rust","Adhesión a las Convenciones de documentación de Rust (RFC 1574)"],"fr":["Nécessite une base de code Rust","Conformité aux Conventions de documentation Rust (RFC 1574)"],"de":["Benötigt Rust-Codebasis","Einhaltung der Rust-Dokumentationskonventionen (RFC 1574)"],"pt":["Requer base de código Rust","Aderência às Convenções de Documentação do Rust (RFC 1574)"],"ru":["Требуется база кода Rust","Соблюдение Конвенций документации Rust (RFC 1574)"],"ar":["يتطلب قاعدة كود الرست","الامتثال لاتفاقيات توثيق الرست (RFC 1574)"]},"version":4},"contentHash":"e98bcd1db4a98ae378833ddda62fb160c017479feae64aa138d2e04baa2f2836","qualityScore":48}');
