INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('uwu/flora/rustdoc', 'rustdoc', 'uwu', 'flora', 'community', 'rustdoc uwu flora community rustdoc helps Rust developers write proper documentation for their code. It provides guidelines for writing doc comments that follow Rust Documentation Conventions (RFC 1574). Rustdoc 是一种用于生成 Rust 代码文档的工具，通过遵循特定的文档约定可以提高代码质量 Rustdoc は Rust コードの文書化に使用されるツールです - AIエージェント開発 Rustdoc은 러스트 코드 문서화에 사용되는 도구로, 특정 문서 규칙을 준수하면 코드 품질을 높일 수 있습니다 Rustdoc es una herramienta para documentar código Rust. Permite crear documentación clara y concisa para tus proyectos Rustdoc est un outil pour documenter du code Rust. Il permet de créer une documentation claire et concise pour vos projets Rustdoc ist ein Tool zur Dokumentation von Rust-Code. Es ermöglicht die Erstellung klarer und präziser Dokumentationen für Ihre Projekte O Rustdoc é uma ferramenta essencial para documentar código Rust. Aprenda a usá-lo para melhorar a produtividade do seu time Rustdoc - это важнейший инструмент для документирования кода на Rust. Узнайте, как им пользоваться, чтобы повысить производительность вашей команды رسومات روست هي أداة أساسية لتوثيق شفرة روست. تعلم كيفية استخدامها لتحسين إنتاجية فريقك how to use rustdoc rustdoc documentation conventions rustdoc vs rust book rustdoc install guide rustdoc setup for rust developers what is rustdoc rustdoc alternative tools rustdoc best practices Rustdoc RFC 1574 文档约定 代码质量 Rust 代码文档 文档注释 第三人称单数现在时态 Applies Rust Documentation Conventions (RFC 1574) for consistent documentation Enforces the use of third person singular present indicative in summary sentences Requires a period at the end of summary sentences for proper grammar Supports documentation of public Rust items with proper formatting Provides guidelines for writing clear and concise doc comments rustdoc is a documentation tool that helps Rust developers follow standard conventions for writing doc comments, ensuring clarity and consistency in their code documentation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('captjay98/gemini-livestockai/Property Testing', 'community', 'captjay98', 'gemini-livestockai', 'captjay98/gemini-livestockai', 'Property Testing', 0, 0, 48, '2026-03-08T01:57:15.638Z', '2026-03-08T02:13:40.024Z', '6be2fad4034eed3deb7e3c81678e8501379af7dfa2504a9050e9d2220d16a693', '{"id":"captjay98/gemini-livestockai/Property Testing","name":"Property Testing","description":{"en":"Property Testing validates business logic invariants using property-based testing with fast-check, benefiting AI agent developers. It ensures properties hold for all possible inputs.","zh":"属性测试是使用fast-check验证业务逻辑不变量的方法，提高代码质量和可靠性","ja":"プロパティテストは、fast-checkを使用してビジネスロジックの不変量を検証する方法であり、コードの品質と信頼性を向上させる","ko":"속성 테스트는 fast-check를 사용하여 비즈니스 논리의 불변량을 검증하는 방법으로, 코드 품질과 신뢰성을 향상시킵니다","es":"Property Testing es una técnica que utiliza pruebas de propiedades para validar la lógica de negocio en proyectos de IA. Utiliza fast-check para verificar invariantes.","fr":"Le test de propriétés est une technique qui utilise des tests de propriétés pour valider la logique métier dans les projets d''IA. Il utilise fast-check pour vérifier les invariants.","de":"Property Testing ist eine Technik, die Eigenschaftstests verwendet, um die Geschäftslogik in KI-Projekten zu validieren. Sie verwendet fast-check, um Invarianten zu überprüfen.","pt":"O teste de propriedades é uma técnica de teste que valida invariantes de lógica de negócios. A LivestockAI usa fast-check para testar propriedades.","ru":"Тестирование свойств - это метод тестирования, который проверяет инварианты бизнес-логики. LivestockAI использует fast-check для тестирования свойств.","ar":"اختبار الخواص هو تقنية اختبار تقوم بالتحقق من الثوابت المنطقية للأعمال. تستخدم LivestockAI سريع الفحص لاختبار الخواص."},"seo":{"title":{"en":"Property Testing: Fast-Check Validation for AI Agents | A...","zh":"属性测试Setup Guide - 使用fast-check验证业务逻辑","ja":"プロパティテストBest Practices - fast-checkを使用したビジネスロジックの検証","ko":"속성 테스트 설정 가이드 - fast-check를 사용한 비즈니스 논리 검증","es":"Guía de configuración de Property Testing para agentes de IA","fr":"Guide de mise en place du test de propriétés pour les out...","de":"Einrichtungsleitfaden für Property Testing in KI-Agents","pt":"Guia de Configuração de Teste de Propriedades com Ferrame...","ru":"Настройка тестирования свойств с помощью инструментов ИИ ...","ar":"دليل إعداد اختبار الخواص مع أدوات الإي أجهزة"},"description":{"en":"Unlock robust testing with Property Testing! Learn how to validate business logic invariants using fast-check and discover the power of property-based testin...","zh":"了解属性测试的概念和应用，使用fast-check验证业务逻辑不变量，提高代码质量","ja":"プロパティテストの概念と適用を学び、fast-checkを使用してビジネスロジックの不変量を検証する","ko":"속성 테스트의 개념과 적용을 배우고, fast-check를 사용하여 비즈니스 논리의 불변량을 검증하여 코드 품질을 향상시키세요","es":"Aprende a validar la lógica de negocio con property-based testing y fast-check en tus proyectos de IA","fr":"Découvrez comment valider la logique métier avec des tests de propriétés et fast-check dans vos projets d''IA","de":"Erfahren Sie, wie Sie die Geschäftslogik mit property-basiertem Testing und fast-check in Ihren KI-Projekten validieren","pt":"Aprenda a configurar testes de propriedades para validar lógica de negócios com ferramentas de IA e fast-check","ru":"Узнайте, как настроить тестирование свойств для проверки бизнес-логики с помощью инструментов ИИ Агентов и fast-check","ar":"تعرف على كيفية إعداد اختبار الخواص لتأكيد منطق الأعمال مع أدوات الإي أجهزة وسريع الفحص"},"definition":{"en":"Property Testing is a software testing approach that verifies properties hold for all possible inputs, using frameworks like fast-check.","zh":"属性测试是一种使用fast-check验证业务逻辑不变量的软件测试方法","ja":"プロパティテストは、fast-checkを使用してビジネスロジックの不変量を検証するソフトウェアテスト方法の一種である","ko":"속성 테스트는 fast-check를 사용하여 비즈니스 논리의 불변량을 검증하는 소프트웨어 테스트 방법의 일종입니다","es":"Property Testing es una técnica de pruebas que verifica que las propiedades se mantienen para todas las entradas posibles","fr":"Le test de propriétés est une technique de test qui vérifie que les propriétés sont maintenues pour toutes les entrées possibles","de":"Property Testing ist eine Testtechnik, die überprüft, ob die Eigenschaften für alle möglichen Eingaben erhalten bleiben","pt":"Teste de propriedades é uma técnica de teste que verifica se as propriedades são válidas para todas as entradas possíveis.","ru":"Тестирование свойств - это метод тестирования, который проверяет, являются ли свойства действительными для всех возможных входных данных.","ar":"اختبار الخواص هو طريقة اختبار تتحقق من صحة الخواص للجميع المدخلات الممكنة."},"features":{"en":["Validates business logic invariants using property-based testing","Utilizes fast-check for robust testing","Verifies properties for all possible inputs","Ensures correctness of calculations, such as FCR (Feed Conversion Ratio)","Supports TypeScript for test implementation","Integrates with testing frameworks like Jest"],"zh":["使用fast-check验证业务逻辑不变量","支持属性测试的 TypeScript 语法","提高代码质量和可靠性","减少手动测试的工作量","提高测试效率和覆盖率"],"ja":["fast-checkを使用してビジネスロジックの不変量を検証","プロパティテストのTypeScript構文をサポート","コードの品質と信頼性を向上させる","手動テストの作業量を減らす","テストの効率とカバレッジを向上させる"],"ko":["fast-check를 사용하여 비즈니스 논리의 불변량을 검증","속성 테스트의 TypeScript 구문을 지원","코드 품질과 신뢰성을 향상시킵니다","수동 테스트의 작업량을 줄입니다","테스트의 효율과 범위를 향상시킵니다"],"es":["Utiliza fast-check para validar la lógica de negocio","Verifica invariantes en la lógica de negocio","Pruebas de propiedades para todas las entradas posibles","Validación de la lógica de negocio en proyectos de IA","Integración con TypeScript para pruebas de propiedades"],"fr":["Utilise fast-check pour valider la logique métier","Vérifie les invariants dans la logique métier","Tests de propriétés pour toutes les entrées possibles","Validation de la logique métier dans les projets d''IA","Intégration avec TypeScript pour les tests de propriétés"],"de":["Verwendet fast-check, um die Geschäftslogik zu validieren","Überprüft Invarianten in der Geschäftslogik","Eigenschaftstests für alle möglichen Eingaben","Validierung der Geschäftslogik in KI-Projekten","Integration mit TypeScript für Eigenschaftstests"],"pt":["Uso de fast-check para testar propriedades","Validação de invariantes de lógica de negócios","Testes baseados em propriedades em vez de exemplos","Verificação de propriedades para todas as entradas possíveis","Implementação com TypeScript"],"ru":["Использование fast-check для тестирования свойств","Проверка инвариантов бизнес-логики","Тесты на основе свойств вместо примеров","Проверка свойств для всех возможных входных данных","Реализация на TypeScript"],"ar":["استخدام سريع الفحص لاختبار الخواص","التحقق من الثوابت المنطقية للأعمال","اختبارات قائمة على الخواص بدلاً من الأمثلة","التحقق من الخواص لجميع المدخلات الممكنة","تنفيذ بالتايب سكريبت"]},"keywords":{"en":["what is Property Testing","how to use Property Testing","Property Testing vs unit testing","Property Testing alternative to example-based testing","Property Testing setup guide","install Property Testing for AI agents","fast-check Property Testing tutorial","Property Testing for AI agent development","Property Testing best practices"],"zh":["属性测试","fast-check","业务逻辑不变量","TypeScript","软件测试","代码质量","AIエージェント","属性测试设置","属性测试教程"],"ja":["プロパティテスト","fast-check","ビジネスロジック不変量","TypeScript","ソフトウェアテスト","コード品質","AIエージェント","プロパティテスト設定","プロパティテストチュートリアル"],"ko":["속성 테스트","fast-check","비즈니스 논리 불변량","TypeScript","소프트웨어 테스트","코드 품질","AI 에이전트","속성 테스트 설정","속성 테스트 튜토리얼"],"es":["property testing","pruebas de propiedades","fast-check","validación de lógica de negocio","proyectos de IA","typescript","test de propiedad","agentes de IA","herramientas de IA"],"fr":["test de propriétés","tests de propriétés","fast-check","validation de la logique métier","projets d''IA","typescript","test de propriété","outils d''IA","agents d''IA"],"de":["property testing","eigenschaftstests","fast-check","validierung der geschäftslogik","ki-projekte","typescript","eigenschaftstest","ki-agenten","ki-tools"],"pt":["teste de propriedades","ferramentas de IA","fast-check","lógica de negócios","invariantes","TypeScript","testes baseados em propriedades"],"ru":["тестирование свойств","инструменты ИИ Агентов","fast-check","бизнес-логика","инварианты","TypeScript","тесты на основе свойств"],"ar":["اختبار الخواص","أدوات الإي أجهزة","سريع الفحص","منطق الأعمال","الثوابت","تايب سكريبت","اختبارات قائمة على الخواص"]}},"owner":"captjay98","repo":"gemini-livestockai","repoPath":"captjay98/gemini-livestockai","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.638Z","topics":[],"category":"community","skillMd":{"name":"Property Testing","description":"Property-based testing with fast-check for business logic validation","bodyPreview":"# Property Testing\n\nLivestockAI uses property-based testing (PBT) with fast-check to validate business logic invariants.\n\n## What is Property Testing?\n\nInstead of testing specific examples, property tests verify that properties hold for ALL possible inputs:\n\n```typescript\n// Example-based test\nit(''calculates FCR correctly'', () => {\n  expect(calculateFCR(150, 100)).toBe(1.5)\n})\n\n// Property-based test\nit(''FCR is always positive when inputs are positive'', () => {\n  fc.assert(\n    fc.property(","body":"# Property Testing\n\nLivestockAI uses property-based testing (PBT) with fast-check to validate business logic invariants.\n\n## What is Property Testing?\n\nInstead of testing specific examples, property tests verify that properties hold for ALL possible inputs:\n\n```typescript\n// Example-based test\nit(''calculates FCR correctly'', () => {\n  expect(calculateFCR(150, 100)).toBe(1.5)\n})\n\n// Property-based test\nit(''FCR is always positive when inputs are positive'', () => {\n  fc.assert(\n    fc.property(\n      fc.float({ min: 0.1, max: 10000 }),\n      fc.float({ min: 0.1, max: 10000 }),\n      (feed, weight) => {\n        const fcr = calculateFCR(feed, weight)\n        return fcr === null || fcr > 0\n      },\n    ),\n  )\n})\n```\n\n## fast-check Basics\n\n```typescript\nimport { describe, it, expect } from ''vitest''\nimport * as fc from ''fast-check''\n\ndescribe(''Property Tests'', () => {\n  it(''property holds for all inputs'', () => {\n    fc.assert(\n      fc.property(fc.integer({ min: 1, max: 100000 }), (quantity) => {\n        // Property must return true or throw\n        return quantity > 0\n      }),\n      { numRuns: 100 },\n    )\n  })\n})\n```\n\n## Common Arbitraries\n\n```typescript\n// Integers\nfc.integer({ min: 1, max: 100000 })\nfc.nat() // Non-negative integer\n\n// Floats\nfc.float({ min: 0, max: 10000 })\n\n// Strings\nfc.string()\nfc.uuid()\n\n// Arrays\nfc.array(fc.integer(), { minLength: 0, maxLength: 20 })\n\n// Objects\nfc.record({\n  quantity: fc.integer({ min: 1, max: 1000 }),\n  price: fc.float({ min: 0, max: 10000 }),\n})\n```\n\n## Inventory Invariant Example\n\nFrom `tests/features/batches/batches.property.test.ts`:\n\n```typescript\n/**\n * Property 4: Inventory Invariant\n * For any batch, current_quantity SHALL always equal:\n * initial_quantity - sum(mortality) - sum(sales)\n */\ndescribe(''Property 4: Inventory Invariant'', () => {\n  it(''current_quantity equals initial - mortalities - sales'', () => {\n    fc.assert(\n      fc.property(\n        fc.integer({ min: 1, max: 100000 }),\n        fc.array(fc.integer({ min: 1, max: 1000 })),\n        fc.array(fc.integer({ min: 1, max: 1000 })),\n        (initial, mortalities, sales) => {\n          const { constrained } = constrainQuantities(\n            initial,\n            mortalities,\n            sales,\n          )\n          const current = calculateCurrentQuantity(initial, constrained)\n\n          expect(current).toBeGreaterThanOrEqual(0)\n          expect(current).toBeLessThanOrEqual(initial)\n        },\n      ),\n      { numRuns: 100 },\n    )\n  })\n})\n```\n\n## Linking to Requirements\n\nAnnotate tests with requirement links:\n\n```typescript\n/**\n * **Validates: Requirements 3.2, 4.2, 8.2**\n */\nit(''inventory invariant holds'', () => {\n  // ...\n})\n```\n\n## When to Use Property Testing\n\n- Mathematical calculations (FCR, mortality rate, profit)\n- Invariants (quantity never negative, totals match)\n- State transitions (batch status changes)\n- Data transformations (currency conversion)\n\n## Related Skills\n\n- `vitest-patterns` - Unit testing basics\n- `three-layer-architecture` - Service layer testing\n"},"lastSynced":"2026-03-08T02:13:40.024Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing advanced property-based testing capabilities with fast-check","zh":"非常适合需要使用 fast-check 进行高级属性基于测试的 AI Agent 开发人员","ja":"fast-check を使用した高度なプロパティベースのテスト機能を必要とする AI エージェント開発者に最適","ko":"fast-check를 사용한 고급 속성 기반 테스트 기능이 필요한 AI 에이전트 개발자를 위한 완벽한 솔루션","es":"Ideal para desarrolladores de Agentes de IA que necesitan capacidades de prueba avanzadas basadas en propiedades con fast-check","fr":"Parfait pour les développeurs d''agents IA ayant besoin de capacités de test avancées basées sur les propriétés avec fast-check","de":"Perfekt für AI-Agent-Entwickler, die erweiterte Eigenschaftsbasiert-Testfunktionen mit fast-check benötigen","pt":"Perfeito para desenvolvedores de Agentes de IA que necessitam de capacidades avançadas de teste baseado em propriedades com fast-check","ru":"Идеально для разработчиков агентов ИИ, которым требуются продвинутые возможности тестирования на основе свойств с помощью fast-check","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يحتاجون إلى إمكانيات متقدمة لاختبار القائم على الخصائص مع fast-check"},"recommendation":{"en":"Empowers agents to validate business logic invariants using property-based testing with fast-check, ensuring properties hold for all possible inputs via fc.assert and fc.property, and leveraging TypeScript for robust testing","zh":"赋予代理验证业务逻辑不变量使用属性基于测试与 fast-check，确保属性对所有可能的输入保持不变通过 fc.assert 和 fc.property，并利用 TypeScript 进行强大的测试","ja":"エージェントに、fast-check を使用したプロパティベースのテストでビジネスロジックの不変量を検証する能力を与え、fc.assert と fc.property を使用してすべての可能な入力でプロパティが保持されることを保証し、TypeScript を使用して堅牢なテストを実現する","ko":"에이전트가 fast-check를 사용한 속성 기반 테스트로 비즈니스 논리 불변식을 검증할 수 있도록 하여 fc.assert와 fc.property를 통해 모든 가능한 입력에서 속성이 유지되는 것을 보장하고, TypeScript를 통해 강력한 테스트를 제공함","es":"Habilita a los agentes a validar invariantes de lógica de negocio utilizando pruebas basadas en propiedades con fast-check, garantizando que las propiedades se cumplan para todas las entradas posibles a través de fc.assert y fc.property, y aprovechando TypeScript para pruebas robustas","fr":"Permet aux agents de valider les invariants de logique métier en utilisant des tests basés sur les propriétés avec fast-check, en garantissant que les propriétés sont valables pour toutes les entrées possibles via fc.assert et fc.property, et en exploitant TypeScript pour des tests robustes","de":"Ermächtigt Agenten, Unternehmenslogik-Invarianten mithilfe von Eigenschaftsbasiert-Tests mit fast-check zu überprüfen, indem sichergestellt wird, dass Eigenschaften für alle möglichen Eingaben über fc.assert und fc.property gelten und TypeScript für robuste Tests nutzt","pt":"Habilita os agentes a validar invariantes de lógica de negócios usando teste baseado em propriedades com fast-check, garantindo que as propriedades sejam válidas para todas as entradas possíveis via fc.assert e fc.property, e aproveitando o TypeScript para testes robustos","ru":"Позволяет агентам проверять инварианты бизнес-логики с помощью тестирования на основе свойств с помощью fast-check, гарантируя, что свойства остаются действительными для всех возможных входных данных через fc.assert и fc.property, и использует TypeScript для надёжного тестирования","ar":"تمكين الوكلاء من التحقق من البرامج الثابتة لمنطق الأعمال باستخدام اختبار القائم على الخصائص مع fast-check، وضمان صحة الخصائص لجميع الإدخالات المحتملة عبر fc.assert و fc.property، وتحقيق TypeScript لاختبارات قوية"},"useCases":{"en":["Validating complex business logic","Testing mathematical functions for correctness","Ensuring data integrity across various input scenarios"],"zh":["验证复杂的业务逻辑","测试数学函数的正确性","确保在各种输入场景中数据的完整性"],"ja":["複雑なビジネスロジックの検証","数学関数の正しさのテスト","様々な入力シナリオでデータの完全性を確保"],"ko":["복잡한 비즈니스 논리의 검증","수학 함수의 올바름 테스트","다양한 입력 시나리오에서 데이터 무결성을 보장"],"es":["Validar lógica de negocio compleja","Probar funciones matemáticas para la corrección","Garantizar la integridad de los datos en varios escenarios de entrada"],"fr":["Valider la logique métier complexe","Tester les fonctions mathématiques pour la correction","Assurer l''intégrité des données dans différents scénarios d''entrée"],"de":["Komplexe Geschäftlogik überprüfen","Mathematische Funktionen auf Korrektheit testen","Datenintegrität in verschiedenen Eingabeszenarien sicherstellen"],"pt":["Validar lógica de negócios complexa","Testar funções matemáticas para correção","Garantir integridade de dados em vários cenários de entrada"],"ru":["Проверка сложной бизнес-логики","Тестирование математических функций на правильность","Обеспечение целостности данных в различных сценариях входных данных"],"ar":["التحقق من منطق الأعمال المعقد","اختبار الدوال الرياضية للصحة","ضمان سلامة البيانات في سيناريوهات الإدخال المختلفة"]},"limitations":{"en":["Requires fast-check library integration","Limited to property-based testing scenarios","TypeScript compatibility required"],"zh":["需要 fast-check 库集成","仅限于属性基于测试场景","需要 TypeScript 兼容性"],"ja":["fast-check ライブラリの統合が必要","プロパティベースのテストシナリオのみ","TypeScript との互換性が必要"],"ko":["fast-check 라이브러리 통합이 필요","속성 기반 테스트 시나리오에만 한정","TypeScript와의 호환성이 필요"],"es":["Requiere la integración de la biblioteca fast-check","Limitado a escenarios de pruebas basadas en propiedades","Se requiere compatibilidad con TypeScript"],"fr":["Nécessite l''intégration de la bibliothèque fast-check","Limité aux scénarios de tests basés sur les propriétés","Compatibilité avec TypeScript requise"],"de":["Erfordert die Integration der fast-check-Bibliothek","Begrenzt auf Szenarien von Eigenschaftsbasiert-Tests","TypeScript-Kompatibilität erforderlich"],"pt":["Requer integração com a biblioteca fast-check","Limitado a cenários de teste baseado em propriedades","Compatibilidade com TypeScript necessária"],"ru":["Требует интеграции с библиотекой fast-check","Ограничен тестированием на основе свойств","Требуется совместимость с TypeScript"],"ar":["يتطلب دمجًا مع مكتبة fast-check","محدود بالسيناريوهات التي تتم على أساس اختبار الخصائص","يتطلب توافقًا مع TypeScript"]},"version":4},"contentHash":"6be2fad4034eed3deb7e3c81678e8501379af7dfa2504a9050e9d2220d16a693","qualityScore":48}');
