INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('captjay98/gemini-livestockai/Property Testing', 'Property Testing', 'captjay98', 'gemini-livestockai', 'community', 'Property Testing captjay98 gemini-livestockai community Property Testing validates business logic invariants using property-based testing with fast-check, benefiting AI agent developers. It ensures properties hold for all possible inputs. 属性测试是使用fast-check验证业务逻辑不变量的方法，提高代码质量和可靠性 プロパティテストは、fast-checkを使用してビジネスロジックの不変量を検証する方法であり、コードの品質と信頼性を向上させる 속성 테스트는 fast-check를 사용하여 비즈니스 논리의 불변량을 검증하는 방법으로, 코드 품질과 신뢰성을 향상시킵니다 Property Testing es una técnica que utiliza pruebas de propiedades para validar la lógica de negocio en proyectos de IA. Utiliza fast-check para verificar invariantes. Le test de propriétés est une technique qui utilise des tests de propriétés pour valider la logique métier dans les projets d''IA. Il utilise fast-check pour vérifier les invariants. Property Testing ist eine Technik, die Eigenschaftstests verwendet, um die Geschäftslogik in KI-Projekten zu validieren. Sie verwendet fast-check, um Invarianten zu überprüfen. O teste de propriedades é uma técnica de teste que valida invariantes de lógica de negócios. A LivestockAI usa fast-check para testar propriedades. Тестирование свойств - это метод тестирования, который проверяет инварианты бизнес-логики. LivestockAI использует fast-check для тестирования свойств. اختبار الخواص هو تقنية اختبار تقوم بالتحقق من الثوابت المنطقية للأعمال. تستخدم LivestockAI سريع الفحص لاختبار الخواص. what is Property Testing how to use Property Testing Property Testing vs unit testing Property Testing alternative to example-based testing Property Testing setup guide install Property Testing for AI agents fast-check Property Testing tutorial Property Testing for AI agent development Property Testing best practices 属性测试 fast-check 业务逻辑不变量 TypeScript 软件测试 代码质量 AIエージェント 属性测试设置 属性测试教程 Validates business logic invariants using property-based testing Utilizes fast-check for robust testing Verifies properties for all possible inputs Ensures correctness of calculations, such as FCR (Feed Conversion Ratio) Supports TypeScript for test implementation Integrates with testing frameworks like Jest Property Testing is a software testing approach that verifies properties hold for all possible inputs, using frameworks like fast-check.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tuist/tuist/using-tuist-generated-projects', 'community', 'tuist', 'tuist', 'tuist/tuist', 'using-tuist-generated-projects', 0, 0, 48, '2026-03-08T01:57:15.646Z', '2026-03-08T02:13:46.650Z', 'b378a819ded936a3a745a7ca3d93de381765d0cc627a9b4922e0d73070443846', '{"id":"tuist/tuist/using-tuist-generated-projects","name":"using-tuist-generated-projects","description":{"en":"The using-tuist-generated-projects skill enables mobile developers to efficiently manage projects. It provides a virtual platform team for generating and building projects.","zh":"Tuist生成项目提供了一种便捷的方式来管理移动开发项目，包括快速开始和项目定义","ja":"Tuist生成プロジェクトは、xcodebuildとCLIを使用してモバイル開発プロジェクトを管理するためのプラットフォームです","ko":"Tuist 생성 프로젝트는 모바일 개발 프로젝트를 관리하기 위한 가상 플랫폼 팀입니다","es":"Tuist es una plataforma virtual para desarrolladores móviles que permite generar proyectos de manera eficiente","fr":"Tuist est une plateforme virtuelle pour les développeurs mobiles qui permet de générer des projets de manière efficace","de":"Tuist ist eine virtuelle Plattform für Mobile-Entwickler, die es ermöglicht, Projekte effizient zu generieren","pt":"O Tuist é uma plataforma virtual para desenvolvedores móveis que desejam gerar projetos com eficiência. Aprenda a configurar e executar projetos com facilidade.","ru":"Tuist - это виртуальная платформа для мобильных разработчиков, которые хотят генерировать проекты с эффективностью. Узнайте, как настроить и запустить проекты с легкостью.","ar":"Tuist هي منصة افتراضية لمطوري التطبيقات المحمولة الذين يرغبون في تشغيل مشاريع بفعالية. تعرف على كيفية ضبط وتنفيذ المشاريع بسهولة"},"seo":{"title":{"en":"using-tuist-generated-projects: Tuist Project Setup Guide...","zh":"使用Tuist生成项目的最佳实践","ja":"Tuist生成プロジェクトのセットアップガイド - AIエージェント","ko":"Tuist 생성 프로젝트 설정 가이드 - AI 도구","es":"Guía de configuración de proyectos generados con Tuist","fr":"Guide de démarrage rapide pour les projets Tuist générés","de":"Setup-Leitfaden für Tuist-erzeugte Projekte","pt":"Guia de Configuração do Tuist para Projetos Móveis","ru":"Настройка Tuist для Мобильных Проектов: ИИ Агенты","ar":"دليل الإعداد لتشغيل مشاريع Tuist المحمولة"},"description":{"en":"Discover how to leverage Tuist-generated projects for streamlined mobile development. Learn to generate workspaces, build schemes, and run tests with ease.","zh":"了解如何使用Tuist生成项目，包括快速开始、项目定义和构建可执行文件夹","ja":"Tuist生成プロジェクトの使い方を学ぶ - xcodebuildとCLIの使用方法","ko":"Tuist 생성 프로젝트를 설정하는 방법을 알아보세요 - 프로젝트 정의와 빌드 가능 폴더","es":"Aprenda a utilizar proyectos generados con Tuist para mejorar su flujo de trabajo de desarrollo móvil","fr":"Découvrez comment utiliser les projets générés par Tuist pour améliorer votre flux de travail de développement mobile","de":"Erfahren Sie, wie Sie Tuist-erzeugte Projekte verwenden können, um Ihren mobilen Entwicklungsprozess zu optimieren","pt":"Aprenda a usar o Tuist para gerar projetos móveis com eficiência. Descubra como configurar e executar projetos com facilidade.","ru":"Узнайте, как использовать Tuist для генерации мобильных проектов. Настройте и запустите проекты с легкостью с помощью ИИ Агентов.","ar":"تعرف على كيفية استخدام Tuist لتشغيل مشاريع المحمول بفعالية. اكتشف كيفية ضبط وتنفيذ المشاريع بسهولة"},"definition":{"en":"using-tuist-generated-projects is a skill that utilizes Tuist to generate and manage mobile development projects, facilitating efficient workspace creation and scheme building.","zh":"Tuist生成项目是一种使用Tuist工具生成和管理移动开发项目的方法","ja":"Tuist生成プロジェクトは、Tuistツールを使用してモバイル開発プロジェクトを生成して管理するための手法です","ko":"Tuist 생성 프로젝트는 Tuist 도구를 사용하여 모바일 개발 프로젝트를 생성하고 관리하는 방법입니다","es":"Un proyecto generado con Tuist es un conjunto de archivos y configuraciones creados automáticamente para facilitar el desarrollo móvil","fr":"Un projet généré par Tuist est un ensemble de fichiers et de configurations créés automatiquement pour faciliter le développement mobile","de":"Ein mit Tuist erzeugtes Projekt ist eine Sammlung von Dateien und Konfigurationen, die automatisch erstellt werden, um die mobile Entwicklung zu erleichtern","pt":"O que é Tuist? É uma ferramenta para gerar projetos móveis com buildable folders e sources.","ru":"Что такое Tuist? Это инструмент для генерации мобильных проектов с buildable folders и sources.","ar":"ما هو Tuist؟ هو أداة لتشغيل مشاريع المحمول مع مجلدات قابلة للبناء ومصادر"},"features":{"en":["Generates workspace without opening Xcode using `tuist generate --no-open` command","Builds a scheme with `xcodebuild` command for streamlined project development","Runs tests with `xcodebuild test` command for efficient quality assurance","Utilizes `buildableFolders` for synchronized project structure","Supports project definition using `App.xcworkspace` and `AppTests` schemes"],"zh":["快速开始：使用tuist generate --no-open生成工作区","项目定义：使用buildableFolders代替sources和resources globs","构建可执行文件夹：使用xcodebuild build和xcodebuild test","运行测试：使用xcodebuild test -only-testing","使用CLI管理项目"],"ja":["クイックスタート：tuist generate --no-openを使用してワークスペースを生成","プロジェクト定義：buildableFoldersを使用してsourcesとresources globsを置き換える","ビルド可能フォルダの構築：xcodebuild buildとxcodebuild testを使用","テストの実行：xcodebuild test -only-testingを使用","CLIを使用してプロジェクトを管理"],"ko":["快速 시작：tuist generate --no-open을 사용하여 작업 공간 생성","프로젝트 정의：buildableFolders를 사용하여 sources와 resources globs를 대체","빌드 가능 폴더의構築：xcodebuild build와 xcodebuild test를 사용","테스트 실행：xcodebuild test -only-testing을 사용","CLI를 사용하여 프로젝트 관리"],"es":["Generación de espacios de trabajo sin abrir Xcode","Compilación de esquemas con xcodebuild","Ejecución de pruebas con xcodebuild","Uso de carpetas compilables en lugar de fuentes y recursos","Sincronización de carpetas compilables"],"fr":["Génération d''espaces de travail sans ouvrir Xcode","Compilation de schémas avec xcodebuild","Exécution de tests avec xcodebuild","Utilisation de dossiers compilables au lieu de sources et de ressources","Synchronisation de dossiers compilables"],"de":["Generierung von Arbeitsbereichen ohne Xcode zu öffnen","Kompilierung von Schemata mit xcodebuild","Ausführung von Tests mit xcodebuild","Verwendung von kompilierbaren Ordnern anstelle von Quellen und Ressourcen","Synchronisation von kompilierbaren Ordnern"],"pt":["Geração de projetos móveis com buildable folders","Uso de xcodebuild para build e testar projetos","Suporte a schemes e targets no Xcode","Configuração de projetos com tuist generate --no-open","Execução de testes com xcodebuild test"],"ru":["Генерация мобильных проектов с buildable folders","Использование xcodebuild для сборки и тестирования проектов","Поддержка схем и целей в Xcode","Настройка проектов с tuist generate --no-open","Запуск тестов с xcodebuild test"],"ar":["إنشاء مشاريع المحمول مع مجلدات قابلة للبناء","استخدام xcodebuild لتشغيل واختبار المشاريع","دعم مخططات وأهداف في Xcode","ضبط المشاريع مع tuist generate --no-open","تشغيل الاختبارات مع xcodebuild test"]},"keywords":{"en":["how to use using-tuist-generated-projects","what is using-tuist-generated-projects","using-tuist-generated-projects alternative","using-tuist-generated-projects vs fastlane","using-tuist-generated-projects install","using-tuist-generated-projects setup guide","tuist project generation","xcodebuild command"],"zh":["Tuist生成项目","移动开发","xcodebuild","CLI","构建可执行文件夹","运行测试","项目定义","buildableFolders","Tuist工具"],"ja":["Tuist生成プロジェクト","モバイル開発","xcodebuild","CLI","ビルド可能フォルダ","テストの実行","プロジェクト定義","buildableFolders","Tuistツール","AIエージェント"],"ko":["Tuist 생성 프로젝트","모바일 개발","xcodebuild","CLI","빌드 가능 폴더","테스트 실행","프로젝트 정의","buildableFolders","Tuist 도구","AI 도구"],"es":["proyectos generados con Tuist","desarrollo móvil","xcodebuild","compilación de esquemas","ejecución de pruebas","carpetas compilables","Herramientas de desarrollo móvil","Tuist para desarrolladores"],"fr":["projets générés par Tuist","développement mobile","xcodebuild","compilation de schémas","exécution de tests","dossiers compilables","Outils de développement mobile","Tuist pour les développeurs"],"de":["mit Tuist erzeugte Projekte","mobile Entwicklung","xcodebuild","Kompilierung von Schemata","Ausführung von Tests","kompilierbare Ordner","Mobile-Entwicklertools","Tuist für Entwickler"],"pt":["tuist","projetos móveis","buildable folders","xcodebuild","schemes","targets","testes","desenvolvimento móvel","ferramentas de desenvolvimento"],"ru":["tuist","мобильные проекты","buildable folders","xcodebuild","схемы","цели","тесты","мобильная разработка","инструменты разработки","ИИ Агенты"],"ar":["tuist","مشاريع المحمول","مجلدات قابلة للبناء","xcodebuild","مخططات","أهداف","اختبارات","تطوير المحمول","أدوات التطوير","وكلاء الذكاء الاصطناعي"]}},"owner":"tuist","repo":"tuist","repoPath":"tuist/tuist","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.646Z","topics":[],"category":"community","skillMd":{"name":"using-tuist-generated-projects","description":"Guides day-to-day work in Tuist-generated Xcode workspaces, including generation, build and test commands, and buildable folders. Use when working in a Tuist-generated project or when users mention `tuist generate`, `xcodebuild test`, or generated workspaces.","bodyPreview":"# Using Tuist Generated Projects\n\n## Quick Start\n\n```bash\n# Generate workspace without opening Xcode\ntuist generate --no-open\n\n# Build a scheme with xcodebuild\nxcodebuild build -workspace App.xcworkspace -scheme App\n\n# Run tests with xcodebuild\nxcodebuild test -workspace App.xcworkspace -scheme AppTests -only-testing AppTests/MyTestCase\n```\n\n## Project definition\n\n### Prefer buildable folders\n\nUse `buildableFolders` instead of `sources` and `resources` globs. Buildable folders stay synchronized","body":"# Using Tuist Generated Projects\n\n## Quick Start\n\n```bash\n# Generate workspace without opening Xcode\ntuist generate --no-open\n\n# Build a scheme with xcodebuild\nxcodebuild build -workspace App.xcworkspace -scheme App\n\n# Run tests with xcodebuild\nxcodebuild test -workspace App.xcworkspace -scheme AppTests -only-testing AppTests/MyTestCase\n```\n\n## Project definition\n\n### Prefer buildable folders\n\nUse `buildableFolders` instead of `sources` and `resources` globs. Buildable folders stay synchronized with the file system, so adding or removing files does not require regeneration.\n\n```swift\nlet target = Target(\n  name: \"App\",\n  buildableFolders: [\n    \"App/Sources\",\n    \"App/Resources\",\n  ]\n)\n```\n\n### Tag targets for focus\n\nUse target tags to group areas of the project, for example:\n\n- `tag:team:*`\n- `tag:feature:*`\n- `tag:layer:*`\n\nThese tags make it easier to scope generation and testing later.\n\nExample target metadata with tags:\n\n```swift\nlet target = Target(\n  name: \"PaymentsUI\",\n  metadata: .metadata(tags: [\n    \"tag:team:commerce\",\n    \"tag:feature:payments\",\n    \"tag:layer:ui\",\n  ])\n)\n```\n\nWhen working on a focused area, generate only what you need:\n\n```bash\ntuist generate tag:feature:payments\ntuist generate PaymentsUI PaymentsTests\n```\n\n### Align build configurations\n\nKeep build configurations aligned between the project and external dependencies. Use `PackageSettings(settings: .settings(configurations: []))` to mirror project configurations; mismatches emit warnings.\n\n## Workflows\n\n### Generate intentionally\n\n- Use `tuist generate --no-open` in automation and scripts to avoid launching Xcode.\n- Regenerate when any manifest changes (or the dependency graph changes).\n- If generation fails due to missing products, run `tuist install` to resolve dependencies and retry.\n\n### Build with xcodebuild\n\nUse `xcodebuild build` against the generated workspace and scheme.\n\n```bash\nxcodebuild build \\\n  -workspace App.xcworkspace \\\n  -scheme App \\\n  -destination \"generic/platform=iOS Simulator\"\n```\n\n### Test with xcodebuild\n\nUse `xcodebuild test` for running tests locally. Prefer it over `tuist test` because `tuist test` regenerates the project on each invocation, which slows down iteration.\n\nTo optimize test run time:\n\n- **Use `--only-testing`** to run only the specific test suite or test case you are working on, instead of the full target.\n- **Pick the scheme with the fewest compilation targets** that still includes the test target you need. This minimizes build time before tests run.\n\n```bash\n# Run a specific test suite\nxcodebuild test \\\n  -workspace App.xcworkspace \\\n  -scheme AppTests \\\n  -only-testing AppTests/MyTestSuite\n\n# Run a single test case\nxcodebuild test \\\n  -workspace App.xcworkspace \\\n  -scheme AppTests \\\n  -only-testing AppTests/MyTestSuite/testMyFunction\n```\n\n## Guidelines\n\n- Keep `buildableFolders` paths aligned to the target''s real file system layout.\n- Avoid overlapping `buildableFolders` with `sources` or `resources` globs in the same target.\n- Open Xcode manually when needed after running `tuist generate --no-open`.\n\n## Troubleshooting\n\n**Static side effects warnings:** adjust product types deliberately. Use `Target.product` for local targets and `PackageSettings(productTypes:)` for external products. Making everything dynamic with `.framework` can compile and run, but it may hurt launch time. Prefer static products (static frameworks or libraries) when possible and when they do not introduce side effects.\n\n**Objective-C dependency crashes:** add `-ObjC` or `-force_load` via `OTHER_LDFLAGS` on consuming targets as needed. Reference: `https://docs.tuist.dev/en/guides/features/projects/dependencies#objectivec-dependencies`.\n"},"lastSynced":"2026-03-08T02:13:46.650Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile Development Agents needing efficient project management and automation with Tuist and Xcode","zh":"非常适合需要使用Tuist和Xcode进行高效项目管理和自动化的移动开发代理","ja":"TuistとXcodeを使用した効率的なプロジェクト管理と自動化が必要なモバイル開発エージェントに最適","ko":"Tuist와 Xcode를 사용하여 효율적인 프로젝트 관리 및 자동화를 필요로 하는 모바일 개발 에이전트에게 완벽함","es":"Perfecto para agentes de desarrollo móvil que necesitan una gestión de proyectos y automatización eficientes con Tuist y Xcode","fr":"Idéal pour les agents de développement mobile nécessitant une gestion de projet et une automatisation efficaces avec Tuist et Xcode","de":"Perfekt für Mobile Development Agents, die eine effiziente Projektverwaltung und Automatisierung mit Tuist und Xcode benötigen","pt":"Perfeito para Agentes de Desenvolvimento Móvel que necessitam de gerenciamento de projeto eficiente e automação com Tuist e Xcode","ru":"Идеально для Мобильных Разработчиков, которым необходим эффективный менеджмент проектов и автоматизация с помощью Tuist и Xcode","ar":"مثالي لعملاقة تطوير الهاتف المحمول التي تحتاج إلى إدارة مشروع فعالة وتأتمت مع Tuist و Xcode"},"recommendation":{"en":"Empowers agents to generate and build projects using Tuist, leveraging xcodebuild for seamless integration with Xcode, and supporting advanced project definition with buildable folders and scheme-based testing","zh":"授权代理使用Tuist生成和构建项目，利用xcodebuild实现与Xcode的无缝集成，并支持使用可构建文件夹和基于scheme的测试进行高级项目定义","ja":"エージェントがTuistを使用してプロジェクトを生成してビルドし、xcodebuildを使用してXcodeとシームレスに統合し、構築可能なフォルダとスキームベースのテストを使用した高度なプロジェクト定義をサポート","ko":"에이전트가 Tuist를 사용하여 프로젝트를 생성하고 빌드하며, xcodebuild를 사용하여 Xcode와의無缝한 통합을 지원하며, 빌드할 수 있는 폴더와 스키마 기반의 테스트를 사용한 고급 프로젝트 정의를 지원","es":"Habilita a los agentes a generar y compilar proyectos utilizando Tuist, aprovechando xcodebuild para una integración sin problemas con Xcode, y admitiendo una definición de proyecto avanzada con carpetas compilables y pruebas basadas en esquemas","fr":"Permet aux agents de générer et de construire des projets en utilisant Tuist, en exploitant xcodebuild pour une intégration transparente avec Xcode, et en prenant en charge une définition de projet avancée avec des dossiers constructibles et des tests basés sur des schémas","de":"Ermächtigt Agents, Projekte mit Tuist zu generieren und zu erstellen, indem xcodebuild für eine nahtlose Integration mit Xcode genutzt wird, und unterstützt eine erweiterte Projektdefinition mit compilierbaren Ordnern und schemabasiertem Testen","pt":"Habilita agentes a gerar e construir projetos usando Tuist, aproveitando xcodebuild para integração perfeita com Xcode, e apoiando definição avançada de projeto com pastas construíveis e testes baseados em esquemas","ru":"Наделяет агентов возможностью генерировать и строить проекты с помощью Tuist, используя xcodebuild для бесшовной интеграции с Xcode, и поддерживает расширенное определение проекта с помощью собираемых папок и тестирования на основе схем","ar":"تمكين الوكلاء من توليد و بناء المشاريع باستخدام Tuist ، واستخدام xcodebuild من أجل التكامل السلس مع Xcode ، ودعم تعريف مشروع متقدم مع مجلدات قابلة للبناء واختبارات قائمة على السchemes"},"useCases":{"en":["Generating workspace without opening Xcode","Building schemes with xcodebuild","Running tests with xcodebuild and scheme-based testing"],"zh":["在不打开Xcode的情况下生成工作区","使用xcodebuild构建scheme","使用xcodebuild和基于scheme的测试运行测试"],"ja":["Xcodeを開かずにワークスペースを生成","xcodebuildを使用してスキームをビルド","xcodebuildとスキームベースのテストを使用してテストを実行"],"ko":["Xcode를 열지 않고 작업 공간을 생성","xcodebuild를 사용하여 스키마 빌드","xcodebuild와 스키마 기반 테스트를 사용하여 테스트 실행"],"es":["Generar espacio de trabajo sin abrir Xcode","Compilar esquemas con xcodebuild","Ejecutar pruebas con xcodebuild y pruebas basadas en esquemas"],"fr":["Générer un espace de travail sans ouvrir Xcode","Construire des schémas avec xcodebuild","Exécuter des tests avec xcodebuild et des tests basés sur des schémas"],"de":["Arbeitsbereich ohne Öffnen von Xcode generieren","Schemata mit xcodebuild erstellen","Tests mit xcodebuild und schemabasiertem Testen ausführen"],"pt":["Geração de espaço de trabalho sem abrir o Xcode","Construção de esquemas com xcodebuild","Execução de testes com xcodebuild e testes baseados em esquemas"],"ru":["Генерация рабочего пространства без открытия Xcode","Строение схем с помощью xcodebuild","Выполнение тестов с помощью xcodebuild и тестирование на основе схем"],"ar":["توليد مساحة عمل بدون فتح Xcode","بناء مخططات باستخدام xcodebuild","تشغيل الاختبارات مع xcodebuild واختبارات قائمة على السchemes"]},"limitations":{"en":["Requires Tuist installation","Xcode and xcodebuild accessibility needed","Limited to projects compatible with Tuist and Xcode"],"zh":["需要安装Tuist","需要Xcode和xcodebuild的可访问性","仅限与Tuist和Xcode兼容的项目"],"ja":["Tuistのインストールが必要","Xcodeとxcodebuildのアクセスが必要","TuistとXcodeと互換性のあるプロジェクトのみ"],"ko":["Tuist 설치가 필요","Xcode 및 xcodebuild 액세스가 필요","Tuist 및 Xcode와 호환되는 프로젝트만"],"es":["Requiere instalación de Tuist","Se necesita accesibilidad de Xcode y xcodebuild","Limitado a proyectos compatibles con Tuist y Xcode"],"fr":["Nécessite l''installation de Tuist","L''accessibilité de Xcode et xcodebuild est nécessaire","Limité aux projets compatibles avec Tuist et Xcode"],"de":["Benötigt Tuist-Installation","Xcode- und xcodebuild-Zugriff erforderlich","Begrenzt auf mit Tuist und Xcode kompatible Projekte"],"pt":["Requer instalação do Tuist","Acessibilidade do Xcode e xcodebuild necessária","Limitado a projetos compatíveis com Tuist e Xcode"],"ru":["Требует установки Tuist","Необходим доступ к Xcode и xcodebuild","Ограничен проектами, совместимыми с Tuist и Xcode"],"ar":["يتطلب تثبيت Tuist","تحتاج إلى إمكانية الوصول إلى Xcode و xcodebuild","محدود بمشاريع متوافقة مع Tuist و Xcode"]},"version":4},"contentHash":"b378a819ded936a3a745a7ca3d93de381765d0cc627a9b4922e0d73070443846","qualityScore":48}');
