INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tuist/tuist/using-tuist-generated-projects', 'using-tuist-generated-projects', 'tuist', 'tuist', 'community', 'using-tuist-generated-projects tuist tuist community The using-tuist-generated-projects skill enables mobile developers to efficiently manage projects. It provides a virtual platform team for generating and building projects. Tuist生成项目提供了一种便捷的方式来管理移动开发项目，包括快速开始和项目定义 Tuist生成プロジェクトは、xcodebuildとCLIを使用してモバイル開発プロジェクトを管理するためのプラットフォームです Tuist 생성 프로젝트는 모바일 개발 프로젝트를 관리하기 위한 가상 플랫폼 팀입니다 Tuist es una plataforma virtual para desarrolladores móviles que permite generar proyectos de manera eficiente Tuist est une plateforme virtuelle pour les développeurs mobiles qui permet de générer des projets de manière efficace Tuist ist eine virtuelle Plattform für Mobile-Entwickler, die es ermöglicht, Projekte effizient zu generieren O Tuist é uma plataforma virtual para desenvolvedores móveis que desejam gerar projetos com eficiência. Aprenda a configurar e executar projetos com facilidade. Tuist - это виртуальная платформа для мобильных разработчиков, которые хотят генерировать проекты с эффективностью. Узнайте, как настроить и запустить проекты с легкостью. Tuist هي منصة افتراضية لمطوري التطبيقات المحمولة الذين يرغبون في تشغيل مشاريع بفعالية. تعرف على كيفية ضبط وتنفيذ المشاريع بسهولة how to use using-tuist-generated-projects what is using-tuist-generated-projects using-tuist-generated-projects alternative using-tuist-generated-projects vs fastlane using-tuist-generated-projects install using-tuist-generated-projects setup guide tuist project generation xcodebuild command Tuist生成项目 移动开发 xcodebuild CLI 构建可执行文件夹 运行测试 项目定义 buildableFolders Tuist工具 Generates workspace without opening Xcode using `tuist generate --no-open` command Builds a scheme with `xcodebuild` command for streamlined project development Runs tests with `xcodebuild test` command for efficient quality assurance Utilizes `buildableFolders` for synchronized project structure Supports project definition using `App.xcworkspace` and `AppTests` schemes using-tuist-generated-projects is a skill that utilizes Tuist to generate and manage mobile development projects, facilitating efficient workspace creation and scheme building.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wollfoo/setup-opencode/common', 'community', 'wollfoo', 'setup-opencode', 'wollfoo/setup-opencode', 'common', 0, 0, 48, '2026-03-08T01:57:15.647Z', '2026-03-08T02:13:49.066Z', '4dfa81b6e37ad8111f05064450a8039a9261ae6b8cb8b83d7975d534aa191f74', '{"id":"wollfoo/setup-opencode/common","name":"common","description":{"en":"The Common skill provides utilities for managing API keys and supporting Vertex AI, benefiting developers working with the Gemini API.","zh":"Common AI工具提供Gemini API Key管理、Vertex AI支持和Client Helpers等功能，帮助开发者简化AI开发流程","ja":"Common AIエージェントは、Gemini API Key管理、Vertex AIサポート、クライアントヘルパーなどの機能を提供し、AI開発プロセスを簡素化します","ko":"Common AI 에이전트는 Gemini API Key 관리, Vertex AI 지원, 클라이언트 헬퍼 등의 기능을 제공하여 AI 개발 프로세스를 간소화합니다","es":"La habilidad común es una biblioteca que ofrece utilidades compartidas para los desarrolladores de Agentes de IA, incluyendo gestión de claves API y soporte para Vertex AI","fr":"La compétence commune est une bibliothèque qui propose des utilitaires partagés pour les développeurs d''Outils d''IA, notamment la gestion des clés API et le support de Vertex AI","de":"Die gemeinsame Fähigkeit ist eine Bibliothek, die gemeinsam genutzte Utilitys für KI-Agents-Entwickler bietet, einschließlich API-Schlüsselverwaltung und Unterstützung für Vertex AI","pt":"O Common é uma biblioteca de utilitários de skill para Gemini API, oferecendo gerenciamento de chaves API, suporte a Vertex AI e ajudas de cliente","ru":"Common - это библиотека общих утилит для Gemini API и ИИ Агентов, предоставляющая управление ключами API, поддержку Vertex AI и помощь клиентам","ar":"Common هي مكتبة أدوات مهارات مشتركة لجيميني API ووكيلات الذكاء الاصطناعي، تقدم إدارة مفتاح API ودعم Vertex AI ومساعدة العميل"},"seo":{"title":{"en":"Common: API Key Management and Vertex AI Support | AI Age...","zh":"Common AI工具设置指南 - Gemini API K