INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wollfoo/setup-opencode/common', 'common', 'wollfoo', 'setup-opencode', 'community', 'common wollfoo setup-opencode community The Common skill provides utilities for managing API keys and supporting Vertex AI, benefiting developers working with the Gemini API. Common AI工具提供Gemini API Key管理、Vertex AI支持和Client Helpers等功能，帮助开发者简化AI开发流程 Common AIエージェントは、Gemini API Key管理、Vertex AIサポート、クライアントヘルパーなどの機能を提供し、AI開発プロセスを簡素化します Common AI 에이전트는 Gemini API Key 관리, Vertex AI 지원, 클라이언트 헬퍼 등의 기능을 제공하여 AI 개발 프로세스를 간소화합니다 La habilidad común es una biblioteca que ofrece utilidades compartidas para los desarrolladores de Agentes de IA, incluyendo gestión de claves API y soporte para Vertex AI La compétence commune est une bibliothèque qui propose des utilitaires partagés pour les développeurs d''Outils d''IA, notamment la gestion des clés API et le support de Vertex AI Die gemeinsame Fähigkeit ist eine Bibliothek, die gemeinsam genutzte Utilitys für KI-Agents-Entwickler bietet, einschließlich API-Schlüsselverwaltung und Unterstützung für Vertex AI O Common é uma biblioteca de utilitários de skill para Gemini API, oferecendo gerenciamento de chaves API, suporte a Vertex AI e ajudas de cliente Common - это библиотека общих утилит для Gemini API и ИИ Агентов, предоставляющая управление ключами API, поддержку Vertex AI и помощь клиентам Common هي مكتبة أدوات مهارات مشتركة لجيميني API ووكيلات الذكاء الاصطناعي، تقدم إدارة مفتاح API ودعم Vertex AI ومساعدة العميل how to use common skill common skill alternative common skill vs gemini api common skill install guide what is common skill common skill setup tutorial common skill and vertex ai common skill api key management common skill for ai agents Common AI工具 Gemini API Key管理 Vertex AI支持 Client Helpers Python开发 AI开发库 AI工具设置 API Key Management via automatic GEMINI_API_KEY detection Vertex AI Support for seamless AI Studio and Vertex AI transitions Client Helpers for automatic client initialization Compatibility with Python for streamlined development Integration with Gemini API for enhanced functionality Simplified client setup using sys and pathlib modules Common is a library that offers API key management and Vertex AI support for developers using the Gemini API.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kryptobaseddev/openclaw-cleo/sherpa-onnx-tts', 'community', 'kryptobaseddev', 'openclaw-cleo', 'kryptobaseddev/openclaw-cleo', 'sherpa-onnx-tts', 0, 0, 48, '2026-03-08T01:57:15.649Z', '2026-03-08T02:13:50.610Z', '4ed0e7d7b7711ccfece96fd8a13faade7ba97339c56df963490b7afe2418eb1b', '{"id":"kryptobaseddev/openclaw-cleo/sherpa-onnx-tts","name":"sherpa-onnx-tts","description":{"en":"sherpa-onnx-tts enables local text-to-speech functionality using the OpenClaw installer and CLEO task management. It benefits developers seeking automated LXC provisioning and Doppler secrets integration.","zh":"sherpa-onnx-tts 是一个本地 TTS 解决方案，使用 OpenClaw 安装程序和 CLEO 任务管理","ja":"sherpa-onnx-tts は、OpenClaw インストーラーと CLEO タスク管理を使用したローカル TTS ソリューションです","ko":"sherpa-onnx-tts는 OpenClaw 설치 프로그램과 CLEO 작업 관리를 사용하는 로컬 TTS 솔루션입니다","es":"sherpa-onnx-tts es una herramienta de voz de IA que utiliza OpenClaw y CLEO para la configuración de voz offline. Incluye integración con Doppler secrets y NGINX Proxy Manager","fr":"sherpa-onnx-tts est un outil de voix d''IA qui utilise OpenClaw et CLEO pour la configuration de voix hors ligne. Intégration avec secrets Doppler et NGINX Proxy Manager","de":"sherpa-onnx-tts ist ein KI-Sprachtool, das OpenClaw und CLEO für die Offline-Sprachkonfiguration verwendet. Integration mit Doppler-Geheimnissen und NGINX-Proxy-Manager","pt":"O sherpa-onnx-tts é uma ferramenta de instalação superpoderosa para Proxmox, com suporte a Doppler secrets e NGINX Proxy Manager","ru":"sherpa-onnx-tts - это супермощный инсталлятор для Proxmox, с поддержкой Doppler secrets и NGINX Proxy Manager","ar":"sherpa-onnx-tts هو أداة تثبيت قوية للغاية لبروكسيموكس، مع دعم لسرعات Doppler و NGINX Proxy Manager"},"seo":{"title":{"en":"sherpa-onnx-tts: Local TTS Setup Guide | AI Agent Skill","zh":"sherpa-onnx-tts 本地 TTS 安装指南","ja":"sherpa-onnx-tts ローカル TTS セットアップ ガイド","ko":"sherpa-onnx-tts 로컬 TTS 설치 가이드","es":"sherpa-onnx-tts: Guía de configuración para herramientas ...","fr":"sherpa-onnx-tts: Guide de configuration pour les outils d...","de":"sherpa-onnx-tts: Konfigurationsleitfaden für KI-Sprachtools","pt":"sherpa-onnx-tts: Guia de Instalação para Ferramentas de IA","ru":"sherpa-onnx-tts: Руководство по Установке для ИИ Агентов","ar":"sherpa-onnx-tts: دليل الإعداد لأدوات الإي الإلكترونية"},"description":{"en":"Unlock offline text-to-speech capabilities with sherpa-onnx-tts. Learn how to install and configure this AI agent skill for seamless LXC provisioning and NGI...","zh":"使用 sherpa-onnx-tts 实现本地 TTS 功能，集成 Doppler 秘钥和 NGINX 代理管理器","ja":"sherpa-onnx-tts を使用してローカル TTS 機能を実現し、Doppler キーと NGINX プロキシ マネージャーを統合する","ko":"sherpa-onnx-tts를 사용하여 로컬 TTS 기능을 구현하고 Doppler 키 및 NGINX 프록시 관리자를 통합합니다","es":"Aprende a configurar sherpa-onnx-tts para voz offline con OpenClaw y CLEO. Descubre cómo integrar Doppler secrets y NGINX Proxy Manager","fr":"Découvrez comment configurer sherpa-onnx-tts pour la voix hors ligne avec OpenClaw et CLEO. Intégration de secrets Doppler et NGINX Proxy Manager","de":"Erfahren Sie, wie Sie sherpa-onnx-tts für Offline-Sprachverarbeitung mit OpenClaw und CLEO konfigurieren. Integration von Doppler-Geheimnissen und NGINX-Prox...","pt":"Aprenda a instalar e configurar o sherpa-onnx-tts para uso offline com CLI e integração com Doppler secrets e NGINX Proxy Manager","ru":"Узнайте, как установить и настроить sherpa-onnx-tts для офлайн использования с CLI и интеграцией с Doppler secrets и NGINX Proxy Manager","ar":"تعرف على كيفية تثبيت وتكوين sherpa-onnx-tts للاستخدام دون اتصال بالإنترنت مع CLI ودمجها مع Doppler secrets و NGINX Proxy Manager"},"definition":{"en":"sherpa-onnx-tts is a super-powered OpenClaw installer for Proxmox, providing local TTS capabilities using the sherpa-onnx offline CLI and integrating with NGINX Proxy Manager.","zh":"sherpa-onnx-tts 是一个使用 OpenClaw 和 CLEO 的本地 TTS 工具","ja":"sherpa-onnx-tts は、OpenClaw と CLEO を使用したローカル TTS ツールです","ko":"sherpa-onnx-tts는 OpenClaw와 CLEO를 사용하는 로컬 TTS 도구입니다","es":"sherpa-onnx-tts es una herramienta de voz de IA que permite la configuración de voz offline con OpenClaw y CLEO","fr":"sherpa-onnx-tts est un outil de voix d''IA qui permet la configuration de voix hors ligne avec OpenClaw et CLEO","de":"sherpa-onnx-tts ist ein KI-Sprachtool, das die Offline-Sprachkonfiguration mit OpenClaw und CLEO ermöglicht","pt":"sherpa-onnx-tts é uma ferramenta de texto-a-voz offline que utiliza a CLI do sherpa-onnx","ru":"sherpa-onnx-tts - это офлайн инструмент текст-в-речь, использующий CLI sherpa-onnx","ar":"sherpa-onnx-tts هو أداة نص-صوت للاستخدام دون اتصال بالإنترنت باستخدام واجهة سطر الأوامر لشيربا-أونكس"},"features":{"en":["Includes Doppler secrets for secure configuration","Supports automated LXC provisioning for efficient deployment","Integrates with NGINX Proxy Manager for streamlined traffic management","Utilizes the sherpa-onnx offline CLI for local text-to-speech functionality","Requires updating ~/.openclaw/openclaw.json for customized settings","Extracts voice models into ~/.openclaw/tools/sherpa-onnx-tts/models for personalized speech synthesis"],"zh":["使用 OpenClaw 安装程序","集成 Doppler 秘钥","支持 NGINX 代理管理器","自动 LXC 提供","使用 CLEO 任务管理"],"ja":["OpenClaw インストーラーを使用","Doppler キーを統合","NGINX プロキシ マネージャーをサポート","自動 LXC プロビジョニング","CLEO タスク管理を使用"],"ko":["OpenClaw 설치 프로그램 사용","Doppler 키 통합","NGINX 프록시 관리자 지원","자동 LXC 프로비저닝","CLEO 작업 관리 사용"],"es":["Configuración de voz offline con OpenClaw","Integración con Doppler secrets","Integración con NGINX Proxy Manager","Automatización de la provisión de LXC","Compatibilidad con CLEO task management","Soporte para modelos de voz personalizados"],"fr":["Configuration de voix hors ligne avec OpenClaw","Intégration avec secrets Doppler","Intégration avec NGINX Proxy Manager","Automatisation de la provision de LXC","Compatibilité avec CLEO task management","Prise en charge de modèles de voix personnalisés"],"de":["Offline-Sprachkonfiguration mit OpenClaw","Integration mit Doppler-Geheimnissen","Integration mit NGINX-Proxy-Manager","Automatisierung der LXC-Bereitstellung","Kompatibilität mit CLEO-Aufgabenverwaltung","Unterstützung für benutzerdefinierte Sprachmodelle"],"pt":["Suporte a Doppler secrets","Integração com NGINX Proxy Manager","Provisionamento automático de LXC","Uso offline com CLI do sherpa-onnx","Instalação superpoderosa para Proxmox"],"ru":["Поддержка Doppler secrets","Интеграция с NGINX Proxy Manager","Автоматическое развертывание LXC","Офлайн использование с CLI sherpa-onnx","Супермощный инсталлятор для Proxmox"],"ar":["دعم سرعات Doppler","التكامل مع NGINX Proxy Manager","توفير تلقائي ل LXC","الاستخدام دون اتصال بالإنترنت مع واجهة سطر الأوامر لشيربا-أونكس","أداة تثبيت قوية للغاية لبروكسيموكس"]},"keywords":{"en":["how to install sherpa-onnx-tts","sherpa-onnx-tts vs other TTS solutions","sherpa-onnx-tts setup guide","what is sherpa-onnx-tts","sherpa-onnx-tts alternative for Proxmox","sherpa-onnx-tts local TTS configuration","NGINX Proxy Manager integration with sherpa-onnx-tts","automated LXC provisioning with sherpa-onnx-tts","Doppler secrets in sherpa-onnx-tts"],"zh":["sherpa-onnx-tts","本地 TTS","OpenClaw","CLEO","Doppler","NGINX 代理管理器","LXC","AI エージェント","sherpa-onnx-tts 安装"],"ja":["sherpa-onnx-tts","ローカル TTS","OpenClaw","CLEO","Doppler","NGINX プロキシ マネージャー","LXC","AI エージェント","sherpa-onnx-tts セットアップ"],"ko":["sherpa-onnx-tts","로컬 TTS","OpenClaw","CLEO","Doppler","NGINX 프록시 관리자","LXC","AI 에이전트","sherpa-onnx-tts 설치"],"es":["sherpa-onnx-tts","herramientas de voz de IA","OpenClaw","CLEO","Doppler secrets","NGINX Proxy Manager","configuración de voz offline","automatización de LXC","modelos de voz personalizados"],"fr":["sherpa-onnx-tts","outils de voix d''IA","OpenClaw","CLEO","secrets Doppler","NGINX Proxy Manager","configuration de voix hors ligne","automatisation de LXC","modèles de voix personnalisés"],"de":["sherpa-onnx-tts","KI-Sprachtools","OpenClaw","CLEO","Doppler-Geheimnisse","NGINX-Proxy-Manager","Offline-Sprachkonfiguration","Automatisierung der LXC-Bereitstellung","benutzerdefinierte Sprachmodelle"],"pt":["sherpa-onnx-tts","ferramentas de IA","instalação de Proxmox","Doppler secrets","NGINX Proxy Manager","LXC","CLI","texto-a-voz offline"],"ru":["sherpa-onnx-tts","ИИ Агенты","установка Proxmox","Doppler secrets","NGINX Proxy Manager","LXC","CLI","офлайн текст-в-речь"],"ar":["sherpa-onnx-tts","أدوات الإي الإلكترونية","تثبيت بروكسيموكس","سرعات Doppler","NGINX Proxy Manager","LXC","واجهة سطر الأوامر","نص-صوت للاستخدام دون اتصال بالإنترنت"]}},"owner":"kryptobaseddev","repo":"openclaw-cleo","repoPath":"kryptobaseddev/openclaw-cleo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.649Z","topics":[],"category":"community","skillMd":{"name":"sherpa-onnx-tts","description":"Local text-to-speech via sherpa-onnx (offline, no cloud)","bodyPreview":"# sherpa-onnx-tts\n\nLocal TTS using the sherpa-onnx offline CLI.\n\n## Install\n\n1. Download the runtime for your OS (extracts into `~/.openclaw/tools/sherpa-onnx-tts/runtime`)\n2. Download a voice model (extracts into `~/.openclaw/tools/sherpa-onnx-tts/models`)\n\nUpdate `~/.openclaw/openclaw.json`:\n\n```json5\n{\n  skills: {\n    entries: {\n      \"sherpa-onnx-tts\": {\n        env: {\n          SHERPA_ONNX_RUNTIME_DIR: \"~/.openclaw/tools/sherpa-onnx-tts/runtime\",\n          SHERPA_ONNX_MODEL_DIR: \"~/.opencla","body":"# sherpa-onnx-tts\n\nLocal TTS using the sherpa-onnx offline CLI.\n\n## Install\n\n1. Download the runtime for your OS (extracts into `~/.openclaw/tools/sherpa-onnx-tts/runtime`)\n2. Download a voice model (extracts into `~/.openclaw/tools/sherpa-onnx-tts/models`)\n\nUpdate `~/.openclaw/openclaw.json`:\n\n```json5\n{\n  skills: {\n    entries: {\n      \"sherpa-onnx-tts\": {\n        env: {\n          SHERPA_ONNX_RUNTIME_DIR: \"~/.openclaw/tools/sherpa-onnx-tts/runtime\",\n          SHERPA_ONNX_MODEL_DIR: \"~/.openclaw/tools/sherpa-onnx-tts/models/vits-piper-en_US-lessac-high\",\n        },\n      },\n    },\n  },\n}\n```\n\nThe wrapper lives in this skill folder. Run it directly, or add the wrapper to PATH:\n\n```bash\nexport PATH=\"{baseDir}/bin:$PATH\"\n```\n\n## Usage\n\n```bash\n{baseDir}/bin/sherpa-onnx-tts -o ./tts.wav \"Hello from local TTS.\"\n```\n\nNotes:\n\n- Pick a different model from the sherpa-onnx `tts-models` release if you want another voice.\n- If the model dir has multiple `.onnx` files, set `SHERPA_ONNX_MODEL_FILE` or pass `--model-file`.\n- You can also pass `--tokens-file` or `--data-dir` to override the defaults.\n- Windows: run `node {baseDir}\\\\bin\\\\sherpa-onnx-tts -o tts.wav \"Hello from local TTS.\"`\n"},"lastSynced":"2026-03-08T02:13:50.610Z","agentAnalysis":{"suitability":{"en":"Perfect for Voice Assistants and Conversational AI Agents needing local text-to-speech functionality using OpenClaw and CLEO task management.","zh":"非常适合需要使用 OpenClaw 和 CLEO 任务管理的语音助手和对话式 AI 代理的本地文本转语音功能","ja":"OpenClaw と CLEO タスク管理を使用したローカルのテキストツースピーチ機能ality を必要とするボイスアシスタントや会話型 AI エージェントに最適","ko":"OpenClaw와 CLEO 태스크 관리를 사용하는 로컬 텍스트 음성 변환 기능이 필요한 보이스 어시스턴트 및 대화형 AI 에이전트에 적합","es":"Perfecto para asistentes de voz y agentes de inteligencia artificial conversacional que necesitan funcionalidad de texto a voz local utilizando OpenClaw y gestión de tareas CLEO.","fr":"Parfait pour les assistants vocaux et les agents d''intelligence artificielle conversationnelle nécessitant une fonctionnalité de texte à parole locale en utilisant OpenClaw et la gestion de tâches CLEO.","de":"Perfekt für Sprachassistenten und konversationale KI-Agents, die lokale Text-to-Speech-Funktionalität mit OpenClaw und CLEO-Aufgabenverwaltung benötigen.","pt":"Perfeito para Assistentes de Voz e Agentes de IA Conversacional que necessitam de funcionalidade de texto-para-fala local usando OpenClaw e gerenciamento de tarefas CLEO.","ru":"Идеально подходит для голосовых помощников и разговорных агентов ИИ, которым требуется локальная функциональность текст-в-речь с использованием OpenClaw и управления задачами CLEO.","ar":"مثالي لمرافقي الصوت ووكلاء الذكاء الاصطناعي المحادثية الذين يحتاجون إلى وظائف النص إلى الكلام المحلية باستخدام OpenClaw وإدارة المهام CLEO."},"recommendation":{"en":"Empowers agents to leverage the sherpa-onnx offline CLI for local text-to-speech capabilities, utilizing OpenClaw installer and integrating Doppler secrets, enabling automated LXC provisioning and secure voice model management with OpenNX models.","zh":"赋予代理使用 sherpa-onnx 离线 CLI 进行本地文本转语音功能，利用 OpenClaw 安装程序并集成 Doppler 密钥，实现自动化 LXC 提供和安全的语音模型管理，使用 OpenNX 模型","ja":"エージェントが sherpa-onnx オフライン CLI を使用してローカルのテキストツースピーチ機能を利用できるようにし、OpenClaw インストーラーを使用し、Doppler シークレットを統合し、自動化された LXC プロビジョニングと OpenNX モデルを使用した安全なボイスモデル管理を可能にします","ko":"에이전트가 sherpa-onnx 오프라인 CLI를 사용하여 로컬 텍스트 음성 변환 기능을 사용할 수 있도록 해주고, OpenClaw 설치 프로그램을 사용하고, Doppler 시크릿을 통합하여 자동화된 LXC 프로비저닝 및 OpenNX 모델을 사용한 보안 음성 모델 관리를 가능하게 함","es":"Habilita a los agentes a aprovechar el sherpa-onnx offline CLI para capacidades de texto a voz locales, utilizando el instalador OpenClaw e integrando secretos Doppler, lo que permite la provisión automatizada de LXC y la gestión segura de modelos de voz con modelos OpenNX.","fr":"Permet aux agents d''exploiter le sherpa-onnx offline CLI pour des capacités de texte à parole locales, en utilisant l''installateur OpenClaw et en intégrant des secrets Doppler, ce qui permet la provision automatique de LXC et la gestion sécurisée des modèles de voix avec des modèles OpenNX.","de":"Ermächtigt Agents, das sherpa-onnx offline CLI für lokale Text-to-Speech-Fähigkeiten zu nutzen, indem es den OpenClaw-Installer verwendet und Doppler-Geheimnisse integriert, was die automatisierte Bereitstellung von LXC und die sichere Sprachmodellverwaltung mit OpenNX-Modellen ermöglicht.","pt":"Habilita os agentes a aproveitar o sherpa-onnx offline CLI para capacidades de texto-para-fala local, utilizando o instalador OpenClaw e integrando segredos Doppler, permitindo provisionamento automático LXC e gerenciamento seguro de modelos de voz com modelos OpenNX.","ru":"Предоставляет агентам возможность использовать офлайн-CLI sherpa-onnx для локальных возможностей текст-в-речь, используя установщик OpenClaw и интегрируя секреты Doppler, что позволяет автоматизировать обеспечение LXC и безопасное управление моделями голоса с моделями OpenNX.","ar":"يمنح الوكلاء القدرة على استخدام واجهة سطر الأوامر غير المتصل sherpa-onnx للقدرات المحلية للنص إلى الكلام، باستخدام مثبت OpenClaw ودمج أسرار Doppler، وتمكين توفير LXC التلقائي وإدارة نماذج الصوت الآمنة مع نماذج OpenNX."},"useCases":{"en":["Automating voice responses with local TTS","Generating voice models for offline applications","Integrating Doppler secrets for secure voice model storage"],"zh":["使用本地 TTS 自动化语音响应","为离线应用程序生成语音模型","集成 Doppler 密钥用于安全的语音模型存储"],"ja":["ローカルの TTS を使用したボイス応答の自動化","オフライン アプリケーション用のボイス モデルの生成","Doppler シークレットの統合による安全なボイス モデル ストレージ"],"ko":["로컬 TTS를 사용한 보이스 응답 자동화","오프라인 애플리케이션을 위한 보이스 모델 생성","Doppler 시크릿 통합을 통한 보안 음성 모델 저장"],"es":["Automatizar respuestas de voz con TTS local","Generar modelos de voz para aplicaciones sin conexión","Integrar secretos Doppler para el almacenamiento seguro de modelos de voz"],"fr":["Automatiser les réponses vocales avec TTS local","Générer des modèles de voix pour des applications hors ligne","Intégrer des secrets Doppler pour le stockage sécurisé des modèles de voix"],"de":["Automatisieren von Sprachantworten mit lokalem TTS","Erzeugen von Sprachmodellen für Offline-Anwendungen","Integrieren von Doppler-Geheimnissen für sichere Sprachmodell-speicherung"],"pt":["Automatizar respostas de voz com TTS local","Gerar modelos de voz para aplicações offline","Integrar segredos Doppler para armazenamento seguro de modelos de voz"],"ru":["Автоматизировать голосовые ответы с локальным TTS","Генерировать голосовые модели для офлайн-приложений","Интегрировать секреты Doppler для безопасного хранения голосовых моделей"],"ar":["توفير استجابات صوتية تلقائية مع التTS المحلي","توليد نماذج صوتية لتطبيقات غير متصلة","دمج أسرار Doppler لتخزين نماذج الصوت الآمن"]},"limitations":{"en":["Requires OpenClaw installer","Needs CLEO task management","Limited to local text-to-speech functionality"],"zh":["需要 OpenClaw 安装程序","需要 CLEO 任务管理","仅限本地文本转语音功能"],"ja":["OpenClaw インストーラーが必要","CLEO タスク管理が必要","ローカルのテキストツースピーチ機能に限定"],"ko":["OpenClaw 설치 프로그램이 필요","CLEO 태스크 관리가 필요","로컬 텍스트 음성 변환 기능에 한정"],"es":["Requiere instalador OpenClaw","Necesita gestión de tareas CLEO","Limitado a la funcionalidad de texto a voz local"],"fr":["Nécessite l''installateur OpenClaw","Nécessite la gestion de tâches CLEO","Limité à la fonctionnalité de texte à parole locale"],"de":["Benötigt OpenClaw-Installer","Benötigt CLEO-Aufgabenverwaltung","Begrenzt auf lokale Text-to-Speech-Funktionalität"],"pt":["Exige instalador OpenClaw","Necessita gerenciamento de tarefas CLEO","Limitado à funcionalidade de texto-para-fala local"],"ru":["Требует установщика OpenClaw","Требует управления задачами CLEO","Ограничен локальной функциональностью текст-в-речь"],"ar":["يتطلب مثبت OpenClaw","يحتاج إلى إدارة المهام CLEO","محدود بالوظائف المحلية للنص إلى الكلام"]},"version":4},"contentHash":"4ed0e7d7b7711ccfece96fd8a13faade7ba97339c56df963490b7afe2418eb1b","qualityScore":48}');
