INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kryptobaseddev/openclaw-cleo/sherpa-onnx-tts', 'sherpa-onnx-tts', 'kryptobaseddev', 'openclaw-cleo', 'community', 'sherpa-onnx-tts kryptobaseddev openclaw-cleo community sherpa-onnx-tts enables local text-to-speech functionality using the OpenClaw installer and CLEO task management. It benefits developers seeking automated LXC provisioning and Doppler secrets integration. sherpa-onnx-tts 是一个本地 TTS 解决方案，使用 OpenClaw 安装程序和 CLEO 任务管理 sherpa-onnx-tts は、OpenClaw インストーラーと CLEO タスク管理を使用したローカル TTS ソリューションです sherpa-onnx-tts는 OpenClaw 설치 프로그램과 CLEO 작업 관리를 사용하는 로컬 TTS 솔루션입니다 sherpa-onnx-tts es una herramienta de voz de IA que utiliza OpenClaw y CLEO para la configuración de voz offline. Incluye integración con Doppler secrets y NGINX Proxy Manager sherpa-onnx-tts est un outil de voix d''IA qui utilise OpenClaw et CLEO pour la configuration de voix hors ligne. Intégration avec secrets Doppler et NGINX Proxy Manager sherpa-onnx-tts ist ein KI-Sprachtool, das OpenClaw und CLEO für die Offline-Sprachkonfiguration verwendet. Integration mit Doppler-Geheimnissen und NGINX-Proxy-Manager O sherpa-onnx-tts é uma ferramenta de instalação superpoderosa para Proxmox, com suporte a Doppler secrets e NGINX Proxy Manager sherpa-onnx-tts - это супермощный инсталлятор для Proxmox, с поддержкой Doppler secrets и NGINX Proxy Manager sherpa-onnx-tts هو أداة تثبيت قوية للغاية لبروكسيموكس، مع دعم لسرعات Doppler و NGINX Proxy Manager how to install sherpa-onnx-tts sherpa-onnx-tts vs other TTS solutions sherpa-onnx-tts setup guide what is sherpa-onnx-tts sherpa-onnx-tts alternative for Proxmox sherpa-onnx-tts local TTS configuration NGINX Proxy Manager integration with sherpa-onnx-tts automated LXC provisioning with sherpa-onnx-tts Doppler secrets in sherpa-onnx-tts sherpa-onnx-tts 本地 TTS OpenClaw CLEO Doppler NGINX 代理管理器 LXC AI エージェント sherpa-onnx-tts 安装 Includes Doppler secrets for secure configuration Supports automated LXC provisioning for efficient deployment Integrates with NGINX Proxy Manager for streamlined traffic management Utilizes the sherpa-onnx offline CLI for local text-to-speech functionality Requires updating ~/.openclaw/openclaw.json for customized settings Extracts voice models into ~/.openclaw/tools/sherpa-onnx-tts/models for personalized speech synthesis sherpa-onnx-tts is a super-powered OpenClaw installer for Proxmox, providing local TTS capabilities using the sherpa-onnx offline CLI and integrating with NGINX Proxy Manager.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aj-geddes/useful-ai-prompts/profiling-optimization', 'community', 'aj-geddes', 'useful-ai-prompts', 'aj-geddes/useful-ai-prompts', 'profiling-optimization', 0, 0, 48, '2026-03-08T01:57:15.656Z', '2026-03-08T02:13:57.668Z', '40d4679d624b95ae13fc914fd45b6c8fda5c707736211c8612f1770a11d33d4c', '{"id":"aj-geddes/useful-ai-prompts/profiling-optimization","name":"profiling-optimization","description":{"en":"Profiling-optimization helps developers identify performance bottlenecks and optimize critical code paths. It benefits developers seeking to improve application performance.","zh":"Profiling Optimization AIエージェント用于优化代码执行和找出性能瓶颈。它提供了数据驱动的性能优化方法","ja":"Profiling Optimization AIエージェントは、コードの実行を最適化し、パフォーマンスのボトルネックを特定するために使用されます。データ駆動のパフォーマンス最適化方法を提供します","ko":"Profiling Optimization AI 에이전트는 코드 실행을 최적화하고 성능 병목현상을 식별하는 데 사용됩니다. 데이터 기반의 성능 최적화 방법을 제공합니다","es":"El perfilado y la optimización de código permiten identificar cuellos de botella de rendimiento y optimizar rutas críticas","fr":"Le profilage et l''optimisation de code permettent d''identifier les goulots d''étranglement des performances et d''optimiser les chemins critiques","de":"Profilerstellung und Leistungsoptimierung ermöglichen die Identifizierung von Leistungsengpässen und die Optimierung kritischer Pfade","pt":"O profiling-optimization é uma coleção de prompts de IA úteis para identificar gargalos de desempenho e otimizar caminhos críticos","ru":"Профилирование и оптимизация - это коллекция полезных запросов ИИ для выявления проблем с производительностью и оптимизации критических путей","ar":"بروفايل التحسين هو مجموعة من استفسارات الذكاء الاصطناعي المفيدة لتحديد معوقات الأداء وتحسين المسارات الحرجة"},"seo":{"title":{"en":"Profiling-Optimization: Performance Bottleneck Setup Guid...","zh":"AIエージェント性能优化设置指南 - Profiling Optimization","ja":"AIエージェントのパフォーマンス最適化設定ガイド - Profiling Optimization","ko":"AI 에이전트 성능 최적화 설정 가이드 - Profiling Optimization","es":"Guía de configuración de perfilado y optimización de rend...","fr":"Guide de configuration du profilage et de l''optimisation ...","de":"Leitfaden für Profilerstellung und Leistungsoptimierung","pt":"Otimização de Desempenho: Guia de Configuração para Profi...","ru":"Профилирование и Оптимизация: Руководство по Настройке ИИ...","ar":"تحسين الأداء: دليل الإعداد لبروفايل التحسين"},"description":{"en":"Unlock data-driven optimization with profiling-optimization. Discover how to identify CPU bottlenecks and reduce latency - get started now!","zh":"了解如何使用Profiling Optimization AIエージェント优化代码执行，找出性能瓶颈，并提高应用程序性能","ja":"Profiling Optimization AIエージェントを使用してコードの実行を最適化し、パフォーマンスのボトルネックを特定し、アプリケーションのパフォーマンスを向上させる方法を学びます","ko":"Profiling Optimization AI 에이전트를 사용하여 코드 실행을 최적화하고 성능 병목현상을 식별하며 애플리케이션 성능을 향상시키는 방법을 알아보세요","es":"Identifica cuellos de botella de rendimiento y optimiza rutas críticas con enfoques basados en datos","fr":"Identifiez les goulots d''étranglement des performances et optimisez les chemins critiques à l''aide d''approches basées sur les données","de":"Identifizieren Sie Leistungsengpässe und optimieren Sie kritische Pfade mit datengetriebenen Ansätzen","pt":"Aprenda a identificar gargalos de desempenho e otimizar caminhos críticos com abordagens baseadas em dados","ru":"Узнайте, как выявлять проблемы с производительностью и оптимизировать критические пути с помощью данных","ar":"تعرف على كيفية تحديد معوقات الأداء وتحسين المسارات الحرجة باستخدام نهج قائم على البيانات"},"definition":{"en":"Profiling-optimization is a technique for analyzing code execution to identify performance bottlenecks and optimize critical paths using data-driven approaches.","zh":"Profiling Optimization是指使用数据驱动的方法优化代码执行，找出性能瓶颈的过程","ja":"Profiling Optimizationは、コードの実行を最適化し、パフォーマンスのボトルネックを特定するためにデータ駆動の方法を使用するプロセスです","ko":"Profiling Optimization은 데이터 기반의 방법을 사용하여 코드 실행을 최적화하고 성능 병목현상을 식별하는 과정입니다","es":"El perfilado y la optimización es el proceso de analizar el rendimiento de un código para identificar y optimizar cuellos de botella","fr":"Le profilage et l''optimisation est le processus d''analyse des performances d''un code pour identifier et optimiser les goulots d''étranglement","de":"Profilerstellung und Leistungsoptimierung ist der Prozess der Analyse der Leistung eines Codes, um Engpässe zu identifizieren und zu optimieren","pt":"O que é profiling-optimization? É uma técnica para identificar gargalos de desempenho e otimizar caminhos críticos","ru":"Что такое профилирование и оптимизация? Это метод выявления проблем с производительностью и оптимизации критических путей","ar":"ما هو بروفايل التحسين؟ إنه تقنية لتحديد معوقات الأداء وتحسين المسارات الحرجة"},"features":{"en":["Profiles code execution to identify CPU bottlenecks","Optimizes hot paths for improved performance","Investigates slow requests to reduce latency","Provides reference guides for optimization","Offers best practices for data-driven optimization","Supports quick start for rapid performance improvement"],"zh":["代码执行优化","性能瓶颈识别","数据驱动的性能优化","CPU瓶颈优化","热路径优化","延迟减少"],"ja":["コードの実行を最適化","パフォーマンスのボトルネックを特定","データ駆動のパフォーマンス最適化","CPUのボトルネックを最適化","ホットパスの最適化","レイテンシーの削減"],"ko":["코드 실행 최적화","성능 병목현상 식별","데이터 기반의 성능 최적화","CPU 병목현상 최적화","핫패스 최적화","지연 감소"],"es":["Identificación de cuellos de botella de CPU","Optimización de rutas críticas","Investigación de solicitudes lentas","Reducción de la latencia","Mejora del rendimiento con enfoques basados en datos"],"fr":["Identification des goulots d''étranglement de CPU","Optimisation des chemins critiques","Investigation des requêtes lentes","Réduction de la latence","Amélioration des performances avec des approches basées sur les données"],"de":["Identifizierung von CPU-Engpässen","Optimierung kritischer Pfade","Untersuchung von langsamen Anfragen","Reduzierung der Latenz","Leistungsverbesserung mit datengetriebenen Ansätzen"],"pt":["Identificação de gargalos de desempenho","Otimização de caminhos críticos","Análise de CPU","Investigação de requisições lentas","Redução de latência","Melhoria de desempenho"],"ru":["Выявление проблем с производительностью","Оптимизация критических путей","Анализ CPU","Расследование медленных запросов","Снижение задержки","Улучшение производительности"],"ar":["تحديد معوقات الأداء","تحسين المسارات الحرجة","تحليل وحدة المعالجة المركزية","تحقيق في الطلبات البطيئة","تقليل التأخير","تحسين الأداء"]},"keywords":{"en":["how to use profiling-optimization","what is profiling-optimization","profiling-optimization alternative","profiling-optimization vs performance monitoring","profiling-optimization install","profiling-optimization setup guide","optimizing critical code paths","identifying CPU bottlenecks","reducing latency with profiling-optimization"],"zh":["AIエージェント","性能优化","代码执行优化","性能瓶颈识别","数据驱动的性能优化","CPU瓶颈优化","热路径优化","延迟减少","Profiling Optimization"],"ja":["AIエージェント","パフォーマンス最適化","コードの実行を最適化","パフォーマンスのボトルネックを特定","データ駆動のパフォーマンス最適化","CPUのボトルネックを最適化","ホットパスの最適化","レイテンシーの削減","Profiling Optimization"],"ko":["AI 에이전트","성능 최적화","코드 실행 최적화","성능 병목현상 식별","데이터 기반의 성능 최적화","CPU 병목현상 최적화","핫패스 최적화","지연 감소","Profiling Optimization"],"es":["perfilado y optimización","optimización de rendimiento","identificación de cuellos de botella","optimización de rutas críticas","reducción de la latencia","herramientas de perfilado","Agentes de IA para optimización","Herramientas de optimización de rendimiento"],"fr":["profilage et optimisation","optimisation des performances","identification des goulots d''étranglement","optimisation des chemins critiques","réduction de la latence","outils de profilage","Agents d''IA pour l''optimisation","Outils d''optimisation des performances"],"de":["Profilerstellung und Leistungsoptimierung","Leistungsoptimierung","Identifizierung von Leistungsengpässen","Optimierung kritischer Pfade","Reduzierung der Latenz","Profilerstellungstools","KI-Agents für Optimierung","Leistungsoptimierungstools"],"pt":["otimização de desempenho","profiling","análise de CPU","requisições lentas","latência","desempenho","IA","ferramentas de IA","desenvolvimento de software"],"ru":["оптимизация производительности","профилирование","анализ CPU","медленные запросы","задержка","производительность","ИИ","инструменты ИИ","разработка программного обеспечения"],"ar":["تحسين الأداء","بروفايل","تحليل وحدة المعالجة المركزية","الطلبات البطيئة","التأخير","الأداء","الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","تطوير البرمجيات"]}},"owner":"aj-geddes","repo":"useful-ai-prompts","repoPath":"aj-geddes/useful-ai-prompts","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.656Z","topics":[],"category":"community","skillMd":{"name":"profiling-optimization","description":">","bodyPreview":"# Profiling & Optimization\n\n## Table of Contents\n\n- [Overview](#overview)\n- [When to Use](#when-to-use)\n- [Quick Start](#quick-start)\n- [Reference Guides](#reference-guides)\n- [Best Practices](#best-practices)\n\n## Overview\n\nProfile code execution to identify performance bottlenecks and optimize critical paths using data-driven approaches.\n\n## When to Use\n\n- Performance optimization\n- Identifying CPU bottlenecks\n- Optimizing hot paths\n- Investigating slow requests\n- Reducing latency\n- Improving t","body":"# Profiling & Optimization\n\n## Table of Contents\n\n- [Overview](#overview)\n- [When to Use](#when-to-use)\n- [Quick Start](#quick-start)\n- [Reference Guides](#reference-guides)\n- [Best Practices](#best-practices)\n\n## Overview\n\nProfile code execution to identify performance bottlenecks and optimize critical paths using data-driven approaches.\n\n## When to Use\n\n- Performance optimization\n- Identifying CPU bottlenecks\n- Optimizing hot paths\n- Investigating slow requests\n- Reducing latency\n- Improving throughput\n\n## Quick Start\n\nMinimal working example:\n\n```typescript\nimport { performance, PerformanceObserver } from \"perf_hooks\";\n\nclass Profiler {\n  private marks = new Map<string, number>();\n\n  mark(name: string): void {\n    this.marks.set(name, performance.now());\n  }\n\n  measure(name: string, startMark: string): number {\n    const start = this.marks.get(startMark);\n    if (!start) throw new Error(`Mark ${startMark} not found`);\n\n    const duration = performance.now() - start;\n    console.log(`${name}: ${duration.toFixed(2)}ms`);\n\n    return duration;\n  }\n\n  async profile<T>(name: string, fn: () => Promise<T>): Promise<T> {\n    const start = performance.now();\n\n    try {\n      return await fn();\n    } finally {\n// ... (see reference guides for full implementation)\n```\n\n## Reference Guides\n\nDetailed implementations in the `references/` directory:\n\n| Guide | Contents |\n|---|---|\n| [Node.js Profiling](references/nodejs-profiling.md) | Node.js Profiling |\n| [Chrome DevTools CPU Profile](references/chrome-devtools-cpu-profile.md) | Chrome DevTools CPU Profile |\n| [Python cProfile](references/python-cprofile.md) | Python cProfile |\n| [Benchmarking](references/benchmarking.md) | Benchmarking |\n| [Database Query Profiling](references/database-query-profiling.md) | Database Query Profiling |\n| [Flame Graph Generation](references/flame-graph-generation.md) | Flame Graph Generation |\n\n## Best Practices\n\n### ✅ DO\n\n- Profile before optimizing\n- Focus on hot paths\n- Measure impact of changes\n- Use production-like data\n- Consider memory vs speed tradeoffs\n- Document optimization rationale\n\n### ❌ DON''T\n\n- Optimize without profiling\n- Ignore readability for minor gains\n- Skip benchmarking\n- Optimize cold paths\n- Make changes without measurement\n"},"lastSynced":"2026-03-08T02:13:57.668Z","agentAnalysis":{"suitability":{"en":"Perfect for Performance Optimization Agents needing advanced code analysis and bottleneck identification capabilities.","zh":"非常适合需要高级代码分析和瓶颈识别能力的性能优化代理。","ja":"パフォーマンス最適化エージェントが高度なコード分析とボトルネック識別機能を必要とする場合に最適です。","ko":"고급 코드 분석 및 병목 현상 식별 기능이 필요한 성능 최적화 에이전트에 적합합니다.","es":"Perfecto para agentes de optimización de rendimiento que necesitan un análisis de código avanzado y capacidades de identificación de cuellos de botella.","fr":"Parfait pour les agents d''optimisation des performances nécessitant une analyse de code avancée et des capacités d''identification de goulets d''étranglement.","de":"Perfekt für Leistungs-Optimierungs-Agents, die erweiterte Code-Analyse und Engpass-Identifizierungs-Fähigkeiten benötigen.","pt":"Perfeito para Agentes de Otimização de Desempenho que precisam de análise de código avançada e capacidades de identificação de gargalos.","ru":"Идеально подходит для агентов оптимизации производительности, которым требуются продвинутые возможности анализа кода и определения узких мест.","ar":"مثالي لعمليات تحسين الأداء التي تتطلب تحليل код متقدم وcapabilities لتحديد عنق الزجاجة."},"recommendation":{"en":"Empowers agents to profile code execution and optimize critical paths using data-driven approaches, reducing latency and improving overall application performance through CPU bottleneck identification and hot path optimization.","zh":"赋予代理以数据驱动的方法分析代码执行并优化关键路径，减少延迟并通过 CPU 瓶颈识别和热路径优化提高整体应用程序性能。","ja":"エージェントにコードの実行を分析し、データ駆動型アプローチでクリティカルパスを最適化する機能を提供し、CPU のボトルネック識別とホットパス最適化により、待ち時間を短縮し、全体的なアプリケーションのパフォーマンスを向上させます。","ko":"에이전트가 코드 실행을 프로파일링하고 데이터 주도 접근 방식을 사용하여 중요한 경로를 최적화하여 대기 시간을 줄이고 CPU 병목 현상 식별 및 핫 패스 최적화를 통해 전체 애플리케이션 성능을 개선할 수 있도록 합니다.","es":"Habilita a los agentes a perfilizar la ejecución de código y optimizar caminos críticos utilizando enfoques basados en datos, reduciendo la latencia y mejorando el rendimiento general de la aplicación a través de la identificación de cuellos de botella de CPU y la optimización de caminos calientes.","fr":"Permet aux agents de profiler l''exécution de code et d''optimiser les chemins critiques à l''aide d''approches basées sur les données, en réduisant la latence et en améliorant les performances globales de l''application grâce à l''identification des goulets d''étranglement de CPU et à l''optimisation des chemins chauds.","de":"Ermächtigt Agents, Code-Ausführung zu profilieren und kritische Pfade mit datengetriebten Ansätzen zu optimieren, Latenz zu reduzieren und die Gesamtleistung der Anwendung durch CPU-Engpass-Identifizierung und heiße Pfad-Optimierung zu verbessern.","pt":"Habilita os agentes a criar perfis de execução de código e otimizar caminhos críticos usando abordagens baseadas em dados, reduzindo a latência e melhorando o desempenho geral da aplicação por meio da identificação de gargalos de CPU e otimização de caminhos quentes.","ru":"Позволяет агентам создавать профили выполнения кода и оптимизировать критические пути с помощью подходов, основанных на данных, снижая задержку и улучшая общую производительность приложения за счет определения узких мест CPU и оптимизации горячих путей.","ar":"تمكين الوكيل من إنشاء ملفات تعريف تنفيذ الكود وتحسين المسارات الحرجة باستخدام نهج مدعوم بالبيانات، وتقليل التأخير وتحسين أداء التطبيق بشكل عام من خلال تحديد عنق الزجاجة CPU وتحسين المسارات الساخنة."},"useCases":{"en":["Identifying performance bottlenecks in critical code paths","Optimizing hot paths for improved application performance","Investigating slow requests and reducing latency","Debugging CPU-intensive code sections","Improving overall application responsiveness"],"zh":["识别关键代码路径中的性能瓶颈","优化热路径以提高应用程序性能","调查缓慢的请求并减少延迟","调试 CPU 密集型代码部分","提高应用程序的整体响应性"],"ja":["クリティカルコードパスのパフォーマンスボトルネックを識別する","ホットパスを最適化してアプリケーションのパフォーマンスを向上させる","遅いリクエストを調査して待ち時間を短縮する","CPU 集中型コードセクションをデバッグする","アプリケーションの全体的なレスポンス性を向上させる"],"ko":["중요한 코드 경로에서 성능 병목 현상을 식별하는 것","핫 패스를 최적화하여 애플리케이션 성능을 개선하는 것","느린 요청을 조사하고 대기 시간을 줄이는 것","CPU 집중형 코드 섹션을 디버깅하는 것","애플리케이션의 전체적인 응답성을 개선하는 것"],"es":["Identificar cuellos de botella de rendimiento en caminos de código críticos","Optimizar caminos calientes para mejorar el rendimiento de la aplicación","Investigar solicitudes lentas y reducir la latencia","Depurar secciones de código intensivas en CPU","Mejorar la respuesta general de la aplicación"],"fr":["Identifier les goulets d''étranglement de performances dans les chemins de code critiques","Optimiser les chemins chauds pour améliorer les performances de l''application","Enquêter sur les requêtes lentes et réduire la latence","Déboguer les sections de code intensives en CPU","Améliorer la réactivité globale de l''application"],"de":["Leistungs-Engpässe in kritischen Code-Pfaden identifizieren","Heiße Pfade für verbesserte Anwendungsleistung optimieren","Langsame Anfragen untersuchen und Latenz reduzieren","CPU-intensive Code-Abschnitte debuggen","Gesamtsystemreaktion der Anwendung verbessern"],"pt":["Identificar gargalos de desempenho em caminhos de código críticos","Otimizar caminhos quentes para melhorar o desempenho da aplicação","Investigar solicitações lentas e reduzir a latência","Depurar seções de código intensivas em CPU","Melhorar a resposta geral da aplicação"],"ru":["Определение узких мест производительности в критических кодовых путях","Оптимизация горячих путей для улучшения производительности приложения","Расследование медленных запросов и снижение задержки","Отладка секций кода, интенсивно использующих CPU","Улучшение общей отзывчивости приложения"],"ar":["تحديد عنق الزجاجة في مسارات الكود الحرجة","تحسين المسارات الساخنة لتحسين أداء التطبيق","تحقيق الطلبات البطيئة وتقليل التأخير","تصحيح الأقسام الشديدة في الكود","تحسين الاستجابة العامة للتطبيق"]},"limitations":{"en":["Requires access to code execution data","Limited to applications with profiling capabilities","May require additional setup for accurate bottleneck identification"],"zh":["需要访问代码执行数据","仅限具有分析功能的应用程序","可能需要额外的设置以便于准确的瓶颈识别"],"ja":["コードの実行データへのアクセスが必要","プロファイリング機能のあるアプリケーションに限定される","ボトルネックの正確な識別のために追加の設定が必要になることがある"],"ko":["코드 실행 데이터에 대한 액세스가 필요함","프로파일링 기능이 있는 애플리케이션에만 적용됨","정확한 병목 현상 식별을 위한 추가 설정이 필요할 수 있음"],"es":["Requiere acceso a datos de ejecución de código","Limitado a aplicaciones con capacidades de perfilado","Puede requerir configuración adicional para una identificación precisa de cuellos de botella"],"fr":["Nécessite un accès aux données d''exécution de code","Limité aux applications avec des capacités de profilage","Peut nécessiter une configuration supplémentaire pour une identification précise des goulets d''étranglement"],"de":["Benötigt Zugriff auf Code-Ausführungsdaten","Begrenzt auf Anwendungen mit Profiler-Funktionen","Kann eine zusätzliche Konfiguration für eine genaue Engpass-Identifizierung erfordern"],"pt":["Requer acesso a dados de execução de código","Limitado a aplicações com capacidades de perfil","Pode requerer configuração adicional para identificação precisa de gargalos"],"ru":["Требует доступа к данным выполнения кода","Ограничен для приложений с возможностями профилирования","Может потребовать дополнительной настройки для точного определения узких мест"],"ar":["يتطلب الوصول إلى بيانات تنفيذ الكود","محدود للتطبيقات التي لديها إمكانيات ملف تعريف","يمكن أن يتطلب إعدادًا إضافيًا لتحديد عنق الزجاجة بدقة"]},"version":4},"contentHash":"40d4679d624b95ae13fc914fd45b6c8fda5c707736211c8612f1770a11d33d4c","qualityScore":48}');
