INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aj-geddes/useful-ai-prompts/profiling-optimization', 'profiling-optimization', 'aj-geddes', 'useful-ai-prompts', 'community', 'profiling-optimization aj-geddes useful-ai-prompts community Profiling-optimization helps developers identify performance bottlenecks and optimize critical code paths. It benefits developers seeking to improve application performance. Profiling Optimization AIエージェント用于优化代码执行和找出性能瓶颈。它提供了数据驱动的性能优化方法 Profiling Optimization AIエージェントは、コードの実行を最適化し、パフォーマンスのボトルネックを特定するために使用されます。データ駆動のパフォーマンス最適化方法を提供します Profiling Optimization AI 에이전트는 코드 실행을 최적화하고 성능 병목현상을 식별하는 데 사용됩니다. 데이터 기반의 성능 최적화 방법을 제공합니다 El perfilado y la optimización de código permiten identificar cuellos de botella de rendimiento y optimizar rutas críticas Le profilage et l''optimisation de code permettent d''identifier les goulots d''étranglement des performances et d''optimiser les chemins critiques Profilerstellung und Leistungsoptimierung ermöglichen die Identifizierung von Leistungsengpässen und die Optimierung kritischer Pfade O profiling-optimization é uma coleção de prompts de IA úteis para identificar gargalos de desempenho e otimizar caminhos críticos Профилирование и оптимизация - это коллекция полезных запросов ИИ для выявления проблем с производительностью и оптимизации критических путей بروفايل التحسين هو مجموعة من استفسارات الذكاء الاصطناعي المفيدة لتحديد معوقات الأداء وتحسين المسارات الحرجة how to use profiling-optimization what is profiling-optimization profiling-optimization alternative profiling-optimization vs performance monitoring profiling-optimization install profiling-optimization setup guide optimizing critical code paths identifying CPU bottlenecks reducing latency with profiling-optimization AIエージェント 性能优化 代码执行优化 性能瓶颈识别 数据驱动的性能优化 CPU瓶颈优化 热路径优化 延迟减少 Profiling Optimization Profiles code execution to identify CPU bottlenecks Optimizes hot paths for improved performance Investigates slow requests to reduce latency Provides reference guides for optimization Offers best practices for data-driven optimization Supports quick start for rapid performance improvement Profiling-optimization is a technique for analyzing code execution to identify performance bottlenecks and optimize critical paths using data-driven approaches.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('peppone-choi/opensamguk/verify-npc-data', 'community', 'peppone-choi', 'opensamguk', 'peppone-choi/opensamguk', 'verify-npc-data', 0, 0, 48, '2026-03-08T01:11:19Z', '2026-03-08T02:14:12.244Z', '2ac722c00cdffd7f7ac078c28a8db2106c8091f989e74f6826dd750f0ed9bf2c', '{"id":"peppone-choi/opensamguk/verify-npc-data","name":"verify-npc-data","description":{"en":"The verify-npc-data skill validates NPC data against official Three Kingdoms 14 standards, ensuring 5-stat completion and accuracy. It benefits developers working with scenario JSON data.","zh":"verify-npc-data 工具用于验证 NPC 数据，确保其准确性和一致性，支持 5-stat 完成、数据对齐和历史验证","ja":"verify-npc-data ツールは NPC データを検証し、正確性と一貫性を確保します。5-stat 完了、データの一貫性、歴史的正確性をサポートします","ko":"verify-npc-data 스킬은 NPC 데이터를 검증하여 정확성과 일관성을 보장합니다. 5-stat 완성, 데이터 일치성, 역사적 정확성을 지원합니다","es":"Verify-npc-data es una herramienta de IA que verifica la precisión de los datos de personajes no jugables en juegos, incluyendo la migración de 3-stat a 5-stat y la comprobación de la coherencia con los datos oficiales de Three Kingdoms 14","fr":"Verify-npc-data est un outil d''IA qui vérifie la précision des données de personnages non jouables dans les jeux, y compris la migration de 3-stat à 5-stat et la vérification de la cohérence avec les données officielles de Three Kingdoms 14","de":"Verify-npc-data ist ein KI-Tool, das die Genauigkeit von Nicht-Spieler-Charakter-Daten in Spielen überprüft, einschließlich der Migration von 3-Stat zu 5-Stat und der Überprüfung der Konsistenz mit den offiziellen Daten von Three Kingdoms 14","pt":"O verify-npc-data é uma ferramenta que valida dados de NPC em projetos, garantindo a consistência com os dados oficiais de Three Kingdoms 14. Ele verifica a migração de 3-stat para 5-stat, dados de NPC em falta e mais","ru":"Verify-npc-data — это инструмент, проверяющий данные НПС в проектах, обеспечивающий соответствие официальным данным Three Kingdoms 14. Он проверяет миграцию с 3-stat на 5-stat, отсутствующие данные НПС и многое другое в ИИ Агентах","ar":"verify-npc-data هو أداة للتحقق من بيانات NPC في المشاريع، وضمان الاتساق مع البيانات الرسمية لثري كينغدومز 14. وهو يتحقق من هجرة 3-stat إلى 5-stat، والبيانات الناقصة لNPC وغيرها في أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"verify-npc-data: NPC Data Validation Setup Guide | AI Age...","zh":"NPC 数据验证工具 Setup Guide","ja":"NPC データ検証ツール Best Practices","ko":"verify-npc-data 스킬 설정 가이드","es":"Guía de configuración de verify-npc-data para agentes de IA","fr":"Guide de mise en œuvre de verify-npc-data pour les outils...","de":"Einrichtungsleitfaden für verify-npc-data in KI-Agents","pt":"Guia de Configuração do verify-npc-data: Validação de Dad...","ru":"Настройка verify-npc-data: Проверка Данных НПС в ИИ Агентах","ar":"دليل إعداد verify-npc-data: التحقق من بيانات NPC في أدوات..."},"description":{"en":"Discover how to ensure accuracy in your NPC data with verify-npc-data. Validate 5-stat completion, compare with official data, and identify missing character...","zh":"使用 verify-npc-data 工具验证 NPC 数据的准确性，确保 5-stat 完成、数据一致性和历史准确性","ja":"verify-npc-data ツールを使用して NPC データの正確性を検証し、5-stat 完了、データの一貫性、歴史的正確性を確保する","ko":"verify-npc-data 스킬을 사용하여 NPC 데이터의 정확성을 검증하고 5-stat 완성, 데이터 일치性, 역사적 정확성을 보장합니다","es":"Aprende a verificar datos de NPC con verify-npc-data, una herramienta de IA para garantizar la precisión de los datos de personajes no jugables","fr":"Découvrez comment vérifier les données de NPC avec verify-npc-data, un outil d''IA pour assurer la précision des données de personnages non jouables","de":"Erfahren Sie, wie Sie NPC-Daten mit verify-npc-data überprüfen, einem KI-Tool für die Gewährleistung der Genauigkeit von Nicht-Spieler-Charakter-Daten","pt":"Aprenda a configurar o verify-npc-data para validar dados de NPC em seu projeto, garantindo a consistência com os dados oficiais de Three Kingdoms 14","ru":"Узнайте, как настроить verify-npc-data для проверки данных НПС в вашем проекте, обеспечивая соответствие официальным данным Three Kingdoms 14 в ИИ Агентах","ar":"تعرف على كيفية إعداد verify-npc-data للتحقق من بيانات NPC في مشروعك، وضمان الاتساق مع البيانات الرسمية لثري كينغدومز 14 في أدوات الذكاء الاصطناعي"},"definition":{"en":"verify-npc-data is a skill that validates NPC data by checking 5-stat completion, comparing with official Three Kingdoms 14 data, and identifying missing characters.","zh":"verify-npc-data 是一种用于验证 NPC 数据准确性和一致性的工具","ja":"verify-npc-data は NPC データの正確性と一貫性を検証するためのツールです","ko":"verify-npc-data는 NPC 데이터의 정확성과 일관성을 검증하는 스킬입니다","es":"Verify-npc-data es una herramienta de IA que verifica la precisión de los datos de personajes no jugables en juegos","fr":"Verify-npc-data est un outil d''IA qui vérifie la précision des données de personnages non jouables dans les jeux","de":"Verify-npc-data ist ein KI-Tool, das die Genauigkeit von Nicht-Spieler-Charakter-Daten in Spielen überprüft","pt":"O verify-npc-data é uma ferramenta de validação de dados de NPC que garante a consistência com os dados oficiais de Three Kingdoms 14","ru":"Verify-npc-data — это инструмент проверки данных НПС, обеспечивающий соответствие официальным данным Three Kingdoms 14 в ИИ Агентах","ar":"verify-npc-data هو أداة للتحقق من بيانات NPC التي تضمن الاتساق مع البيانات الرسمية لثري كينغدومز 14 في أدوات الذكاء الاصطناعي"},"features":{"en":["Checks 5-stat completion for NPC data migration from 3-stat","Compares NPC stats with official Three Kingdoms 14 data","Identifies missing characters in scenario JSON data","Verifies name consistency with official Korean translations","Checks era-specific consistency for NPC birth and death years","Validates non-historical NPC data using official formulas"],"zh":["5-stat 完成验证","三国志14 官方数据对齐","缺失将军识别","名称一致性检查","时代一致性验证","非历史 NPC 官方验证"],"ja":["5-stat 完了検証","三国志14 公式データとの照合","欠け将軍の識別","名前の一致性チェック","時代の一致性検証","非歴史 NPC 公式検証"],"ko":["5-stat 완성 검증","삼국지14 공식 데이터와의 일치성 확인","누락 장수 식별","이름 일치성 확인","시대별 일치성 확인","비역사 NPC 공식 확인"],"es":["Migración de 3-stat a 5-stat para personajes no jugables","Verificación de la coherencia con los datos oficiales de Three Kingdoms 14","Comprobación de la existencia de personajes no jugables en el juego","Verificación de la consistencia de los nombres de personajes no jugables","Comprobación de la coherencia de la fecha de nacimiento y muerte de personajes no jugables","Verificación de la generación oficial de personajes no jugables virtuales"],"fr":["Migration de 3-stat à 5-stat pour les personnages non jouables","Vérification de la cohérence avec les données officielles de Three Kingdoms 14","Vérification de l''existence de personnages non jouables dans le jeu","Vérification de la consistance des noms de personnages non jouables","Vérification de la cohérence de la date de naissance et de décès de personnages non jouables","Vérification de la génération officielle de personnages non jouables virtuels"],"de":["Migration von 3-Stat zu 5-Stat für Nicht-Spieler-Charaktere","Überprüfung der Konsistenz mit den offiziellen Daten von Three Kingdoms 14","Überprüfung der Existenz von Nicht-Spieler-Charakteren im Spiel","Überprüfung der Konsistenz der Namen von Nicht-Spieler-Charakteren","Überprüfung der Konsistenz des Geburts- und Sterbedatums von Nicht-Spieler-Charakteren","Überprüfung der offiziellen Generierung von virtuellen Nicht-Spieler-Charakteren"],"pt":["Verificação da migração de 3-stat para 5-stat","Validação de dados de NPC contra os dados oficiais de Three Kingdoms 14","Detecção de dados de NPC em falta","Verificação da consistência dos nomes de NPC","Verificação da consistência das datas de nascimento e morte de NPC","Geração de dados de NPC fictícios de acordo com as regras oficiais"],"ru":["Проверка миграции с 3-stat на 5-stat","Проверка данных НПС против официальных данных Three Kingdoms 14 в ИИ Агентах","Обнаружение отсутствующих данных НПС","Проверка соответствия имён НПС","Проверка соответствия дат рождения и смерти НПС","Генерация данных НПС по официальным правилам"],"ar":["التحقق من هجرة 3-stat إلى 5-stat","التحقق من بيانات NPC ضد البيانات الرسمية لثري كينغدومز 14 في أدوات الذكاء الاصطناعي","التحقق من البيانات الناقصة لNPC","التحقق من الاتساق في أسماء NPC","التحقق من الاتساق في تواريخ ميلاد ووفاة NPC","توليد بيانات NPC الخيالية وفقًا للقواعد الرسمية"]},"keywords":{"en":["how to use verify-npc-data","verify-npc-data setup guide","NPC data validation tools","Three Kingdoms 14 data comparison","verify-npc-data alternative","verify-npc-data vs data validation tools","scenario JSON data management","5-stat completion verification"],"zh":["NPC 数据验证","AI 工具","verify-npc-data","5-stat 完成","三国志14 数据对齐","游戏开发","数据一致性","历史准确性"],"ja":["NPC データ検証","AI エージェント","verify-npc-data","5-stat 完了","三国志14 データの一貫性","ゲーム開発","データの一貫性","歴史的正確性"],"ko":["NPC 데이터 검증","AI 에이전트","verify-npc-data","5-stat 완성","삼국지14 데이터 일치성","게임 개발","데이터 일치성","역사적 정확성"],"es":["herramientas de IA para juegos","verificación de datos de personajes no jugables","migración de 3-stat a 5-stat","Three Kingdoms 14","personajes no jugables","datos de juegos","herramientas de desarrollo de juegos","IA para juegos","verify-npc-data"],"fr":["outils d''IA pour les jeux","vérification des données de personnages non jouables","migration de 3-stat à 5-stat","Three Kingdoms 14","personnages non jouables","données de jeux","outils de développement de jeux","IA pour les jeux","verify-npc-data"],"de":["KI-Tools für Spiele","Überprüfung von Nicht-Spieler-Charakter-Daten","Migration von 3-Stat zu 5-Stat","Three Kingdoms 14","Nicht-Spieler-Charaktere","Spieldaten","Entwicklungstools für Spiele","KI für Spiele","verify-npc-data"],"pt":["verify-npc-data","validação de dados de NPC","Three Kingdoms 14","migração de 3-stat para 5-stat","dados de NPC em falta","consistência de nomes de NPC","consistência de datas de nascimento e morte de NPC","geração de dados de NPC fictícios"],"ru":["verify-npc-data","проверка данных НПС","Three Kingdoms 14","миграция с 3-stat на 5-stat","отсутствующие данные НПС","соответствие имён НПС","соответствие дат рождения и смерти НПС","генерация данных НПС по официальным правилам","ИИ Агенты"],"ar":["verify-npc-data","التحقق من بيانات NPC","ثري كينغدومز 14","هجرة 3-stat إلى 5-stat","البيانات الناقصة لNPC","الاتساق في أسماء NPC","الاتساق في تواريخ ميلاد ووفاة NPC","توليد بيانات NPC الخيالية","أدوات الذكاء الاصطناعي"]}},"owner":"peppone-choi","repo":"opensamguk","repoPath":"peppone-choi/opensamguk","stars":0,"forks":0,"updatedAt":"2026-03-08T01:11:19Z","topics":[],"category":"community","skillMd":{"name":"verify-npc-data","description":"시나리오 NPC 장수 데이터가 삼국지14 기준 5-stat(통무지정매)으로 최신화되었는지 확인합니다. 시나리오/장수 데이터 수정 후 사용.","bodyPreview":"# NPC Data 검증\n\n## Purpose\n\n시나리오 NPC 장수 데이터가 삼국지14 무장 정보 기준으로 최신화되었는지 검증합니다:\n\n1. **5-stat 완성** — 레거시 3-stat(통솔/무력/지력) → 5-stat(통솔/무력/지력/정치/매력) 마이그레이션 확인\n2. **삼국지14 기준 대조** — NPC 장수의 스탯이 삼국지14 공식 데이터와 일치하는지 확인\n3. **누락 장수** — 삼국지14에 존재하지만 시나리오에 없는 장수 식별\n4. **이름 정합** — 장수 이름이 삼국지14 한국어 표기와 일치하는지 확인\n5. **시대별 정합** — 장수의 생년/몰년이 삼국지14 데이터와 일치하는지 확인\n6. **비역사 NPC 공식** — 삼국지14에 없는 가상/비역사 NPC의 정치/매력이 공식에 의해 생성되었는지 확인\n\n## When to Run\n\n- 시나리오 JSON의 장수 데이터를 수정한 후\n- 새로운 시나리오를 추가한 후\n- 3-stat → 5-stat 마이그레이션을 수행한","body":"# NPC Data 검증\n\n## Purpose\n\n시나리오 NPC 장수 데이터가 삼국지14 무장 정보 기준으로 최신화되었는지 검증합니다:\n\n1. **5-stat 완성** — 레거시 3-stat(통솔/무력/지력) → 5-stat(통솔/무력/지력/정치/매력) 마이그레이션 확인\n2. **삼국지14 기준 대조** — NPC 장수의 스탯이 삼국지14 공식 데이터와 일치하는지 확인\n3. **누락 장수** — 삼국지14에 존재하지만 시나리오에 없는 장수 식별\n4. **이름 정합** — 장수 이름이 삼국지14 한국어 표기와 일치하는지 확인\n5. **시대별 정합** — 장수의 생년/몰년이 삼국지14 데이터와 일치하는지 확인\n6. **비역사 NPC 공식** — 삼국지14에 없는 가상/비역사 NPC의 정치/매력이 공식에 의해 생성되었는지 확인\n\n## When to Run\n\n- 시나리오 JSON의 장수 데이터를 수정한 후\n- 새로운 시나리오를 추가한 후\n- 3-stat → 5-stat 마이그레이션을 수행한 후\n- 삼국지14 데이터 기반으로 장수 스탯을 갱신한 후\n- NPC 장수 데이터의 전체 정합성을 점검할 때\n\n## Data Sources\n\n삼국지14 무장 정보는 다음 소스에서 확인합니다:\n\n1. **로컬 xlsx** — `삼국지14 무장정보.xlsx` (프로젝트 루트)\n2. **온라인 위키** — https://wikiwiki.jp/sangokushi14/史実武将 (기본), https://wikiwiki.jp/sangokushi14/史実武将(PK) (PK 추가 무장)\n\nxlsx 파일이 최우선 소스이며, 온라인 위키는 보조/검증용입니다.\n\n## Stat Mapping\n\n| 한글 | 영문 필드    | 레거시 | 삼국지14 | 새 프로젝트 |\n| ---- | ------------ | ------ | -------- | ----------- |\n| 통솔 | `leadership` | O      | O        | O           |\n| 무력 | `strength`   | O      | O        | O           |\n| 지력 | `intel`      | O      | O        | O           |\n| 정치 | `politics`   | X      | O        | O           |\n| 매력 | `charm`      | X      | O        | O           |\n\n**핵심:** 레거시 시나리오 JSON은 `[affinity, name, picture, nationID, city, leadership, strength, intel, officerLevel, birth, death, ego, special, text]` 튜플 형식으로 3-stat만 포함. 새 프로젝트는 `politics`와 `charm`을 추가하여 5-stat 튜플로 확장해야 함.\n\n## Related Files\n\n| File                                           | Purpose                                |\n| ---------------------------------------------- | -------------------------------------- |\n| `삼국지14 무장정보.xlsx`                       | 삼국지14 무장 스탯 원본 데이터         |\n| `legacy/hwe/scenario/scenario_*.json`          | 레거시 시나리오 장수 데이터 (3-stat)   |\n| `legacy/hwe/scenario/frame.json`               | 시나리오 프레임/기본 구조              |\n| `legacy/hwe/sammo/Scenario/GeneralBuilder.php` | 레거시 장수 빌더 (3-stat)              |\n| `legacy/hwe/sammo/Scenario.php`                | 레거시 시나리오 로더                   |\n| `docs/architecture/legacy-scenarios.md`        | 시나리오 시스템 문서                   |\n| `backend/src/main/resources/data/scenarios/`   | 새 시나리오 데이터 (구현 대상, 5-stat) |\n\n## Workflow\n\n### Step 1: 새 프로젝트 시나리오 데이터 형식 확인\n\n**검사:** 새 프로젝트의 시나리오 장수 데이터가 5-stat 형식인지 확인합니다.\n\n```bash\n# 새 프로젝트 시나리오 파일 존재 확인\nls backend/src/main/resources/data/scenarios/ 2>/dev/null\n\n# 장수 데이터에서 politics/charm 필드 존재 확인\ngrep -rn \"politics\\|charm\" backend/src/main/resources/data/scenarios/ 2>/dev/null\n```\n\n**PASS:** 시나리오 장수 데이터에 5개 스탯(leadership, strength, intel, politics, charm) 모두 포함\n**FAIL:** politics 또는 charm이 누락됨 — 3-stat에서 마이그레이션 필요\n\n### Step 2: 레거시 시나리오 3-stat 현황 파악\n\n**파일:** `legacy/hwe/scenario/scenario_*.json`\n\n**검사:** 레거시 시나리오의 장수 수와 3-stat 구조를 파악합니다.\n\n```bash\n# 레거시 시나리오 수\nls legacy/hwe/scenario/scenario_*.json | wc -l\n\n# 샘플 장수 데이터 (첫 시나리오의 general 배열)\npython3 -c \"\nimport json\nwith open(''legacy/hwe/scenario/scenario_1010.json'') as f:\n    data = json.load(f)\ngenerals = data.get(''general'', [])\nprint(f''장수 수: {len(generals)}'')\nif generals:\n    g = generals[0]\n    print(f''첫 장수: {g[1]}, 통={g[5]}, 무={g[6]}, 지={g[7]}'')\n    print(f''튜플 길이: {len(g)}'')\n\" 2>/dev/null\n```\n\n**기록:** 레거시 튜플 인덱스 매핑:\n\n- `[0]` affinity, `[1]` name, `[2]` picture, `[3]` nationID\n- `[4]` city, `[5]` leadership, `[6]` strength, `[7]` intel\n- `[8]` officerLevel, `[9]` birth, `[10]` death\n- `[11]` ego, `[12]` special, `[13]` text (optional)\n\n### Step 3: 삼국지14 데이터 대조\n\n**검사:** 시나리오 NPC 장수의 스탯이 삼국지14 기준과 일치하는지 확인합니다.\n\n**xlsx 사용 시:**\n\n```bash\n# xlsx에서 장수 데이터 추출 (python3 + openpyxl)\npython3 -c \"\nimport openpyxl\nwb = openpyxl.load_workbook(''삼국지14 무장정보.xlsx'', read_only=True)\nws = wb.active\nheaders = [cell.value for cell in next(ws.iter_rows(min_row=1, max_row=1))]\nprint(''컬럼:'', headers[:10])\nfor row in ws.iter_rows(min_row=2, max_row=6, values_only=True):\n    print(row[:10])\n\" 2>/dev/null || echo \"openpyxl 미설치 — pip install openpyxl 필요\"\n```\n\n**온라인 위키 사용 시:**\n\n- https://wikiwiki.jp/sangokushi14/史実武将 에서 장수별 통솔/무력/지력/정치/매력 확인\n- https://wikiwiki.jp/sangokushi14/史実武将(PK) 에서 PK 추가 무장 확인\n\n**비교 방법:**\n\n1. 시나리오 장수 이름으로 삼국지14 데이터 검색\n2. 통솔/무력/지력 3개 스탯이 삼국지14와 일치하는지 확인\n3. 정치/매력 2개 스탯이 삼국지14에서 추출되어 추가되었는지 확인\n\n**PASS:** 장수 스탯이 삼국지14와 일치 (±5 범위 허용)\n**FAIL:** 스탯 불일치 또는 정치/매력 미추가\n\n### Step 4: 누락 장수 식별\n\n**검사:** 삼국지14에 존재하지만 시나리오에 없는 주요 장수를 식별합니다.\n\n```bash\n# 시나리오별 장수 이름 추출\npython3 -c \"\nimport json, glob\nnames = set()\nfor f in glob.glob(''legacy/hwe/scenario/scenario_*.json''):\n    with open(f) as fh:\n        data = json.load(fh)\n    for g in data.get(''general'', []) + data.get(''general_ex'', []) + data.get(''general_neutral'', []):\n        names.add(g[1])\nprint(f''고유 장수 수: {len(names)}'')\n\" 2>/dev/null\n```\n\n**PASS:** 삼국지14 주요 장수가 시나리오에 포함됨\n**FAIL:** 누락된 주요 장수 발견\n\n### Step 5: 이름/생몰년 정합성\n\n**검사:** 장수 이름이 삼국지14 한국어 표기와 일치하고, 생년/몰년이 정확한지 확인합니다.\n\n```bash\n# 이름 및 생몰년 샘플 추출\npython3 -c \"\nimport json\nwith open(''legacy/hwe/scenario/scenario_1010.json'') as f:\n    data = json.load(f)\nfor g in data.get(''general'', [])[:10]:\n    print(f''{g[1]}: 통={g[5]} 무={g[6]} 지={g[7]} 생={g[9]} 몰={g[10]}'')\n\" 2>/dev/null\n```\n\n**PASS:** 이름/생몰년이 삼국지14와 일치\n**FAIL:** 표기 차이 또는 생몰년 불일치 발견\n\n### Step 6: 비역사 NPC 정치/매력 공식 검증\n\n**검사:** 삼국지14에 존재하지 않는 가상/비역사 NPC 장수의 정치(politics)와 매력(charm) 스탯이 정의된 공식에 의해 생성되었는지 확인합니다.\n\n**배경:** 레거시 시나리오에는 삼국지14에 없는 가상 NPC(오랑캐, 이벤트 전용 장수 등)가 존재합니다. 이들은 삼국지14 대조가 불가능하므로, 기존 3-stat(통솔/무력/지력)을 기반으로 정치/매력을 생성하는 공식이 필요합니다.\n\n**공식 요구사항:**\n\n- 입력: 기존 3-stat (leadership, strength, intel) + 장수 특성(ego, special 등)\n- 출력: politics (0-100), charm (0-100)\n- 결정적: 같은 입력 → 같은 출력 (랜덤 요소 없음)\n- 합리적 분포: 극단값(0, 100) 편중 없이 자연스러운 분포\n\n```bash\n# 비역사 NPC 공식 관련 코드 검색\ngrep -rn \"generatePolitics\\|generateCharm\\|calcPolitics\\|calcCharm\\|formulaPolitics\\|formulaCharm\\|nonHistorical\\|virtualGeneral\" backend/src/main/kotlin/com/opensam/ 2>/dev/null\n\n# 가상 장수 식별 로직 검색\ngrep -rn \"isHistorical\\|isVirtual\\|isFictional\\|삼국지14\" backend/src/main/kotlin/com/opensam/ 2>/dev/null\n```\n\n**검증 항목:**\n\n1. 공식 함수가 존재하는지 확인\n2. 공식이 결정적인지 확인 (같은 입력 → 같은 출력)\n3. 삼국지14 대조 불가 장수에 대해 공식이 적용되었는지 확인\n4. 생성된 politics/charm 값이 0-100 범위이고 합리적 분포인지 확인\n\n**PASS:** 비역사 NPC용 정치/매력 생성 공식이 존재하고 올바르게 적용됨\n**FAIL:** 공식 미구현 또는 비역사 NPC에 정치/매력이 누락됨\n\n### Step 7: 5-stat 마이그레이션 진행률 보고\n\n모든 검사 결과를 종합하여 마이그레이션 상태를 보고합니다.\n\n## Output Format\n\n```markdown\n## NPC Data 검증 결과\n\n### 5-stat 마이그레이션 상태\n\n| 항목                    | 상태      | 상세                      |\n| ----------------------- | --------- | ------------------------- |\n| 새 시나리오 5-stat 형식 | PASS/FAIL | X개 시나리오 중 Y개 완료  |\n| politics 필드 추가      | PASS/FAIL | X명 장수 중 Y명 추가 완료 |\n| charm 필드 추가         | PASS/FAIL | X명 장수 중 Y명 추가 완료 |\n\n### 삼국지14 대조 결과\n\n| #   | 장수 이름 | 통  | 무  | 지  | 정  | 매  | 삼14 일치 | 비고      |\n| --- | --------- | --- | --- | --- | --- | --- | --------- | --------- |\n| 1   | 조조      | 72  | 72  | 91  | 91  | 96  | PASS      |           |\n| 2   | 유비      | 75  | 66  | 65  | 78  | 99  | FAIL      | 지력 차이 |\n\n### 비역사 NPC 공식 적용\n\n| 항목               | 상태      | 상세                            |\n| ------------------ | --------- | ------------------------------- |\n| 공식 함수 존재     | PASS/FAIL | 함수명/위치                     |\n| 결정적 출력        | PASS/FAIL | 같은 입력 → 같은 출력 확인      |\n| 적용 대상 커버리지 | PASS/FAIL | X명 비역사 NPC 중 Y명 적용 완료 |\n\n### 요약\n\n- 고유 장수 수: N명\n- 삼국지14 일치: X명 (X%)\n- 스탯 불일치: Y명\n- politics/charm 미추가: Z명\n- 비역사 NPC 공식 적용: W명\n```\n\n## Exceptions\n\n다음은 **위반이 아닙니다**:\n\n1. **레거시 시나리오의 3-stat** — 레거시 JSON은 원본 참조용; 3-stat이 정상. 새 프로젝트 시나리오만 5-stat 필수\n2. **스탯 미세 차이 (±5)** — 삼국지14 기본판과 PK판 간 스탯이 다를 수 있고, 게임 밸런스 조정이 있을 수 있음; ±5 이내 차이는 허용\n3. **가상 장수의 삼국지14 대조 면제** — 삼국지14에 없는 장수(오랑캐, 가상 NPC)는 삼국지14 스탯 대조 대상에서 제외; 단, 5-stat 완성은 필수이며 정치/매력은 공식에 의해 생성되어야 함\n4. **시나리오별 스탯 변동** — 삼국지14도 시나리오별로 장수 스탯이 변할 수 있음; 기본값 기준 대조\n5. **xlsx 미존재** — xlsx 파일이 없는 경우 온라인 위키만으로 검증 가능; xlsx 부재는 에러가 아님\n6. **openpyxl 미설치** — Python 패키지 미설치 시 수동 검증으로 대체; 에러가 아닌 안내로 보고\n7. **neutral/ex 장수** — `general_neutral`, `general_ex` 배열의 장수도 동일 기준 적용하되, 이 배열이 비어있는 것은 정상\n"},"lastSynced":"2026-03-08T02:14:12.244Z","agentAnalysis":{"suitability":{"en":"Perfect for Game Development Agents needing comprehensive NPC data validation against official Three Kingdoms 14 standards.","zh":"非常适合需要对官方三国志14标准进行全面NPC数据验证的游戏开发代理。","ja":"Official Three Kingdoms 14標準に対する包括的なNPCデータ検証を必要とするゲーム開発エージェントに最適です。","ko":"공식 삼국지 14 표준에 대해 종합적인 NPC 데이터 검증이 필요한 게임 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo de juegos que necesitan una validación de datos de NPC completa contra los estándares oficiales de Three Kingdoms 14.","fr":"Parfait pour les agents de développement de jeux nécessitant une validation complète des données de NPC contre les normes officielles de Three Kingdoms 14.","de":"Perfekt für Game-Development-Agents, die eine umfassende Validierung von NPC-Daten gegen die offiziellen Three Kingdoms 14-Standards benötigen.","pt":"Perfeito para Agentes de Desenvolvimento de Jogos que necessitam de validação abrangente de dados de NPC contra os padrões oficiais do Three Kingdoms 14.","ru":"Идеально подходит для агентов по разработке игр, которым требуется всесторонняя проверка данных NPC на соответствие официальным стандартам Three Kingdoms 14.","ar":"مثالي للوكلاء الذين يحتاجون إلى التحقق الشامل من بيانات NPC مقابل معايير Three Kingdoms 14 الرسمية."},"recommendation":{"en":"Empowers agents to validate NPC data for 5-stat completion and accuracy, ensuring consistency with official Three Kingdoms 14 data, including JSON scenario data, using standards such as 통솔/무력/지력/정치/매력 stats and 한국어 name conventions.","zh":"赋予代理验证NPC数据的5项统计完成和准确性，确保与官方三国志14数据的一致性，包括JSON场景数据，使用诸如统率/武力/智力/政治/魅力统计和韩语名称约定的标准。","ja":"エージェントが、統率/武力/智力/政治/魅力の統計や韓国語の名前規約などの標準を使用して、公式の三国志14データ（JSONシナリオデータを含む）との一貫性を確保するための、NPCデータの5つのステータス完成と精度の検証を可能にします。","ko":"에이전트가 통솔/무력/지력/정치/매력 통계 및 한국어 이름 규약 등을 사용하여 공식 삼국지 14 데이터(JSON 시나리오 데이터 포함)와 일관성을 보장하는 NPC 데이터의 5가지 통계 완성 및 정확도 검사를 수행할 수 있도록 합니다.","es":"Habilita a los agentes a validar los datos de NPC para la finalización y precisión de 5 estadísticas, garantizando la consistencia con los datos oficiales de Three Kingdoms 14, incluidos los datos de escenario JSON, utilizando estándares como las estadísticas 통솔/무력/지력/정치/매력 y las convenciones de nombres en 한국어.","fr":"Permet aux agents de valider les données de NPC pour l''achèvement et la précision des 5 statistiques, en garantissant la cohérence avec les données officielles de Three Kingdoms 14, y compris les données de scénario JSON, en utilisant des normes telles que les statistiques 통솔/무력/지력/정치/매력 et les conventions de noms en 한국어.","de":"Ermächtigt die Agenten, NPC-Daten für die Vervollständigung und Genauigkeit von 5 Statistiken zu validieren, um die Konsistenz mit den offiziellen Three Kingdoms 14-Daten sicherzustellen, einschließlich JSON-Szenariodaten, unter Verwendung von Standards wie 통솔/무력/지력/정치/매력-Statistiken und 한국어-Namenskonventionen.","pt":"Habilita os agentes a validar dados de NPC para conclusão de 5 estatutos e precisão, garantindo a consistência com os dados oficiais do Three Kingdoms 14, incluindo dados de cenário JSON, usando padrões como estatutos 통솔/무력/지력/정치/매력 e convenções de nomenclatura em 한국어.","ru":"Наделяет агентов возможностью проверять данные NPC на полноту и точность, обеспечивая соответствие официальным данным Three Kingdoms 14, включая сценарные данные JSON, используя стандарты, такие как статистики 통솔/무력/지력/정치/매력 и именные конвенции на корейском языке.","ar":"يمكن الوكلاء من التحقق من بيانات NPC لاستكمال 5 إحصائيات وضمان الدقة، مما يضمن الاتساق مع البيانات الرسمية لبرنامج Three Kingdoms 14، بما في ذلك بيانات السيناريو JSON، باستخدام معايير مثل إحصائيات 통솔/무력/지력/정치/매력 وتوافق التسمية باللغة الكورية."},"useCases":{"en":["Validating scenario JSON data against official Three Kingdoms 14 standards","Identifying missing NPCs in scenario data","Verifying NPC stats and names for consistency with official data"],"zh":["验证场景JSON数据是否符合官方三国志14标准","识别场景数据中缺失的NPC","验证NPC统计数据和名称是否与官方数据一致"],"ja":["公式の三国志14標準に対するシナリオJSONデータの検証","シナリオデータ内の不足しているNPCの特定","公式データとの一貫性を確保するためのNPCの統計と名前の検証"],"ko":["공식 삼국지 14 표준에 대한 시나리오 JSON 데이터의 검증","시나리오 데이터에서 누락된 NPC를 식별","공식 데이터와의 일관성을 보장하기 위한 NPC 통계 및 이름의 검증"],"es":["Validar los datos JSON de escenario contra los estándares oficiales de Three Kingdoms 14","Identificar NPCs faltantes en los datos de escenario","Verificar las estadísticas y nombres de los NPCs para la coherencia con los datos oficiales"],"fr":["Valider les données JSON de scénario contre les normes officielles de Three Kingdoms 14","Identifier les NPCs manquants dans les données de scénario","Vérifier les statistiques et les noms des NPCs pour la cohérence avec les données officielles"],"de":["JSON-Szenariodaten gegen die offiziellen Three Kingdoms 14-Standards validieren","Fehlende NPCs in den Szenariodaten identifizieren","NPC-Statistiken und -Namen auf Konsistenz mit den offiziellen Daten überprüfen"],"pt":["Validar dados JSON de cenário contra os padrões oficiais do Three Kingdoms 14","Identificar NPCs ausentes nos dados de cenário","Verificar estatutos e nomes de NPCs para consistência com os dados oficiais"],"ru":["Проверка данных JSON-сценария на соответствие официальным стандартам Three Kingdoms 14","Определение отсутствующих NPC в данных сценария","Проверка статистики и имен NPC на соответствие официальным данным"],"ar":["التحقق من بيانات السيناريو JSON مقابل معايير Three Kingdoms 14 الرسمية","تحديد NPCs الناقصة في بيانات السيناريو","التحقق من إحصائيات وأسماء NPCs للتأكد من الاتساق مع البيانات الرسمية"]},"limitations":{"en":["Requires access to official Three Kingdoms 14 data","Limited to scenario JSON data","Specific to Three Kingdoms 14 game data"],"zh":["需要访问官方三国志14数据","仅限于场景JSON数据","特定于三国志14游戏数据"],"ja":["公式の三国志14データへのアクセスが必要","シナリオJSONデータのみに限定される","三国志14ゲームデータに特有のもの"],"ko":["공식 삼국지 14 데이터에 대한 액세스가 필요","시나리오 JSON 데이터에만 제한","삼국지 14 게임 데이터에 특정"],"es":["Requiere acceso a los datos oficiales de Three Kingdoms 14","Limitado a los datos JSON de escenario","Específico para los datos del juego Three Kingdoms 14"],"fr":["Nécessite un accès aux données officielles de Three Kingdoms 14","Limité aux données JSON de scénario","Spécifique aux données du jeu Three Kingdoms 14"],"de":["Benötigt Zugriff auf die offiziellen Three Kingdoms 14-Daten","Begrenzt auf JSON-Szenariodaten","Spezifisch für Three Kingdoms 14-Spiel-Daten"],"pt":["Requer acesso aos dados oficiais do Three Kingdoms 14","Limitado a dados JSON de cenário","Específico para dados de jogo do Three Kingdoms 14"],"ru":["Требует доступа к официальным данным Three Kingdoms 14","Ограничен данными JSON-сценария","Спецефичен для данных игры Three Kingdoms 14"],"ar":["يتطلب الوصول إلى البيانات الرسمية لبرنامج Three Kingdoms 14","محدود ببيانات السيناريو JSON","محدد لبيانات لعبة Three Kingdoms 14"]},"version":4},"contentHash":"2ac722c00cdffd7f7ac078c28a8db2106c8091f989e74f6826dd750f0ed9bf2c","qualityScore":48}');
