INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('curiositech/some_claude_skills/fancy-yard-landscaper', 'fancy-yard-landscaper', 'curiositech', 'some_claude_skills', 'community', 'fancy-yard-landscaper curiositech some_claude_skills community fancy-yard-landscaper 是一款智能园林设计 AIエージェント，帮助开发者自动化设计和管理园林 fancy-yard-landscaper は、庭園設計を自動化する AIエージェントで、開発者の仕事を容易にします fancy-yard-landscaper는 인공지능 정원 디자인 도구로 개발자가 정원 관리를 자동화하도록 도와줍니다 Fancy-yard-landscaper es una herramienta de inteligencia artificial que facilita la vida de los desarrolladores de aplicaciones de jardinería Fancy-yard-landscaper est un outil d''intelligence artificielle qui facilite la vie des développeurs d''applications de jardinage Fancy-yard-landscaper ist ein KI-Tool, das das Leben von Entwicklern von Gartenanwendungen erleichtert O fancy-yard-landscaper é uma ferramenta de IA que facilita a criação de jardins elegantes e personalizados ИИ Агент fancy-yard-landscaper - это инструмент, который упрощает создание красивых и индивидуальных ландшафтов أداة fancy-yard-landscaper هي أداة ذكاء اصطناعي تساعد على تصميم حدائق أنيقة ومخصصة Claude skills that make my life easier. AIエージェント 智能园林设计 fancy-yard-landscaper 如何使用 fancy-yard-landscaper fancy-yard-landscaper 安装指南 fancy-yard-landscaper 与其他设计工具的比较 Claude skills that make my life easier.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryanallen/Studio/capture-webpage', 'community', 'ryanallen', 'Studio', 'ryanallen/Studio', 'capture-webpage', 1, 0, 48, '2026-03-03T01:39:11Z', '2026-03-03T02:09:01.921Z', '7b04d59351a684f76efa06928ad8b5a1a21fd32240161ab86d5a538157a0a031', '{"id":"ryanallen/Studio/capture-webpage","name":"capture-webpage","description":{"zh":"捕获网页是一种操作系统，用于编排团队的AI代理，提高设计过程的效率","ja":"キャプチャーウェブページは、チームのAIエージェントをオーケストレートするオペレーションシステムで、デザインプロセスの効率を高める","ko":"웹페이지 캡처는 팀의 AI 에이전트를 오케스트레이션하는 운영 체제로 디자인 프로세스의 효율을 높인다","es":"Nuestra herramienta de captura de página web es un sistema de operaciones para equipos que orquesta Agentes de IA especializados a través del proceso de diseño","fr":"Notre outil de capture de page web est un système d''exploitation pour les équipes qui orchestre des Agents IA spécialisés à travers le processus de conception","de":"Unser Tool für die Erfassung von Webseiten ist ein Betriebssystem für Teams, das spezialisierte KI-Agents durch den Entwicklungsprozess orchestriert","pt":"Sistema de operações para equipes que orquestra agentes de IA especializados através do processo de design","ru":"Операционная система для команд, которая оркестрирует специализированные ИИ Агенты через процесс проектирования","ar":"نظام عمليات للفرق التي توجيه وكلاء الذكاء الاصطناعي المتخصصين من خلال عملية التصميم","en":"an operations system for teams that orchestrates specialized AI agents through the design process"},"seo":{"title":{"zh":"AI代理捕获网页 - 按设计过程编排团队","ja":"AIエージェントによるウェブページのキャプチャー - デザインプロセスをオーケストレート","ko":"AI 에이전트 웹페이지 캡처 - 디자인 프로세스 오케스트레이션","es":"Herramientas de captura de página web con Agentes de IA","fr":"Outil de capture de page web avec Agents IA","de":"Webseitenerfassung mit KI-Agents","pt":"Ferramenta de Captura de Página Web com Agentes de IA","ru":"ИИ Агенты для Захвата Веб-страниц","ar":"أداة التقاط صفحة ا