INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryanallen/Studio/capture-webpage', 'capture-webpage', 'ryanallen', 'Studio', 'community', 'capture-webpage ryanallen Studio community 捕获网页是一种操作系统，用于编排团队的AI代理，提高设计过程的效率 キャプチャーウェブページは、チームのAIエージェントをオーケストレートするオペレーションシステムで、デザインプロセスの効率を高める 웹페이지 캡처는 팀의 AI 에이전트를 오케스트레이션하는 운영 체제로 디자인 프로세스의 효율을 높인다 Nuestra herramienta de captura de página web es un sistema de operaciones para equipos que orquesta Agentes de IA especializados a través del proceso de diseño Notre outil de capture de page web est un système d''exploitation pour les équipes qui orchestre des Agents IA spécialisés à travers le processus de conception Unser Tool für die Erfassung von Webseiten ist ein Betriebssystem für Teams, das spezialisierte KI-Agents durch den Entwicklungsprozess orchestriert Sistema de operações para equipes que orquestra agentes de IA especializados através do processo de design Операционная система для команд, которая оркестрирует специализированные ИИ Агенты через процесс проектирования نظام عمليات للفرق التي توجيه وكلاء الذكاء الاصطناعي المتخصصين من خلال عملية التصميم an operations system for teams that orchestrates specialized AI agents through the design process 如何使用AI代理 什么是AI工具 捕获网页安装 捕获网页设置指南 AI代理与CLI 捕获网页与React 捕获网页与Python 捕获网页与Node.js an operations system for teams that orchestrates specialized AI agents through the design process');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SynkraAI/aios-core/aios-sm', 'community', 'SynkraAI', 'aios-core', 'SynkraAI/aios-core', 'aios-sm', 1899, 655, 48, '2026-02-28T12:35:32Z', '2026-02-28T12:48:04.363Z', 'f340516e649f508f4ed9fb832a1517f42955849f9b3dad760ad1fbcc1f3df382', '{"id":"SynkraAI/aios-core/aios-sm","name":"aios-sm","description":{"zh":"Synkra AIOS v4.0是一个AI编排系统框架，专为全栈开发设计。它使用Node.js和TypeScript构建，提供AI代理自动化、CLI工具集成和开发工作流优化，支持与Claude AI等模型的集成。","ja":"Synkra AIOS v4.0は、フルスタック開発向けに設計されたAIオーケストレーションシステムフレームワークです。Node.jsとTypeScriptで構築され、AIエージェントの自動化、CLIツール統合、開発ワークフロー最適化を提供し、Claude AIなどのモデルと連携します。","ko":"Synkra AIOS v4.0은 풀스택 개발을 위해 설계된 AI 오케스트레이션 시스템 프레임워크입니다. Node.js와 TypeScript로 구축되었으며, AI 에이전트 자동화, CLI 도구 통합 및 개발 워크플로우 최적화를 제공하고 Claude AI 등의 모델과 연동합니다.","es":"Synkra AIOS es un framework de orquestación de agentes IA para desarrollo full stack. Proporciona herramientas para automatizar tareas de desarrollo, integrar con modelos como Claude y optimizar flujos de trabajo con Node.js y TypeScript.","fr":"Synkra AIOS est un framework d''orchestration d''outils IA pour le développement full stack. Il offre des outils pour automatiser les tâches de développement, intégrer des modèles comme Claude et optimiser les flux de travail avec Node.js et TypeScript.","de":"Synkra AIOS ist ein KI-Agenten Orchestrierungs-Framework für die Full-Stack Entwicklung. Es bietet Tools zur Automatisierung von Entwicklungsaufgaben, Integration mit Modellen wie Claude und Optimierung von Workflows mit Node.js und TypeScript.","pt":"Synkra AIOS é um framework de orquestração de agentes IA para desenvolvimento full stack em Node.js e TypeScript. Automatiza fluxos de trabalho complexos com CLI integrado e arquitetura modular para equipes de desenvolvimento.","ru":"Synkra AIOS - это фреймворк оркестрации ИИ агентов для full stack разработки на Node.js и TypeScript. Автоматизирует сложные рабочие процессы с интегрированным CLI и модульной архитектурой для команд разработки.","ar":"Synkra AIOS هو إطار عمل لتنسيق أدوات الذكاء الاصطناعي للتطوير الشامل باستخدام Node.js و TypeScript. يقوم بأتمتة سير العمل المعقدة باستخدام CLI مدمج وهندسة معيارية لفرق التطوير.","en":"Synkra AIOS: AI-Orchestrated System for Full Stack Development - Core Framework v4.0"},"seo":{"title":{"zh":"Synkra AIOS v4.0: AI智能体全栈开发框架 - Node.js自动化工具","ja":"Synkra AIOS v4.0: AIエージェントのフルスタック開発フレームワーク","ko":"Synkra AIOS v4.0: AI 에이전트 풀스택 개발 프레임워크 - Node.js 자동화","es":"Synkra AIOS: Framework de Agentes IA para Desarrollo Full...","fr":"Synkra AIOS: Framework d''Outils IA pour le Développement ...","de":"Synkra AIOS: KI-Agenten Framework für Full-Stack Entwicklung","pt":"Synkra AIOS: Framework de Agentes IA para Desenvolvimento...","ru":"Synkra AIOS: Фреймворк ИИ Агентов для Full Stack Разработки","ar":"Synkra AIOS: إطار عمل أدوات الذكاء الاصطناعي للتطوير الشامل","en":"aios-sm"},"description":{"zh":"Synkra AIOS v4.0是一个AI编排系统框架，专为全栈开发设计。它使用Node.js和TypeScript构建，提供AI代理自动化、CLI工具集成和开发工作流优化，支持与Claude AI等模型的集成。","ja":"Synkra AIOS v4.0は、フルスタック開発向けに設計されたAIオーケストレーションシステムフレームワークです。Node.jsとTypeScriptで構築され、AIエージェントの自動化、CLIツール統合、開発ワークフロー最適化を提供し、Claude AIなどのモデルと連携します。","ko":"Synkra AIOS v4.0은 풀스택 개발을 위해 설계된 AI 오케스트레이션 시스템 프레임워크입니다. Node.js와 TypeScript로 구축되었으며, AI 에이전트 자동화, CLI 도구 통합 및 개발 워크플로우 최적화를 제공하고 Claude AI 등의 모델과 연동합니다.","es":"Synkra AIOS es un framework de orquestación de agentes IA para desarrollo full stack. Proporciona herramientas para automatizar tareas de desarrollo, integra...","fr":"Synkra AIOS est un framework d''orchestration d''outils IA pour le développement full stack. Il offre des outils pour automatiser les tâches de développement, ...","de":"Synkra AIOS ist ein KI-Agenten Orchestrierungs-Framework für die Full-Stack Entwicklung. Es bietet Tools zur Automatisierung von Entwicklungsaufgaben, Integr...","pt":"Synkra AIOS é um framework de orquestração de agentes IA para