INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Heldinhow/openclaw-swarm/sherpa-onnx-tts', 'sherpa-onnx-tts', 'Heldinhow', 'openclaw-swarm', 'community', 'sherpa-onnx-tts Heldinhow openclaw-swarm community sherpa-onnx-tts enables local text-to-speech functionality using the OpenClaw offline CLI, benefiting developers who require advanced TTS capabilities. It supports context sharing, event-driven, and parallel execution. sherpa-onnx-tts是一个本地语音合成工具，使用OpenClaw的sherpa-onnx offline CLI实现语音合成 sherpa-onnx-ttsは、OpenClawのsherpa-onnxオフラインCLIを使用したローカルTTSの実現 sherpa-onnx-tts는 OpenClaw의 sherpa-onnx 오프라인 CLI를 사용하여 로컬 TTS를 구현하는 도구 sherpa-onnx-tts es una herramienta de inteligencia artificial que permite la orquestación de subagentes y la compartición de contexto mediante la línea de comandos offline de OpenClaw sherpa-onnx-tts est un outil d''intelligence artificielle qui permet l''orchestration de sous-agents et le partage de contexte via la ligne de commande offline d''OpenClaw sherpa-onnx-tts ist ein künstliches Intelligenz-Tool, das die Orchestrierung von Subagenten und die Kontextfreigabe über die Offline-CLI von OpenClaw ermöglicht O sherpa-onnx-tts é uma ferramenta de IA que permite a orquestração de subagentes com compartilhamento de contexto e execução paralela sherpa-onnx-tts - это инструмент ИИ, который позволяет оркестровать субагентов с обменом контекстом и параллельным выполнением sherpa-onnx-tts هو أداة ذكاء اصطناعي تتيح إدارة المشتقات مع مشاركة السياق والتنفيذ الموازي how to use sherpa-onnx-tts sherpa-onnx-tts install sherpa-onnx-tts setup guide what is sherpa-onnx-tts sherpa-onnx-tts alternative sherpa-onnx-tts vs OpenClaw local TTS solutions offline CLI text-to-speech sherpa-onnx-tts configuration sherpa-onnx-tts 本地语音合成 AIエージェント OpenClaw sherpa-onnx offline CLI 语音模型 事件驱动 并行执行 Utilizes the sherpa-onnx offline CLI for local TTS functionality Supports context sharing for enhanced subagent orchestration Enables event-driven and parallel execution for efficient processing Requires downloading the runtime for the user''s OS, extracting into ~/.openclaw/tools/sherpa-onnx-tts/runtime Needs a voice model download, extracting into ~/.openclaw/tools/sherpa-onnx-tts/models Involves updating ~/.openclaw/openclaw.json for configuration sherpa-onnx-tts is a skill that provides local text-to-speech functionality using the sherpa-onnx offline CLI, enabling enhanced subagent orchestration for OpenClaw.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wollfoo/codex-setup/common', 'community', 'wollfoo', 'codex-setup', 'wollfoo/codex-setup', 'common', 0, 0, 48, '2026-03-07T01:49:01.804Z', '2026-03-07T03:27:45.329Z', '4dfa81b6e37ad8111f05064450a8039a9261ae6b8cb8b83d7975d534aa191f74', '{"id":"wollfoo/codex-setup/common","name":"common","description":{"en":"The Common skill provides utilities for managing API keys and supporting Vertex AI, benefiting AI agent developers by simplifying client initialization and API interactions.","zh":"Common Skill 是一个用于 Gemini API 的通用库，提供 API Key 管理、Vertex AI 支持和 Client Helpers 等功能","ja":"Common Skill は Gemini API 用の共通ライブラリで、API Key 管理、Vertex AI サポート、クライアントヘルパーなどの機能を提供します","ko":"Common Skill은 Gemini API용 공통 라이브러리로서 API 키 관리, Vertex AI 지원, 클라이언트 헬퍼 등의 기능을 제공합니다","es":"Common Skill es una biblioteca de utilidades compartidas para desarrolladores que utilizan la API de Gemini, con funcionalidades como gestión de claves API y soporte para Vertex AI","fr":"Common Skill est une bibliothèque d''utilitaires partagés pour les développeurs qui utilisent l''API Gemini, avec des fonctionnalités comme la gestion des clés API et le support de Vertex AI","de":"Common Skill ist eine Bibliothek von gemeinsam genutzten Utilitys für Entwickler, die die Gemini-API verwenden, mit Funktionen wie API-Schlüsselverwaltung und Vertex-AI-Unterstützung","pt":"O Common Skill é uma biblioteca de utilitários para desenvolvedores que utilizam a API Gemini, oferecendo recursos como gerenciamento de chaves API e suporte ao Vertex AI","ru":"Common Skill - это библиотека утилит для разработчиков, использующих API Gemini, предоставляющая функции như управление ключами API и поддержка Vertex AI","ar":"مهارة Common هي مكتبة من أدوات المساعدة للعاملين في مجال التطوير الذين يستخدمون واجهة برمجة تطبيقات Gemini، وتقدم ميزات مثل إدارة مفاتيح API ودعم Vertex AI"},"seo":{"title":{"en":"Common: API Key Management and Vertex AI Support for AI A...","zh":"Common Skill Setup Guide: Gemini API 和 Vertex AI 集成","ja":"Common Skill セットアップガイド: Gemini API と Vertex AI の統合","ko":"Common Skill 설정 가이드: Gemini API 및 Vertex AI 통합","es":"Guía de configuración de Common Skill para Agentes de IA","fr":"Guide de configuration de Common Skill pour les Outils d''IA","de":"Einrichtungsleitfaden für Common Skill bei KI-Agents","pt":"Guia de Configuração do Common Skill para Desenvolvedores","ru":"Настройка Common Skill: ИИ Агенты для Разработчиков","ar":"دليل إعداد مهارة Common للعاملين في مجال التطوير"},"description":{"en":"Discover how to streamline API key management and leverage Vertex AI support with the Common skill - get started now and optimize your AI workflow!","zh":"了解 Common Skill 的功能和特点，包括 API Key 管理、Vertex AI 支持和 Client Helpers","ja":"Common Skill の機能と特徴をご紹介します。API Key 管理、Vertex AI サポート、クライアントヘルパーなど","ko":"Common Skill의 기능과 특징을 알아보세요. API 키 관리, Vertex AI 지원, 클라이언트 헬퍼 등","es":"Aprende a configurar Common Skill para desarrolladores, con características como gestión de claves API y soporte para Vertex AI","fr":"Découvrez comment configurer Common Skill pour les développeurs, avec des fonctionnalités comme la gestion des clés API et le support de Vertex AI","de":"Erfahren Sie, wie Sie Common Skill für Entwickler konfigurieren, mit Funktionen wie API-Schlüsselverwaltung und Vertex-AI-Unterstützung","pt":"Aprenda a configurar o Common Skill para utilizar a API Gemini de forma eficaz, com recursos como gerenciamento de chaves API e suporte ao Vertex AI","ru":"Узнайте, как настроить Common Skill для эффективного использования API Gemini, с функциями như управление ключами API и поддержка Vertex AI","ar":"تعرف على كيفية إعداد مهارة Common لاستخدام واجهة برمجة تطبيقات Gemini بشكل فعال، مع ميزات مثل إدارة مفاتيح API ودعم Vertex AI"},"definition":{"en":"Common is a library of utilities for AI agent skills using the Gemini API, offering features like API key management and Vertex AI support.","zh":"Common Skill 是一个用于 Gemini API 的通用库","ja":"Common Skill は Gemini API 用の共通ライブラリです","ko":"Common Skill은 Gemini API용 공통 라이브러리입니다","es":"Common Skill es una biblioteca de utilidades compartidas para desarrolladores de Agentes de IA","fr":"Common Skill est une bibliothèque d''utilitaires partagés pour les développeurs d''Outils d''IA","de":"Common Skill ist eine Bibliothek von gemeinsam genutzten Utilitys für KI-Agents-Entwickler","pt":"O Common Skill é uma biblioteca de utilitários de código aberto que fornece funcionalidades compartilhadas para desenvolvedores que utilizam a API Gemini","ru":"Common Skill - это открытая библиотека утилит, обеспечивающая общие функции для разработчиков, использующих API Gemini","ar":"مهارة Common هي مكتبة من أدوات المساعدة مفتوحة المصدر توفر وظائف مشتركة للعاملين في مجال التطوير الذين يستخدمون واجهة برمجة تطبيقات Gemini"},"features":{"en":["Automates API key management via GEMINI_API_KEY","Supports Vertex AI for seamless AI Studio integration","Provides client helpers for automatic client initialization","Utilizes Python for flexible and efficient development","Leverages the Gemini API for robust AI agent interactions","Enables easy switching between AI Studio and Vertex AI"],"zh":["API Key 管理","Vertex AI 支持","Client Helpers","自动初始化 client","Gemini API 集成","Vertex AI 与 AI Studio 之间的切换"],"ja":["API Key 管理","Vertex AI サポート","クライアントヘルパー","自動クライアント初期化","Gemini API 統合","Vertex AI と AI Studio の切り替え"],"ko":["API 키 관리","Vertex AI 지원","클라이언트 헬퍼","자동 클라이언트 초기화","Gemini API 통합","Vertex AI와 AI Studio 사이의 전환"],"es":["Gestión de claves API","Soporte para Vertex AI","Ayuda para clientes","Inicialización automática de clientes","Integración con la API de Gemini"],"fr":["Gestion des clés API","Support de Vertex AI","Aide pour les clients","Initialisation automatique des clients","Intégration avec l''API Gemini"],"de":["API-Schlüsselverwaltung","Vertex-AI-Unterstützung","Kundenhilfe","Automatische Initialisierung von Kunden","Integration mit der Gemini-API"],"pt":["Gerenciamento de chaves API","Suporte ao Vertex AI","Inicialização automática de clientes","Integração com a API Gemini","Utilitários de código aberto para desenvolvedores"],"ru":["Управление ключами API","Поддержка Vertex AI","Автоматическая инициализация клиентов","Интеграция с API Gemini","Открытые утилиты для разработчиков"],"ar":["إدارة مفاتيح API","دعم Vertex AI","تخصيص العميل تلقائيًا","إدماج واجهة برمجة تطبيقات Gemini","أدوات مفتوحة المصدر للعاملين في مجال التطوير"]},"keywords":{"en":["common skill install","how to use common for AI agents","common vs Gemini API","common setup guide for Vertex AI","what is common skill","common alternative for AI key management","common API key management tutorial","vertex AI support with common skill","common skill for AI agent development"],"zh":["Common Skill","Gemini API","Vertex AI","AIエージェント","API Key 管理","Client Helpers","Python","库"],"ja":["Common Skill","Gemini API","Vertex AI","AIエージェント","API Key 管理","クライアントヘルパー","Python","ライブラリ"],"ko":["Common Skill","Gemini API","Vertex AI","AI 에이전트","API 키 관리","클라이언트 헬퍼","Python","라이브러리"],"es":["Common Skill","Agentes de IA","desarrollo de Agentes de IA","API de Gemini","gestión de claves API","soporte para Vertex AI","Ayuda para clientes","Inicialización automática de clientes"],"fr":["Common Skill","Outils d''IA","développement d''Outils d''IA","API Gemini","gestion des clés API","support de Vertex AI","Aide pour les clients","Initialisation automatique des clients"],"de":["Common Skill","KI-Agents","Entwicklung von KI-Agents","Gemini-API","API-Schlüsselverwaltung","Vertex-AI-Unterstützung","Kundenhilfe","Automatische Initialisierung von Kunden"],"pt":["Common Skill","API Gemini","Gerenciamento de chaves API","Suporte ao Vertex AI","Desenvolvimento de software","Bibliotecas de utilitários","Código aberto","Programação em Python"],"ru":["Common Skill","API Gemini","Управление ключами API","Поддержка Vertex AI","Разработка программного обеспечения","Библиотеки утилит","Открытый код","Программирование на Python"],"ar":["مهارة Common","واجهة برمجة تطبيقات Gemini","إدارة مفاتيح API","دعم Vertex AI","تطوير البرمجيات","مكتبات الأدوات","الكود المفتوح","برمجة بالغة بايثون"]}},"owner":"wollfoo","repo":"codex-setup","repoPath":"wollfoo/codex-setup","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.804Z","topics":[],"category":"community","skillMd":{"name":"common","description":"Shared utilities for Gemini-based skills including API key management, Vertex AI configuration, and client helpers. Use as dependency for skills requiring Gemini API access.","bodyPreview":"# Common Skill Utilities\n\nThư viện dùng chung cho các skills sử dụng Gemini API.\n\n## Capabilities\n\n- **API Key Management** (quản lý API key) – Tự động tìm `GEMINI_API_KEY` từ nhiều nguồn\n- **Vertex AI Support** (hỗ trợ Vertex AI) – Chuyển đổi giữa AI Studio và Vertex AI\n- **Client Helpers** (trợ giúp client) – Tự động khởi tạo client phù hợp\n\n## Usage\n\n```python\nimport sys\nfrom pathlib import Path\n\n# Thêm common directory vào path\ncommon_dir = Path(__file__).parent.parent.parent / ''common''\nsys.","body":"# Common Skill Utilities\n\nThư viện dùng chung cho các skills sử dụng Gemini API.\n\n## Capabilities\n\n- **API Key Management** (quản lý API key) – Tự động tìm `GEMINI_API_KEY` từ nhiều nguồn\n- **Vertex AI Support** (hỗ trợ Vertex AI) – Chuyển đổi giữa AI Studio và Vertex AI\n- **Client Helpers** (trợ giúp client) – Tự động khởi tạo client phù hợp\n\n## Usage\n\n```python\nimport sys\nfrom pathlib import Path\n\n# Thêm common directory vào path\ncommon_dir = Path(__file__).parent.parent.parent / ''common''\nsys.path.insert(0, str(common_dir))\n\nfrom api_key_helper import get_api_key_or_exit, get_client, get_vertex_config\n\n# Lấy API key\napi_key = get_api_key_or_exit()\n\n# Hoặc lấy client tự động\nclient_info = get_client()\n```\n\n## API Key Lookup Order\n\n1. Process environment variable (`GEMINI_API_KEY`)\n2. Project root `.env` file\n3. `.claude/.env` file\n4. `.claude/skills/.env` file\n5. Skill directory `.env` file\n\n## Vertex AI Configuration\n\n```bash\nexport GEMINI_USE_VERTEX=true\nexport VERTEX_PROJECT_ID=your-gcp-project-id\nexport VERTEX_LOCATION=us-central1\n```\n\n## Files\n\n- `api_key_helper.py` – Main utility module\n- `README.md` – Detailed documentation\n"},"lastSynced":"2026-03-07T03:27:45.329Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing streamlined API key management and Vertex AI support.","zh":"非常适合需要简化API密钥管理和Vertex AI支持的AI代理开发人员。","ja":"APIキー管理とVertex AIサポートの簡素化が必要なAIエージェント開発者に最適です。","ko":"API 키 관리 및 Vertex AI 지원을 간소화해야 하는 AI 에이전트 개발자를 위한 최적의 솔루션입니다.","es":"Perfecto para desarrolladores de Agentes de IA que necesitan una gestión de claves de API simplificada y soporte para Vertex AI.","fr":"Parfait pour les développeurs d''Agents IA ayant besoin d''une gestion de clés d''API simplifiée et d''un support pour Vertex AI.","de":"Perfekt für AI-Agent-Entwickler, die eine vereinfachte API-Schlüsselverwaltung und Unterstützung für Vertex AI benötigen.","pt":"Perfeito para Desenvolvedores de Agentes de IA que precisam de gerenciamento de chaves de API simplificado e suporte ao Vertex AI.","ru":"Идеально для разработчиков агентов ИИ, которым необходим упрощенный менеджмент ключей API и поддержка Vertex AI.","ar":"مثالي لمنطقيين وكتاب برمجيات وكلاء الذكاء الاصطناعي الذين يحتاجون إلى إدارة مفتاح واجهة برمجة التطبيقات المبسطة ودعم Vertex AI."},"recommendation":{"en":"Empowers agents to seamlessly manage API keys from multiple sources and switch between AI Studio and Vertex AI using automated client helpers and the Gemini API.","zh":"赋予代理无缝管理来自多个来源的API密钥，并使用自动化客户端帮助程序和Gemini API在AI Studio和Vertex AI之间切换的能力。","ja":"エージェントが自動クライアントヘルパーとGemini APIを使用して、複数のソースからのAPIキーの管理とAI StudioおよびVertex AIの切り替えをシームレスに実行することができます。","ko":"에이전트가 자동 클라이언트 헬퍼와 Gemini API를 사용하여 여러 소스에서 가져온 API 키를 관리하고 AI Studio 및 Vertex AI를无缝切换할 수 있도록 합니다.","es":"Permite a los agentes gestionar de forma transparente las claves de API de múltiples fuentes y cambiar entre AI Studio y Vertex AI utilizando ayudantes de cliente automatizados y la Gemini API.","fr":"Permet aux agents de gérer de manière transparente les clés d''API provenant de plusieurs sources et de basculer entre AI Studio et Vertex AI en utilisant des aides clientes automatisées et l''API Gemini.","de":"Ermöglicht es den Agenten, API-Schlüssel aus mehreren Quellen nahtlos zu verwalten und zwischen AI Studio und Vertex AI mit automatisierten Client-Hilfen und der Gemini-API zu wechseln.","pt":"Permite que os agentes gerenciem de forma transparente as chaves de API de várias fontes e alternem entre o AI Studio e o Vertex AI usando ajudantes de cliente automatizados e a API Gemini.","ru":"Наделяет агентов возможностью бесшовно управлять ключами API из нескольких источников и переключаться между средами AI Studio и Vertex AI с помощью автоматизированных клиентских помощников и API Gemini.","ar":"يمكن الوكلاء من إدارة مفاتيح واجهة برمجة التطبيقات بسهولة من مصادر متعددة والتبديل بين بيئة استوديو الذكاء الاصطناعي و Vertex AI باستخدام مساعدين عميلين أوتوماتيكيين و واجهة برمجة تطبيقات Gemini."},"useCases":{"en":["Automating API key retrieval","Switching between AI Studio and Vertex AI environments","Simplifying client initialization for AI agents"],"zh":["自动化API密钥检索","在AI Studio和Vertex AI环境之间切换","简化AI代理的客户端初始化"],"ja":["APIキーの自動取得","AI StudioとVertex AIの環境間の切り替え","AIエージェントのクライアント初期化の簡素化"],"ko":["API 키 자동 검색","AI Studio 및 Vertex AI 환경 간 전환","AI 에이전트 클라이언트 초기화 단순화"],"es":["Automatización de la recuperación de claves de API","Alternancia entre entornos de AI Studio y Vertex AI","Simplificación de la inicialización de clientes para agentes de IA"],"fr":["Automatisation de la récupération des clés d''API","Basculage entre les environnements d''AI Studio et de Vertex AI","Simplification de l''initialisation des clients pour les agents d''IA"],"de":["Automatisierung der API-Schlüsselabruf","Wechsel zwischen AI Studio- und Vertex-AI-Umgebungen","Vereinfachung der Client-Initialisierung für AI-Agenten"],"pt":["Automatizar a recuperação de chaves de API","Alternar entre ambientes de AI Studio e Vertex AI","Simplificar a inicialização do cliente para agentes de IA"],"ru":["Автоматизировать получение ключей API","Переключаться между средами AI Studio и Vertex AI","Упрощать инициализацию клиента для агентов ИИ"],"ar":["تحسين استرجاع مفتاح واجهة برمجة التطبيقات","تبديل بين بيئات استوديو الذكاء الاصطناعي و Vertex AI","تبسيط تهيئة العميل لوكلاء الذكاء الاصطناعي"]},"limitations":{"en":["Requires Gemini API access","Python compatibility required"],"zh":["需要Gemini API访问","需要Python兼容性"],"ja":["Gemini APIへのアクセスが必要","Pythonの互換性が必要"],"ko":["Gemini API 액세스가 필요합니다.","Python 호환성이 필요합니다."],"es":["Requiere acceso a la Gemini API","Se requiere compatibilidad con Python"],"fr":["Nécessite l''accès à l''API Gemini","La compatibilité Python est requise"],"de":["Benötigt Zugriff auf die Gemini-API","Python-Kompatibilität erforderlich"],"pt":["Requer acesso à API Gemini","Compatibilidade com Python necessária"],"ru":["Требуется доступ к API Gemini","Требуется совместимость с Python"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات Gemini","متطلبات التوافق مع Python"]},"version":4},"contentHash":"4dfa81b6e37ad8111f05064450a8039a9261ae6b8cb8b83d7975d534aa191f74","qualityScore":48}');
