INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wollfoo/codex-setup/common', 'common', 'wollfoo', 'codex-setup', 'community', 'common wollfoo codex-setup community The Common skill provides utilities for managing API keys and supporting Vertex AI, benefiting AI agent developers by simplifying client initialization and API interactions. Common Skill 是一个用于 Gemini API 的通用库，提供 API Key 管理、Vertex AI 支持和 Client Helpers 等功能 Common Skill は Gemini API 用の共通ライブラリで、API Key 管理、Vertex AI サポート、クライアントヘルパーなどの機能を提供します Common Skill은 Gemini API용 공통 라이브러리로서 API 키 관리, Vertex AI 지원, 클라이언트 헬퍼 등의 기능을 제공합니다 Common Skill es una biblioteca de utilidades compartidas para desarrolladores que utilizan la API de Gemini, con funcionalidades como gestión de claves API y soporte para Vertex AI Common Skill est une bibliothèque d''utilitaires partagés pour les développeurs qui utilisent l''API Gemini, avec des fonctionnalités comme la gestion des clés API et le support de Vertex AI Common Skill ist eine Bibliothek von gemeinsam genutzten Utilitys für Entwickler, die die Gemini-API verwenden, mit Funktionen wie API-Schlüsselverwaltung und Vertex-AI-Unterstützung O Common Skill é uma biblioteca de utilitários para desenvolvedores que utilizam a API Gemini, oferecendo recursos como gerenciamento de chaves API e suporte ao Vertex AI Common Skill - это библиотека утилит для разработчиков, использующих API Gemini, предоставляющая функции như управление ключами API и поддержка Vertex AI مهارة Common هي مكتبة من أدوات المساعدة للعاملين في مجال التطوير الذين يستخدمون واجهة برمجة تطبيقات Gemini، وتقدم ميزات مثل إدارة مفاتيح API ودعم Vertex AI common skill install how to use common for AI agents common vs Gemini API common setup guide for Vertex AI what is common skill common alternative for AI key management common API key management tutorial vertex AI support with common skill common skill for AI agent development Common Skill Gemini API Vertex AI AIエージェント API Key 管理 Client Helpers Python 库 Automates API key management via GEMINI_API_KEY Supports Vertex AI for seamless AI Studio integration Provides client helpers for automatic client initialization Utilizes Python for flexible and efficient development Leverages the Gemini API for robust AI agent interactions Enables easy switching between AI Studio and Vertex AI Common is a library of utilities for AI agent skills using the Gemini API, offering features like API key management and Vertex AI support.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fedify-dev/fedify/add-vocab', 'community', 'fedify-dev', 'fedify', 'fedify-dev/fedify', 'add-vocab', 947, 95, 47, '2026-02-28T23:14:38Z', '2026-03-06T06:26:20.552Z', 'b2224a7d2346e0b171c55daf6cc4862d849fce2ee23db5bbdb3d9c6df52b0890', '{"id":"fedify-dev/fedify/add-vocab","name":"add-vocab","description":{"en":"The add-vocab skill enables developers to add new vocabulary types to the @fedify/vocab package, utilizing YAML definition files and code generation. This benefits developers working with ActivityPub server frameworks in TypeScript.","zh":"添加词汇包是使用 @fedify/vocab 包的关键步骤，需要创建 YAML 定义文件并运行代码生成","ja":"ボキャブラリーの追加は @fedify/vocab パッケージを使用するための重要なステップで、YAML 定義ファイルの作成とコード生成が必要です","ko":"보キャブラ리 추가는 @fedify/vocab 패키지를 사용하는 중요한 단계로, YAML 정의 파일을 생성하고 코드 생성을 실행해야 합니다","es":"Add-vocab es una herramienta para agregar vocabulario a @fedify/vocab, utilizada en servidores ActivityPub con TypeScript","fr":"Add-vocab est un outil pour ajouter un vocabulaire à @fedify/vocab, utilisé dans les serveurs ActivityPub avec TypeScript","de":"Add-vocab ist ein Tool zum Hinzufügen von Vokabular zu @fedify/vocab, verwendet in ActivityPub-Servern mit TypeScript","pt":"O add-vocab é uma habilidade para adicionar vocabulário ao pacote @fedify/vocab em TypeScript, utilizando YAML e geração de código.","ru":"add-vocab — это навык для добавления словаря к пакету @fedify/vocab на TypeScript, использующий YAML и генерацию кода.","ar":"add-vocab هو مهارة لإضافة المفردات إلى حزمة @fedify/vocab بالتايب سكريبت، باستخدام YAML وإنشاء رمز."},"seo":{"title":{"en":"add-vocab: ActivityPub Server Framework Setup Guide | AI ...","zh":"添加词汇包的设置指南 - AIエージェント","ja":"ボキャブラリー追加のベストプラクティス - AIエージェント","ko":"보キャブラ리 추가 설정 가이드 - AI 에이전트","es":"Guía de configuración de add-vocab para ActivityPub con T...","fr":"Configurer add-vocab pour ActivityPub avec TypeScript - M...","de":"Einrichten von add-vocab für ActivityPub mit TypeScript -...","pt":"Guia de Configuração add-vocab para Servidores ActivityPu...","ru":"Настройка add-vocab: Рамки Сервера ActivityPub на TypeScr...","ar":"دليل إضافة المفردات add-vocab لخادم ActivityPub بالتايب س..."},"description":{"en":"Discover how to add vocabulary to @fedify/vocab with ease. Learn the step-by-step process and get started with ActivityPub server framework in TypeScript today!","zh":"了解如何使用 @fedify/vocab 包添加新词汇类型，并使用 TypeScript 和 ActivityPub 创建 YAML 定义文件","ja":"ActivityPub サーバー フレームワークを使用して @fedify/vocab パッケージに新しいボキャブラリー タイプを追加する方法を学習します","ko":"TypeScript와 ActivityPub를 사용하여 @fedify/vocab 패키지에 새로운 보キャブラ리 유형을 추가하는 방법을 알아보세요","es":"Aprende a agregar vocabulario a @fedify/vocab con add-vocab y mejora tu servidor ActivityPub en TypeScript","fr":"Découvrez comment ajouter un vocabulaire à @fedify/vocab avec add-vocab pour améliorer votre serveur ActivityPub en TypeScript","de":"Erfahren Sie, wie Sie Vokabular zu @fedify/vocab mit add-vocab hinzufügen und Ihren ActivityPub-Server in TypeScript verbessern","pt":"Aprenda a adicionar vocabulário ao pacote @fedify/vocab com YAML e geração de código em TypeScript","ru":"Добавьте словарь к пакету @fedify/vocab с помощью YAML и генерации кода на TypeScript для ИИ Агентов","ar":"تعلم كيفية إضافة المفردات إلى حزمة @fedify/vocab باستخدام YAML وإنشاء رمز في TypeScript"},"definition":{"en":"add-vocab is a skill for adding vocabulary to @fedify/vocab package using YAML definition files and code generation in a TypeScript environment.","zh":"添加词汇包是指使用 @fedify/vocab 包创建新的词汇类型","ja":"ボキャブラリー追加とは、@fedify/vocab パッケージを使用して新しいボキャブラリー タイプを作成することです","ko":"보キャブラ리 추가란 @fedify/vocab 패키지를 사용하여 새로운 보キャブラ리 유형을 생성하는 것을 의미합니다","es":"Add-vocab es una herramienta de código abierto para agregar vocabulario a @fedify/vocab","fr":"Add-vocab est un outil open source pour ajouter un vocabulaire à @fedify/vocab","de":"Add-vocab ist ein Open-Source-Tool zum Hinzufügen von Vokabular zu @fedify/vocab","pt":"O add-vocab é uma habilidade que permite adicionar vocabulário personalizado ao pacote @fedify/vocab.","ru":"add-vocab — это навык, позволяющий добавлять пользовательский словарь к пакету @fedify/vocab.","ar":"add-vocab هو مهارة يسمح بإضافة مفردات مخصصة إلى حزمة @fedify/vocab."},"features":{"en":["Creates YAML definition files in packages/vocab/src/","Utilizes code generation for new vocabulary types","Requires human review for vocabulary definitions","Ensures wire compatibility with existing software in the fediverse","Supports ActivityPub server framework in TypeScript","Integrates with technologies like Bun, Deno, and NodeJS"],"zh":["使用 @fedify/vocab 包添加新词汇类型","创建 YAML 定义文件","运行代码生成","支持 ActivityPub 服务器框架","使用 TypeScript 开发"],"ja":["ActivityPub サーバー フレームワークを使用して @fedify/vocab パッケージに新しいボキャブラリー タイプを追加","YAML 定義ファイルの作成","コード生成の実行","TypeScript を使用して開発","Bun と Deno のサポート"],"ko":["TypeScript와 ActivityPub를 사용하여 @fedify/vocab 패키지에 새로운 보キャブラ리 유형을 추가","YAML 정의 파일을 생성","코드 생성을 실행","ActivityPub 서버 프레임워크 지원","Node.js와 Fediverse의 통합"],"es":["Compatibilidad con ActivityPub","Soporte para TypeScript","Generación de código automático","Revisión de vocabulario por humanos","Integración con @fedify/vocab","Utiliza YAML para definir vocabulario"],"fr":["Compatibilité avec ActivityPub","Prise en charge de TypeScript","Génération de code automatique","Révision du vocabulaire par des humains","Intégration avec @fedify/vocab","Utilise YAML pour définir le vocabulaire"],"de":["Kompatibilität mit ActivityPub","Unterstützung für TypeScript","Automatische Codegenerierung","Vokabular-Überprüfung durch Menschen","Integration mit @fedify/vocab","Verwenden von YAML zur Definition von Vokabular"],"pt":["Adição de vocabulário personalizado ao pacote @fedify/vocab","Utilização de YAML para definição de vocabulário","Geração de código em TypeScript","Compatibilidade com servidores ActivityPub","Utilização do framework Bun e Deno"],"ru":["Добавление пользовательского словаря к пакету @fedify/vocab","Использование YAML для определения словаря","Генерация кода на TypeScript","Совместимость с серверами ActivityPub","Использование фреймворка Bun и Deno"],"ar":["إضافة مفردات مخصصة إلى حزمة @fedify/vocab","استخدام YAML لتعريف المفردات","إنشاء رمز في TypeScript","توافق مع خوادم ActivityPub","استخدام إطار العمل Bun و Deno"]},"keywords":{"en":["how to use add-vocab","what is add-vocab","add-vocab alternative","add-vocab vs fedify","add-vocab install","add-vocab setup guide","ActivityPub server framework","TypeScript vocabulary management","fediverse development tools"],"zh":["添加词汇包","AIエージェント","TypeScript","ActivityPub","YAML 定义文件","代码生成","Bun","Deno","Fediverse"],"ja":["ボキャブラリー追加","AIエージェント","TypeScript","ActivityPub","YAML定義ファイル","コード生成","Bun","Deno","Fediverse","Node.js"],"ko":["보キャブラ리 추가","AI 에이전트","TypeScript","ActivityPub","YAML 정의 파일","코드 생성","Bun","Deno","Fediverse","Node.js","Hacktoberfest"],"es":["add-vocab","ActivityPub","TypeScript","fedify","vocabulario","servidor ActivityPub","herramientas de código abierto","generación de código automático","revisión de vocabulario"],"fr":["add-vocab","ActivityPub","TypeScript","fedify","vocabulaire","serveur ActivityPub","outils open source","génération de code automatique","révision de vocabulaire"],"de":["add-vocab","ActivityPub","TypeScript","fedify","Vokabular","ActivityPub-Server","Open-Source-Tools","automatische Codegenerierung","Vokabular-Überprüfung"],"pt":["add-vocab","ActivityPub","TypeScript","YAML","Bun","Deno","Fediverse","Hacktoberfest","NodeJS","desenvolvimento de servidores"],"ru":["add-vocab","ActivityPub","TypeScript","YAML","Bun","Deno","Fediverse","Hacktoberfest","NodeJS","разработка серверов","ИИ Агенты"],"ar":["add-vocab","ActivityPub","TypeScript","YAML","Bun","Deno","Fediverse","Hacktoberfest","NodeJS"," تطوير الخوادم","أدوات الذكاء الاصطناعي"]}},"owner":"fedify-dev","repo":"fedify","repoPath":"fedify-dev/fedify","stars":947,"forks":95,"updatedAt":"2026-02-28T23:14:38Z","topics":["activitypub","bun","deno","fedify","fediverse","hacktoberfest","nodejs","typescript"],"category":"community","skillMd":{"name":"add-vocab","description":">-","version":"1.0.0","bodyPreview":"Adding vocabulary to @fedify/vocab\n==================================\n\nTo add a new vocabulary type to the `@fedify/vocab` package, create a YAML\ndefinition file in `packages/vocab/src/`, then run code generation.\n\n\nHuman review requirement\n------------------------\n\n**Vocabulary definitions must always be reviewed carefully by a human before\nbeing merged.** Errors in vocabulary definitions are difficult to fix after\nrelease because they break wire compatibility with existing software in the\nfedi","body":"Adding vocabulary to @fedify/vocab\n==================================\n\nTo add a new vocabulary type to the `@fedify/vocab` package, create a YAML\ndefinition file in `packages/vocab/src/`, then run code generation.\n\n\nHuman review requirement\n------------------------\n\n**Vocabulary definitions must always be reviewed carefully by a human before\nbeing merged.** Errors in vocabulary definitions are difficult to fix after\nrelease because they break wire compatibility with existing software in the\nfediverse. Specifically, verify:\n\n -  The type URI and property URIs match the spec exactly (a single character\n    difference causes silent interoperability failures)\n -  The `defaultContext` is complete and all terms compact correctly (see\n    “Ensuring Complete Compaction Coverage” below)\n -  The `entity` flag is correct — getting this wrong changes the entire\n    async/sync interface contract\n -  The `functional` flag is correct — marking a multi-valued property as\n    functional silently drops values\n -  Every property `range` entry is accurate — wrong range types produce incorrect\n    TypeScript types\n -  The spec document (FEP or W3C spec) has been read in full, not just skimmed\n\nDo not rely solely on automated checks (`mise run check`)—they verify only\nTypeScript compilation, not semantic correctness of the vocabulary.\n\n\nWorkflow\n--------\n\n1.  Read the spec document (FEP, W3C spec, or informal documentation) carefully\n2.  Identify the type''s URI, JSON-LD context, and properties\n3.  Check whether the JSON-LD context URL is already preloaded in\n    `packages/vocab-runtime/src/contexts.ts`\n4.  Create the YAML file at `packages/vocab/src/<typename-lowercase>.yaml`\n5.  If a new context URL is needed, add it to\n    `packages/vocab-runtime/src/contexts.ts`\n6.  Run `mise run codegen` to generate TypeScript classes\n7.  Run `mise run check` to verify everything compiles\n8.  Ask the user to review the YAML definition and generated code carefully\n    before committing\n\nThe generated TypeScript class is automatically exported from `@fedify/vocab`\nvia `packages/vocab/src/vocab.ts` (generated) and `packages/vocab/src/mod.ts`.\n\n\nYAML file format\n----------------\n\nEvery YAML file must begin with the schema reference:\n\n~~~~ yaml\n$schema: ../../vocab-tools/schema.yaml\n~~~~\n\n### Top-level fields\n\n| Field            | Required | Description                                                                                                                                    |\n| ---------------- | -------- | ---------------------------------------------------------------------------------------------------------------------------------------------- |\n| `name`           | yes      | TypeScript class name (PascalCase, e.g. `Note`)                                                                                                |\n| `uri`            | yes      | Fully qualified RDF type URI                                                                                                                   |\n| `entity`         | yes      | `true` for entity types (async property accessors); `false` for value types (sync accessors). Must be consistent across the inheritance chain. |\n| `description`    | yes      | JSDoc string. May use `{@link ClassName}` for cross-references.                                                                                |\n| `properties`     | yes      | Array of property definitions (can be empty `[]`)                                                                                              |\n| `compactName`    | no       | Short name in compact JSON-LD (e.g. `\"Note\"`). Omit if the type has no compact representation.                                                 |\n| `extends`        | no       | URI of the parent type. Omit for root types.                                                                                                   |\n| `typeless`       | no       | If `true`, `@type` is omitted when serializing to JSON-LD. Used for anonymous structures like `Endpoints` or `Source`.                         |\n| `defaultContext` | no       | JSON-LD context used by `toJsonLd()`. See below.                                                                                               |\n\n**Entity vs. value type (`entity` flag):**\n\n -  `entity: true` — property accessors are `async` and can fetch remote objects\n -  `entity: false` — property accessors are synchronous; used for embedded value\n    objects (e.g. `Endpoints`, `Source`, `Hashtag`)\n\n### `defaultContext` format\n\nThe `defaultContext` field specifies the JSON-LD `@context` written when\n`toJsonLd()` is called. It can be:\n\n**A single context URL:**\n\n~~~~ yaml\ndefaultContext: \"https://www.w3.org/ns/activitystreams\"\n~~~~\n\n**An array of URLs and/or embedded context objects:**\n\n~~~~ yaml\ndefaultContext:\n  - \"https://www.w3.org/ns/activitystreams\"\n  - \"https://w3id.org/security/data-integrity/v1\"\n  - toot: \"http://joinmastodon.org/ns#\"\n    Emoji: \"toot:Emoji\"\n    sensitive: \"as:sensitive\"\n    featured:\n      \"@id\": \"toot:featured\"\n      \"@type\": \"@id\"\n~~~~\n\nEmbedded context entries are YAML mappings where:\n\n -  String value `\"prefix:term\"` or `\"https://...\"` defines a simple term alias\n -  Object value with `\"@id\"` and optionally `\"@type\": \"@id\"` defines a term that\n    should be treated as an IRI (linked resource)\n\n### Ensuring complete compaction coverage\n\nThe `defaultContext` must cover **every term that appears in the JSON-LD\ndocument produced by `toJsonLd()`**, including:\n\n1.  **The type''s own `compactName`** — if the type has a `compactName`, the\n    context must map that name to the type''s URI.\n\n2.  **All own property `compactName`s** — every property defined directly on this\n    type must have its `compactName` (or full URI fallback) resolvable via the\n    context.\n\n3.  **Inherited properties** — properties from parent types are usually covered\n    by the parent''s context URL (e.g., `https://www.w3.org/ns/activitystreams`\n    covers all core ActivityStreams properties). Verify that the parent''s\n    context URL is included.\n\n4.  **Properties of embedded types** — when a property''s value is an object type\n    that is **serialized inline** (not just referenced by URL), the context must\n    also cover all of that embedded type''s properties. This is the most commonly\n    missed case.\n\n    Common embedded types and the context URLs that cover them:\n\n    | Embedded type                       | Context URL to include                        |\n    | ----------------------------------- | --------------------------------------------- |\n    | `DataIntegrityProof` (from `proof`) | `https://w3id.org/security/data-integrity/v1` |\n    | `Key` (from `publicKey`)            | `https://w3id.org/security/v1`                |\n    | `Multikey` (from `assertionMethod`) | `https://w3id.org/security/multikey/v1`       |\n    | `DidService` (from `service`)       | `https://www.w3.org/ns/did/v1`                |\n    | `PropertyValue` (from `attachment`) | schema.org terms in embedded context          |\n\n\n5.  **Redundant property `compactName`s** — if a property has\n    `redundantProperties`, all their `compactName`s must also be defined in the\n    context.\n\n**Practical rule:** look at an existing type with similar embedded relationships\nas a reference. For example, `Note` and `Article` include\n`\"https://w3id.org/security/data-integrity/v1\"` because they embed\n`DataIntegrityProof` objects via the `proof` property. `Person` additionally\nincludes security and DID contexts because it embeds `Key`, `Multikey`, and\n`DidService` objects inline.\n\nOmitting a required context causes silent compaction failure: the property\nappears in expanded form (`\"https://example.com/ns#term\": [...]`) rather than\ncompact form (`\"term\": ...`) in the output.\n\n\nProperty definitions\n--------------------\n\nEach entry in `properties` is one of two kinds:\n\n### Non-functional property (multiple values)\n\nGenerates `get<PluralName>()` async iterable and optionally a singular accessor.\n\n~~~~ yaml\n- pluralName: attachments # accessor: getAttachments() / attachments\n  singularName: attachment # used if singularAccessor: true\n  singularAccessor: true # also generate getAttachment() / attachment\n  compactName: attachment # JSON-LD compact key\n  uri: \"https://www.w3.org/ns/activitystreams#attachment\"\n  description: |\n    Identifies a resource attached or related to an object.\n  range:\n    - \"https://www.w3.org/ns/activitystreams#Object\"\n    - \"https://www.w3.org/ns/activitystreams#Link\"\n~~~~\n\nRequired: `pluralName`, `singularName`, `uri`, `description`, `range`\n\nOptional: `singularAccessor` (default `false`), `compactName`, `subpropertyOf`,\n`container` (`\"graph\"` or `\"list\"`), `embedContext`, `untyped`\n\n### Functional property (exactly one value)\n\nGenerates a single `get<SingularName>()` / `<singularName>` accessor.\n\n~~~~ yaml\n- singularName: published\n  functional: true\n  compactName: published\n  uri: \"https://www.w3.org/ns/activitystreams#published\"\n  description: The date and time at which the object was published.\n  range:\n    - \"http://www.w3.org/2001/XMLSchema#dateTime\"\n~~~~\n\nRequired: `singularName`, `functional: true`, `uri`, `description`, `range`\n\nOptional: `compactName`, `subpropertyOf`, `redundantProperties`, `untyped`,\n`embedContext`\n\n### Redundant properties (functional only)\n\nWhen a property has equivalent URIs from multiple vocabularies, use\n`redundantProperties` to write all aliases on serialization and try them in\norder on deserialization:\n\n~~~~ yaml\n- singularName: quoteUrl\n  functional: true\n  compactName: quoteUrl\n  uri: \"https://www.w3.org/ns/activitystreams#quoteUrl\"\n  redundantProperties:\n    - compactName: _misskey_quote\n      uri: \"https://misskey-hub.net/ns#_misskey_quote\"\n    - compactName: quoteUri\n      uri: \"http://fedibird.com/ns#quoteUri\"\n  description: The URI of the quoted ActivityStreams object.\n  range:\n    - \"fedify:url\"\n~~~~\n\n### The `embedContext` field\n\nUse `embedContext` when a nested object should carry its own `@context` (e.g.,\n`proof` graphs in Data Integrity):\n\n~~~~ yaml\nembedContext:\n  compactName: proof # key under which the context is embedded\n  inherit: true # use the same context as the enclosing document\n~~~~\n\n### The `untyped` field\n\nWhen `untyped: true`, the serialized value will not have a `@type` field.\nRequires exactly one type in `range`. Used for embedded anonymous structures:\n\n~~~~ yaml\n- singularName: source\n  functional: true\n  compactName: source\n  uri: \"https://www.w3.org/ns/activitystreams#source\"\n  description: The source from which the content markup was derived.\n  untyped: true\n  range:\n    - \"https://www.w3.org/ns/activitystreams#Source\"\n~~~~\n\n\nRange type reference\n--------------------\n\n### XSD scalar types → TypeScript types\n\n| Range URI                                               | TypeScript type         |\n| ------------------------------------------------------- | ----------------------- |\n| `http://www.w3.org/2001/XMLSchema#string`               | `string`                |\n| `http://www.w3.org/2001/XMLSchema#boolean`              | `boolean`               |\n| `http://www.w3.org/2001/XMLSchema#integer`              | `number`                |\n| `http://www.w3.org/2001/XMLSchema#nonNegativeInteger`   | `number`                |\n| `http://www.w3.org/2001/XMLSchema#float`                | `number`                |\n| `http://www.w3.org/2001/XMLSchema#anyURI`               | `URL` (stored as `@id`) |\n| `http://www.w3.org/2001/XMLSchema#dateTime`             | `Temporal.Instant`      |\n| `http://www.w3.org/2001/XMLSchema#duration`             | `Temporal.Duration`     |\n| `http://www.w3.org/1999/02/22-rdf-syntax-ns#langString` | `LanguageString`        |\n\n### Security scalar types\n\n| Range URI                                     | TypeScript type    |\n| --------------------------------------------- | ------------------ |\n| `https://w3id.org/security#cryptosuiteString` | `\"eddsa-jcs-2022\"` |\n| `https://w3id.org/security#multibase`         | `Uint8Array`       |\n\n### Fedify internal types\n\n| Range URI             | TypeScript type                                        | Notes                               |\n| --------------------- | ------------------------------------------------------ | ----------------------------------- |\n| `fedify:langTag`      | `Intl.Locale`                                          | BCP 47 language tag as plain string |\n| `fedify:url`          | `URL`                                                  | URL stored as `@value` (not `@id`)  |\n| `fedify:publicKey`    | `CryptoKey`                                            | PEM SPKI-encoded public key         |\n| `fedify:multibaseKey` | `CryptoKey`                                            | Multibase-encoded key (Ed25519)     |\n| `fedify:proofPurpose` | `\"assertionMethod\" \\| \"authentication\" \\| ...`         | Proof purpose string                |\n| `fedify:units`        | `\"cm\" \\| \"feet\" \\| \"inches\" \\| \"km\" \\| \"m\" \\| \"miles\"` | Place units                         |\n\n### Vocabulary types\n\nAny `uri` from another YAML vocabulary file can be used as a range. The\nTypeScript type will be the corresponding generated class (e.g.,\n`\"https://www.w3.org/ns/activitystreams#Object\"` → `Object`).\n\n\nAdding preloaded JSON-LD contexts\n---------------------------------\n\nWhen `defaultContext` references a URL not already in\n`packages/vocab-runtime/src/contexts.ts`, add it to `preloadedContexts`.\n\nCheck existing keys in that file first by searching for the URL. If missing,\nfetch the actual context document from its canonical URL and add an entry:\n\n~~~~ typescript\n\"https://example.com/ns/v1\": {\n  \"@context\": {\n    // ... paste actual context content here ...\n  },\n},\n~~~~\n\nThe keys of `preloadedContexts` must match the URL strings used in YAML\n`defaultContext` fields. This enables offline JSON-LD processing.\n\n\nComplete minimal example\n------------------------\n\n~~~~ yaml\n$schema: ../../vocab-tools/schema.yaml\nname: Move\ncompactName: Move\nuri: \"https://www.w3.org/ns/activitystreams#Move\"\nextends: \"https://www.w3.org/ns/activitystreams#Activity\"\nentity: true\ndescription: |\n  Indicates that the actor has moved object from origin to target.\n  If the origin or target are not specified, either can be determined by\n  context.\ndefaultContext:\n  - \"https://www.w3.org/ns/activitystreams\"\n  - \"https://w3id.org/security/data-integrity/v1\"\nproperties: []\n~~~~\n\n\nComplete extended example (new vocabulary type)\n-----------------------------------------------\n\nWhen implementing a new type from a FEP (e.g. a new `Interaction` type with\ncustom properties from a hypothetical `https://example.com/ns#` namespace):\n\n~~~~ yaml\n$schema: ../../vocab-tools/schema.yaml\nname: Interaction\ncompactName: Interaction\nuri: \"https://example.com/ns#Interaction\"\nextends: \"https://www.w3.org/ns/activitystreams#Activity\"\nentity: true\ndescription: |\n  Represents a generic interaction with an object.\n  See [FEP-xxxx](https://w3id.org/fep/xxxx).\ndefaultContext:\n  - \"https://www.w3.org/ns/activitystreams\"\n  - \"https://w3id.org/security/data-integrity/v1\"\n  - example: \"https://example.com/ns#\"\n    Interaction: \"example:Interaction\"\n    interactionCount:\n      \"@id\": \"example:interactionCount\"\n      \"@type\": \"http://www.w3.org/2001/XMLSchema#nonNegativeInteger\"\n\nproperties:\n  - singularName: interactionCount\n    functional: true\n    compactName: interactionCount\n    uri: \"https://example.com/ns#interactionCount\"\n    description: The number of interactions recorded.\n    range:\n      - \"http://www.w3.org/2001/XMLSchema#nonNegativeInteger\"\n\n  - pluralName: participants\n    singularName: participant\n    singularAccessor: true\n    compactName: participant\n    uri: \"https://example.com/ns#participant\"\n    description: Actors who participated in this interaction.\n    range:\n      - \"https://www.w3.org/ns/activitystreams#Person\"\n      - \"https://www.w3.org/ns/activitystreams#Group\"\n      - \"https://www.w3.org/ns/activitystreams#Organization\"\n      - \"https://www.w3.org/ns/activitystreams#Service\"\n      - \"https://www.w3.org/ns/activitystreams#Application\"\n~~~~\n"},"lastSynced":"2026-03-06T06:26:20.552Z","agentAnalysis":{"suitability":{"en":"Ideal for TypeScript-based AI Agents requiring customized vocabulary extensions for ActivityPub server frameworks","zh":"适用于需要为ActivityPub服务器框架自定义词汇扩展的TypeScript-based AI Agents","ja":"ActivityPubサーバー フレームワークのカスタマイズされた語彙拡張を必要とするTypeScriptベースのAIエージェントに適しています","ko":"ActivityPub 서버 프레임워크를 위한 사용자 정의된 어휘 확장을 필요로 하는 TypeScript 기반의 AI 에이전트에 적합합니다","es":"Ideal para agentes de inteligencia artificial basados en TypeScript que requieren extensiones de vocabulario personalizadas para frameworks de servidores ActivityPub","fr":"Idéal pour les agents d''intelligence artificielle basés sur TypeScript nécessitant des extensions de vocabulaire personnalisées pour les frameworks de serveurs ActivityPub","de":"Ideal für TypeScript-basierte KI-Agents, die benutzerdefinierte Vokabulerweiterungen für ActivityPub-Server-Frameworks erfordern","pt":"Ideal para Agentes de IA baseados em TypeScript que necessitam de extensões de vocabulário personalizadas para frameworks de servidores ActivityPub","ru":"Идеально для агентов ИИ на основе TypeScript, требующих настраиваемых расширений словарного запаса для фреймворков серверов ActivityPub","ar":"مثالي لعميل الذكاء الاصطناعي المستند إلى TypeScript الذي يتطلب امتدادات مفردات مخصصة لإطارات الخادم ActivityPub"},"recommendation":{"en":"Empowers agents to seamlessly integrate new vocabulary types into the @fedify/vocab package using YAML definition files and code generation, ensuring wire compatibility with existing software in the fedi ecosystem through careful human review of vocabulary definitions","zh":"赋予代理无缝地将新的词汇类型集成到@fedify/vocab包中，使用YAML定义文件和代码生成，通过对词汇定义的人工审查，确保与现有软件在fedi生态系统中的线路兼容性","ja":"@fedify/vocabパッケージに新しい語彙タイプをシームレスに統合することをエージェントに可能にし、YAML定義ファイルとコード生成を使用し、fediエコシステムの既存ソフトウェアとのワイヤー互換性を確保するために、語彙定義の慎重な人間によるレビューを実施する","ko":"@fedify/vocab 패키지에 새로운 어휘 유형을 무결점으로 통합할 수 있는 에이전트를 제공하며, YAML 정의 파일 및 코드 생성을 사용하며, 기존 소프트웨어와의와이어 호환성을 보장하기 위해 어휘 정의에 대한주의 깊은 인간의 검토를 수행한다","es":"Habilita a los agentes a integrar sin problemas nuevos tipos de vocabulario en el paquete @fedify/vocab utilizando archivos de definición YAML y generación de código, asegurando la compatibilidad con cable con el software existente en el ecosistema fedi a través de una cuidadosa revisión humana de las definiciones de vocabulario","fr":"Permet aux agents d''intégrer sans problème de nouveaux types de vocabulaire dans le package @fedify/vocab en utilisant des fichiers de définition YAML et de génération de code, garantissant la compatibilité filaire avec les logiciels existants dans l''écosystème fedi grâce à une révision humaine minutieuse des définitions de vocabulaire","de":"Ermöglicht es den Agents, neue Vokabulartypen nahtlos in das @fedify/vocab-Paket zu integrieren, indem YAML-Definitionen und Codegenerierung verwendet werden, und stellt die Kompatibilität mit bestehender Software im Fedi-Ökosystem durch sorgfältige menschliche Überprüfung der Vokabulardefinitionen sicher","pt":"Habilita os agentes a integrar novos tipos de vocabulário no pacote @fedify/vocab utilizando arquivos de definição YAML e geração de código, garantindo compatibilidade com software existente no ecossistema fedi por meio de revisão cuidadosa humana das definições de vocabulário","ru":"Наделяет агентов возможностью бесшовно интегрировать новые типы словарного запаса в пакет @fedify/vocab с помощью файлов определения YAML и генерации кода, обеспечивая совместимость с существующим программным обеспечением в экосистеме fedi посредством тщательного человеческого обзора определений словарного запаса","ar":"يمنح الوكلاء القدرة على دمج أنواع مفردات جديدة في حزمة @fedify/vocab باستخدام ملفات تعريف YAML وإنشاء كود، مما يضمن التوافق مع البرامج الحالية في نظام فدي من خلال مراجعة دقيقة للبشر لتعريفات المفردات"},"useCases":{"en":["Extending vocabulary for ActivityPub server frameworks","Creating custom YAML definition files for @fedify/vocab","Reviewing and merging new vocabulary definitions"],"zh":["为ActivityPub服务器框架扩展词汇","为@fedify/vocab创建自定义YAML定义文件","审查和合并新的词汇定义"],"ja":["ActivityPubサーバー フレームワークの語彙を拡張する","@fedify/vocab用のカスタムYAML定義ファイルを作成する","新しい語彙定義をレビューしてマージする"],"ko":["ActivityPub 서버 프레임워크를 위한 어휘 확장","@fedify/vocab를 위한 사용자 정의 YAML 정의 파일 생성","새로운 어휘 정의의 검토 및 병합"],"es":["Extender el vocabulario para frameworks de servidores ActivityPub","Crear archivos de definición YAML personalizados para @fedify/vocab","Revisar y fusionar nuevas definiciones de vocabulario"],"fr":["Étendre le vocabulaire pour les frameworks de serveurs ActivityPub","Créer des fichiers de définition YAML personnalisés pour @fedify/vocab","Réviser et fusionner de nouvelles définitions de vocabulaire"],"de":["Erweitern des Vokabulars für ActivityPub-Server-Frameworks","Erstellen benutzerdefinierter YAML-Definitionsdateien für @fedify/vocab","Überprüfen und Zusammenführen neuer Vokabulardefinitionen"],"pt":["Extensão de vocabulário para frameworks de servidores ActivityPub","Criação de arquivos de definição YAML personalizados para @fedify/vocab","Revisão e mesclagem de novas definições de vocabulário"],"ru":["Расширение словарного запаса для фреймворков серверов ActivityPub","Создание пользовательских файлов определения YAML для @fedify/vocab","Просмотр и слияние новых определений словарного запаса"],"ar":["توسيع المفردات لإطارات الخادم ActivityPub","إنشاء ملفات تعريف YAML مخصصة لـ @fedify/vocab","استعراض ودمج تعريفات المفردات الجديدة"]},"limitations":{"en":["Requires human review of vocabulary definitions","TypeScript environment necessary","Compatibility issues may arise if vocabulary definitions contain errors"],"zh":["需要对词汇定义进行人类审查","需要TypeScript环境","如果词汇定义包含错误，可能会出现兼容性问题"],"ja":["語彙定義に対する人間によるレビューが必要","TypeScript環境が必要","語彙定義にエラーが含まれている場合、互換性の問題が発生する可能性がある"],"ko":["어휘 정의에 대한 인간의 검토가 필요","TypeScript 환경이 필요","어휘 정의에 오류가 포함되어 있는 경우 호환성 문제가 발생할 수 있다"],"es":["Requiere revisión humana de las definiciones de vocabulario","Entorno de TypeScript necesario","Pueden surgir problemas de compatibilidad si las definiciones de vocabulario contienen errores"],"fr":["Nécessite une révision humaine des définitions de vocabulaire","Environnement TypeScript nécessaire","Des problèmes de compatibilité peuvent survenir si les définitions de vocabulaire contiennent des erreurs"],"de":["Benötigt menschliche Überprüfung der Vokabulardefinitionen","TypeScript-Umgebung erforderlich","Kompatibilitätsprobleme können auftreten, wenn die Vokabulardefinitionen Fehler enthalten"],"pt":["Requer revisão humana das definições de vocabulário","Ambiente TypeScript necessário","Problemas de compatibilidade podem surgir se as definições de vocabulário contiverem erros"],"ru":["Требуется человеческий обзор определений словарного запаса","Необходимо окружение TypeScript","Проблемы совместимости могут возникнуть, если определения словарного запаса содержат ошибки"],"ar":["يتطلب مراجعة بشرية لتعريفات المفردات","بيئة TypeScript ضرورية","مشاكل التوافق قد ت出现 إذا كانت تعريفات المفردات تحتوي على أخطاء"]},"version":4},"contentHash":"b2224a7d2346e0b171c55daf6cc4862d849fce2ee23db5bbdb3d9c6df52b0890","qualityScore":47}');
