INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fedify-dev/fedify/add-vocab', 'add-vocab', 'fedify-dev', 'fedify', 'community', 'add-vocab fedify-dev fedify community activitypub bun deno fedify fediverse hacktoberfest nodejs typescript The add-vocab skill enables developers to add new vocabulary types to the @fedify/vocab package, utilizing YAML definition files and code generation. This benefits developers working with ActivityPub server frameworks in TypeScript. 添加词汇包是使用 @fedify/vocab 包的关键步骤，需要创建 YAML 定义文件并运行代码生成 ボキャブラリーの追加は @fedify/vocab パッケージを使用するための重要なステップで、YAML 定義ファイルの作成とコード生成が必要です 보キャブラ리 추가는 @fedify/vocab 패키지를 사용하는 중요한 단계로, YAML 정의 파일을 생성하고 코드 생성을 실행해야 합니다 Add-vocab es una herramienta para agregar vocabulario a @fedify/vocab, utilizada en servidores ActivityPub con TypeScript Add-vocab est un outil pour ajouter un vocabulaire à @fedify/vocab, utilisé dans les serveurs ActivityPub avec TypeScript Add-vocab ist ein Tool zum Hinzufügen von Vokabular zu @fedify/vocab, verwendet in ActivityPub-Servern mit TypeScript O add-vocab é uma habilidade para adicionar vocabulário ao pacote @fedify/vocab em TypeScript, utilizando YAML e geração de código. add-vocab — это навык для добавления словаря к пакету @fedify/vocab на TypeScript, использующий YAML и генерацию кода. add-vocab هو مهارة لإضافة المفردات إلى حزمة @fedify/vocab بالتايب سكريبت، باستخدام YAML وإنشاء رمز. how to use add-vocab what is add-vocab add-vocab alternative add-vocab vs fedify add-vocab install add-vocab setup guide ActivityPub server framework TypeScript vocabulary management fediverse development tools 添加词汇包 AIエージェント TypeScript ActivityPub YAML 定义文件 代码生成 Bun Deno Fediverse Creates YAML definition files in packages/vocab/src/ Utilizes code generation for new vocabulary types Requires human review for vocabulary definitions Ensures wire compatibility with existing software in the fediverse Supports ActivityPub server framework in TypeScript Integrates with technologies like Bun, Deno, and NodeJS add-vocab is a skill for adding vocabulary to @fedify/vocab package using YAML definition files and code generation in a TypeScript environment.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zio/zio-blocks/docs-enrich-section', 'community', 'zio', 'zio-blocks', 'zio/zio-blocks', 'docs-enrich-section', 99, 136, 47, '2026-03-06T20:58:55Z', '2026-03-07T01:50:07.493Z', 'ec3a04da464bc848ef780cb69d7b7330a9a0a00ccf4fa70ea782925b854f348b', '{"id":"zio/zio-blocks/docs-enrich-section","name":"docs-enrich-section","description":{"en":"docs-enrich-section is a skill that enhances API documentation by providing motivation and use-cases. It benefits developers by turning thin documentation sections into comprehensive guides.","zh":"docs-enrich-section技能提供了强大的文档丰富功能，使用Avro、BSON、JSON等技术，帮助开发者创建更好的云原生应用文档","ja":"docs-enrich-sectionは強力なドキュメントの強化機能を提供し、Avro、BSON、JSONなどの技術を使用してクラウドネイティブアプリケーションのドキュメントを作成","ko":"docs-enrich-section 스킬은 강력한 문서 강화 기능을 제공하며 Avro, BSON, JSON 등을 사용하여 클라우드 네이티브 애플리케이션 문서를 생성","es":"Docs-enrich-section es una herramienta para enriquecer secciones de documentación con motivación y casos de uso para aplicaciones en la nube","fr":"Docs-enrich-section est un outil pour enrichir les sections de documentation avec la motivation et les cas d''utilisation pour les applications cloud","de":"Docs-enrich-section ist ein Tool zum Anreichern von Dokumentationssektionen mit Motivation und Anwendungsfällen für Cloud-Anwendungen","pt":"O docs-enrich-section é uma ferramenta poderosa para criar documentação enriquecida para aplicativos em nuvem, com recursos como avro, json e scala","ru":"docs-enrich-section - это мощный инструмент для создания обогащенной документации для облачных приложений с помощью ИИ Агентов","ar":"docs-enrich-section هو أداة قوية لإنشاء توثيق متقدم للتطبيقات السحابية مع تقنيات مثل avro و json"},"seo":{"title":{"en":"docs-enrich-section: API Documentation Setup Guide | AI A...","zh":"docs-enrich-section 技术文档丰富指南","ja":"docs-enrich-section AIエージェントによるドキュメントの強化","ko":"docs-enrich-section 개발자 문서 개선 가이드","es":"Guía de configuración de docs-enrich-section para aplicac...","fr":"Guide de démarrage rapide pour docs-enrich-section dans l...","de":"Einrichtungsleitfaden für docs-enrich-section in Cloud-An...","pt":"Guia de Configuração do docs-enrich-section para Aplicati...","ru":"Настройка ИИ Агентов docs-enrich-section для Обогащения Д...","ar":"دليل إعداد docs-enrich-section لتعزيز الوثائق في التطبيقا..."},"description":{"en":"Unlock the full potential of your API docs with docs-enrich-section. Learn how to enrich your documentation sections with real-world use cases and motivation...","zh":"使用docs-enrich-section技能，通过Avro、BSON、JSON等技术，打造更强大的云原生应用文档","ja":"docs-enrich-sectionを使用して、Avro、BSON、JSONなどの技術で強力なクラウドネイティブアプリケーションのドキュメントを作成","ko":"docs-enrich-section 스킬을 사용하여 Avro, BSON, JSON 등을 통해 더 강력한 클라우드 네이티브 애플리케이션 문서를 생성","es":"Aprende a enriquecer secciones de documentación con motivación y casos de uso para aplicaciones cloud-natives con docs-enrich-section","fr":"Découvrez comment enrichir les sections de documentation avec la motivation et les cas d''utilisation pour les applications cloud natives avec docs-enrich-sec...","de":"Erfahren Sie, wie Sie Dokumentationssektionen mit Motivation und Anwendungsfällen für Cloud-Anwendungen mit docs-enrich-section anreichern","pt":"Aprenda a usar o docs-enrich-section para criar documentação rica e útil para aplicativos em nuvem, com recursos como avro, json e scala","ru":"Узнайте, как использовать docs-enrich-section для создания богатой и полезной документации для облачных приложений с помощью ИИ Агентов","ar":"تعلم كيفية استخدام docs-enrich-section لإنشاء توثيق متقدم وملائم لتحسين التطبيقات السحابية مع تقنيات مثل avro و json"},"definition":{"en":"docs-enrich-section is a technical skill that enriches documentation sections with details on what an API returns, why it exists, and when to use it.","zh":"docs-enrich-section是一种AI技能，用于丰富和强化技术文档，提供更好的开发者体验","ja":"docs-enrich-sectionは、ドキュメントを強化し、開発者の体験を向上させるAIエージェ