INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tractorjuice/arc-kit/auto-memory', 'community', 'tractorjuice', 'arc-kit', 'tractorjuice/arc-kit', 'auto-memory', 96, 16, 47, '2026-02-28T23:15:21Z', '2026-03-06T06:32:09.780Z', 'f9542fd6b0a8389cb06b08a7a4b1b4d9df75c4dc17233596625afe613dc30200', '{"id":"tractorjuice/arc-kit/auto-memory","name":"auto-memory","description":{"en":"The auto-memory skill enables developers to retain project knowledge across Claude Code sessions using a persistent memory directory. It benefits enterprise architecture governance and vendor procurement teams.","zh":"Auto-Memory 是一种用于企业架构治理和供应商采购的工具包，通过持久化 auto memory 实现项目知识的保留和结构化管理","ja":"Auto-Memory はエンタープライズアーキテクチャガバナンスとベンダー調達のためのツールキットで、永続的な auto memory を使用してプロジェクトの知識を保留し、構造化します","ko":"Auto-Memory는 엔터프라이즈 아키텍처 거버넌스와 벤더 조달을 위한 툴킷으로, 영속적인 auto memory를 사용하여 프로젝트 지식을 보존하고 구조화합니다","es":"La función de auto-memoria utiliza un directorio de memoria persistente para retener el conocimiento del proyecto. Mejora la gestión de la arquitectura empresarial","fr":"L''auto-mémoire utilise un répertoire de mémoire persistant pour conserver les connaissances de projet. Améliorez la gestion de l''architecture d''entreprise","de":"Die Auto-Speicher-Funktion nutzt ein persistierendes Speicherverzeichnis, um Projektwissen zu speichern. Verbessern Sie die Unternehmensarchitekturverwaltung","pt":"O auto-memória é uma ferramenta de governança de arquitetura de empresa que retém conhecimento de projetos em sessões de Claude Code","ru":"Авто-память - это инструмент управления архитектурой предприятия, который сохраняет знания проектов в сессиях Claude Code","ar":"الذاكرة التلقائية هي أداة حوكمة هندسية للمؤسسات التي تحفظ معرفة المشاريع في جلسات Claude Code"},"seo":{"title":{"en":"auto-memory: Persistent Knowledge Management Setup Guide ...","zh":"Auto-Memory 设置指南：企业架构治理和供应商采购工具包","ja":"Auto-Memory 導入ガイド：エンタープライズアーキテクチャガバナンスとベンダー調達ツールキット","ko":"Auto-Memory 설정 가이드: 엔터프라이즈 아키텍처 거버넌스 및 벤더 조달 툴킷","es":"Guía de Configuración de Auto-Memoria para Agentes de IA","fr":"Guide de Mise en Place de l''Auto-Mémoire pour Outils d''IA","de":"Einrichtungsleitfaden für Auto-Speicher in KI-Agenten","pt":"Guia de Configuração do Auto-Memória para Governança de A...","ru":"Настройка Авто-Памяти для Управления Архитектурой Предпри...","ar":"دليل إعداد الذاكرة التلقائية للحوكمة الهندسية للمؤسسات وأ..."},"description":{"en":"Discover how auto-memory streamlines project knowledge retention across sessions. Learn to set up and utilize its structured knowledge base for efficient ent...","zh":"了解 Auto-Memory 功能，用于企业架构治理和供应商采购，实现项目知识的持久化和结构化管理","ja":"Auto-Memory 機能を使用してエンタープライズアーキテクチャガバナンスとベンダー調達を実現し、プロジェクトの知識を永続化して構造化します","ko":"Auto-Memory 기능을 사용하여 엔터프라이즈 아키텍처 거버넌스와 벤더 조달을 실現하고 프로젝트 지식을 영속화하여 구조화합니다","es":"Aprende a configurar la función de auto-memoria para retener el conocimiento del proyecto en sesiones de Claude Code. Mejora la gestión de la arquitectura em...","fr":"Découvrez comment configurer l''auto-mémoire pour conserver les connaissances de projet lors des sessions Claude Code. Améliorez la gestion de l''architecture ...","de":"Erfahren Sie, wie Sie die Auto-Speicher-Funktion einrichten, um Projektwissen in Claude-Code-Sitzungen zu speichern. Verbessern Sie die Unternehmensarchitekt...","pt":"Aprenda a configurar o auto-memória para reter conhecimento de projetos em sessões de Claude Code e melhorar a governança de arquitetura de empresa","ru":"Узнайте, как настроить авто-память для сохранения знаний проектов в сессиях Claude Code и улучшения управления архитектурой предприятия с помощью ИИ Агенты","ar":"تعرف على كيفية إعداد الذاكرة التلقائية لحفظ معرفة المشاريع في جلسات Claude Code وتحسين حوكمة الهندسة للمؤسسات باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"auto-memory is a toolkit for enterprise architecture governance and vendor procurement that utilizes a persistent memory directory to store project knowledge.","zh":"Auto-Memory 是一种用于保留和结构化项目知识的技术，通过持久化 auto memory 实现项目间的知识共享","ja":"Auto-Memory はプロジェクトの知識を保留し、構造化するための技術で、永続的な auto memory を使用してプロジェクト間の知識共有を実現します","ko":"Auto-Memory는 프로젝트 지식을 보존하고 구조화하는 기술로, 영속적인 auto memory를 사용하여 프로젝트 간 지식 공유를 실현합니다","es":"La auto-memoria es una función que retiene el conocimiento del proyecto en un directorio de memoria persistente","fr":"L''auto-mémoire est une fonction qui conserve les connaissances de projet dans un répertoire de mémoire persistant","de":"Die Auto-Speicher ist eine Funktion, die Projektwissen in einem persistierenden Speicherverzeichnis speichert","pt":"O que é auto-memória? É uma ferramenta que usa memória persistente para reter conhecimento de projetos","ru":"Что такое авто-память? Это инструмент, использующий постоянную память для сохранения знаний проектов","ar":"ما هي الذاكرة التلقائية؟ هي أداة تستخدم الذاكرة الثابتة لحفظ معرفة المشاريع"},"features":{"en":["Stores project knowledge in a concise index file (MEMORY.md)","Creates detailed topic files for a structured knowledge base","Utilizes a memory directory (~/.claude/projects/<path>/memory/) for data storage","Loads MEMORY.md into the system prompt for easy access","Supports topic files like architecture.md for specific knowledge domains"],"zh":["持久化 auto memory 实现项目知识的保留","结构化知识管理通过 MEMORY.md 和 topic 文件","支持多个项目的知识共享和管理","使用 ~/.claude/projects/<path>/memory/ 目录存储知识索引","MEMORY.md 文件始终加载到系统提示中"],"ja":["永続的な auto memory を使用してプロジェクトの知識を保留","構造化された知識管理を MEMORY.md とトピックファイルを使用","複数のプロジェクトの知識共有と管理をサポート"," ~/.claude/projects/<path>/memory/ ディレクトリを使用して知識索引を保存","MEMORY.md ファイルを常にシステムプロンプトに読み込み"],"ko":["영속적인 auto memory를 사용하여 프로젝트 지식을 보존","구조화된 지식 관리를 MEMORY.md와 토픽 파일을 사용","複数의 프로젝트 지식 공유와 관리를 지원"," ~/.claude/projects/<path>/memory/ 디렉토리를 사용하여 지식 인덱스를 저장","MEMORY.md 파일을 항상 시스템 프롬프트에 로드"],"es":["Directorio de memoria persistente (~/.claude/projects/<path>/memory/)","Archivo de índice conciso (MEMORY.md)","Archivos de temas detallados (architecture.md)","Creación de una base de conocimientos estructurada","Carga automática de MEMORY.md en el sistema","Compatibilidad con Claude Code"],"fr":["Répertoire de mémoire persistant (~/.claude/projects/<path>/memory/)","Fichier d''index concis (MEMORY.md)","Fichiers de sujets détaillés (architecture.md)","Création d''une base de connaissances structurée","Chargement automatique de MEMORY.md dans le système","Compatibilité avec Claude Code"],"de":["Persistierendes Speicherverzeichnis (~/.claude/projects/<path>/memory/)","Kompaktes Index-Datei (MEMORY.md)","Detailierte Themen-Dateien (architecture.md)","Erstellung einer strukturierten Wissensbasis","Automatisches Laden von MEMORY.md in das System","Kompatibilität mit Claude Code"],"pt":["Usa memória persistente para reter conhecimento de projetos","Cria um índice conciso em MEMORY.md","Armazena arquivos de tópicos detalhados em architecture.md","Permite a criação de uma base de conhecimento estruturada","Funciona em sessões de Claude Code","Melhora a governança de arquitetura de empresa"],"ru":["Использует постоянную память для сохранения знаний проектов","Создаёт краткий индекс в MEMORY.md","Хранит подробные файлы тем в architecture.md","Позволяет создавать структурированную базу знаний","Работает в сессиях Claude Code","Улучшает управление архитектурой предприятия с помощью ИИ Агенты"],"ar":["تستخدم الذاكرة الثابتة لحفظ معرفة المشاريع","تخلق فهرساً موجزاً في MEMORY.md","تحفظ ملفات مواضيع مفصلة في architecture.md","تمكن من إنشاء قاعدة معرفة منظم","تعمل في جلسات Claude Code","تحسن حوكمة الهندسة للمؤسسات باستخدام أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use auto-memory","auto-memory setup guide","enterprise architecture governance tools","vendor procurement software","auto-memory alternative","auto-memory vs claude code","what is auto-memory","auto-memory install","auto-memory for AI agents"],"zh":["Auto-Memory","企业架构治理","供应商采购","项目知识管理","持久化 auto memory","结构化知识管理","MEMORY.md","topic 文件","AI工具","AIエージェント"],"ja":["Auto-Memory","エンタープライズアーキテクチャガバナンス","ベンダー調達","プロジェクトの知識管理","永続的な auto memory","構造化された知識管理","MEMORY.md","トピックファイル","AIツール","AIエージェント"],"ko":["Auto-Memory","엔터프라이즈 아키텍처 거버넌스","벤더 조달","프로젝트 지식 관리","영속적인 auto memory","구조화된 지식 관리","MEMORY.md","토픽 파일","AI 툴","AI 에이전트"],"es":["auto-memoria","agentes de ia","herramientas de ia","gestión de arquitectura empresarial","claude code","desarrollo de software","ingeniería de software","tecnologías de ia","herramientas de desarrollo"],"fr":["auto-mémoire","outils d''ia","agents d''ia","gestion de l''architecture d''entreprise","claude code","développement de logiciels","ingénierie de logiciels","technologies d''ia","outils de développement"],"de":["auto-speicher","ki-agenten","ki-tools","unternehmensarchitekturverwaltung","claude code","software-entwicklung","software-ingennieurwesen","ki-technologien","entwicklertools"],"pt":["auto-memória","governança de arquitetura de empresa"," Claude Code","memória persistente","índice conciso","arquivos de tópicos detalhados","base de conhecimento estruturada","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["авто-память","управление архитектурой предприятия","ИИ Агенты","Claude Code","постоянная память","краткий индекс","подробные файлы тем","структурированная база знаний","разработка программного обеспечения","инструменты разработки"],"ar":["الذاكرة التلقائية","حوكمة الهندسة للمؤسسات","أدوات الذكاء الاصطناعي","Claude Code","الذاكرة الثابتة","فهرس موجز","ملفات مواضيع مفصلة","قاعدة معرفة منظم","تطوير البرمجيات","أدوات التطوير"]}},"owner":"tractorjuice","repo":"arc-kit","repoPath":"tractorjuice/arc-kit","stars":96,"forks":16,"updatedAt":"2026-02-28T23:15:21Z","topics":[],"category":"community","skillMd":{"name":"auto-memory","description":"This skill should be used when the user asks to set up memory, create memory files, create MEMORY.md, set up topic files, improve memory organization, what should I remember, how to structure memory files, MEMORY.md is too long, what goes in memory vs topic files, memory best practices, or wants to establish a persistent knowledge base across Claude Code sessions. Triggers on: memory setup, MEMORY.md, topic files, cross-session knowledge, persistent notes, memory maintenance, memory pruning.","bodyPreview":"# Auto Memory Management\n\nUse persistent auto memory to retain project knowledge across Claude Code sessions. The memory directory (`~/.claude/projects/<path>/memory/`) stores a concise index file (`MEMORY.md`) and detailed topic files, creating a structured knowledge base that grows with the project.\n\n## Core Architecture\n\n```text\n~/.claude/projects/<project-path>/memory/\n├── MEMORY.md          # Always loaded into system prompt (~200 lines max)\n├── architecture.md    # Topic file: system archi","body":"# Auto Memory Management\n\nUse persistent auto memory to retain project knowledge across Claude Code sessions. The memory directory (`~/.claude/projects/<path>/memory/`) stores a concise index file (`MEMORY.md`) and detailed topic files, creating a structured knowledge base that grows with the project.\n\n## Core Architecture\n\n```text\n~/.claude/projects/<project-path>/memory/\n├── MEMORY.md          # Always loaded into system prompt (~200 lines max)\n├── architecture.md    # Topic file: system architecture decisions\n├── patterns.md        # Topic file: code patterns and conventions\n├── debugging.md       # Topic file: debugging insights\n├── workflows.md       # Topic file: development workflows\n└── known-issues.md    # Topic file: bug tracking\n```\n\n### Two-Tier Design\n\n1. **MEMORY.md** (always in context): Concise index with key facts, quick reference tables, and links to topic files. Lines after 200 are truncated — keep it tight.\n2. **Topic files** (consulted as needed): Detailed reference organized by domain. No size limit, but keep each file focused on one topic.\n\n## What to Save\n\n### Save These\n\n- **Stable patterns** confirmed across multiple interactions (naming conventions, file organization, coding style)\n- **Architectural decisions** and their rationale\n- **Important file paths** and project structure\n- **User preferences** for workflow, tools, and communication style\n- **Solutions to recurring problems** and debugging insights\n- **Critical gotchas** that cause repeated mistakes\n- **Explicit user requests** (\"always use bun\", \"never auto-commit\") — save immediately, no need to wait for confirmation across sessions\n\n### Do NOT Save\n\n- **Session-specific context** (current task details, in-progress work, temporary state)\n- **Unverified information** — verify against project docs before writing\n- **Duplicates of CLAUDE.md** — memory supplements project instructions, never contradicts them\n- **Speculative conclusions** from reading a single file\n- **Rapidly changing values** (exact line numbers, temporary feature flags)\n\n## Setting Up Auto Memory\n\n### Step 1: Create the Memory Directory\n\nThe directory is created automatically by Claude Code, but to initialize manually:\n\n```bash\nmkdir -p ~/.claude/projects/<project-path>/memory/\n```\n\nThe `<project-path>` typically mirrors the working directory with slashes replaced by dashes (e.g., `/workspaces/my-app` becomes `-workspaces-my-app`).\n\n### Step 2: Create MEMORY.md\n\nStart with a minimal index and expand as patterns emerge. Include:\n\n- **Project overview**: Key architectural facts (2-3 bullet points)\n- **Quick reference**: Counts, paths, conventions that come up repeatedly\n- **Critical gotchas**: Hard-won lessons that prevent repeated mistakes\n- **Topic file index**: Table linking to detailed files with \"when to consult\" guidance\n\nSee [examples/MEMORY.md](examples/MEMORY.md) for a starter template.\n\n### Step 3: Create Topic Files as Needed\n\nCreate topic files only when a domain accumulates enough detail to warrant its own file. Common topic files:\n\n| File | Purpose |\n|------|---------|\n| `architecture.md` | System design decisions, component relationships |\n| `patterns.md` | Code conventions, naming, file organization |\n| `debugging.md` | Solutions to recurring problems |\n| `workflows.md` | Build, test, deploy procedures |\n| `known-issues.md` | Bug tracking, open/fixed issues |\n| `release-process.md` | Version management, release checklists |\n| `dependencies.md` | Package versions, compatibility notes |\n\nSee [examples/topic-file.md](examples/topic-file.md) for the recommended structure.\n\n## Organization Principles\n\n### Semantic Over Chronological\n\nOrganize by topic, not by date. \"Architecture decisions\" is better than \"Session notes 2026-02-15\". When new information arrives, integrate it into the appropriate topic rather than appending chronologically.\n\n### Concise Index, Detailed Topics\n\nMEMORY.md answers \"what do I need to know right now?\" Topic files answer \"what are all the details about X?\" Keep the index scannable — use bullet points, tables, and bold for key terms.\n\n### Topic File Index Table\n\nAlways include a table in MEMORY.md linking to topic files with guidance on when to consult each:\n\n```markdown\n## Topic Files\n\n| File | When to consult |\n|------|----------------|\n| `architecture.md` | Working on system design, component changes |\n| `patterns.md` | Writing new code, reviewing conventions |\n| `debugging.md` | Investigating bugs, error messages |\n```\n\n### One Topic Per File\n\nEach file covers one domain. If a file grows beyond ~5,000 words or covers multiple unrelated topics, split it. A file named `misc.md` or `notes.md` is a sign of poor organization.\n\n## Maintenance\n\n### When to Update\n\n- After discovering a mistake that could recur\n- When a pattern is confirmed across 2+ interactions\n- When the user explicitly asks to remember something\n- After resolving a tricky bug worth documenting\n- When project structure changes significantly\n\n### When to Remove or Edit\n\n- When stored information becomes outdated (version bumps, removed features)\n- When a gotcha is fixed and no longer relevant\n- When the user asks to forget something\n- When MEMORY.md exceeds ~200 lines — prune or move detail to topic files\n\n### Avoiding Drift\n\nPeriodically review memory files against the actual project state. Stale entries (wrong counts, outdated paths, fixed bugs still listed as open) erode trust in the memory system. Mark fixed issues as fixed rather than deleting them — the history of what went wrong is itself valuable.\n\n## Additional Resources\n\n### Reference Files\n\nFor detailed patterns, anti-patterns, and advanced techniques:\n\n- **[references/patterns.md](references/patterns.md)** — Writing style guide, MEMORY.md structure patterns, topic file patterns, common anti-patterns\n\n### Example Files\n\nWorking examples ready to adapt:\n\n- **[examples/MEMORY.md](examples/MEMORY.md)** — Starter MEMORY.md template\n- **[examples/topic-file.md](examples/topic-file.md)** — Topic file template with recommended structure\n"},"lastSynced":"2026-03-06T06:32:09.780Z","agentAnalysis":{"suitability":{"en":"Ideal for Claude Code Agents requiring persistent knowledge retention across sessions","zh":"适用于需要跨会话保持持久性知识保留的 Claude Code Agents","ja":"クロードコードエージェントがセッション間で永続的な知識の保持を必要とする場合に最適","ko":"세션 간 지속적인 지식 보유가 필요한 Claude Code 에이전트에 적합","es":"Ideal para agentes de Claude Code que requieren una retención de conocimiento persistente en sesiones","fr":"Idéal pour les agents Claude Code nécessitant une rétention de connaissances persistante entre les sessions","de":"Ideal für Claude Code-Agents, die eine persistente Wissensspeicherung über Sitzungen hinweg erfordern","pt":"Ideal para Agentes de Código Claude que exigem retenção de conhecimento persistente entre sessões","ru":"Идеально для агентов Claude Code, требующих постоянного сохранения знаний между сессиями","ar":"مثالي لعميل كلود كود الذي يتطلب الحفاظ على المعرفة المستدامة عبر الجلسات"},"recommendation":{"en":"Empowers agents to leverage a structured knowledge base using a persistent memory directory, storing concise index files like MEMORY.md and detailed topic files, enhancing enterprise architecture governance and vendor procurement workflows with protocols like file system access and markdown formats","zh":"使得代理能够利用持久性内存目录中的结构化知识库，存储诸如 MEMORY.md 和详细主题文件等简洁的索引文件，通过文件系统访问和 markdown 格式等协议增强企业架构管理和供应商采购工作流","ja":"エージェントが持続的なメモリディレクトリ内の構造化されたナレッジベースを活用できるようにし、MEMORY.mdや詳細トピックファイルなどの簡潔なインデックスファイルを保存し、ファイルシステムアクセスやマークダウン形式などのプロトコルでエンタープライズアーキテクチャ管理とベンダープロキュアメントワークフローを強化","ko":"에이전트가持續적인 메모리 디렉토리의 구조화된 지식 베이스를 활용할 수 있게 하며, MEMORY.md 및 세부 주제 파일과 같은 간결한 색인 파일을 저장하며, 파일 시스템 액세스 및 마크다운 형식과 같은 프로토콜을 통해 기업 아키텍처 관리 및 벤더 采购 워크플로를 강화","es":"Habilita a los agentes a aprovechar una base de conocimiento estructurada utilizando un directorio de memoria persistente, almacenando archivos de índice concisos como MEMORY.md y archivos de temas detallados, mejorando la gobernanza de la arquitectura empresarial y los flujos de trabajo de adquisición de proveedores con protocolos como acceso al sistema de archivos y formatos de markdown","fr":"Permet aux agents d''exploiter une base de connaissances structurée en utilisant un répertoire de mémoire persistant, stockant des fichiers d''index concis comme MEMORY.md et des fichiers de sujets détaillés, améliorant la gouvernance de l''architecture d''entreprise et les flux de travail d''approvisionnement des fournisseurs avec des protocoles tels que l''accès au système de fichiers et les formats markdown","de":"Ermöglicht es den Agents, eine strukturierte Wissensbasis zu nutzen, indem ein persistenter Speicherordner verwendet wird, in dem knappe Indexdateien wie MEMORY.md und detaillierte ThemenDateien gespeichert werden, wodurch die Unternehmensarchitektur-Governance und die Beschaffungsworkflows der Lieferanten mit Protokollen wie Dateisystemzugriff und Markdown-Formaten verbessert werden","pt":"Habilita os agentes a aproveitar uma base de conhecimento estruturada usando um dir