INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kcosr/assistant/plugins-guide', 'plugins-guide', 'kcosr', 'assistant', 'community', 'plugins-guide kcosr assistant community The plugins-guide skill provides a panel-based personal assistant with a plugin architecture for productivity workflows, supporting Claude Code, Codex, and pi CLI agents. It benefits developers who want to extend their workflows with custom plugins. plugins-guide是一款面板式个人助手，支持自定义插件和内置插件导出。包括面板开发、CLI打包等技术细节 AIエージェントのプラグイン開発ガイド。面板開発、CLIパッケージ、WebSocketなどのテクニックを紹介します AI 에이전트 플러그인 개발 가이드. 패널 개발, CLI 패키징, WebSocket 등에 대한 기술 정보를 제공합니다 Desarrolla plugins para agentes de inteligencia artificial con nuestra guía de mejores prácticas sobre panel chrome y operaciones Développez des plugins pour les agents d''intelligence artificielle avec notre guide de bonnes pratiques sur le chrome de panneau et les opérations Entwickeln Sie Plug-ins für KI-Agents mit unserer Leitfaden zu besten Praktiken für Panel-Chrome und Operationen O guia de plugins fornece padrões reutilizáveis para construir painéis de plugins para ferramentas de IA, incluindo Claude Code, Codex e pi CLI Руководство по плагинам предоставляет повторно используемые шаблоны для построения панелей плагинов для ИИ Агентов, включая Claude Code, Codex и pi CLI يدور دليل الملحقات حول توفير أنماط قابلة لإعادة الاستخدام لإنشاء لوحات الملحقات للعاملات الذكية، بما في ذلك Claude Code و Codex و pi CLI how to use plugins-guide plugins-guide setup guide plugins-guide alternative plugins-guide vs panel-based assistants plugins-guide install plugins-guide developer guide Claude Code plugin development Codex plugin integration pi CLI plugin setup AI工具插件开发 plugins-guide 面板开发 CLI打包 WebSocket 二进制端点 跨平台行为 Claude Code Codex pi CLI代理 Supports Claude Code, Codex, and pi CLI agents with text and voice interfaces Allows extensions with custom plugins or built-in plugins exported as skills with CLIs Provides a panel-based workspace with notes, lists, and other panels Includes a standard chrome header with controls for panel management Supports binary endpoints and WebSocket usage for plugin development Enables cross-platform behavior for plugins plugins-guide is a panel-based personal assistant with a plugin architecture, supporting text and voice interfaces, and allowing extensions with custom plugins or built-in plugins exported as skills with CLIs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Rykuno/SojuStack/sojustack-best-practices', 'community', 'Rykuno', 'SojuStack', 'Rykuno/SojuStack', 'sojustack-best-practices', 14, 0, 47, '2026-02-21T20:05:40Z', '2026-03-06T06:44:04.675Z', 'f42741481f4a894b2d13e71434bb2fa80b21dd7cc90b391975c9faf6650d9981', '{"id":"Rykuno/SojuStack/sojustack-best-practices","name":"sojustack-best-practices","description":{"en":"The sojustack-best-practices skill helps developers maintain a secure and consistent repository by enforcing strict typing and naming conventions. It benefits developers working with NestJS, TanStack, and Drizzle ORM.","zh":"SojuStack最佳实践指南，帮助开发者保持代码 idiomatic 和安全，涵盖NestJS、Drizzle ORM、TanStack等技术","ja":"SojuStackのベストプラクティスを学び、コードを安全かつ保守しやすくしましょう","ko":"SojuStack_best_practices_를_학습하고_코드를_안전하고_유지_보수_하기_쉽게_만들어보세요","es":"SojuStack Best Practices es un conjunto de reglas para mantener cambios idiomáticos y seguros en tu repositorio, utilizando tecnologías como NestJS y TanStack","fr":"SojuStack Best Practices est un ensemble de règles pour maintenir des changements idiomatiques et sécurisés dans votre référentiel, en utilisant des technologies telles que NestJS et TanStack","de":"SojuStack Best Practices ist eine Sammlung von Regeln, um Änderungen idiomatisch und sicher in Ihrem Repository zu halten, mit Technologien wie NestJS und TanStack","pt":"O SojuStack é uma pilha de tecnologias que inclui NestJS, Drizzle ORM e TanStack. Siga as melhores práticas para manter seu código organizado e seguro.","ru":"SojuStack - это стек технологий, включающий NestJS, Drizzle ORM и TanStack. Следуйте лучшим практикам, чтобы сохранить ваш код организованным и безопасным для ИИ Агентов","ar":"SojuStack هو مجموعة من التكنولوجيا تشمل NestJS و Drizzle ORM و TanStack. اتبع أفضل الممارسات للحفاظ على شفرتك منظمة وأمنة لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"sojustack-best-practices: Repository Management Best Prac...","zh":"SojuStack 最佳实践指南","ja":"SojuStack ベストプラクティスセットアップガイド","ko":"SojuStack_best_practices_설치_가이드","es":"Guía de configuración para SojuStack Best Practices","fr":"Configurer les meilleures pratiques SojuStack","de":"SojuStack Best Practices Einrichtungsleitfaden","pt":"Configuração do SojuStack: Melhores Práticas para Desenvo...","ru":"Настройка SojuStack: Лучшие Практики для Разработчиков ИИ...","ar":"إعداد SojuStack: أفضل الممارسات لمنشئي أدوات الذكاء الاصط..."},"description":{"en":"Discover how to maintain a safe and idiomatic repository with sojustack-best-practices. Learn the universal rules for NestJS, TanStack, and Drizzle ORM.","zh":"了解SojuStack最佳实践，保持代码 idiomatic 和安全，涵盖NestJS、Drizzle ORM、TanStack等技术","ja":"SojuStackのベストプラクティスを学び、コードを安全かつ保守しやすくしましょう。NestJS、Drizzle ORM、TanStackなどを使用","ko":"SojuStack_best_practices_를_학습하고_코드를_안전하고_유지_보수_하기_쉽게_만들어보세요. NestJS, Drizzle ORM, TanStack_등을_사용","es":"Aprende a mantener cambios idiomáticos y seguros en tu repositorio con SojuStack Best Practices y herramientas de desarrollo como NestJS y TanStack","fr":"Découvrez comment maintenir des changements idiomatiques et sécurisés dans votre référentiel avec SojuStack Best Practices et des outils de développement tel...","de":"Erfahren Sie, wie Sie Änderungen idiomatisch und sicher in Ihrem Repository mit SojuStack Best Practices und Entwicklungstools wie NestJS und TanStack halten","pt":"Aprenda a configurar o SojuStack com as melhores práticas para manter seu código idiômático e seguro, incluindo NestJS e TanStack","ru":"Узнайте, как настроить SojuStack с лучшими практиками, чтобы сохранить ваш код идиоматичным и безопасным, включая NestJS и TanStack для ИИ Агентов","ar":"تعلم كيفية إعداد SojuStack بأفضل الممارسات للحفاظ على شفرتك آمنة وموحدة، بما في ذلك NestJS و TanStack لأدوات الذكاء الاصطناعي"},"definition":{"en":"sojustack-best-practices is a set of guidelines for managing a repository with NestJS, TanStack, and Drizzle ORM, ensuring idiomatic and safe changes.","zh":"SojuStack最佳实践是一套保持代码 idiomatic 和安全的指南，涵盖NestJS、Drizzle ORM、TanStack等技术","ja":"SojuStackのベストプラクティスは、コードを安全かつ保守しやすくするためのガイドラインです","ko":"SojuStack_best_practices_는_코드를_안전하고_유지_보수_하기_쉽게_만들어주는_가이드라인입니다","es":"SojuStack Best Practices es un conjunto de reglas para desarrollo seguro y eficiente","fr":"SojuStack Best Practices est un ensemble de règles pour un développement sécurisé et efficace","de":"SojuStack Best Practices ist eine Sammlung von Regeln für sichere und effiziente Entwicklung","pt":"SojuStack é uma coleção de tecnologias para desenvolvimento de aplicações, incluindo backend e frontend, com foco em segurança e organização","ru":"SojuStack - это коллекция технологий для разработки приложений, включая бэкенд и фронтенд, с фокусом на безопасности и организации для ИИ Агентов","ar":"SojuStack هو مجموعة من التكنولوجيا لإنشاء التطبيقات، بما في ذلك الخلفية والأمامية، مع التركيز على الأمان والتنظيم لأدوات الذكاء الاصطناعي"},"features":{"en":["Enforces strict typing to avoid `any` and unsafe casts","Maintains a repository map with clear backend and frontend boundaries","Supports TanStack Start, TanStack Query, and TanStack Form for frontend development","Utilizes Drizzle ORM for efficient database management","Implements Better Auth for secure authentication","Follows naming and folder conventions for consistency"],"zh":["使用NestJS和Drizzle ORM构建后端","使用TanStack Start和TanStack Query构建前端","使用Better Auth进行身份验证","使用ShadCN/Base UI进行界面设计","保持严格的类型检查和命名约定"],"ja":["NestJSとDrizzle ORMを使用したバックエンドの構築","TanStack StartとTanStack Queryを使用したフロントエンドの構築","Better Authを使用した認証","ShadCN/Base UIを使用したUI設計","厳格な型チェックと命名規約の保持"],"ko":["NestJS와_Drizzle_ORM을_사용한_백엔드_구축","TanStack_Start와_TanStack_Query를_사용한_프론트엔드_구축","Better_Auth를_사용한_인증","ShadCN/Base_UI를_사용한_UI_디자인","严格한_타입_체크와_命名_규칙_保持"],"es":["Utiliza NestJS y Drizzle ORM para el backend","Utiliza TanStack Start, TanStack Query y TanStack Form para el frontend","Mantiene la tipificación estricta y evita el uso de ''any''","Sigue convenciones de nombramiento y carpetas","Mantiene el ámbito ajustado a la solicitud del usuario","Evita refactorizaciones oportunistas"],"fr":["Utilise NestJS et Drizzle ORM pour le backend","Utilise TanStack Start, TanStack Query et TanStack Form pour le frontend","Maintient la typification stricte et évite l''utilisation de ''any''","Suive les conventions de nommage et de dossiers","Maintient la portée ajustée à la demande de l''utilisateur","Évite les refactorisations opportunistes"],"de":["Verwendet NestJS und Drizzle ORM für das Backend","Verwendet TanStack Start, TanStack Query und TanStack Form für das Frontend","Hält die Typisierung streng und vermeidet den Einsatz von ''any''","Folgt Namens- und Verzeichnis-Konventionen","Hält den Umfang auf die Benutzeranfrage beschränkt","Vermeidet opportunistische Refactorings"],"pt":["Utiliza NestJS para backend","Integra TanStack para frontend","Inclui Drizzle ORM para gerenciamento de banco de dados","Segue convenções de nomeação e pasta","Mantém tipagem estrita e evita casts inseguros","Otimaiza a segurança com Better Auth"],"ru":["Использует NestJS для бэкенда","Интегрирует TanStack для фронтенда","Включает Drizzle ORM для управления базой данных","Следует соглашениям об именовании и папке","Сохраняет строгую типизацию и избегает небезопасных кастов","Оптимизирует безопасность с Better Auth для ИИ Агентов"],"ar":["يستخدم NestJS للخلفية","يدمج TanStack للأمامية","يشتمل على Drizzle ORM لإدارة قاعدة البيانات","يتبع اتفاقيات التسمية والمجلد","يحافظ على التصنيف الصارم وتجنب الصب غير الآمن","يحسن الأمان مع Better Auth لأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use sojustack-best-practices","sojustack-best-practices repository management","sojustack-best-practices vs nestjs","sojustack-best-practices install guide","sojustack-best-practices setup for tanstack","what is sojustack-best-practices","sojustack-best-practices alternative","sojustack-best-practices best practices for drizzle orm","sojustack-best-practices tutorial"],"zh":["SojuStack最佳实践","NestJS","Drizzle ORM","TanStack","Better Auth","ShadCN/Base UI","代码安全","代码维护"],"ja":["SojuStackベストプラクティス","NestJS","Drizzle ORM","TanStack","Better Auth","ShadCN/Base UI","コードの安全性","コードの保守"],"ko":["SojuStack_best_practices","NestJS","Drizzle_ORM","TanStack","Better_Auth","ShadCN/Base_UI","코드_안전성","코드_유지_보수"],"es":["SojuStack Best Practices","desarrollo de software","NestJS","TanStack","Drizzle ORM","mejores prácticas de desarrollo","seguridad en el desarrollo","eficiencia en el desarrollo"],"fr":["SojuStack Best Practices","développement de logiciels","NestJS","TanStack","Drizzle ORM","meilleures pratiques de développement","sécurité dans le développement","efficacité dans le développement"],"de":["SojuStack Best Practices","Software-Entwicklung","NestJS","TanStack","Drizzle ORM","Best Practices für die Entwicklung","Sicherheit in der Entwicklung","Effizienz in der Entwicklung"],"pt":["SojuStack","NestJS","TanStack","Drizzle ORM","melhores práticas de desenvolvimento","segurança de código","organização de projeto","desenvolvimento de aplicações","backend","frontend"],"ru":["SojuStack","NestJS","TanStack","Drizzle ORM","лучшие практики разработки","безопасность кода","организация проекта","разработка приложений","бэкенд","фронтенд","ИИ Агенты"],"ar":["SojuStack","NestJS","TanStack","Drizzle ORM","أفضل الممارسات لتطوير","أمان الشفرة","تنظيم المشروع","تطوير التطبيقات","الخلفية","الأمامية","أدوات الذكاء الاصطناعي"]}},"owner":"Rykuno","repo":"SojuStack","repoPath":"Rykuno/SojuStack","stars":14,"forks":0,"updatedAt":"2026-02-21T20:05:40Z","topics":[],"category":"community","skillMd":{"name":"sojustack-best-practices","description":"Best-practice guidance for the SojuStack monorepo (NestJS + Drizzle + Better Auth + TanStack Start). Use when editing files in apps/api or apps/web, designing routes, query/form patterns, auth/transaction flows, or implementing cross-stack features.","bodyPreview":"# SojuStack Best Practices\n\nUse this skill to keep changes idiomatic and safe in this repository.\n\n## Repository Map\n\n- Backend: `apps/api/` (NestJS + Drizzle ORM + Better Auth)\n- Frontend: `apps/web/` (TanStack Start + TanStack Query + TanStack Form + ShadCN/Base UI)\n- Shared config: `packages/typescript-config/`\n\n## Universal Rules\n\n- Keep scope tight to the user request; avoid opportunistic refactors.\n- Maintain strict typing; avoid `any` and unsafe casts.\n- Match naming and folder convention","body":"# SojuStack Best Practices\n\nUse this skill to keep changes idiomatic and safe in this repository.\n\n## Repository Map\n\n- Backend: `apps/api/` (NestJS + Drizzle ORM + Better Auth)\n- Frontend: `apps/web/` (TanStack Start + TanStack Query + TanStack Form + ShadCN/Base UI)\n- Shared config: `packages/typescript-config/`\n\n## Universal Rules\n\n- Keep scope tight to the user request; avoid opportunistic refactors.\n- Maintain strict typing; avoid `any` and unsafe casts.\n- Match naming and folder conventions already used in the touched area.\n- Prefer small reusable helpers over duplicate logic.\n- If behavior changes, update/add tests for the impacted area.\n\n## Frontend Rules (`apps/web`)\n\n### Routing (TanStack Start)\n\n- Keep route modules focused; move reusable logic to hooks or components.\n\n### Data Fetching (TanStack Query)\n\n- Use stable query keys like `[''resource'', id, ''sub-resource'']`.\n- Use `invalidateQueries()` without parameters when broad refresh is intended.\n- Keep server-state logic in query/mutation hooks, not presentational components.\n\n### UI (ShadCN + Base UI)\n\n- Prefer components from `apps/web/src/components/ui/`.\n- Prefer Base UI primitives over raw HTML where an equivalent exists.\n- Use `cn()` from `apps/web/src/lib/utils.ts` for class composition.\n- Keep Tailwind usage aligned with existing tokens and utility patterns.\n\n## Backend Rules (`apps/api`)\n\n### Database (Drizzle)\n\n- Add tables in `apps/api/src/databases/tables/{name}.table.ts`.\n- Export new tables from `drizzle.schema.ts`.\n- Add/update relations in `drizzle.relations.ts`.\n\n### Auth (Better Auth)\n\n- Follow existing setup in `apps/api/src/auth/better-auth.provider.ts`.\n- Use framework auth helpers (`@Auth()`, `@ActiveUser()`, `@ActiveSession()`) rather than ad hoc request parsing.\n\n### Transactions\n\n- Use `@Transactional()` with `TransactionHost<DrizzleTransactionClient>`.\n- Do not manually nest/start transactions via `tx.transaction()`.\n\n### Services and Errors\n\n- Keep controllers thin; place business logic in services or providers.\n- Use NestJS exceptions (`NotFoundException`, `UnauthorizedException`, etc.) for expected failures.\n\n### API Type Safety\n\n- Treat `apps/api/generated/openapi.d.ts` as generated source of truth for E2E typing.\n- Use existing DTO and serialization patterns in the module.\n\n## Execution Workflow\n\n1. Read nearby code and existing module patterns.\n2. Implement the smallest correct change.\n3. Run repository validation commands from the repo root:\n   - `pnpm typecheck`\n   - `pnpm format`\n   - `pnpm lint`\n4. If any of those commands fail, fix the issues and re-run until they pass.\n5. Ensure unrelated files are not modified.\n6. Report what changed, why, and how it was validated.\n\n## Do / Don''t\n\n### Do\n\n- Prefer simplicity and human readability of code over complex or verbose implementations.\n- Heir on asking more questions rather than too little.\n- Beware of premature optimization\n- Reuse existing providers/utilities before adding abstractions.\n- Keep functions cohesive and predictable.\n- Add short comments only for non-obvious logic.\n\n### Don''t\n\n- Introduce architectural shifts unless requested.\n- Add dependencies when existing stack primitives are sufficient.\n- Bypass validation, auth, or typing conventions.\n"},"lastSynced":"2026-03-06T06:44:04.675Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents working with NestJS, TanStack, and Drizzle ORM, needing strict typing and naming conventions enforcement.","zh":"适合使用NestJS、TanStack和Drizzle ORM的全栈代理，需要严格的类型和命名约定强制执行。","ja":"NestJS、TanStack、Drizzle ORMを使用するフルスタックエージェントに適しています。厳格な型付けと命名規則の適用が必要です。","ko":"NestJS, TanStack, Drizzle ORM를 사용하는 풀스택 에이전트에게 적합하며, 엄격한 타이핑과 명명 규칙 적용이 필요합니다.","es":"Perfecto para Agentes de Full Stack que trabajan con NestJS, TanStack y Drizzle ORM, necesitando una aplicación estricta de tipado y convenciones de nomenclatura.","fr":"Parfait pour les agents Full Stack travaillant avec NestJS, TanStack et Drizzle ORM, nécessitant une application stricte de typage et de conventions de dénomination.","de":"Perfekt für Full-Stack-Agents, die mit NestJS, TanStack und Drizzle ORM arbeiten und eine strenge Typisierung und Namenskonventionen benötigen.","pt":"Perfeito para Agentes Full Stack que trabalham com NestJS, TanStack e Drizzle ORM, necessitando de aplicação estrita de tipagem e convenções de nomenclatura.","ru":"Идеально подходит для полнофункциональных агентов, работающих с NestJS, TanStack и Drizzle ORM, требующих строгого соблюдения правил типизации и наименований.","ar":"مثالي لعميل الخدمة الكاملة الذي يعمل مع NestJS و TanStack و Drizzle ORM ، والذي يحتاج إلى فرض صارم للنوع والاتفاقيات المتبعة في التسمية."},"recommendation":{"en":"Empowers agents to maintain secure and consistent repositories by enforcing strict typing, avoiding `any` and unsafe casts, and matching naming and folder conventions, leveraging NestJS, Drizzle ORM, and TanStack Query.","zh":"赋予代理维护安全一致的仓库的能力，通过执行严格的类型检查，避免使用`any`和不安全的类型转换，并匹配命名和文件夹约定，利用NestJS、Drizzle ORM和TanStack Query。","ja":"エージェントが安全で一貫性のあるリポジトリを維持できるようにし、厳格な型付けを適用し、`any`や不安全なキャストを回避し、命名とフォルダの規則に従い、NestJS、Drizzle ORM、TanStack Queryを利用します。","ko":"에이전트가 안전하고 일관된 저장소를 유지할 수 있는 능력을 부여하고, 엄격한 타이핑을 적용하고, `any`와 불안전한 형식 변환을 피하며, 이름과 폴더 규칙에 맞추고, NestJS, Drizzle ORM, TanStack Query를 활용합니다.","es":"Permite a los agentes mantener repositorios seguros y coherentes mediante la aplicación de tipado estricto, evitando `any` y casts inseguros, y coincidiendo con las convenciones de nomenclatura y carpeta, aprovechando NestJS, Drizzle ORM y TanStack Query.","fr":"Permet aux agents de maintenir des référentiels sécurisés et cohérents en appliquant un typage strict, en évitant `any` et les casts non sécurisés, et en faisant correspondre les conventions de dénomination et de dossier, en exploitant NestJS, Drizzle ORM et TanStack Query.","de":"Ermöglicht es Agenten, sichere und konsistente Repositorys durch die Durchsetzung strenger Typisierung, Vermeidung von `any` und unsicheren Umwandlungen sowie Übereinstimmung mit Namens- und Ordnerkonventionen zu erhalten, indem es NestJS, Drizzle ORM und TanStack Query nutzt.","pt":"Habilita os agentes a manter repositórios seguros e consistentes, aplicando tipagem estrita, evitando `any` e conversões inseguras, e correspondendo às convenções de nomenclatura e pastas, utilizando NestJS, Drizzle ORM e TanStack Query.","ru":"Наделяет агентов возможностью поддерживать безопасные и последовательные репозитории, обеспечивая строгую типизацию, избегая `any` и небезопасных приведений типов, и соответствуя соглашениям об именах и папках, используя NestJS, Drizzle ORM и TanStack Query.","ar":"يُثقف العميل للحد من مستودعات آمنة ومتناسقة من خلال فرض نوع صارم وتجنب `any` والتحويلات غير الآمنة والمطابقة لاتفاقيات التسمية والمجلدات، باستخدام NestJS و Drizzle ORM و TanStack Query."},"useCases":{"en":["Enforcing strict typing in NestJS applications","Maintaining consistent naming conventions across TanStack projects","Validating repository structure for Drizzle ORM integrations"],"zh":["在NestJS应用中执行严格的类型检查","在TanStack项目中保持一致的命名约定","验证Drizzle ORM集成的仓库结构"],"ja":["NestJSアプリケーションで厳格な型付けを適用する","TanStackプロジェクトで一貫性のある命名規則を維持する","Drizzle ORM統合のリポジトリ構造を検証する"],"ko":["NestJS 애플리케이션에서 엄격한 타이핑을 적용하는 것","TanStack 프로젝트에서 일관된 명명 규칙을 유지하는 것","Drizzle ORM 통합의 저장소 구조를 검증하는 것"],"es":["Aplicar tipado estricto en aplicaciones NestJS","Mantener convenciones de nomenclatura coherentes en proyectos TanStack","Validar la estructura del repositorio para integraciones de Drizzle ORM"],"fr":["Appliquer un typage strict dans les applications NestJS","Maintenir des conventions de dénomination cohérentes dans les projets TanStack","Valider la structure du référentiel pour les intégrations de Drizzle ORM"],"de":["Strenges Typisieren in NestJS-Anwendungen durchsetzen","Konsistente Namenskonventionen in TanStack-Projekten aufrechterhalten","Repository-Struktur für Drizzle-ORM-Integrationen überprüfen"],"pt":["Aplicar tipagem estrita em aplicações NestJS","Manter convenções de nomenclatura consistentes em projetos TanStack","Validar estrutura de repositório para integrações Drizzle ORM"],"ru":["Применение строгой типизации в приложениях NestJS","Поддержание последовательных соглашений об именах в проектах TanStack","Проверка структуры репозитория для интеграций Drizzle ORM"],"ar":["تطبيق نوع صارم في تطبيقات NestJS","الحفاظ على اتفاقيات تسمية متسقة في مشاريع TanStack","التحقق من بنية المستودع لتكاملات Drizzle ORM"]},"limitations":{"en":["Requires repository structure consistency","Limited to NestJS, TanStack, and Drizzle ORM ecosystems"],"zh":["需要仓库结构的一致性","仅限于NestJS、TanStack和Drizzle ORM生态系统"],"ja":["リポジトリ構造の一貫性が必要","NestJS、TanStack、Drizzle ORMのエコシステムに限定される"],"ko":["저장소 구조的一致성이 필요","NestJS, TanStack, Drizzle ORM 생태계에만 국한"],"es":["Requiere coherencia en la estructura del repositorio","Limitado a los ecosistemas de NestJS, TanStack y Drizzle ORM"],"fr":["Nécessite une cohérence dans la structure du référentiel","Limité aux écosystèmes de NestJS, TanStack et Drizzle ORM"],"de":["Benötigt Konsistenz in der Repository-Struktur","Begrenzt auf die Ökosysteme von NestJS, TanStack und Drizzle ORM"],"pt":["Exige consistência na estrutura do repositório","Limitado aos ecossistemas NestJS, TanStack e Drizzle ORM"],"ru":["Требует согласованности структуры репозитория","Ограничен экосистемами NestJS, TanStack и Drizzle ORM"],"ar":["يتطلب الاتس