INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Rykuno/SojuStack/sojustack-best-practices', 'sojustack-best-practices', 'Rykuno', 'SojuStack', 'community', 'sojustack-best-practices Rykuno SojuStack community The sojustack-best-practices skill helps developers maintain a secure and consistent repository by enforcing strict typing and naming conventions. It benefits developers working with NestJS, TanStack, and Drizzle ORM. SojuStack最佳实践指南，帮助开发者保持代码 idiomatic 和安全，涵盖NestJS、Drizzle ORM、TanStack等技术 SojuStackのベストプラクティスを学び、コードを安全かつ保守しやすくしましょう SojuStack_best_practices_를_학습하고_코드를_안전하고_유지_보수_하기_쉽게_만들어보세요 SojuStack Best Practices es un conjunto de reglas para mantener cambios idiomáticos y seguros en tu repositorio, utilizando tecnologías como NestJS y TanStack SojuStack Best Practices est un ensemble de règles pour maintenir des changements idiomatiques et sécurisés dans votre référentiel, en utilisant des technologies telles que NestJS et TanStack SojuStack Best Practices ist eine Sammlung von Regeln, um Änderungen idiomatisch und sicher in Ihrem Repository zu halten, mit Technologien wie NestJS und TanStack O SojuStack é uma pilha de tecnologias que inclui NestJS, Drizzle ORM e TanStack. Siga as melhores práticas para manter seu código organizado e seguro. SojuStack - это стек технологий, включающий NestJS, Drizzle ORM и TanStack. Следуйте лучшим практикам, чтобы сохранить ваш код организованным и безопасным для ИИ Агентов SojuStack هو مجموعة من التكنولوجيا تشمل NestJS و Drizzle ORM و TanStack. اتبع أفضل الممارسات للحفاظ على شفرتك منظمة وأمنة لأدوات الذكاء الاصطناعي how to use sojustack-best-practices sojustack-best-practices repository management sojustack-best-practices vs nestjs sojustack-best-practices install guide sojustack-best-practices setup for tanstack what is sojustack-best-practices sojustack-best-practices alternative sojustack-best-practices best practices for drizzle orm sojustack-best-practices tutorial SojuStack最佳实践 NestJS Drizzle ORM TanStack Better Auth ShadCN/Base UI 代码安全 代码维护 Enforces strict typing to avoid `any` and unsafe casts Maintains a repository map with clear backend and frontend boundaries Supports TanStack Start, TanStack Query, and TanStack Form for frontend development Utilizes Drizzle ORM for efficient database management Implements Better Auth for secure authentication Follows naming and folder conventions for consistency sojustack-best-practices is a set of guidelines for managing a repository with NestJS, TanStack, and Drizzle ORM, ensuring idiomatic and safe changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lbb00/ai-rules-sync/sync-readme', 'community', 'lbb00', 'ai-rules-sync', 'lbb00/ai-rules-sync', 'sync-readme', 14, 1, 47, '2026-02-27T10:57:37Z', '2026-03-06T06:44:07.790Z', 'd31bb94cf8b18fe746a9c1ee4f4da98153bee3968687e45bf4966cadc2854c62', '{"id":"lbb00/ai-rules-sync/sync-readme","name":"sync-readme","description":{"en":"sync-readme helps developers keep their English and Chinese README files up-to-date by synchronizing changes and translating content. It supports agents like Claude Code, Copilot, and Codex.","zh":"sync-readme是一个用于同步和管理AI规则、技能、命令和子代理的工具，支持多语言文档同步","ja":"sync-readmeは、AIエージェントのREADMEを同期して管理するためのツールです","ko":"sync-readme는 AI 에이전트의 README를 동기화하고 관리하기 위한 도구입니다","es":"Sync-readme es una habilidad para sincronizar y gestionar documentos de README para agentes de IA. Permite la traducción y sincronización de cambios entre versiones en inglés y chino.","fr":"Sync-readme est une compétence pour synchroniser et gérer les documents README pour les agents IA. Elle permet la traduction et la synchronisation des modifications entre les versions en anglais et en chinois.","de":"Sync-readme ist eine Fähigkeit, um README-Dokumente für KI-Agents zu synchronisieren und zu verwalten. Sie ermöglicht die Übersetzung und Synchronisation von Änderungen zwischen den englischen und chinesischen Versionen.","pt":"O Sync Readme é uma ferramenta que ajuda a manter a documentação em sincronia, traduzindo e sincronizando alterações entre README.md e README_ZH.md","ru":"Sync Readme - это инструмент, который помогает поддерживать документацию в синхронизации, переводя и обновляя изменения между README.md и README_ZH.md","ar":"Sync Readme هو أداة تساعد في الحفاظ على التوثيق متزامنًا، ترجمة وتحديث التغييرات بين README.md وREADME_ZH.md"},"seo":{"title":{"en":"sync-readme: README Sync Setup Guide | AI Agent Skill","zh":"sync-readme 文档同步工具","ja":"sync-readme AIエージェントのREADME同期ガイド","ko":"sync-readme README 동기화 설정 가이드","es":"Guía de configuración de sync-readme para agentes de IA","fr":"Configurer sync-readme pour les agents IA : Guide étape p...","de":"Einrichten von sync-readme für KI-Agents: Schritt-für-Sch...","pt":"Guia de Configuração do Sync Readme para Ferramentas de IA","ru":"ИИ Агенты: Настройка Sync Readme для Обновления Документации","ar":"دليل إعداد Sync Readme لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to keep your English and Chinese README files in sync with sync-readme. Learn how to translate and synchronize changes with ease. Get started now!","zh":"使用sync-readme工具保持English和Chinese文档同步，自动翻译和更新README.md和README_ZH.md","ja":"sync-readmeを使用して、EnglishとJapaneseのREADMEを自動同期してください","ko":"sync-readme를 사용하여 README.md와 README_ZH.md를 자동으로 동기화하고 번역합니다","es":"Aprende a sincronizar y gestionar documentos de README con sync-readme para agentes de IA como Claude Code, Copilot y más","fr":"Découvrez comment synchroniser et gérer vos documents README avec sync-readme pour les agents IA tels que Claude Code, Copilot, etc.","de":"Erfahren Sie, wie Sie Dokumente mit sync-readme für KI-Agents wie Claude Code, Copilot und mehr synchronisieren und verwalten","pt":"Mantenha a documentação em sincronia com o Sync Readme. Traduza e sincronize alterações entre README.md e README_ZH.md com facilidade","ru":"Синхронизируйте документацию с помощью Sync Readme. Переведите и обновите изменения между README.md и README_ZH.md легко","ar":"احتفظ بالتوثيق متزامنًا باستخدام Sync Readme. ترجم وحدد التغييرات بين README.md وREADME_ZH.md بسهولة"},"definition":{"en":"sync-readme is a skill that synchronizes and manages README files in English and Chinese, ensuring consistency and accuracy across languages.","zh":"sync-readme是一种用于同步和管理文档的工具，特别适用于多语言环境","ja":"sync-readmeは、AIエージェントのREADMEを同期して管理するためのツールの一種です","ko":"sync-readme는 문서를 동기화하고 관리하기 위한 도구로, 특히 다국어 환경에서 유용합니다","es":"Sync-readme es una herramienta de sincronización de documentos de README para agentes de IA","fr":"Sync-readme est un outil de synchronisation de documents README pour les agents IA","de":"Sync-readme ist ein Tool zur Synchronisation von README-Dokumenten für KI-Agents","pt":"O que é Sync Readme? É uma ferramenta de sincronização de documentação que traduz e atualiza alterações entre arquivos README","ru":"Что такое Sync Readme? Это инструмент синхронизации документации, который переводит и обновляет изменения между файлами README","ar":"ما هو Sync Readme؟ هو أداة لتزامن التوثيق التي ترجمة وتحديث التغييرات بين ملفات README"},"features":{"en":["Compares README.md and README_ZH.md files to identify differences","Determines sync direction based on file update history","Translates English to Chinese (EN → ZH) or Chinese to English (ZH → EN) as needed","Supports subagents like Cursor, Claude Code, Copilot, OpenCode, Trae AI, Codex, Gemini CLI, and Warp","Enables easy management of AI rules, skills, commands, and subagents"],"zh":["自动翻译English和Chinese文档","支持README.md和README_ZH.md同步","比较和更新文档差异","支持多种子代理，如Cursor、Claude Code、Copilot"],"ja":["EnglishとJapaneseのREADMEを自動同期","README.mdとREADME_JP.mdの同期をサポート","文書の差異を比較して更新","サブエージェントのサポート、例：Cursor、Claude Code、Copilot"],"ko":["English와 Korean의 README를 자동으로 동기화","README.md와 README_KO.md의 동기화를 지원","문서의 차이점을 비교하고 업데이트함","다양한 子代理를 지원함, 예: Cursor, Claude Code, Copilot"],"es":["Sincronización de documentos de README en inglés y chino","Traducción automática de cambios entre versiones","Compatibilidad con agentes de IA como Claude Code, Copilot y más","Identificación de secciones que difieren entre versiones","Nota de nuevas secciones en cualquier archivo"],"fr":["Synchronisation de documents README en anglais et en chinois","Traduction automatique des modifications entre les versions","Compatibilité avec les agents IA tels que Claude Code, Copilot, etc.","Identification des sections qui diffèrent entre les versions","Note des nouvelles sections dans n''importe quel fichier"],"de":["Synchronisation von README-Dokumenten in Englisch und Chinesisch","Automatische Übersetzung von Änderungen zwischen den Versionen","Kompatibilität mit KI-Agents wie Claude Code, Copilot und mehr","Identifizierung von Abschnitten, die zwischen den Versionen unterschiedlich sind","Notiz von neuen Abschnitten in beliebigen Dateien"],"pt":["Comparação de arquivos README.md e README_ZH.md","Determinação da direção de sincronização com base na data de atualização","Tradução de texto de EN para ZH e vice-versa","Atualização de seções que diferem entre os arquivos","Identificação de novas seções em qualquer um dos arquivos"],"ru":["Сравнение файлов README.md и README_ZH.md","Определение направления синхронизации на основе даты обновления","Перевод текста с EN на ZH и обратно","Обновление разделов, которые различаются между файлами","Обнаружение новых разделов в любом из файлов"],"ar":["مقارنة ملفات README.md وREADME_ZH.md","تحديد اتجاه التزامن بناءً على تاريخ التحديث","ترجمة النص من EN إلى ZH والعكس","تحديث الأقسام التي تختلف بين الملفات","كشف الأقسام الجديدة في أي من الملفات"]},"keywords":{"en":["how to use sync-readme","sync-readme setup guide","sync-readme alternative","sync-readme vs trae","sync-readme install","what is sync-readme","sync-readme for AI agents","README file synchronization","AI agent skill management"],"zh":["sync-readme","AI规则","技能管理","README同步","多语言文档","自动翻译","Cursor","Claude Code","Copilot"],"ja":["sync-readme","AIエージェント","README同期","自動翻訳","サブエージェント","Cursor","Claude Code","Copilot","AIツール"],"ko":["sync-readme","AI 에이전트","README 동기화","자동 번역","서브 에이전트","Cursor","Claude Code","Copilot","AI 도구"],"es":["agentes de IA","herramientas de IA","sync-readme","sincronización de documentos","traducción automática","Claude Code","Copilot","README"],"fr":["agents IA","outils IA","sync-readme","synchronisation de documents","traduction automatique","Claude Code","Copilot","README"],"de":["KI-Agents","KI-Tools","sync-readme","Synchronisation von Dokumenten","automatische Übersetzung","Claude Code","Copilot","README"],"pt":["ferramentas de ia","sync readme","documentação em sincronia","tradução automática","atualização de arquivos readme","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["ии агенты","sync readme","документация в синхронизации","автоматический перевод","обновление файлов readme","разработка программного обеспечения","инструменты разработки"],"ar":["أدوات الذكاء الاصطناعي","sync readme","توثيق متزامن","ترجمة 自动","تحديث ملفات readme","تطوير البرمجيات","أدوات التطوير"]}},"owner":"lbb00","repo":"ai-rules-sync","repoPath":"lbb00/ai-rules-sync","stars":14,"forks":1,"updatedAt":"2026-02-27T10:57:37Z","topics":["agents","claude-code","claude-skills","codex","copilot","copilot-prompts","cursor","gemini","opencode","rules","skills","subagents","trae","warp"],"category":"community","skillMd":{"name":"sync-readme","description":"Synchronize English README.md with Chinese README_ZH.md, maintaining content parity.","bodyPreview":"# Sync README\n\n## Purpose\n\nKeep the English (README.md) and Chinese (README_ZH.md) documentation in sync. When one is updated, this skill helps translate and synchronize changes to the other.\n\n## Instructions\n\n1. **Compare Both Files**\n   - Read README.md and README_ZH.md\n   - Identify sections that differ\n   - Note new sections in either file\n\n2. **Determine Sync Direction**\n   - If English was updated more recently: translate EN → ZH\n   - If Chinese was updated more recently: translate ZH → EN","body":"# Sync README\n\n## Purpose\n\nKeep the English (README.md) and Chinese (README_ZH.md) documentation in sync. When one is updated, this skill helps translate and synchronize changes to the other.\n\n## Instructions\n\n1. **Compare Both Files**\n   - Read README.md and README_ZH.md\n   - Identify sections that differ\n   - Note new sections in either file\n\n2. **Determine Sync Direction**\n   - If English was updated more recently: translate EN → ZH\n   - If Chinese was updated more recently: translate ZH → EN\n   - If unclear, ask user which is the source of truth\n\n3. **Translate Content**\n   - Preserve all code blocks unchanged\n   - Translate prose sections accurately\n   - Keep technical terms consistent:\n     - \"rules\" → \"规则\"\n     - \"commands\" → \"命令\"\n     - \"skills\" → \"技能\"\n     - \"agents\" → \"代理\"\n     - \"instructions\" → \"指令\"\n     - \"adapter\" → \"适配器\"\n     - \"symbolic link\" → \"软链接\"\n\n4. **Preserve Structure**\n   - Keep same heading hierarchy\n   - Maintain table formats\n   - Preserve all links and badges\n   - Keep code examples identical\n\n5. **Update Language Links**\n   - Ensure language toggle links are present\n   - English: `[English](./README.md) | [中文](./README_ZH.md)`\n   - Chinese: `[English](./README.md) | [中文](./README_ZH.md)`\n\n6. **Verify Completeness**\n   - All sections present in both files\n   - All features documented in both\n   - Examples work in both versions\n\n## Translation Guidelines\n\n### Section Headers\n| English | Chinese |\n|---------|---------|\n| Install | 安装 |\n| Commands | 命令 |\n| Architecture | 架构 |\n| Tab Completion | Tab 补全 |\n| Legacy compatibility | Legacy 兼容说明 |\n| Supported Sync Types | 支持的同步类型 |\n\n### Common Phrases\n| English | Chinese |\n|---------|---------|\n| Default mapping | 默认映射 |\n| Source directory | 源目录 |\n| Target directory | 目标目录 |\n| Run this command | 运行此命令 |\n| This command will | 该命令会 |\n\n## Output\n\nAfter running this skill:\n- Both README files contain identical information\n- All features documented in both languages\n- Formatting consistent across both files\n"},"lastSynced":"2026-03-06T06:44:07.790Z","agentAnalysis":{"suitability":{"en":"Perfect for Multilingual Support Agents needing synchronized README file management across English and Chinese documentation.","zh":"非常适合需要在英文和中文文档中同步README文件的多语言支持代理","ja":"英語と中国語のドキュメントでREADMEファイルを同期する必要があるマルチリンガルサポートエージェントに最適","ko":"영어와 중국어 문서에서 README 파일을 동기화해야 하는 다국어 지원 에이전트에게 최적","es":"Perfecto para agentes de soporte multilingüe que necesitan una gestión de archivos README sincronizados en documentación inglesa y china.","fr":"Parfait pour les agents de support multilingues ayant besoin d''une gestion de fichiers README synchronisés dans la documentation anglaise et chinoise.","de":"Perfekt für multilinguale Supportagenten, die eine synchronisierte Verwaltung von README-Dateien in englischer und chinesischer Dokumentation benötigen.","pt":"Perfeito para Agentes de Suporte Multilíngue que precisam de gerenciamento de arquivos README sincronizados em documentação em inglês e chinês.","ru":"Идеально подходит для многоязычных агентов поддержки, которым необходима синхронизированная управление файлами README по всей документации на английском и китайском языках.","ar":"مثالي لوسائل دعم متعددة اللغات التي تحتاج إلى إدارة ملفات README متزامنة عبر الوثائق باللغة الإنجليزية والصينية."},"recommendation":{"en":"Empowers agents to maintain consistent and up-to-date README files in both English and Chinese by synchronizing changes and translating content using Markdown file formats, supporting agents like Claude Code, Copilot, and Codex.","zh":"通过同步更改和使用Markdown文件格式翻译内容，赋予代理维护英文和中文README文件的一致性和更新，支持诸如Claude Code、Copilot和Codex的代理","ja":"MarkDownファイル形式を使用して変更を同期し、コンテンツを翻訳することで、エージェントは英語と中国語のREADMEファイルを一貫して最新の状態に保つことができ、Claude Code、Copilot、Codexなどのエージェントをサポート","ko":"마크다운 파일 형식을 사용하여 변경 사항을 동기화하고 내용을 번역함으로써 에이전트는 영어와 중국어 README 파일을 일관성 있게 최신 상태로 유지할 수 있으며 Claude Code, Copilot, Codex와 같은 에이전트를 지원","es":"Habilita a los agentes a mantener archivos README consistentes y actualizados en inglés y chino, sincronizando cambios y traduciendo contenido utilizando formatos de archivo Markdown, y soporta a agentes como Claude Code, Copilot y Codex.","fr":"Permet aux agents de maintenir des fichiers README cohérents et à jour en anglais et en chinois en synchronisant les modifications et en traduisant le contenu à l''aide de formats de fichiers Markdown, et prend en charge des agents tels que Claude Code, Copilot et Codex.","de":"Ermöglicht es Agenten, konsistente und aktuelle README-Dateien in Englisch und Chinesisch zu verwalten, indem Änderungen synchronisiert und Inhalte mithilfe von Markdown-Dateiformaten übersetzt werden, und unterstützt Agenten wie Claude Code, Copilot und Codex.","pt":"Permite que os agentes mantenham arquivos README consistentes e atualizados em inglês e chinês, sincronizando alterações e traduzindo conteúdo usando formatos de arquivo Markdown, dando suporte a agentes como Claude Code, Copilot e Codex.","ru":"Наделяет агентов возможностью поддерживать согласованные и актуальные файлы README на английском и китайском языках, синхронизируя изменения и переводя содержимое с помощью форматов файлов Markdown, поддерживая агентов seperti Claude Code, Copilot и Codex.","ar":"يمكن للوكلاء الحفاظ على ملفات README متسقة ومتجددة باللغة الإنجليزية والصينية من خلال مزامنة التغييرات وترجمة المحتوى باستخدام تنسيقات الملفات Markdown، ودعم وكلاء مثل Claude Code وCopilot وCodex."},"useCases":{"en":["Synchronizing English and Chinese README files after updates","Translating new sections from English to Chinese or vice versa","Comparing and identifying differences between README.md and README_ZH.md files"],"zh":["更新后同步英文和中文README文件","将新节从英文翻译成中文或反之","比较和识别README.md和README_ZH.md文件之间的差异"],"ja":["更新後英語と中国語のREADMEファイルを同期する","新しいセクションを英語から中国語に翻訳するか、またはその逆","README.mdとREADME_ZH.mdファイルの間の差異を比較して特定する"],"ko":["업데이트 후 영어와 중국어 README 파일을 동기화","새 섹션을 영어에서 중국어로 번역하거나 또는 그 반대","README.md와 README_ZH.md 파일 간의 차이를 비교하여 식별"],"es":["Sincronizar archivos README en inglés y chino después de las actualizaciones","Traducir nuevas secciones del inglés al chino o viceversa","Comparar e identificar las diferencias entre los archivos README.md y README_ZH.md"],"fr":["Synchroniser les fichiers README en anglais et en chinois après les mises à jour","Traduire de nouvelles sections de l''anglais vers le chinois ou vice versa","Comparer et identifier les différences entre les fichiers README.md et README_ZH.md"],"de":["Synchronisieren von README-Dateien in Englisch und Chinesisch nach Updates","Übersetzen neuer Abschnitte vom Englischen ins Chinesische oder umgekehrt","Vergleichen und Identifizieren von Unterschieden zwischen den Dateien README.md und README_ZH.md"],"pt":["Sincronizar arquivos README em inglês e chinês após atualizações","Traduzir novas seções do inglês para o chinês ou vice-versa","Comparar e identificar diferenças entre arquivos README.md e README_ZH.md"],"ru":["Синхронизировать файлы README на английском и китайском языках после обновлений","Переводить новые разделы с английского на китайский или наоборот","Сравнивать и определять различия между файлами README.md и README_ZH.md"],"ar":["مزامنة ملفات README باللغة الإنجليزية والصينية بعد التحديثات","ترجمة الأقسام الجديدة من الإنجليزية إلى الصينية أو العكس","مقارنة والتحديد الفرق بين ملفات README.md وREADME_ZH.md"]},"limitations":{"en":["Requires both README.md and README_ZH.md files to be present","Limited to synchronizing English and Chinese languages","Supports specific agents like Claude Code, Copilot, and Codex"],"zh":["需要同时存在README.md和README_ZH.md文件","仅限于同步英文和中文语言","仅支持诸如Claude Code、Copilot和Codex的特定代理"],"ja":["README.mdとREADME_ZH.mdの両方のファイルが存在する必要がある","英語と中国語の言語の同期のみ","Claude Code、Copilot、Codexなどの特定のエージェントのみをサポート"],"ko":["README.md와 README_ZH.md 파일이 모두 존재해야 함","영어와 중국어 언어만 동기화","Claude Code, Copilot, Codex 등의 특정 에이전트만 지원"],"es":["Requiere que ambos archivos README.md y README_ZH.md estén presentes","Limitado a la sincronización de los idiomas inglés y chino","Soporta agentes específicos como Claude Code, Copilot y Codex"],"fr":["Exige que les deux fichiers README.md et README_ZH.md soient présents","Limité à la synchronisation des langues anglaise et chinoise","Prend en charge des agents spécifiques tels que Claude Code, Copilot et Codex"],"de":["Benötigt, dass sowohl die Datei README.md als auch README_ZH.md vorhanden sind","Begrenzt auf die Synchronisierung der Sprachen Englisch und Chinesisch","Unterstützt bestimmte Agenten wie Claude Code, Copilot und Codex"],"pt":["Exige a presença de ambos arquivos README.md e README_ZH.md","Limitado à sincronização de idiomas inglês e chinês","Suporta agentes específicos como Claude Code, Copilot e Codex"],"ru":["Требует наличия обоих файлов README.md и README_ZH.md","Ограничен синхронизацией английского и китайского языков","Поддерживает конкретных агентов, таких как Claude Code, Copilot и Codex"],"ar":["يتطلب وجود كلا الملفين README.md وREADME_ZH.md","محدود بمزامنة اللغتين الإنجليزية والصينية","يدعم وكلاء محددين مثل Claude Code وCopilot وCodex"]},"version":4},"contentHash":"d31bb94cf8b18fe746a9c1ee4f4da98153bee3968687e45bf4966cadc2854c62","qualityScore":47}');
