INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lbb00/ai-rules-sync/sync-readme', 'sync-readme', 'lbb00', 'ai-rules-sync', 'community', 'sync-readme lbb00 ai-rules-sync community agents claude-code claude-skills codex copilot copilot-prompts cursor gemini opencode rules skills subagents trae warp sync-readme helps developers keep their English and Chinese README files up-to-date by synchronizing changes and translating content. It supports agents like Claude Code, Copilot, and Codex. sync-readme是一个用于同步和管理AI规则、技能、命令和子代理的工具，支持多语言文档同步 sync-readmeは、AIエージェントのREADMEを同期して管理するためのツールです sync-readme는 AI 에이전트의 README를 동기화하고 관리하기 위한 도구입니다 Sync-readme es una habilidad para sincronizar y gestionar documentos de README para agentes de IA. Permite la traducción y sincronización de cambios entre versiones en inglés y chino. Sync-readme est une compétence pour synchroniser et gérer les documents README pour les agents IA. Elle permet la traduction et la synchronisation des modifications entre les versions en anglais et en chinois. Sync-readme ist eine Fähigkeit, um README-Dokumente für KI-Agents zu synchronisieren und zu verwalten. Sie ermöglicht die Übersetzung und Synchronisation von Änderungen zwischen den englischen und chinesischen Versionen. O Sync Readme é uma ferramenta que ajuda a manter a documentação em sincronia, traduzindo e sincronizando alterações entre README.md e README_ZH.md Sync Readme - это инструмент, который помогает поддерживать документацию в синхронизации, переводя и обновляя изменения между README.md и README_ZH.md Sync Readme هو أداة تساعد في الحفاظ على التوثيق متزامنًا، ترجمة وتحديث التغييرات بين README.md وREADME_ZH.md how to use sync-readme sync-readme setup guide sync-readme alternative sync-readme vs trae sync-readme install what is sync-readme sync-readme for AI agents README file synchronization AI agent skill management sync-readme AI规则 技能管理 README同步 多语言文档 自动翻译 Cursor Claude Code Copilot Compares README.md and README_ZH.md files to identify differences Determines sync direction based on file update history Translates English to Chinese (EN → ZH) or Chinese to English (ZH → EN) as needed Supports subagents like Cursor, Claude Code, Copilot, OpenCode, Trae AI, Codex, Gemini CLI, and Warp Enables easy management of AI rules, skills, commands, and subagents sync-readme is a skill that synchronizes and manages README files in English and Chinese, ensuring consistency and accuracy across languages.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ondata/albopopTwoDotZero/openspec-explore', 'community', 'ondata', 'albopopTwoDotZero', 'ondata/albopopTwoDotZero', 'openspec-explore', 9, 16, 47, '2026-02-23T12:58:25Z', '2026-03-06T13:03:53.154Z', '64ded43c11f45d9be10670202659bbbb81bb70e4fd67d3579ae31f1a1f693911', '{"id":"ondata/albopopTwoDotZero/openspec-explore","name":"openspec-explore","description":{"en":"The openspec-explore skill enables developers to think deeply and visualize freely, investigating codebases without writing code. It supports creating OpenSpec artifacts like proposals and specs.","zh":"openspec-explore 允许您进入探索模式，深入思考，自由可视化，并创建 OpenSpec 工件","ja":"openspec-explore は探索モードで思考し、アイデアを生み出し、OpenSpec アーティファクトを作成することができます","ko":"openspec-explore는 탐색 모드에서 생각하고 아이디어를 생성하며 OpenSpec 아티팩트를 생성할 수 있습니다","es":"openspec-explore es un modo de exploración que permite pensar y visualizar libremente, sin implementar código, y crear artefactos OpenSpec","fr":"openspec-explore est un mode d''exploration qui permet de réfléchir et de visualiser librement, sans implémenter de code, et de créer des artefacts OpenSpec","de":"openspec-explore ist ein Explorationsmodus, der es ermöglicht, frei zu denken und zu visualisieren, ohne Code zu implementieren, und OpenSpec-Artefakte zu erstellen","pt":"O openspec-explore é um modo de exploração que permite aos desenvolvedores visualizar códigos e criar artefatos OpenSpec","ru":"openspec-explore - это режим изучения, который позволяет разработчикам визуализировать код и создавать артефакты OpenSpec","ar":"openspec-explore هو وضع استكشاف يسمح للمطورين بتصور الكود وإنشاء مكونات OpenSpec"},"seo":{"title":{"en":"openspec-explore: Exploration Mode Setup Guide | AI Agent...","zh":"openspec-explore 设置指南：探索模式和 OpenSpec 工件","ja":"openspec-explore のベストプラクティス：AIエージェントによる探索モード","ko":"openspec-explore 사용법: 탐색 모드 및 OpenSpec 아티팩트 생성","es":"Guía de configuración de openspec-explore para Agentes de IA","fr":"Mode d''exploration openspec-explore : guide de démarrage","de":"Einrichtungsleitfaden für openspec-explore in KI-Tools","pt":"Guia de Configuração do openspec-explore para Desenvolved...","ru":"Настройка openspec-explore: Руководство для Разработчиков...","ar":"دليل إعداد openspec-explore للמطورين باستخدام أدوات الذكا..."},"description":{"en":"Unlock the full potential of openspec-explore. Learn how to enter explore mode, create OpenSpec artifacts, and navigate codebases without implementing change...","zh":"了解 openspec-explore 的探索模式，创建 OpenSpec 工件，并在代码库中进行搜索","ja":"openspec-explore の探索モードでアイデアを生み出し、OpenSpec アーティファクトを作成する方法","ko":"openspec-explore를 사용하여 탐색 모드를 실행하고 OpenSpec 아티팩트를 생성하는 방법","es":"Aprende a utilizar openspec-explore para pensar y visualizar libremente, sin implementar código, y crea artefactos OpenSpec con facilidad","fr":"Découvrez comment utiliser openspec-explore pour réfléchir et visualiser librement, sans implémenter de code, et créez des artefacts OpenSpec avec facilité","de":"Erfahren Sie, wie Sie openspec-explore verwenden können, um frei zu denken und zu visualisieren, ohne Code zu implementieren, und OpenSpec-Artefakte mit Leic...","pt":"Aprenda a utilizar o openspec-explore para explorar códigos e criar artefatos OpenSpec sem implementar recursos","ru":"Узнайте, как использовать openspec-explore для изучения кода и создания артефактов OpenSpec без реализации функций","ar":"تعرف على كيفية استخدام openspec-explore لاستكشاف الكود وإنشاء مكونات OpenSpec دون تنفيذ الميزات"},"definition":{"en":"openspec-explore is a mode for thinking and exploring codebases, allowing developers to read files, search code, and investigate without implementing changes.","zh":"openspec-explore 是一种允许您探索代码库，创建 OpenSpec 工件的 AI 工具","ja":"openspec-explore はコードライブラリを探索し、OpenSpec アーティファクトを作成する AIエージェントです","ko":"openspec-explore는 코드베이스를 탐색하고 OpenSpec 아티팩트를 생성하는 AI 도구입니다","es":"openspec-explore es un modo de exploración de Agentes de IA que permite la creación de artefactos OpenSpec","fr":"openspec-explore est un mode d''exploration d''outils d''IA qui permet la création d''artefacts OpenSpec","de":"openspec-explore ist ein Explorationsmodus von KI-Tools, der die Erstellung von OpenSpec-Artefakten ermöglicht","pt":"O que é openspec-explore? Um modo de exploração para desenvolvedores que permite visualizar códigos sem implementar recursos","ru":"Что такое openspec-explore? Режим изучения для разработчиков, позволяющий визуализировать код без реализации функций","ar":"ما هو openspec-explore? وضع استكشاف للمطورين يسمح بتصور الكود دون تنفيذ الميزات"},"features":{"en":["Enters explore mode for deep thinking and visualization","Supports reading files and searching code without implementation","Allows creation of OpenSpec artifacts like proposals and specs","Reminds users to exit explore mode before implementing changes","Compatible with commands like /opsx:new and /opsx:ff for change implementation"],"zh":["探索模式：深入思考，自由可视化","创建 OpenSpec 工件：提案，设计，规格","代码库搜索：快速找到相关代码","读取文件：查看代码库的详细信息","非实现模式：仅用于思考，不用于实施"],"ja":["探索モード：深く考え，自由に可視化する","OpenSpec アーティファクトの作成：提案，設計，仕様","コードライブラリの検索：関連するコードを迅速に探す","ファイルの読み取り：コードライブラリの詳細を確認する","実装以外のモード：思考のみ，実装は行わない"],"ko":["탐색 모드: 깊이 생각하고 자유롭게 시각화","OpenSpec 아티팩트 생성: 제안, 디자인, 사양","코드베이스 검색: 관련 코드를 빠르게 찾기","파일 읽기: 코드베이스의 세부 정보를 확인","구현 외 모드: 생각만, 구현은 하지 않음"],"es":["Modo de exploración para pensar y visualizar libremente","No implementación de código","Creación de artefactos OpenSpec","Investigación de la base de código","Búsqueda de código","Lectura de archivos"],"fr":["Mode d''exploration pour réfléchir et visualiser librement","Pas d''implémentation de code","Création d''artefacts OpenSpec","Investigation de la base de code","Recherche de code","Lecture de fichiers"],"de":["Explorationsmodus für freies Denken und Visualisieren","Keine Implementierung von Code","Erstellung von OpenSpec-Artefakten","Untersuchung der Codebasis","Code-Suche","Dateilesen"],"pt":["Exploração de códigos sem implementar recursos","Criação de artefatos OpenSpec","Leitura de arquivos e busca de código","Investigação do código-base","Uso de comandos como /opsx:new e /opsx:ff"],"ru":["Изучение кода без реализации функций","Создание артефактов OpenSpec","Чтение файлов и поиск кода","Изучение кодовой базы","Использование команд như /opsx:new и /opsx:ff"],"ar":["استكشاف الكود دون تنفيذ الميزات","إنشاء مكونات OpenSpec","قراءة الملفات و搜索 الكود","استقصاء قاعدة الكود","استخدام أوامر مثل /opsx:new و /opsx:ff"]},"keywords":{"en":["how to use openspec-explore","what is openspec-explore","openspec-explore alternative","openspec-explore vs albopop","openspec-explore install","openspec-explore setup guide","openspec-explore exploration mode","openspec-explore OpenSpec artifacts","openspec-explore codebase investigation"],"zh":["openspec-explore","AI 工具","探索模式","OpenSpec 工件","代码库搜索","读取文件","非实现模式"],"ja":["openspec-explore","AIエージェント","探索モード","OpenSpec アーティファクト","コードライブラリの検索","ファイルの読み取り","実装以外のモード"],"ko":["openspec-explore","AI 도구","탐색 모드","OpenSpec 아티팩트","코드베이스 검색","파일 읽기","구현 외 모드"],"es":["Agentes de IA","openspec-explore","modo de exploración","artefactos OpenSpec","investigación de código","búsqueda de código","creación de artefactos","desarrollo de software","herramientas de IA"],"fr":["outils d''IA","openspec-explore","mode d''exploration","artefacts OpenSpec","investigation de code","recherche de code","création d''artefacts","développement de logiciels","outils de développement"],"de":["KI-Tools","openspec-explore","Explorationsmodus","OpenSpec-Artefakte","Code-Untersuchung","Code-Suche","Erstellung von Artefakten","Software-Entwicklung","Entwicklertools"],"pt":["openspec-explore","desenvolvimento de software","exploração de códigos","artefatos OpenSpec","ferramentas de desenvolvimento","GUIA de configuração","desenvolvedores de software","ferramentas de código","openspec"],"ru":["openspec-explore","разработка программного обеспечения","изучение кода","артефакты OpenSpec","инструменты разработки","РУКОВОДСТВО по настройке","разработчики программного обеспечения","инструменты кода","ИИ Агенты"],"ar":["openspec-explore","تطوير البرمجيات","استكشاف الكود","مكونات OpenSpec","أدوات التطوير","دليل الإعداد","مطورو البرمجيات","أدوات الكود","أدوات الذكاء الاصطناعي"]}},"owner":"ondata","repo":"albopopTwoDotZero","repoPath":"ondata/albopopTwoDotZero","stars":9,"forks":16,"updatedAt":"2026-02-23T12:58:25Z","topics":[],"category":"community","skillMd":{"name":"openspec-explore","description":"Enter explore mode - a thinking partner for exploring ideas, investigating problems, and clarifying requirements. Use when the user wants to think through something before or during a change.","version":"1.0","bodyPreview":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s c","body":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s capturing thinking, not implementing.\n\n**This is a stance, not a workflow.** There are no fixed steps, no required sequence, no mandatory outputs. You''re a thinking partner helping the user explore.\n\n---\n\n## The Stance\n\n- **Curious, not prescriptive** - Ask questions that emerge naturally, don''t follow a script\n- **Open threads, not interrogations** - Surface multiple interesting directions and let the user follow what resonates. Don''t funnel them through a single path of questions.\n- **Visual** - Use ASCII diagrams liberally when they''d help clarify thinking\n- **Adaptive** - Follow interesting threads, pivot when new information emerges\n- **Patient** - Don''t rush to conclusions, let the shape of the problem emerge\n- **Grounded** - Explore the actual codebase when relevant, don''t just theorize\n\n---\n\n## What You Might Do\n\nDepending on what the user brings, you might:\n\n**Explore the problem space**\n- Ask clarifying questions that emerge from what they said\n- Challenge assumptions\n- Reframe the problem\n- Find analogies\n\n**Investigate the codebase**\n- Map existing architecture relevant to the discussion\n- Find integration points\n- Identify patterns already in use\n- Surface hidden complexity\n\n**Compare options**\n- Brainstorm multiple approaches\n- Build comparison tables\n- Sketch tradeoffs\n- Recommend a path (if asked)\n\n**Visualize**\n```\n┌─────────────────────────────────────────┐\n│     Use ASCII diagrams liberally        │\n├─────────────────────────────────────────┤\n│                                         │\n│   ┌────────┐         ┌────────┐        │\n│   │ State  │────────▶│ State  │        │\n│   │   A    │         │   B    │        │\n│   └────────┘         └────────┘        │\n│                                         │\n│   System diagrams, state machines,      │\n│   data flows, architecture sketches,    │\n│   dependency graphs, comparison tables  │\n│                                         │\n└─────────────────────────────────────────┘\n```\n\n**Surface risks and unknowns**\n- Identify what could go wrong\n- Find gaps in understanding\n- Suggest spikes or investigations\n\n---\n\n## OpenSpec Awareness\n\nYou have full context of the OpenSpec system. Use it naturally, don''t force it.\n\n### Check for context\n\nAt the start, quickly check what exists:\n```bash\nopenspec list --json\n```\n\nThis tells you:\n- If there are active changes\n- Their names, schemas, and status\n- What the user might be working on\n\n### When no change exists\n\nThink freely. When insights crystallize, you might offer:\n\n- \"This feels solid enough to start a change. Want me to create one?\"\n  → Can transition to `/opsx:new` or `/opsx:ff`\n- Or keep exploring - no pressure to formalize\n\n### When a change exists\n\nIf the user mentions a change or you detect one is relevant:\n\n1. **Read existing artifacts for context**\n   - `openspec/changes/<name>/proposal.md`\n   - `openspec/changes/<name>/design.md`\n   - `openspec/changes/<name>/tasks.md`\n   - etc.\n\n2. **Reference them naturally in conversation**\n   - \"Your design mentions using Redis, but we just realized SQLite fits better...\"\n   - \"The proposal scopes this to premium users, but we''re now thinking everyone...\"\n\n3. **Offer to capture when decisions are made**\n\n   | Insight Type | Where to Capture |\n   |--------------|------------------|\n   | New requirement discovered | `specs/<capability>/spec.md` |\n   | Requirement changed | `specs/<capability>/spec.md` |\n   | Design decision made | `design.md` |\n   | Scope changed | `proposal.md` |\n   | New work identified | `tasks.md` |\n   | Assumption invalidated | Relevant artifact |\n\n   Example offers:\n   - \"That''s a design decision. Capture it in design.md?\"\n   - \"This is a new requirement. Add it to specs?\"\n   - \"This changes scope. Update the proposal?\"\n\n4. **The user decides** - Offer and move on. Don''t pressure. Don''t auto-capture.\n\n---\n\n## What You Don''t Have To Do\n\n- Follow a script\n- Ask the same questions every time\n- Produce a specific artifact\n- Reach a conclusion\n- Stay on topic if a tangent is valuable\n- Be brief (this is thinking time)\n\n---\n\n## Handling Different Entry Points\n\n**User brings a vague idea:**\n```\nUser: I''m thinking about adding real-time collaboration\n\nYou: Real-time collab is a big space. Let me think about this...\n\n      COLLABORATION SPECTRUM\n      ════════════════════════════════════════════\n\n      Awareness          Coordination         Sync\n          │                   │                 │\n          ▼                   ▼                 ▼\n      ┌────────┐         ┌────────┐        ┌────────┐\n      │Presence│         │Cursors │        │  CRDT  │\n      │  \"3    │         │ Multi  │        │Conflict│\n      │online\" │         │ select │        │  free  │\n      └────────┘         └────────┘        └────────┘\n          │                   │                 │\n       trivial            moderate           complex\n\n      Where''s your head at?\n```\n\n**User brings a specific problem:**\n```\nUser: The auth system is a mess\n\nYou: [reads codebase]\n\n     ┌─────────────────────────────────────────────┐\n     │              CURRENT AUTH FLOW              │\n     └─────────────────────────────────────────────┘\n                        │\n          ┌─────────────┼─────────────┐\n          ▼             ▼             ▼\n     ┌─────────┐  ┌─────────┐  ┌─────────┐\n     │ Google  │  │  GitHub │  │  Email  │\n     │  OAuth  │  │  OAuth  │  │  Magic  │\n     └────┬────┘  └────┬────┘  └────┬────┘\n          │             │             │\n          └─────────────┼─────────────┘\n                        ▼\n                  ┌───────────┐\n                  │  Session  │\n                  └─────┬─────┘\n                        │\n                        ▼\n                  ┌───────────┐\n                  │   Perms   │\n                  └───────────┘\n\n     I see three tangles. Which one''s burning?\n```\n\n**User is stuck mid-implementation:**\n```\nUser: /opsx:explore add-auth-system\n      The OAuth integration is more complex than expected\n\nYou: [reads change artifacts]\n\n     You''re on task 4: \"Implement OAuth flow\"\n\n     Let me trace what''s involved...\n\n     [draws diagram, explores options, suggests paths]\n\n     Want to update the design to reflect this?\n     Or add a spike task to investigate?\n```\n\n**User wants to compare options:**\n```\nUser: Should we use Postgres or SQLite?\n\nYou: Generic answer is boring. What''s the context?\n\nUser: A CLI tool that tracks local dev environments\n\nYou: That changes everything.\n\n     ┌─────────────────────────────────────────────────┐\n     │         CLI TOOL DATA STORAGE                  │\n     └─────────────────────────────────────────────────┘\n\n     Key constraints:\n     • No daemon running\n     • Must work offline\n     • Single user\n\n                  SQLite          Postgres\n     Deployment   embedded ✓      needs server ✗\n     Offline      yes ✓           no ✗\n     Single file  yes ✓           no ✗\n\n     SQLite. Not even close.\n\n     Unless... is there a sync component?\n```\n\n---\n\n## Ending Discovery\n\nThere''s no required ending. Discovery might:\n\n- **Flow into action**: \"Ready to start? /opsx:new or /opsx:ff\"\n- **Result in artifact updates**: \"Updated design.md with these decisions\"\n- **Just provide clarity**: User has what they need, moves on\n- **Continue later**: \"We can pick this up anytime\"\n\nWhen it feels like things are crystallizing, you might summarize:\n\n```\n## What We Figured Out\n\n**The problem**: [crystallized understanding]\n\n**The approach**: [if one emerged]\n\n**Open questions**: [if any remain]\n\n**Next steps** (if ready):\n- Create a change: /opsx:new <name>\n- Fast-forward to tasks: /opsx:ff <name>\n- Keep exploring: just keep talking\n```\n\nBut this summary is optional. Sometimes the thinking IS the value.\n\n---\n\n## Guardrails\n\n- **Don''t implement** - Never write code or implement features. Creating OpenSpec artifacts is fine, writing application code is not.\n- **Don''t fake understanding** - If something is unclear, dig deeper\n- **Don''t rush** - Discovery is thinking time, not task time\n- **Don''t force structure** - Let patterns emerge naturally\n- **Don''t auto-capture** - Offer to save insights, don''t just do it\n- **Do visualize** - A good diagram is worth many paragraphs\n- **Do explore the codebase** - Ground discussions in reality\n- **Do question assumptions** - Including the user''s and your own\n"},"lastSynced":"2026-03-06T13:03:53.154Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing advanced codebase investigation capabilities without writing code.","zh":"适合需要高级代码库调查能力的代码分析代理，不需要编写代码。","ja":"コード分析エージェントがコードベースの高度な調査機能を必要とする場合に適していますが、コードの記述は必要ありません。","ko":"코드 분석 에이전트가 코드베이스의 고급 조사를 필요로 할 때 적합하며 코드를 작성할 필요가 없습니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan capacidades de investigación de código avanzadas sin escribir código.","fr":"Parfait pour les Agents d''Analyse de Code nécessitant des capacités d''investigation de code avancées sans écrire de code.","de":"Perfekt für Code-Analyse-Agents, die erweiterte Codebasis-Untersuchungsfähigkeiten ohne Code-Schreiben benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de capacidades de investigação de código avançadas sem escrever código.","ru":"Идеально для Агентов Анализа Кодов, которым необходимы продвинутые возможности анализа кодовой базы без написания кода.","ar":"مثالي للوكلاء التحليليين للرمز البرمجي الذين يحتاجون إلى قدرات تحقيق متقدمة للقاعدة البرمجية دون كتابة رمز."},"recommendation":{"en":"Empowers agents to think deeply and visualize freely, creating OpenSpec artifacts like proposals and specs, while investigating codebases through file reading and searching, all within the constraints of explore mode, utilizing OpenSpec protocols.","zh":"赋予代理深入思考和自由可视化的能力，创建 OpenSpec 文档，如提案和规范，同时通过文件读取和搜索来调查代码库，所有这些都在探索模式的约束范围内，利用 OpenSpec 协议。","ja":"エージェントに深く考えることと自由に視覚化することを可能にし、OpenSpec プロトコルを使用して、ファイルの読み取りと検索を介してコードベースを調査しながら、提案や仕様などの OpenSpec アーティファクトを作成します。すべては探索モードの制約の範囲内で行われます。","ko":"에이전트가 깊게 생각하고 자유롭게 시각화할 수 있도록 하여 OpenSpec 프로토콜을 사용하여 파일 읽기와 검색을 통해 코드베이스를 조사하면서 제안과 사양 등의 OpenSpec 아티팩트를 생성하고, 모든 작업은 탐색 모드의 제약 범위 내에서 수행됩니다.","es":"Habilita a los agentes a pensar profundamente y visualizar libremente, creando artefactos OpenSpec como propuestas y especificaciones, mientras investigan las bases de código a través de la lectura y búsqueda de archivos, todo dentro de las limitaciones del modo de exploración, utilizando protocolos OpenSpec.","fr":"Permet aux agents de réfléchir profondément et de visualiser librement, en créant des artefacts OpenSpec tels que des propositions et des spécifications, tout en investiguant les bases de code à travers la lecture et la recherche de fichiers, le tout dans les limites du mode d''exploration, en utilisant les protocoles OpenSpec.","de":"Ermächtigt die Agents, tief zu denken und frei zu visualisieren, indem sie OpenSpec-Artefakte wie Vorschläge und Spezifikationen erstellen, während sie Codebasen durch Dateilesen und -suchen untersuchen, all dies innerhalb der Einschränkungen des Explorationsmodus, unter Verwendung von OpenSpec-Protokollen.","pt":"Habilita os agentes a pensar profundamente e visualizar livremente, criando artefatos OpenSpec, como propostas e especificações, enquanto investigam código através da leitura de arquivos e busca, todos dentro das limitações do modo de exploração, utilizando protocolos OpenSpec.","ru":"Направляет агентов на глубокое мышление и свободную визуализацию, создавая артефакты OpenSpec, такие как предложения и спецификации, при этом исследуя кодовые базы через чтение файлов и поиск, все в рамках ограничений режима исследования, используя протоколы OpenSpec.","ar":"يُجهز الوكلاء على التفكير العميق والتصور بحرية، مما يخلق محتوى مفتوح للمواصفات مثل المقترحات والمواصفات، بينما يبحثون في الرمز البرمجي من خلال قراءة الملفات والبحث، كل ذلك في حدود قيود وضع الاستكشاف، باستخدام بروتوكولات المواصفات المفتوحة."},"useCases":{"en":["Investigating codebases without modifying them","Generating OpenSpec proposals and specs","Debugging code issues through deep analysis"],"zh":["在不修改代码库的情况下调查代码库","生成 OpenSpec 提案和规范","通过深入分析调试代码问题"],"ja":["コードベースを変更せずにコードベースを調査する","OpenSpec 提案と仕様を生成する","深い分析によってコードの問題をデバッグする"],"ko":["코드베이스를 수정하지 않고 코드베이스를 조사하는 것","OpenSpec 제안과 사양을 생성하는 것","깊은 분석을 통해 코드 문제를 디버깅하는 것"],"es":["Investigación de bases de código sin modificarlas","Generación de propuestas y especificaciones OpenSpec","Depuración de problemas de código a través de un análisis profundo"],"fr":["Investigation de bases de code sans les modifier","Génération de propositions et spécifications OpenSpec","Débogage de problèmes de code à travers une analyse approfondie"],"de":["Untersuchung von Codebasen ohne sie zu modifizieren","Erstellung von OpenSpec-Vorschlägen und -Spezifikationen","Fehlerbehebung von Codeproblemen durch eine tiefe Analyse"],"pt":["Investigar código sem modificá-lo","Gerar propostas e especificações OpenSpec","Depurar problemas de código através de análise profunda"],"ru":["Изучать кодовые базы без их изменения","Генерировать предложения и спецификации OpenSpec","Отлаживать проблемы кода посредством глубокого анализа"],"ar":["تحقيق الرمز البرمجي دون تعديله","генерировать مقترحات ومواصفات مفتوحة للمواصفات","تصحيح أخطاء الرمز البرمجي من خلال التحليل العميق"]},"limitations":{"en":["Must not write code or implement features in explore mode","Requires exiting explore mode to implement changes","Limited to creating OpenSpec artifacts in explore mode"],"zh":["探索模式下不能编写代码或实现功能","需要退出探索模式来实现更改","仅限在探索模式下创建 OpenSpec 文档"],"ja":["探索モードではコードを記述したり機能を実装したりできない","変更を実装するには探索モードを終了する必要がある","探索モードでは OpenSpec アーティファクトの作成のみ可能"],"ko":["탐색 모드에서는 코드를 작성하거나 기능을 구현할 수 없음","변경 사항을 구현하려면 탐색 모드를 종료해야 함","탐색 모드에서는 OpenSpec 아티팩트의 생성만 가능"],"es":["No debe escribir código o implementar características en el modo de exploración","Requiere salir del modo de exploración para implementar cambios","Limitado a la creación de artefactos OpenSpec en el modo de exploración"],"fr":["Ne doit pas écrire de code ou mettre en œuvre des fonctionnalités en mode d''exploration","Requiert de quitter le mode d''exploration pour mettre en œuvre des changements","Limité à la création d''artefacts OpenSpec en mode d''exploration"],"de":["Darf keinen Code schreiben oder Funktionen im Explorationsmodus implementieren","Erfordert das Verlassen des Explorationsmodus, um Änderungen umzusetzen","Begrenzt auf die Erstellung von OpenSpec-Artefakten im Explorationsmodus"],"pt":["Não deve escrever código ou implementar recursos no modo de exploração","Requer sair do modo de exploração para implementar alterações","Limitado à criação de artefatos OpenSpec no modo de exploração"],"ru":["Не должно писать код или реализовывать функции в режиме исследования","Требует выхода из режима исследования для реализации изменений","Ограничено созданием артефактов OpenSpec в режиме исследования"],"ar":["لا ينبغي كتابة رمز أو تنفيذ ميزات في وضع الاستكشاف","يتطلب الخروج من وضع الاستكشاف لتنفيذ التغييرات","محدود بإنشاء محتوى مفتوح للمواصفات في وضع الاستكشاف"]},"version":4},"contentHash":"64ded43c11f45d9be10670202659bbbb81bb70e4fd67d3579ae31f1a1f693911","qualityScore":47}');
