INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ondata/albopopTwoDotZero/openspec-explore', 'openspec-explore', 'ondata', 'albopopTwoDotZero', 'community', 'openspec-explore ondata albopopTwoDotZero community The openspec-explore skill enables developers to think deeply and visualize freely, investigating codebases without writing code. It supports creating OpenSpec artifacts like proposals and specs. openspec-explore 允许您进入探索模式，深入思考，自由可视化，并创建 OpenSpec 工件 openspec-explore は探索モードで思考し、アイデアを生み出し、OpenSpec アーティファクトを作成することができます openspec-explore는 탐색 모드에서 생각하고 아이디어를 생성하며 OpenSpec 아티팩트를 생성할 수 있습니다 openspec-explore es un modo de exploración que permite pensar y visualizar libremente, sin implementar código, y crear artefactos OpenSpec openspec-explore est un mode d''exploration qui permet de réfléchir et de visualiser librement, sans implémenter de code, et de créer des artefacts OpenSpec openspec-explore ist ein Explorationsmodus, der es ermöglicht, frei zu denken und zu visualisieren, ohne Code zu implementieren, und OpenSpec-Artefakte zu erstellen O openspec-explore é um modo de exploração que permite aos desenvolvedores visualizar códigos e criar artefatos OpenSpec openspec-explore - это режим изучения, который позволяет разработчикам визуализировать код и создавать артефакты OpenSpec openspec-explore هو وضع استكشاف يسمح للمطورين بتصور الكود وإنشاء مكونات OpenSpec how to use openspec-explore what is openspec-explore openspec-explore alternative openspec-explore vs albopop openspec-explore install openspec-explore setup guide openspec-explore exploration mode openspec-explore OpenSpec artifacts openspec-explore codebase investigation openspec-explore AI 工具 探索模式 OpenSpec 工件 代码库搜索 读取文件 非实现模式 Enters explore mode for deep thinking and visualization Supports reading files and searching code without implementation Allows creation of OpenSpec artifacts like proposals and specs Reminds users to exit explore mode before implementing changes Compatible with commands like /opsx:new and /opsx:ff for change implementation openspec-explore is a mode for thinking and exploring codebases, allowing developers to read files, search code, and investigate without implementing changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tatargabor/wt-tools/openspec-explore', 'community', 'tatargabor', 'wt-tools', 'tatargabor/wt-tools', 'openspec-explore', 9, 0, 47, '2026-02-27T01:28:20Z', '2026-03-06T13:04:05.012Z', '1529ae4e8f63033aee2d94a71045667e2c3280ff9f0283421523520ccc1aef47', '{"id":"tatargabor/wt-tools/openspec-explore","name":"openspec-explore","description":{"en":"openspec-explore provides tools for managing context, focus, and parallel work in AI-assisted development, designed for multi-project workflows and human-AI collaboration. It benefits developers working on complex projects.","zh":"openspec-explore是一款为AI辅助开发设计的工具，支持多项目工作流、长时间运行任务和人机协作","ja":"openspec-exploreは、AIエージェントを活用した開発を支援するツールです。マルチプロジェクトワークフロー、長時間実行タスク、ヒューマンAIコラボレーションに対応しています","ko":"openspec-explore는 AI 툴을 활용한 개발을 지원하는 도구로, 다중 프로젝트 작업 흐름, 장기 실행 태스크, 인간-AI 협력을 지원합니다","es":"openspec-explore es una herramienta para la gestión de contexto y enfoque en el desarrollo asistido por IA, diseñada para flujos de trabajo multi-proyecto y colaboración humano-IA","fr":"openspec-explore est un outil pour la gestion de contexte et de focalisation dans le développement assisté par IA, conçu pour les flux de travail multi-projets et la collaboration humain-IA","de":"openspec-explore ist ein Tool für die Kontext- und Fokustools im IA-gesteuerten Entwicklungsprozess, entwickelt für Multi-Projekt-Workflows und die Zusammenarbeit zwischen Mensch und IA","pt":"O openspec-explore é uma ferramenta para gerenciar contextos, focos e trabalhos paralelos em desenvolvimento assistido por IA, projetada para fluxos de trabalho multi-projeto e colaboração humano-IA","ru":"openspec-explore - это инструмент для управления контекстами, фокусами и параллельными работами в разработке с помощью ИИ Агентов, предназначенный для многопроектных рабочих процессов и сотрудничества человека и ИИ","ar":"openspec-explore هو أداة لإدارة السياقات والتركيز والأعمال الموازية في تطوير الإيجابيات الذكية، مصممة لتدفقات العمل متعددة المشاريع والتعاون بين الإنسان والإيجابيات الذكية"},"seo":{"title":{"en":"openspec-explore: AI-Assisted Development Setup Guide | A...","zh":"openspec-explore Setup Guide: AI工具辅助开发","ja":"openspec-exploreのベストプラクティス: AIエージェントによる開発効率化","ko":"openspec-explore 사용자 가이드: AI 툴을 활용한 개발 최적화","es":"Guía de configuración de openspec-explore para desarrollo...","fr":"Configurer openspec-explore pour le développement collabo...","de":"Einrichtungsleitfaden für openspec-explore in der kollabo...","pt":"Guia de Configuração do openspec-explore para Desenvolved...","ru":"Руководство по настройке openspec-explore для разработчик...","ar":"دليل إعداد openspec-explore لمنصة تطوير الإيجابيات الذكية"},"description":{"en":"Unlock efficient multi-project workflows with openspec-explore. Discover how to manage context, focus, and parallel work in AI-assisted development. Get star...","zh":"了解openspec-explore的功能和特点，优化您的AI辅助开发工作流程，提高开发效率","ja":"openspec-exploreの特徴と機能を紹介します。AIエージェントを活用して開発効率を向上させましょう","ko":"openspec-explore의 기능과 특징을 알아보세요. AI 툴을 활용하여 개발 프로세스를 최적화하고 생산성을 향상시킵니다","es":"Descubre cómo openspec-explore optimiza el flujo de trabajo en proyectos de desarrollo con herramientas de gestión de contexto y enfoque","fr":"Découvrez comment openspec-explore améliore le flux de travail dans les projets de développement avec des outils de gestion de contexte et de focalisation","de":"Erfahren Sie, wie openspec-explore den Arbeitsfluss in Entwicklungsprojekten mit Kontext- und Fokustools optimiert","pt":"Aprenda a usar o openspec-explore para gerenciar contextos, focos e trabalhos paralelos em desenvolvimento assistido por IA","ru":"Узнайте, как использовать openspec-explore для управления контекстами, фокусами и параллельными работами в разработке с помощью ИИ Агентов","ar":"تعرف على كيفية استخدام openspec-explore لإدارة السياقات والتركيز والأعمال الموازية في تطوير الإيجابيات الذكية"},"definition":{"en":"openspec-explore is a set of tools for AI-assisted development, enabling efficient management of context, focus, and parallel work in multi-project workflows.","zh":"openspec-explore是一款AI辅助开发工具，用于管理上下文、焦点和并行工作","ja":"openspec-exploreは、AIエージェントを活用した開発を支援するツールで、コンテキスト、フォーカス、並列作業の管理に使用されます","ko":"openspec-explore는 AI 툴을 활용한 개발을 지원하는 도구로, 문맥, 초점, 병렬 작업 관리에 사용됩니다","es":"openspec-explore es una herramienta de desarrollo que facilita la gestión de contexto y enfoque en proyectos de IA","fr":"openspec-explore est un outil de développement qui facilite la gestion de contexte et de focalisation dans les projets d''IA","de":"openspec-explore ist ein Entwicklungstool, das die Kontext- und Fokustools in IA-Projekten erleichtert","pt":"O que é openspec-explore? É uma ferramenta de desenvolvimento assistido por IA para gerenciar contextos e trabalhos paralelos","ru":"Что такое openspec-explore? Это инструмент разработки с помощью ИИ Агентов для управления контекстами и параллельными работами","ar":"ما هو openspec-explore؟ هو أداة تطوير الإيجابيات الذكية لإدارة السياقات والأعمال الموازية"},"features":{"en":["Enter explore mode for thinking and visualization, without implementing code","Supports reading files, searching code, and investigating the codebase","Allows creation of OpenSpec artifacts, such as proposals, designs, and specs","Reminds users to exit explore mode before implementing changes, using commands like /opsx:new or /opsx:ff","Integrates with technologies like Git worktree, PySide6, and Claude Code"],"zh":["支持多项目工作流","长时间运行任务管理","人机协作功能","CLI接口支持","Git Worktree集成","PySide6支持"],"ja":["マルチプロジェクトワークフロー対応","長時間実行タスク管理","ヒューマンAIコラボレーション機能","CLIインターフェース対応","Git Worktree統合","PySide6対応"],"ko":["다중 프로젝트 작업 흐름 지원","장기 실행 태스크 관리","인간-AI 협력 기능","CLI 인터페이스 지원","Git Worktree 통합","PySide6 지원"],"es":["Gestión de contexto para proyectos de desarrollo asistido por IA","Herramientas de enfoque para flujos de trabajo multi-proyecto","Colaboración humano-IA para tareas a largo plazo","Integración con Git Worktree para una gestión de código eficiente","Compatibilidad con PySide6 para interfaces de usuario personalizadas","Soporte para la creación de artefactos OpenSpec"],"fr":["Gestion de contexte pour les projets de développement assisté par IA","Outils de focalisation pour les flux de travail multi-projets","Collaboration humain-IA pour les tâches à long terme","Intégration avec Git Worktree pour une gestion de code efficace","Compatibilité avec PySide6 pour des interfaces utilisateur personnalisées","Prise en charge de la création d''artefacts OpenSpec"],"de":["Kontextverwaltung für IA-gesteuerte Entwicklungsprojekte","Fokustools für Multi-Projekt-Workflows","Zusammenarbeit zwischen Mensch und IA für Langzeit-Aufgaben","Integration mit Git Worktree für effiziente Codeverwaltung","Kompatibilität mit PySide6 für benutzerdefinierte Benutzeroberflächen","Unterstützung für die Erstellung von OpenSpec-Artefakten"],"pt":["Gerenciamento de contextos e focos em desenvolvimento assistido por IA","Suporte a fluxos de trabalho multi-projeto","Colaboração humano-IA para tarefas longas","Integração com Git Worktree e outras ferramentas de desenvolvimento","Criação de artefatos OpenSpec para propostas e designs","Interface de linha de comando (CLI) para uso eficiente"],"ru":["Управление контекстами и фокусами в разработке с помощью ИИ Агентов","Поддержка многопроектных рабочих процессов","Сотрудничество человека и ИИ для длинных задач","Интеграция с Git Worktree и другими инструментами разработки","Создание артефактов OpenSpec для предложений и дизайнов","Интерфейс командной строки (CLI) для эффективного использования"],"ar":["إدارة السياقات والتركيز في تطوير الإيجابيات الذكية","دعم تدفقات العمل متعددة المشاريع","تعاون بين الإنسان والإيجابيات الذكية للأعمال الطويلة","دمج مع Git Worktree وأدوات تطوير أخرى","إنشاء مكونات OpenSpec لل提قات والتصاميم","واجهة سطر الأوامر (CLI) للاستخدام الفعال"]},"keywords":{"en":["how to use openspec-explore","openspec-explore alternative","openspec-explore setup guide","what is openspec-explore","openspec-explore vs claude-code","openspec-explore install","ai-assisted development tools","multi-project workflow management","human-ai collaboration"],"zh":["AI工具","AI辅助开发","openspec-explore","CLI工具","Git Worktree","PySide6","AI开发效率","开发工作流优化"],"ja":["AIエージェント","AIツール","openspec-explore","CLIツール","Git Worktree","PySide6","AI開発効率","開発ワークフロー最適化"],"ko":["AI 툴","AI 개발 도구","openspec-explore","CLI 도구","Git Worktree","PySide6","AI 개발 효율","개발 작업 흐름 최적화"],"es":["herramientas de desarrollo de IA","gestión de contexto en proyectos de IA","colaboración humano-IA","flujos de trabajo multi-proyecto","Git Worktree","PySide6","OpenSpec","desarrollo colaborativo","IA asistida"],"fr":["outils de développement d''IA","gestion de contexte dans les projets d''IA","collaboration humain-IA","flux de travail multi-projets","Git Worktree","PySide6","OpenSpec","développement collaboratif","IA assistée"],"de":["Entwicklungstools für IA","Kontextverwaltung in IA-Projekten","Zusammenarbeit zwischen Mensch und IA","Multi-Projekt-Workflows","Git Worktree","PySide6","OpenSpec","kollaborative Entwicklung","IA-gesteuert"],"pt":["openspec-explore","desenvolvimento assistido por IA","gerenciamento de contextos","fluxos de trabalho multi-projeto","colaboração humano-IA","Git Worktree","OpenSpec","CLI","ferramentas de desenvolvimento","IA para desenvolvedores"],"ru":["openspec-explore","разработка с помощью ИИ Агентов","управление контекстами","многопроектные рабочие процессы","сотрудничество человека и ИИ","Git Worktree","OpenSpec","CLI","инструменты разработки","ИИ для разработчиков"],"ar":["openspec-explore","تطوير الإيجابيات الذكية","إدارة السياقات","تدفقات العمل متعددة المشاريع","تعاون بين الإنسان والإيجابيات الذكية","Git Worktree","OpenSpec","CLI","أدوات تطوير","الإيجابيات الذكية للمطورين"]}},"owner":"tatargabor","repo":"wt-tools","repoPath":"tatargabor/wt-tools","stars":9,"forks":0,"updatedAt":"2026-02-27T01:28:20Z","topics":["ai-agent","claude-code","cli","developer-tools","git-worktree","mcp","pyside6"],"category":"community","skillMd":{"name":"openspec-explore","description":"Enter explore mode - a thinking partner for exploring ideas, investigating problems, and clarifying requirements. Use when the user wants to think through something before or during a change.","version":"1.0","bodyPreview":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s c","body":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s capturing thinking, not implementing.\n\n**This is a stance, not a workflow.** There are no fixed steps, no required sequence, no mandatory outputs. You''re a thinking partner helping the user explore.\n\n---\n\n## The Stance\n\n- **Curious, not prescriptive** - Ask questions that emerge naturally, don''t follow a script\n- **Open threads, not interrogations** - Surface multiple interesting directions and let the user follow what resonates. Don''t funnel them through a single path of questions.\n- **Visual** - Use ASCII diagrams liberally when they''d help clarify thinking\n- **Adaptive** - Follow interesting threads, pivot when new information emerges\n- **Patient** - Don''t rush to conclusions, let the shape of the problem emerge\n- **Grounded** - Explore the actual codebase when relevant, don''t just theorize\n\n---\n\n## What You Might Do\n\nDepending on what the user brings, you might:\n\n**Explore the problem space**\n- Ask clarifying questions that emerge from what they said\n- Challenge assumptions\n- Reframe the problem\n- Find analogies\n\n**Investigate the codebase**\n- Map existing architecture relevant to the discussion\n- Find integration points\n- Identify patterns already in use\n- Surface hidden complexity\n\n**Compare options**\n- Brainstorm multiple approaches\n- Build comparison tables\n- Sketch tradeoffs\n- Recommend a path (if asked)\n\n**Visualize**\n```\n┌─────────────────────────────────────────┐\n│     Use ASCII diagrams liberally        │\n├─────────────────────────────────────────┤\n│                                         │\n│   ┌────────┐         ┌────────┐        │\n│   │ State  │────────▶│ State  │        │\n│   │   A    │         │   B    │        │\n│   └────────┘         └────────┘        │\n│                                         │\n│   System diagrams, state machines,      │\n│   data flows, architecture sketches,    │\n│   dependency graphs, comparison tables  │\n│                                         │\n└─────────────────────────────────────────┘\n```\n\n**Surface risks and unknowns**\n- Identify what could go wrong\n- Find gaps in understanding\n- Suggest spikes or investigations\n\n---\n\n## OpenSpec Awareness\n\nYou have full context of the OpenSpec system. Use it naturally, don''t force it.\n\n### Check memory first\n\nBefore exploring independently, check injected memory context from `<system-reminder>` tags. Summarize what you already know from memory, then fill in gaps with codebase exploration.\n\n### Check for context\n\nAt the start, quickly check what exists:\n```bash\nopenspec list --json\n```\n\nThis tells you:\n- If there are active changes\n- Their names, schemas, and status\n- What the user might be working on\n\n### When no change exists\n\nThink freely. When insights crystallize, you might offer:\n\n- \"This feels solid enough to start a change. Want me to create one?\"\n  → Can transition to `/opsx:new` or `/opsx:ff`\n- Or keep exploring - no pressure to formalize\n\n### When a change exists\n\nIf the user mentions a change or you detect one is relevant:\n\n1. **Read existing artifacts for context**\n   - `openspec/changes/<name>/proposal.md`\n   - `openspec/changes/<name>/design.md`\n   - `openspec/changes/<name>/tasks.md`\n   - etc.\n\n2. **Reference them naturally in conversation**\n   - \"Your design mentions using Redis, but we just realized SQLite fits better...\"\n   - \"The proposal scopes this to premium users, but we''re now thinking everyone...\"\n\n3. **Offer to capture when decisions are made**\n\n   | Insight Type | Where to Capture |\n   |--------------|------------------|\n   | New requirement discovered | `specs/<capability>/spec.md` |\n   | Requirement changed | `specs/<capability>/spec.md` |\n   | Design decision made | `design.md` |\n   | Scope changed | `proposal.md` |\n   | New work identified | `tasks.md` |\n   | Assumption invalidated | Relevant artifact |\n\n   Example offers:\n   - \"That''s a design decision. Capture it in design.md?\"\n   - \"This is a new requirement. Add it to specs?\"\n   - \"This changes scope. Update the proposal?\"\n\n4. **The user decides** - Offer and move on. Don''t pressure. Don''t auto-capture.\n\n---\n\n## What You Don''t Have To Do\n\n- Follow a script\n- Ask the same questions every time\n- Produce a specific artifact\n- Reach a conclusion\n- Stay on topic if a tangent is valuable\n- Be brief (this is thinking time)\n\n---\n\n## Handling Different Entry Points\n\n**User brings a vague idea:**\n```\nUser: I''m thinking about adding real-time collaboration\n\nYou: Real-time collab is a big space. Let me think about this...\n\n      COLLABORATION SPECTRUM\n      ════════════════════════════════════════════\n\n      Awareness          Coordination         Sync\n          │                   │                 │\n          ▼                   ▼                 ▼\n      ┌────────┐         ┌────────┐        ┌────────┐\n      │Presence│         │Cursors │        │  CRDT  │\n      │  \"3    │         │ Multi  │        │Conflict│\n      │online\" │         │ select │        │  free  │\n      └────────┘         └────────┘        └────────┘\n          │                   │                 │\n       trivial            moderate           complex\n\n      Where''s your head at?\n```\n\n**User brings a specific problem:**\n```\nUser: The auth system is a mess\n\nYou: [reads codebase]\n\n     ┌─────────────────────────────────────────────┐\n     │              CURRENT AUTH FLOW              │\n     └─────────────────────────────────────────────┘\n                        │\n          ┌─────────────┼─────────────┐\n          ▼             ▼             ▼\n     ┌─────────┐  ┌─────────┐  ┌─────────┐\n     │ Google  │  │  GitHub │  │  Email  │\n     │  OAuth  │  │  OAuth  │  │  Magic  │\n     └────┬────┘  └────┬────┘  └────┬────┘\n          │             │             │\n          └─────────────┼─────────────┘\n                        ▼\n                  ┌───────────┐\n                  │  Session  │\n                  └─────┬─────┘\n                        │\n                        ▼\n                  ┌───────────┐\n                  │   Perms   │\n                  └───────────┘\n\n     I see three tangles. Which one''s burning?\n```\n\n**User is stuck mid-implementation:**\n```\nUser: /opsx:explore add-auth-system\n      The OAuth integration is more complex than expected\n\nYou: [reads change artifacts]\n\n     You''re on task 4: \"Implement OAuth flow\"\n\n     Let me trace what''s involved...\n\n     [draws diagram, explores options, suggests paths]\n\n     Want to update the design to reflect this?\n     Or add a spike task to investigate?\n```\n\n**User wants to compare options:**\n```\nUser: Should we use Postgres or SQLite?\n\nYou: Generic answer is boring. What''s the context?\n\nUser: A CLI tool that tracks local dev environments\n\nYou: That changes everything.\n\n     ┌─────────────────────────────────────────────────┐\n     │         CLI TOOL DATA STORAGE                  │\n     └─────────────────────────────────────────────────┘\n\n     Key constraints:\n     • No daemon running\n     • Must work offline\n     • Single user\n\n                  SQLite          Postgres\n     Deployment   embedded ✓      needs server ✗\n     Offline      yes ✓           no ✗\n     Single file  yes ✓           no ✗\n\n     SQLite. Not even close.\n\n     Unless... is there a sync component?\n```\n\n---\n\n## Ending Discovery\n\nThere''s no required ending. Discovery might:\n\n- **Flow into action**: \"Ready to start? /opsx:new or /opsx:ff\"\n- **Result in artifact updates**: \"Updated design.md with these decisions\"\n- **Just provide clarity**: User has what they need, moves on\n- **Continue later**: \"We can pick this up anytime\"\n\nWhen it feels like things are crystallizing, you might summarize:\n\n```\n## What We Figured Out\n\n**The problem**: [crystallized understanding]\n\n**The approach**: [if one emerged]\n\n**Open questions**: [if any remain]\n\n**Next steps** (if ready):\n- Create a change: /opsx:new <name>\n- Fast-forward to tasks: /opsx:ff <name>\n- Keep exploring: just keep talking\n```\n\nBut this summary is optional. Sometimes the thinking IS the value.\n\n---\n\n## Guardrails\n\n- **Don''t implement** - Never write code or implement features. Creating OpenSpec artifacts is fine, writing application code is not.\n- **Don''t fake understanding** - If something is unclear, dig deeper\n- **Don''t rush** - Discovery is thinking time, not task time\n- **Don''t force structure** - Let patterns emerge naturally\n- **Don''t auto-capture** - Offer to save insights, don''t just do it\n- **Do visualize** - A good diagram is worth many paragraphs\n- **Do explore the codebase** - Ground discussions in reality\n- **Do question assumptions** - Including the user''s and your own\n"},"lastSynced":"2026-03-06T13:04:05.012Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced human-AI collaboration and multi-project workflow management capabilities.","zh":"适合需要高级人类与AI协作和多项目工作流管理能力的AI代理。","ja":"高度な人間とAIのコラボレーションとマルチプロジェクトのワークフローマネジメント機能を必要とするAIエージェントに最適です。","ko":"고급的人간과 AI 협업 및 다중 프로젝트 워크플로우 관리 기능이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan colaboración avanzada entre humanos y IA y capacidades de administración de flujos de trabajo multi-proyecto.","fr":"Parfait pour les agents IA nécessitant une collaboration avancée entre humains et IA et des capacités de gestion de workflow multi-projet.","de":"Perfekt für KI-Agents, die erweiterte Mensch-KI-Zusammenarbeit und Multi-Projekt-Workflow-Management-Fähigkeiten benötigen.","pt":"Perfeito para agentes de IA que precisam de colaboração avançada entre humanos e IA e capacidades de gerenciamento de fluxo de trabalho multi-projeto.","ru":"Идеально для агентов ИИ, которым необходимы продвинутые возможности сотрудничества между человеком и ИИ и управления рабочим процессом нескольких проектов.","ar":"مثالي لعمليات الوكيل الذكي التي تحتاج إلى تعاون متقدم بين الإنسان والذكاء الاصطناعي وإدارة تدفق عمل متعدد المشاريع."},"recommendation":{"en":"Empowers agents to manage context, focus, and parallel work in AI-assisted development, leveraging OpenSpec artifacts like proposals, designs, and specs, while ensuring strict separation of exploration and implementation phases through protocols like `/opsx:new` and `/opsx:ff`.","zh":"赋予代理管理上下文、焦点和并行工作的能力，在AI辅助开发中利用OpenSpec文档，如提案、设计和规格，同时通过协议如 `/opsx:new` 和 `/opsx:ff` 确保探索和实现阶段的严格分离。","ja":"コンテキスト、フォーカス、並列作業を管理するエージェントを可能にし、AIアシスト開発でOpenSpecアーティファクト（提案、設計、仕様など）を活用し、 `/opsx:new` や `/opsx:ff` のようなプロトコルを通じて、探索と実装のフェーズを厳密に分離します。","ko":"에이전트가 컨텍스트, 초점, 및 병렬 작업을 관리할 수 있도록 하며, AI 지원 개발에서 OpenSpec 아티팩트(제안, 설계, 사양 등)를 활용하고, `/opsx:new` 및 `/opsx:ff`와 같은 프로토콜을 통해 탐색과 구현 단계를 엄격히 분리합니다.","es":"Habilita a los agentes a administrar el contexto, el enfoque y el trabajo paralelo en el desarrollo asistido por IA, aprovechando artefactos de OpenSpec como propuestas, diseños y especificaciones, y garantizando una estricta separación de las fases de exploración e implementación a través de protocolos como `/opsx:new` y `/opsx:ff`.","fr":"Permet aux agents de gérer le contexte, la concentration et le travail parallèle dans le développement assisté par IA, en exploitant les artefacts OpenSpec tels que les propositions, les conceptions et les spécifications, et en assurant une séparation stricte des phases d''exploration et de mise en œuvre via des protocoles tels que `/opsx:new` et `/opsx:ff`.","de":"Ermächtigt Agenten, Kontext, Fokus und parallele Arbeit in der von KI unterstützten Entwicklung zu verwalten, indem OpenSpec-Artefakte wie Vorschläge, Entwürfe und Spezifikationen genutzt werden, während eine strikte Trennung der Explorations- und Implementierungsphasen durch Protokolle wie `/opsx:new` und `/opsx:ff` sichergestellt wird.","pt":"Habilita os agentes a gerenciar contexto, foco e trabalho paralelo no desenvolvimento assistido por IA, aproveitando artefatos OpenSpec como propostas, designs e especificações, garantindo uma separação estrita das fases de exploração e implementação por meio de protocolos como `/opsx:new` e `/opsx:ff`.","ru":"Наделяет агентов возможностью управлять контекстом, фокусом и параллельной работой при разработке с помощью ИИ, используя артефакты OpenSpec, такие как предложения, дизайны и спецификации, обеспечивая строгое разделение фаз исследования и реализации через протоколы, такие как `/opsx:new` и `/opsx:ff`.","ar":"تمكّن الوكيل من إدارة السياق والتركيز والعمل الموازي في التطوير المدعوم بالذكاء الاصطناعي، مستفيداً من مكونات OpenSpec مثل المقترحات والتصاميم والمواصفات، مع ضمان الفصل الصارم بين مراحل الاستكشاف والتنفيذ من خلال بروتوكولات مثل `/opsx:new` و `/opsx:ff`."},"useCases":{"en":["Exploring complex codebases for dependencies and relationships","Generating OpenSpec proposals for new feature development","Investigating codebase issues without modifying existing code"],"zh":["探索复杂代码库以查找依赖关系和联系","为新功能开发生成OpenSpec提案","在不修改现有代码的情况下调查代码库问题"],"ja":["依存関係や関係性を調べるために複雑なコードベースを探索する","新しい機能開発のためにOpenSpec提案を生成する","既存のコードを変更せずにコードベースの問題を調査する"],"ko":["의존성 및 관계를 찾기 위해 복잡한 코드베이스를 탐색하는 것","새로운 기능 개발을 위한 OpenSpec 제안을 생성하는 것","기존 코드를 수정하지 않고 코드베이스 문제를 조사하는 것"],"es":["Explorar bases de código complejas para dependencias y relaciones","Generar propuestas de OpenSpec para el desarrollo de nuevas características","Investigar problemas del código base sin modificar el código existente"],"fr":["Explorer des bases de code complexes pour les dépendances et les relations","Générer des propositions OpenSpec pour le développement de nouvelles fonctionnalités","Enquêter sur les problèmes de la base de code sans modifier le code existant"],"de":["Komplexe Codebasen für Abhängigkeiten und Beziehungen erkunden","OpenSpec-Vorschläge für die Entwicklung neuer Funktionen generieren","Probleme im Codebestand untersuchen, ohne den bestehenden Code zu ändern"],"pt":["Explorar bases de código complexas para dependências e relações","Gerar propostas OpenSpec para desenvolvimento de recursos novos","Investigar problemas de base de código sem modificar o código existente"],"ru":["Изучать сложные базы кода для зависимостей и отношений","Генерировать предложения OpenSpec для разработки новых функций","Изучать проблемы базы кода без изменения существующего кода"],"ar":["استكشاف قواعد الشفرة المعقدة للاتكالات والعلاقات","генерировать مقترحات OpenSpec لتطوير ميزات جديدة","تحقيق مشاكل قاعدة الشفرة دون تعديل الشفرة الحالية"]},"limitations":{"en":["Must exit explore mode to implement changes","Cannot write code or implement features in explore mode","Requires adherence to OpenSpec guidelines and protocols"],"zh":["必须退出探索模式才能实施更改","无法在探索模式下编写代码或实施功能","需要遵守OpenSpec指南和协议"],"ja":["変更を実施するには探索モードを終了する必要がある","探索モードではコードを書いたり機能を実装したりできない","OpenSpecのガイドラインやプロトコルに従う必要がある"],"ko":["변경 사항을 구현하려면 탐색 모드를 종료해야 함","탐색 모드에서는 코드를 작성하거나 기능을 구현할 수 없음","OpenSpec 지침 및 프로토콜을 따라야 함"],"es":["Debe salir del modo de exploración para implementar cambios","No puede escribir código o implementar características en el modo de exploración","Requiere adherirse a las directrices y protocolos de OpenSpec"],"fr":["Doit quitter le mode d''exploration pour mettre en œuvre des changements","Ne peut pas écrire de code ou implémenter des fonctionnalités en mode d''exploration","Nécessite de se conformer aux directives et protocoles OpenSpec"],"de":["Muss den Explorationsmodus verlassen, um Änderungen umzusetzen","Kann keinen Code schreiben oder Funktionen im Explorationsmodus implementieren","Erfordert die Einhaltung der OpenSpec-Richtlinien und -Protokolle"],"pt":["Deve sair do modo de exploração para implementar alterações","Não pode escrever código ou implementar recursos no modo de exploração","Exige adesão às diretrizes e protocolos OpenSpec"],"ru":["Должен выйти из режима исследования, чтобы внести изменения","Не может писать код или реализовывать функции в режиме исследования","Требует соблюдения руководств и протоколов OpenSpec"],"ar":["يجب الخروج من وضع الاستكشاف لتنفيذ التغييرات","لايمكن كتابة الشفرة أو تنفيذ الميزات في وضع الاستكشاف","يتطلب الالتزام بإرشادات وبروتوكولات OpenSpec"]},"version":4},"contentHash":"1529ae4e8f63033aee2d94a71045667e2c3280ff9f0283421523520ccc1aef47","qualityScore":47}');
